/// Maximum number of distinct source-free diagnostics retained in an index receipt.
pub const MAX_FIRST_SLICE_INDEX_DIAGNOSTICS: usize = 100;

/// One source-free diagnostic retained with a published generation.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct FirstSliceIndexDiagnostic {
    /// Stable producer-defined diagnostic code.
    pub code: String,
    /// Bounded source-free diagnostic message.
    pub message: String,
}

/// Immutable generation-neutral identity of one complete logical snapshot.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct FirstSliceLogicalSnapshotIdentity {
    schema_version: String,
    hash: ContentHash,
}

impl FirstSliceLogicalSnapshotIdentity {
    fn new(hash: ContentHash) -> Self {
        Self {
            schema_version: LOGICAL_SNAPSHOT_SCHEMA_VERSION.to_owned(),
            hash,
        }
    }

    /// Returns the version of the canonical logical projection.
    #[must_use]
    pub fn schema_version(&self) -> &str {
        &self.schema_version
    }

    /// Returns the checked numeric version accepted by the current service.
    #[must_use]
    pub fn schema_version_parts(&self) -> Option<(u16, u16)> {
        match self.schema_version.as_str() {
            LOGICAL_SNAPSHOT_SCHEMA_VERSION => Some((1, 0)),
            _ => None,
        }
    }

    /// Returns the generation-neutral logical snapshot digest.
    #[must_use]
    pub const fn hash(&self) -> ContentHash {
        self.hash
    }
}

impl<'de> Deserialize<'de> for FirstSliceLogicalSnapshotIdentity {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        #[derive(Deserialize)]
        #[serde(deny_unknown_fields)]
        struct WireIdentity {
            schema_version: String,
            hash: ContentHash,
        }

        let wire = WireIdentity::deserialize(deserializer)?;
        if wire.schema_version != LOGICAL_SNAPSHOT_SCHEMA_VERSION {
            return Err(serde::de::Error::custom(
                "unsupported logical snapshot schema version",
            ));
        }
        Ok(Self {
            schema_version: wire.schema_version,
            hash: wire.hash,
        })
    }
}

/// Bounded receipt for one first-slice generation.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct FirstSliceIndexReceipt {
    /// Random local-UUID identity stable for aliases of this repository.
    ///
    /// The canonical-root digest is only an internal lookup key, not this
    /// public identity. Durable services persist the UUID with each generation.
    pub repository: RepositoryId,
    /// Immutable generation published into this service instance.
    pub generation: GenerationId,
    /// Prior generation in the same repository lineage, when present.
    pub parent: Option<GenerationId>,
    /// Regular inputs admitted by deterministic discovery.
    pub discovered_inputs: u64,
    /// Files and directories visited by bounded discovery.
    #[serde(default)]
    pub visited_entries: u64,
    /// Whether deterministic discovery reached the end of the repository namespace.
    #[serde(default = "complete_discovery_by_default")]
    pub discovery_complete: bool,
    /// Inputs omitted by stable discovery policy or resource classification.
    #[serde(default)]
    pub excluded_inputs: u64,
    /// Oversized regular inputs omitted by the configured per-file bound.
    #[serde(default)]
    pub oversized_inputs: u64,
    /// Inputs classified as binary and omitted from text analysis.
    #[serde(default)]
    pub binary_inputs: u64,
    /// Other inputs omitted by explicit discovery policy or safe-read rules.
    #[serde(default)]
    pub policy_excluded_inputs: u64,
    /// Total physical and extracted files retained by the generation.
    pub indexed_files: u64,
    /// Subset of indexed files extracted from immutable containers.
    ///
    /// Subtract this from `indexed_files` before comparing with physical
    /// discovery. Legacy durable receipts reconstruct it from verified IR.
    #[serde(default)]
    pub extracted_files: u64,
    /// Semantic entities committed into normalized IR.
    pub entities: u64,
    /// Lexical documents committed into the generation-pinned reader.
    pub lexical_documents: u64,
    /// SQLite bytes allocated by the normalized generation oracle.
    pub oracle_allocated_bytes: u64,
    /// Conservative staging and publication reservation, including safety margin.
    #[serde(default)]
    pub estimated_disk_bytes: u64,
    /// Durable bytes retained for this generation after atomic publication.
    #[serde(default)]
    pub retained_durable_bytes: u64,
    /// Distinct source-free diagnostics retained in deterministic order.
    #[serde(default)]
    pub diagnostics: Vec<FirstSliceIndexDiagnostic>,
    /// Complete generation-neutral identity, absent when no supported sidecar is available.
    #[serde(default, skip_serializing)]
    pub logical_snapshot: Option<FirstSliceLogicalSnapshotIdentity>,
    /// End-to-end indexing time rounded up to microseconds.
    pub elapsed_micros: u64,
}

const fn complete_discovery_by_default() -> bool {
    true
}

fn verified_source_counts(
    snapshot: &rootlight_storage::GenerationSnapshot,
    discovered_inputs: u64,
    cancellation: &Cancellation,
) -> Result<(u64, u64), FirstSliceError> {
    let indexed = u64::try_from(snapshot.file_count()).map_err(|_| FirstSliceError::Limits)?;
    let mut extracted = 0_u64;
    // Verified generations bind each extraction through a whole-container
    // mapping or an authenticated aggregate origin, independently of its path.
    for mapping in &snapshot.document().source_mappings {
        check_cancellation(cancellation)?;
        if mapping.kind == SourceMappingKind::ExtractedFromContainer {
            extracted = extracted.checked_add(1).ok_or(FirstSliceError::Limits)?;
        }
    }
    for envelope in &snapshot.document().extensions {
        check_cancellation(cancellation)?;
        if envelope.namespace == rootlight_ir::AGGREGATE_SOURCE_ORIGIN_NAMESPACE {
            rootlight_ir::decode_aggregate_source_origin_envelope(envelope)
                .map_err(|_| FirstSliceError::CatalogCorrupt)?;
            extracted = extracted.checked_add(1).ok_or(FirstSliceError::Limits)?;
        }
    }
    if indexed
        .checked_sub(extracted)
        .is_none_or(|physical| physical > discovered_inputs)
    {
        return Err(FirstSliceError::CatalogCorrupt);
    }
    Ok((indexed, extracted))
}

/// One committed generation plus confirmed durable bytes written by its operation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FirstSliceIndexCommit {
    receipt: FirstSliceIndexReceipt,
    written_bytes: u64,
    evidence: FirstSliceIndexOperationEvidence,
}

impl FirstSliceIndexCommit {
    /// Returns the published generation receipt.
    #[must_use]
    pub const fn receipt(&self) -> &FirstSliceIndexReceipt {
        &self.receipt
    }

    /// Returns cumulative bytes confirmed by durable writer boundaries.
    #[must_use]
    pub const fn written_bytes(&self) -> u64 {
        self.written_bytes
    }

    /// Returns final source-free reuse, rebuild, I/O, and memory evidence.
    #[must_use]
    pub const fn evidence(&self) -> &FirstSliceIndexOperationEvidence {
        &self.evidence
    }

    /// Separates the published receipt from its operation-local write metric.
    #[must_use]
    pub fn into_parts(self) -> (FirstSliceIndexReceipt, u64) {
        (self.receipt, self.written_bytes)
    }
}

/// Construction strategy used by one committed index operation.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FirstSliceIndexOperationStrategy {
    /// No committed parent generation was available.
    Initial,
    /// Declared dependencies selected bounded parser-artifact reuse.
    DependencyDirected,
    /// Missing dependency evidence required a repository-wide rebuild.
    ConservativeRepositoryRebuild,
    /// The caller requested a complete rebuild without parent reuse.
    CleanRebuild,
    /// An identical retained generation was reactivated without rebuilding it.
    RetainedGeneration,
}

/// One canonical changed-input key retained in a bounded pre-work plan.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
#[non_exhaustive]
pub enum FirstSlicePlanningDependencyKey {
    /// Actual bytes of one file.
    FileContent(FileId),
    /// Canonical path semantics of one file.
    FilePath(FileId),
    /// Selected parser route for one source with an ambiguous suffix.
    FileParserRoute(FileId),
    /// Exported surface of one analysis unit.
    PublicSurface(FactId),
    /// Body summary of one analysis unit.
    BodySummary(FactId),
    /// Import set of one analysis unit.
    ImportSet(FactId),
    /// Build-target membership.
    BuildTarget(FactId),
    /// Compiler and macro options.
    CompilerOptions(FactId),
    /// Dependency identity.
    DependencyVersion(FactId),
    /// Grammar identity.
    GrammarVersion(FactId),
    /// Adapter identity.
    AdapterVersion(FactId),
    /// Global resolver revision.
    ResolverVersion,
    /// Global analysis-configuration revision.
    ConfigurationRevision,
    /// Global search revision.
    SearchRevision,
    /// Derived plan or projection identity.
    DerivedPlan(FactId),
}

/// Bounded canonical changed-input identities retained in a pre-work plan.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FirstSlicePlanningDependencyKeys {
    total: u64,
    samples: Vec<FirstSlicePlanningDependencyKey>,
    complete: bool,
}

impl FirstSlicePlanningDependencyKeys {
    /// Returns the exact number of changed dependency keys.
    #[must_use]
    pub const fn total(&self) -> u64 {
        self.total
    }

    /// Returns at most 32 canonical changed dependency keys.
    #[must_use]
    pub fn samples(&self) -> &[FirstSlicePlanningDependencyKey] {
        &self.samples
    }

    /// Reports whether every changed dependency key is retained.
    #[must_use]
    pub const fn is_complete(&self) -> bool {
        self.complete
    }
}

/// Source-free work and resource bounds selected before generation construction.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FirstSliceIndexPlanning {
    strategy: FirstSliceIndexOperationStrategy,
    fallback_reason: Option<FallbackReason>,
    estimated_analysis_units: u64,
    estimated_files: u64,
    estimated_facts: u64,
    estimated_cost_units: u64,
    estimated_durable_bytes: u64,
    dependency_keys: FirstSlicePlanningDependencyKeys,
}

impl FirstSliceIndexPlanning {
    /// Returns the construction strategy selected before generation work.
    #[must_use]
    pub const fn strategy(&self) -> FirstSliceIndexOperationStrategy {
        self.strategy
    }

    /// Returns why fine-grained planning fell back, when it did.
    #[must_use]
    pub const fn fallback_reason(&self) -> Option<FallbackReason> {
        self.fallback_reason
    }

    /// Returns the upper bound for analysis units selected by the closure.
    #[must_use]
    pub const fn estimated_analysis_units(&self) -> u64 {
        self.estimated_analysis_units
    }

    /// Returns the upper bound for files that may require reconstruction.
    #[must_use]
    pub const fn estimated_files(&self) -> u64 {
        self.estimated_files
    }

    /// Returns the generation-wide upper bound for rebuilt normalized facts.
    #[must_use]
    pub const fn estimated_facts(&self) -> u64 {
        self.estimated_facts
    }

    /// Returns deterministic closure plus bounded reconstruction cost units.
    #[must_use]
    pub const fn estimated_cost_units(&self) -> u64 {
        self.estimated_cost_units
    }

    /// Returns the already-admitted upper bound for operation-owned durable bytes.
    #[must_use]
    pub const fn estimated_durable_bytes(&self) -> u64 {
        self.estimated_durable_bytes
    }

    /// Returns bounded canonical changed-input identities.
    #[must_use]
    pub const fn dependency_keys(&self) -> &FirstSlicePlanningDependencyKeys {
        &self.dependency_keys
    }

    fn retained_generation(estimated_durable_bytes: u64) -> Self {
        Self {
            strategy: FirstSliceIndexOperationStrategy::RetainedGeneration,
            fallback_reason: None,
            estimated_analysis_units: 0,
            estimated_files: 0,
            estimated_facts: 0,
            estimated_cost_units: 0,
            estimated_durable_bytes,
            dependency_keys: FirstSlicePlanningDependencyKeys {
                total: 0,
                samples: Vec::new(),
                complete: true,
            },
        }
    }
}

/// Preparation failure separated by service ownership and observer ownership.
#[derive(Debug)]
#[non_exhaustive]
pub enum FirstSlicePreparationError<ObserverError> {
    /// Repository preparation failed inside the first-slice service.
    Service(FirstSliceError),
    /// The caller-owned pre-work observer rejected the selected plan.
    PlanningObserver(ObserverError),
}

struct FirstSlicePreparationObservers<Progress, Planning> {
    progress: Progress,
    planning: Planning,
}

impl<ObserverError> From<FirstSliceError> for FirstSlicePreparationError<ObserverError> {
    fn from(error: FirstSliceError) -> Self {
        Self::Service(error)
    }
}

impl<ObserverError: std::fmt::Display> std::fmt::Display
    for FirstSlicePreparationError<ObserverError>
{
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Service(error) => error.fmt(formatter),
            Self::PlanningObserver(error) => error.fmt(formatter),
        }
    }
}

impl<ObserverError: std::error::Error + 'static> std::error::Error
    for FirstSlicePreparationError<ObserverError>
{
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Service(error) => Some(error),
            Self::PlanningObserver(error) => Some(error),
        }
    }
}

