/// Fully verified durable state owning its pending generation-memory charges.
///
/// Dropping the state releases its charges. Preparation transfers ownership;
/// installation converts pending charges to resident charges under the cache lock.
pub struct FirstSliceRestoredState {
    generations: Vec<RestoredGeneration>,
}

/// State-independent active-recovery validation awaiting atomic installation.
///
/// Preparing this value may traverse a large normalized snapshot and search
/// index. The opaque result lets a daemon complete that work without holding
/// the service publication lock while retaining the pending memory reservation.
pub struct FirstSlicePreparedActiveRestore {
    generations: Vec<PreparedRestoredGeneration>,
}

struct PreparedRestoredGeneration {
    restored: RestoredGeneration,
    language_coverage: Vec<LanguageCoverageSummary>,
    relationship_count: u64,
    fact_count: u64,
    memory_bytes: u64,
}

impl FirstSliceDeferredRestore {
    /// Reports whether the deferred-open snapshot contains active restore work.
    ///
    /// Deferred open has already validated the bounded activation and generation
    /// manifests. Generation payloads remain unopened until
    /// [`Self::restore_active`] performs their integrity-checked recovery.
    ///
    /// # Errors
    ///
    /// This cached lookup does not currently fail.
    pub fn has_active_restore_work(&self) -> Result<bool, FirstSliceError> {
        Ok(!self.active_targets.is_empty())
    }

    /// Lists active repositories in most-recently-activated order.
    ///
    /// Deferred open has already collected this bounded metadata. Generation
    /// payloads remain unopened so the daemon can publish recovery work before
    /// reconstruction.
    ///
    /// # Errors
    ///
    /// This cached lookup does not currently fail.
    pub fn active_targets(&self) -> Result<Vec<FirstSliceRecoveryTarget>, FirstSliceError> {
        Ok(self.active_targets.clone())
    }

    /// Restores the newest valid generation for one exact repository.
    ///
    /// # Errors
    ///
    /// Returns the same failures as [`Self::restore_active`].
    pub fn restore_active_repository(
        &self,
        repository: RepositoryId,
        cancellation: &Cancellation,
    ) -> Result<FirstSliceRestoredState, FirstSliceError> {
        self.durable
            .restore_active_repository(repository, cancellation)
            .and_then(|generations| self.reserve_restored_state(generations, cancellation))
    }

    /// Verifies retained rollback generations for one repository without repair writes.
    ///
    /// The read-only boundary permits this nonessential validation to run after
    /// active generations and write admission become available. Newly published
    /// immutable generations may be absent from this snapshot and will be
    /// recovered normally after a later restart.
    ///
    /// # Errors
    ///
    /// Returns the same bounded integrity, cancellation, and retention failures
    /// as [`Self::restore_active_repository`].
    pub fn restore_retained_repository(
        &self,
        repository: RepositoryId,
        excluded: &BTreeSet<GenerationId>,
        cancellation: &Cancellation,
    ) -> Result<FirstSliceRestoredState, FirstSliceError> {
        self.durable
            .restore_retained_repository(repository, excluded, cancellation)
            .and_then(|generations| self.reserve_restored_state(generations, cancellation))
    }

    /// Loads and verifies every retained activation-marked generation.
    ///
    /// The work is intentionally separate from service construction so daemon
    /// readiness and lifecycle control do not depend on catalog size.
    /// Payload loading acquires an aggregate logical-memory reservation first;
    /// resource failures leave durable generations available for a later retry.
    ///
    /// # Errors
    ///
    /// Returns a typed durable catalog, integrity, cancellation, or retention
    /// failure.
    pub fn restore(
        &self,
        cancellation: &Cancellation,
    ) -> Result<FirstSliceRestoredState, FirstSliceError> {
        self.durable
            .restore(cancellation)
            .and_then(|generations| self.reserve_restored_state(generations, cancellation))
    }

    /// Loads only the newest valid generation for each retained repository.
    ///
    /// This is the bounded startup path. Older rollback generations remain
    /// immutable on disk and can be added with
    /// [`Self::restore_excluding`] after interactive last-good reads resume.
    ///
    /// # Errors
    ///
    /// Returns the same failures as [`Self::restore`].
    pub fn restore_active(
        &self,
        cancellation: &Cancellation,
    ) -> Result<FirstSliceRestoredState, FirstSliceError> {
        self.durable
            .restore_active(cancellation)
            .and_then(|generations| self.reserve_restored_state(generations, cancellation))
    }

    /// Loads retained rollback generations not already installed.
    ///
    /// # Errors
    ///
    /// Returns the same failures as [`Self::restore`].
    pub fn restore_excluding(
        &self,
        excluded: &BTreeSet<GenerationId>,
        cancellation: &Cancellation,
    ) -> Result<FirstSliceRestoredState, FirstSliceError> {
        self.durable
            .restore_excluding(excluded, cancellation)
            .and_then(|generations| self.reserve_restored_state(generations, cancellation))
    }

    fn reserve_restored_state(
        &self,
        mut generations: Vec<RestoredGeneration>,
        cancellation: &Cancellation,
    ) -> Result<FirstSliceRestoredState, FirstSliceError> {
        for restored in &mut generations {
            check_cancellation(cancellation)?;
            let memory_bytes = restored_generation_memory_bytes(restored, cancellation)?;
            if let Some(reservation) = restored.memory_reservation.as_mut() {
                reservation.resize(memory_bytes, true)?;
            } else {
                restored.memory_reservation = Some(RestoredMemoryReservation::new(
                    Arc::clone(&self.generation_cache),
                    memory_bytes,
                    true,
                )?);
            }
        }
        Ok(FirstSliceRestoredState { generations })
    }
}

impl FirstSliceRestoredState {
    /// Returns the exact immutable generations carried by this restore batch.
    #[must_use]
    pub fn generation_ids(&self) -> BTreeSet<GenerationId> {
        self.generations
            .iter()
            .map(|generation| generation.receipt.generation)
            .collect()
    }

    /// Returns exact source snapshots and bytes verified while building this batch.
    ///
    /// # Errors
    ///
    /// Returns [`FirstSliceError::Limits`] when the bounded aggregate cannot be
    /// represented as public resource counters.
    pub fn recovery_observation(&self) -> Result<FirstSliceRecoveryObservation, FirstSliceError> {
        let mut files_examined = 0_u64;
        let mut bytes_examined = 0_u64;
        for generation in &self.generations {
            files_examined = files_examined
                .checked_add(
                    u64::try_from(generation.verified.snapshot().file_count())
                        .map_err(|_| FirstSliceError::Limits)?,
                )
                .ok_or(FirstSliceError::Limits)?;
            for file in generation.verified.document().files.iter().chain(
                generation
                    .verified
                    .snapshot()
                    .source_files()
                    .entries()
                    .iter()
                    .map(|entry| entry.file()),
            ) {
                bytes_examined = bytes_examined
                    .checked_add(file.byte_length)
                    .ok_or(FirstSliceError::Limits)?;
            }
        }
        Ok(FirstSliceRecoveryObservation {
            files_examined,
            bytes_examined,
        })
    }

    /// Performs state-independent validation for active-generation installation.
    ///
    /// The returned value retains every verified payload and precomputed
    /// accounting field needed by the short stateful installation boundary.
    ///
    /// # Errors
    ///
    /// Returns a typed query smoke, cancellation, integrity, or resource-limit
    /// failure.
    pub fn prepare_active_installation(
        self,
        cancellation: &Cancellation,
    ) -> Result<FirstSlicePreparedActiveRestore, FirstSliceError> {
        prepare_restored_generations(self.generations, true, cancellation)
            .map(|generations| FirstSlicePreparedActiveRestore { generations })
    }
}

