pub enum FirstSliceProjectCoverageLanguage {
    /// Rust project analysis.
    Rust,
    /// TypeScript project analysis.
    TypeScript,
    /// JavaScript project analysis.
    JavaScript,
    /// Python project analysis.
    Python,
    /// Go project analysis.
    Go,
    /// Java project analysis.
    Java,
    /// C++ project analysis.
    Cpp,
    /// C# project analysis.
    CSharp,
    /// PHP project analysis.
    Php,
    /// C project analysis.
    C,
    /// Dart project analysis.
    Dart,
}

impl FirstSliceProjectCoverageLanguage {
    const fn from_label(label: &str) -> Option<Self> {
        match label.as_bytes() {
            b"rust" => Some(Self::Rust),
            b"typescript" => Some(Self::TypeScript),
            b"javascript" => Some(Self::JavaScript),
            b"python" => Some(Self::Python),
            b"go" => Some(Self::Go),
            b"java" => Some(Self::Java),
            b"cpp" => Some(Self::Cpp),
            b"csharp" => Some(Self::CSharp),
            b"php" => Some(Self::Php),
            b"c" => Some(Self::C),
            b"dart" => Some(Self::Dart),
            _ => None,
        }
    }

    /// Returns the canonical source-free language label.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Rust => "rust",
            Self::TypeScript => "typescript",
            Self::JavaScript => "javascript",
            Self::Python => "python",
            Self::Go => "go",
            Self::Java => "java",
            Self::Cpp => "cpp",
            Self::CSharp => "csharp",
            Self::Php => "php",
            Self::C => "c",
            Self::Dart => "dart",
        }
    }
}

/// Closed reason why bounded project evidence cannot replace structural facts.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum FirstSliceProjectCoverageReason {
    /// Aggregate project facts were truncated before composition.
    FactsTruncated,
    /// Project output omitted structural declaration claims.
    StructuralDeclarationLoss,
}

impl FirstSliceProjectCoverageReason {
    /// Returns the stable source-free diagnostic label.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::FactsTruncated => "project_facts_truncated",
            Self::StructuralDeclarationLoss => "structural_declaration_loss",
        }
    }
}

/// Supported configuration that governs repository-registration capacity.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum FirstSliceRepositoryCapacityConfiguration {
    /// Explicit repository-registration ceiling.
    MaximumRepositories,
    /// Per-repository generation retention determines the effective ceiling.
    RetainedGenerations,
}

impl FirstSliceRepositoryCapacityConfiguration {
    /// Returns the canonical source-free user configuration key.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::MaximumRepositories => "storage.maximum_repositories",
            Self::RetainedGenerations => "storage.retained_generations",
        }
    }
}

/// Closed source-redacted component of an identity-verification failure.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FirstSliceIdentityFailure {
    /// Snapshot construction rejected the normalized document.
    InvalidGeneration,
    /// The generation uses a contract without complete identity claims.
    LegacyContract,
    /// A required claim was absent or an unexpected claim was present.
    MissingClaim,
    /// More than one claim described the same stable identity.
    DuplicateClaim,
    /// A stable record ID differed from its canonical recipe.
    IdentityMismatch(IdentityMismatchComponent),
    /// Canonical manifest inputs differed from generation metadata.
    ManifestMismatch,
    /// An extension did not expose a verifiable shared identity recipe.
    UnsupportedExtension,
    /// A fixed typed identity recipe could not be encoded.
    RecipeEncoding,
}

impl FirstSliceIdentityFailure {
    /// Returns the stable public label used by diagnostics and support evidence.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::InvalidGeneration => "invalid_generation",
            Self::LegacyContract => "legacy_contract",
            Self::MissingClaim => "missing_claim",
            Self::DuplicateClaim => "duplicate_claim",
            Self::IdentityMismatch(component) => component.as_str(),
            Self::ManifestMismatch => "manifest_mismatch",
            Self::UnsupportedExtension => "unsupported_extension",
            Self::RecipeEncoding => "recipe_encoding",
        }
    }
}

/// Source-free component accounting for one failed generation-memory admission.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GenerationMemoryBreakdown {
    /// Total memory retained by already admitted generations.
    pub retained_bytes: u64,
    /// Conservative capacity reserved before generation construction.
    pub reserved_bytes: u64,
    /// Retained memory backed by generation-owned allocations.
    pub owned_bytes: u64,
    /// Retained memory referenced without transferring ownership.
    pub referenced_bytes: u64,
    /// Retained memory backed by file mappings.
    pub mapped_bytes: u64,
    /// Memory held by the candidate generation awaiting admission.
    pub staged_bytes: u64,
    /// Retained memory charged to shared allocations.
    pub shared_bytes: u64,
}

/// Stable source-redacted first-slice service failures.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum FirstSliceError {
    /// Internal pre-persistence proof of genuine combined structural capacity.
    #[doc(hidden)]
    #[error("combined structural output exceeded its admitted capacity")]
    AggregateCapacity(AggregateCapacityFailure),
    /// Effective configuration could not initialize.
    #[error("first-slice configuration is invalid")]
    Configuration,
    /// The operating system could not create a local repository UUID.
    #[error("first-slice repository identity is unavailable")]
    RandomUnavailable,
    /// Legacy rejection retained for compatibility with earlier service errors.
    #[error("first-slice indexing requires a monotonic deadline")]
    DeadlineRequired,
    /// Cooperative cancellation or deadline stopped the operation.
    #[error("first-slice operation was cancelled: {0:?}")]
    Cancelled(CancellationReason),
    /// The repository capability could not be established safely.
    #[error("first-slice repository is unavailable")]
    Repository,
    /// The bounded fixture contains an unsupported number or kind of inputs.
    #[error("first-slice fixture shape is unsupported")]
    FixtureShape,
    /// Deterministic discovery failed.
    #[error("first-slice discovery failed")]
    Discovery,
    /// Bounded discovery could not replace an existing complete generation.
    #[error("first-slice discovery observed at least {estimated} {resource:?} with limit {limit}")]
    DiscoveryIncomplete {
        /// Resource that selected the incomplete deterministic prefix.
        resource: FirstSliceResource,
        /// Safe observed or lower-bound demand.
        estimated: u64,
        /// Effective resource ceiling.
        limit: u64,
    },
    /// Incremental baseline or invalidation planning failed.
    #[error("first-slice incremental planning failed")]
    Incremental,
    /// Source changed between discovery and capability snapshot.
    #[error("first-slice discovery snapshot changed")]
    DiscoveryDrift,
    /// Parser or normalized adapter output failed.
    #[error("first-slice analysis failed")]
    Adapter,
    /// Bounded semantic output could not safely replace structural evidence.
    #[error("first-slice semantic refinement coverage is incomplete")]
    IncompleteCoverage,
    /// Bounded project evidence could not safely replace structural facts.
    #[error(
        "first-slice project coverage for {language:?} is incomplete: {reason:?}, missing {missing_declarations} declarations"
    )]
    ProjectCoverageIncomplete {
        /// Canonical project language.
        language: FirstSliceProjectCoverageLanguage,
        /// Closed coverage failure reason.
        reason: FirstSliceProjectCoverageReason,
        /// Exact source-free number of omitted structural declarations.
        missing_declarations: u64,
    },
    /// The isolated project adapter crossed its configured wall-time ceiling.
    #[error("first-slice project adapter wall-time limit was reached")]
    AdapterWallTimeLimit,
    /// The isolated project adapter crossed its configured input-volume ceiling.
    #[error("first-slice project adapter input limit was reached")]
    AdapterInputLimit,
    /// The isolated project adapter crossed its configured output-volume ceiling.
    #[error("first-slice project adapter output limit was reached")]
    AdapterOutputLimit,
    /// The isolated project adapter crossed its configured memory ceiling.
    #[error("first-slice project adapter memory limit was reached")]
    AdapterMemoryLimit,
    /// The isolated project adapter process exited without a valid result.
    #[error("first-slice project adapter process failed")]
    AdapterProcessFailure,
    /// Bounded semantic resolution failed.
    #[error("first-slice semantic resolution failed")]
    Resolution,
    /// Stable identity verification failed.
    #[error("first-slice identity verification failed")]
    Identity,
    /// Stable identity verification failed at a known canonical component.
    #[error("first-slice identity verification failed: {0:?}")]
    IdentityVerification(FirstSliceIdentityFailure),
    /// Normalized SQLite persistence or verification failed.
    #[error("first-slice oracle failed")]
    Catalog,
    /// A retained generation failed integrity validation.
    #[error("first-slice oracle is corrupt")]
    CatalogCorrupt,
    /// A retained generation uses an unsupported storage schema.
    #[error("first-slice oracle requires migration")]
    CatalogMigrationRequired,
    /// Lexical projection, construction, or validation failed.
    #[error("first-slice search failed")]
    Search,
    /// A bounded source read failed.
    #[error("first-slice source read failed")]
    Source,
    /// Retained raw bytes have no supported lossless text encoding for this query.
    #[error("first-slice source encoding does not support text queries")]
    SourceEncodingUnsupported,
    /// A query plan or execution failed.
    #[error("first-slice query failed")]
    Query,
    /// Portable generation export or verified read-only import failed.
    #[error("first-slice shared generation transfer failed")]
    Sharing,
    /// A caller-supplied runtime trace violated its bounded import contract.
    #[error(transparent)]
    RuntimeTrace(#[from] RuntimeTraceImportError),
    /// The requested stable symbol is absent from the pinned generation.
    #[error("first-slice symbol was not found")]
    SymbolNotFound,
    /// A query or source-read budget rejected planning or execution.
    #[error("first-slice execution budget was exceeded")]
    BudgetExceeded,
    /// Query admission rejected its allowed code-aware term count.
    #[error("first-slice query term budget rejected the request (limit {limit})")]
    QueryTermBudget {
        /// Effective maximum term count, including caller reductions.
        limit: u64,
    },
    /// The requested repository registration is unavailable.
    #[error("first-slice repository was not found")]
    RepositoryNotFound,
    /// The immutable generation is not retained by this daemon process.
    #[error("first-slice generation was not found")]
    GenerationNotFound,
    /// The immutable generation belongs to another repository.
    #[error("first-slice generation does not belong to the repository")]
    GenerationMismatch,
    /// Generation or source retention cannot admit more state.
    #[error("first-slice retention is exhausted")]
    Retention,
    /// Repository filesystem access failed in a way that may be transient.
    #[error("first-slice repository access is temporarily unavailable")]
    RepositoryIo,
    /// A bounded resource could not be reserved, but no numeric bound was available.
    #[error("first-slice resource {resource:?} is temporarily unavailable")]
    ResourceUnavailable {
        /// Closed source-free resource label.
        resource: FirstSliceResource,
    },
    /// A configured integer or duration is not representable.
    #[error("first-slice limits are invalid")]
    Limits,
    /// One explicit bounded resource crossed its configured ceiling.
    #[error("first-slice resource {resource:?} observed {observed} above limit {limit}")]
    ResourceLimit {
        /// Closed source-free resource label.
        resource: FirstSliceResource,
        /// Safe observed count or byte total.
        observed: u64,
        /// Configured count or byte ceiling.
        limit: u64,
    },
    /// Repository registration crossed its effective configured capacity.
    #[error(
        "repository registration observed {observed} above limit {limit} governed by {configuration:?}"
    )]
    RepositoryCapacityLimit {
        /// Safe attempted registration count.
        observed: u64,
        /// Effective repository-registration ceiling.
        limit: u64,
        /// Configuration key that currently governs the effective ceiling.
        configuration: FirstSliceRepositoryCapacityConfiguration,
        /// Registrations that have reserved capacity but are not yet committed.
        pending_repositories: u64,
        /// Committed registrations that the supported delete lifecycle can reclaim.
        reclaimable_repositories: u64,
    },
    /// One explicit bounded resource crossed a ceiling whose exact observation was discarded.
    #[error("first-slice resource {resource:?} estimated at least {estimated} above limit {limit}")]
    EstimatedResourceLimit {
        /// Closed source-free resource label.
        resource: FirstSliceResource,
        /// Safe lower-bound estimate for the rejected observation.
        estimated: u64,
        /// Configured count or byte ceiling.
        limit: u64,
    },
    /// Aggregate generation memory cannot admit the pending generation.
    #[error("generation memory observed {observed} bytes above limit {limit} bytes")]
    GenerationMemoryLimit {
        /// Source-free component accounting for the failed admission.
        breakdown: GenerationMemoryBreakdown,
        /// Retained plus pending bytes counted once for admission.
        observed: u64,
        /// Configured generation-memory ceiling.
        limit: u64,
    },
    /// Durable staging cannot preserve its required free-space margin.
    #[error(
        "insufficient disk space for first-slice publication: required {required_bytes} bytes, available {available_bytes} bytes"
    )]
    InsufficientDiskSpace {
        /// Staging reservation including its safety margin.
        required_bytes: u64,
        /// Free bytes observed on the durable state filesystem.
        available_bytes: u64,
    },
    /// Durable publication crossed one configured physical-storage boundary.
    #[error(
        "durable storage {scope:?} requires {required_bytes} bytes; observed {observed_bytes}, projected {projected_bytes}, limit {limit_bytes}, minimum free {minimum_free_bytes}"
    )]
    StorageResourceExhausted {
        /// Closed physical-storage boundary that rejected admission.
        scope: FirstSliceStorageScope,
        /// Additional physical bytes required by the candidate publication.
        required_bytes: u64,
        /// Physical or available bytes observed at admission.
        observed_bytes: u64,
        /// Physical bytes projected after admitting the candidate publication.
        projected_bytes: u64,
        /// Effective ceiling for the selected scope.
        limit_bytes: u64,
        /// Configured filesystem free-space floor.
        minimum_free_bytes: u64,
        /// Retained-state amplification inputs when repository finalization evaluated them.
        repository_amplification: Option<FirstSliceRepositoryAmplification>,
    },
}

/// Source-free configured boundary used by durable storage admission.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum FirstSliceStorageScope {
    /// Per-repository physical-byte ceiling.
    Repository,
    /// Per-repository retained-state amplification ceiling.
    RepositoryAmplification,
    /// Whole-catalog physical-byte ceiling.
    Catalog,
    /// Filesystem free-space floor.
    Filesystem,
}

/// Source-derived retained-state ceiling evaluated at sealed publication.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FirstSliceRepositoryAmplification {
    /// Exact supported source bytes examined for the candidate generation.
    pub examined_source_bytes: u64,
    /// Canonical serialized bytes for the candidate's emitted normalized facts.
    pub emitted_fact_bytes: u64,
    /// Combined configured factors retained as a concise diagnostic summary.
    pub effective_factor: u64,
    /// Configured complete-generation retention count.
    pub retained_generations: u64,
    /// Configured absolute per-repository ceiling.
    pub absolute_limit_bytes: u64,
    /// Source- and fact-derived ceiling before the absolute cap is applied.
    pub amplification_limit_bytes: u64,
}

struct FirstSliceIncrementalPlanningContext<'a> {
    repository: RepositoryId,
    has_parent: bool,
    reuse_policy: FirstSliceReusePolicy,
    parent: Option<&'a InputSnapshot>,
    parent_artifacts: Option<&'a StructuralGenerationArtifacts>,
    discovery: &'a IncrementalDiscovery,
    source_files: &'a BTreeSet<FileId>,
    parser_route_inputs: &'a BTreeMap<FileId, ContentHash>,
    semantic_inputs: &'a [InputFingerprint],
    estimated_facts: u64,
    estimated_durable_bytes: u64,
}

fn prepare_incremental_state(
    context: FirstSliceIncrementalPlanningContext<'_>,
    cancellation: &Cancellation,
) -> Result<PreparedIncrementalPlan, FirstSliceError> {
    let FirstSliceIncrementalPlanningContext {
        repository,
        has_parent,
        reuse_policy,
        parent,
        parent_artifacts,
        discovery,
        source_files,
        parser_route_inputs,
        semantic_inputs,
        estimated_facts,
        estimated_durable_bytes,
    } = context;
    check_cancellation(cancellation)?;
    let parent_inputs = match parent {
        Some(parent) => parent.clone(),
        None => InputSnapshot::new([], PlanningLimits::default(), cancellation)
            .map_err(|error| map_incremental_error(error, cancellation))?,
    };
    let current_inputs = first_slice_input_snapshot(
        discovery,
        source_files,
        parser_route_inputs,
        semantic_inputs,
        cancellation,
    )?;
    let input_keys = incremental_input_keys(&parent_inputs, &current_inputs, cancellation)?;
    let files = incremental_file_ids(&input_keys, cancellation)?;
    let passes = first_slice_passes()?;
    let (nodes, edges) =
        first_slice_dependency_parts(repository, &files, &input_keys, &passes, cancellation)?;
    let graph_limits = GraphLimits::new(5, nodes.len().max(1), edges.len().max(1))
        .map_err(|error| map_incremental_error(error, cancellation))?;
    let registry = DependencyRegistry::new(passes.declarations()?, graph_limits, cancellation)
        .map_err(|error| map_incremental_error(error, cancellation))?;
    verify_first_slice_observations(&registry, &passes)
        .map_err(|error| map_incremental_error(error, cancellation))?;
    let graph = DependencyGraph::new(nodes, edges, &registry, graph_limits, cancellation)
        .map_err(|error| map_incremental_error(error, cancellation))?;
    let artifact_count = parent_artifacts.map_or(0, StructuralGenerationArtifacts::len);
    let planning_limits = incremental_planning_limits(
        input_keys.len(),
        artifact_count,
        graph.nodes().count(),
        graph.edges().count(),
    )?;
    let artifact_summaries = parent_artifact_summaries(
        &parent_inputs,
        parent_artifacts,
        planning_limits,
        cancellation,
    )?;
    let parent_summary = GenerationSummary::new(
        parent_inputs,
        artifact_summaries,
        planning_limits,
        cancellation,
    )
    .map_err(|error| map_incremental_error(error, cancellation))?;
    let plan = plan_invalidation(
        &parent_summary,
        &current_inputs,
        &graph,
        planning_limits,
        cancellation,
    )
    .map_err(|error| map_incremental_error(error, cancellation))?;
    let evidence =
        summarize_incremental_evidence(has_parent, reuse_policy, discovery, source_files, &plan)?;
    let planning = first_slice_index_planning(
        &evidence,
        source_files,
        &plan,
        estimated_facts,
        estimated_durable_bytes,
    )?;
    let reusable_parser_artifacts = if reuse_policy == FirstSliceReusePolicy::CleanRebuild {
        BTreeSet::new()
    } else {
        plan.artifact_decisions()
            .iter()
            .filter(|decision| decision.kind() == ArtifactDecisionKind::Reuse)
            .map(|decision| decision.artifact())
            .collect()
    };
    Ok(PreparedIncrementalPlan {
        state: PreparedIncrementalState {
            baseline: discovery.baseline().clone(),
            inputs: current_inputs,
            evidence,
        },
        reusable_parser_artifacts,
        planning,
    })
}

struct FirstSliceFileOnlyInputs<'a> {
    semantic_inputs: &'a [InputFingerprint],
    source_files: &'a BTreeSet<FileId>,
    parser_route_inputs: &'a BTreeMap<FileId, ContentHash>,
}

fn prepare_file_only_incremental_state(
    has_parent: bool,
    reuse_policy: FirstSliceReusePolicy,
    discovery: &IncrementalDiscovery,
    inputs: FirstSliceFileOnlyInputs<'_>,
    estimated_facts: u64,
    estimated_durable_bytes: u64,
    cancellation: &Cancellation,
) -> Result<PreparedIncrementalPlan, FirstSliceError> {
    check_cancellation(cancellation)?;
    let current_inputs = first_slice_input_snapshot(
        discovery,
        inputs.source_files,
        inputs.parser_route_inputs,
        inputs.semantic_inputs,
        cancellation,
    )?;
    let mut input_counts = BTreeMap::new();
    for change in discovery.changes().changes() {
        check_cancellation(cancellation)?;
        increment_evidence_count(&mut input_counts, change.class())?;
    }
    let input_changes = input_counts
        .into_iter()
        .map(|(class, inputs)| FirstSliceInputChangeCount { class, inputs })
        .collect();
    let mut file_counts = BTreeMap::new();
    for change in discovery.file_changes() {
        check_cancellation(cancellation)?;
        increment_evidence_count(&mut file_counts, change.kind())?;
    }
    let file_changes = file_counts
        .into_iter()
        .map(|(kind, files)| FirstSliceFileChangeCount { kind, files })
        .collect();
    let strategy = if reuse_policy == FirstSliceReusePolicy::CleanRebuild {
        FirstSliceBuildStrategy::CleanRebuild
    } else if has_parent {
        FirstSliceBuildStrategy::DependencyDirected
    } else {
        FirstSliceBuildStrategy::Initial
    };
    let evidence = FirstSliceIncrementalEvidence {
        strategy,
        input_changes,
        file_changes,
        hashed_files: u64::try_from(discovery.hashed_files().len())
            .map_err(|_| FirstSliceError::Limits)?,
        invalidated_domains: Vec::new(),
        invalidated_units: 0,
        fallback_reason: None,
        trace_entries: 0,
        invalidation_trace: Vec::new(),
        parsed_files: 0,
        reused_parser_artifacts: 0,
        reused_parser_artifact_bytes: 0,
        reused_durable_artifact_bytes: 0,
        lowered_files: 0,
        reused_normalized_facts: 0,
        rebuilt_normalized_facts: 0,
        planned_fact_work: Vec::new(),
        normalized_fact_work: Vec::new(),
        structural_cache_retained: false,
    };
    let estimated_files =
        u64::try_from(inputs.source_files.len()).map_err(|_| FirstSliceError::Limits)?;
    let estimated_cost_units = estimated_files
        .checked_add(estimated_facts)
        .ok_or(FirstSliceError::Limits)?;
    let total_dependency_keys =
        u64::try_from(discovery.changes().changes().len()).map_err(|_| FirstSliceError::Limits)?;
    let dependency_key_samples = discovery
        .changes()
        .changes()
        .iter()
        .take(MAX_FIRST_SLICE_PLANNING_DEPENDENCY_KEYS)
        .map(|change| first_slice_planning_dependency_key(change.key()))
        .collect::<Vec<_>>();
    let retained_dependency_keys =
        u64::try_from(dependency_key_samples.len()).map_err(|_| FirstSliceError::Limits)?;
    Ok(PreparedIncrementalPlan {
        state: PreparedIncrementalState {
            baseline: discovery.baseline().clone(),
            inputs: current_inputs,
            evidence,
        },
        reusable_parser_artifacts: BTreeSet::new(),
        planning: FirstSliceIndexPlanning {
            strategy: first_slice_operation_strategy(strategy),
            fallback_reason: None,
            estimated_analysis_units: 0,
            estimated_files,
            estimated_facts,
            estimated_cost_units,
            estimated_durable_bytes,
            dependency_keys: FirstSlicePlanningDependencyKeys {
                total: total_dependency_keys,
                samples: dependency_key_samples,
                complete: total_dependency_keys == retained_dependency_keys,
            },
        },
    })
}

fn first_slice_index_planning(
    evidence: &FirstSliceIncrementalEvidence,
    source_files: &BTreeSet<FileId>,
    plan: &InvalidationPlan,
    estimated_facts: u64,
    estimated_durable_bytes: u64,
) -> Result<FirstSliceIndexPlanning, FirstSliceError> {
    // Generation-bound identities can rebuild normalized records for files whose
    // parser artifacts remain reusable, so the pre-work upper bound covers the
    // complete current source set rather than only directly invalidated files.
    let estimated_files = u64::try_from(source_files.len()).map_err(|_| FirstSliceError::Limits)?;
    let estimated_analysis_units =
        u64::try_from(plan.reanalyze().count()).map_err(|_| FirstSliceError::Limits)?;
    let closure_work = u64::try_from(plan.closure_work()).map_err(|_| FirstSliceError::Limits)?;
    let estimated_cost_units = closure_work
        .checked_add(estimated_analysis_units)
        .and_then(|total| total.checked_add(estimated_files))
        .and_then(|total| total.checked_add(estimated_facts))
        .ok_or(FirstSliceError::Limits)?;
    let total_dependency_keys =
        u64::try_from(plan.changes().changes().len()).map_err(|_| FirstSliceError::Limits)?;
    let retained_dependency_keys = plan
        .changes()
        .changes()
        .len()
        .min(MAX_FIRST_SLICE_PLANNING_DEPENDENCY_KEYS);
    let mut dependency_key_samples = Vec::new();
    dependency_key_samples
        .try_reserve_exact(retained_dependency_keys)
        .map_err(|_| FirstSliceError::Limits)?;
    dependency_key_samples.extend(
        plan.changes()
            .changes()
            .iter()
            .take(MAX_FIRST_SLICE_PLANNING_DEPENDENCY_KEYS)
            .map(|change| first_slice_planning_dependency_key(change.key())),
    );
    let retained_dependency_keys =
        u64::try_from(dependency_key_samples.len()).map_err(|_| FirstSliceError::Limits)?;

    Ok(FirstSliceIndexPlanning {
        strategy: first_slice_operation_strategy(evidence.strategy),
        fallback_reason: evidence.fallback_reason,
        estimated_analysis_units,
        estimated_files,
        estimated_facts,
        estimated_cost_units,
        estimated_durable_bytes,
        dependency_keys: FirstSlicePlanningDependencyKeys {
            total: total_dependency_keys,
            samples: dependency_key_samples,
            complete: total_dependency_keys == retained_dependency_keys,
        },
    })
}

const fn first_slice_operation_strategy(
    strategy: FirstSliceBuildStrategy,
) -> FirstSliceIndexOperationStrategy {
    match strategy {
        FirstSliceBuildStrategy::Initial => FirstSliceIndexOperationStrategy::Initial,
        FirstSliceBuildStrategy::DependencyDirected => {
            FirstSliceIndexOperationStrategy::DependencyDirected
        }
        FirstSliceBuildStrategy::ConservativeRepositoryRebuild => {
            FirstSliceIndexOperationStrategy::ConservativeRepositoryRebuild
        }
        FirstSliceBuildStrategy::CleanRebuild => FirstSliceIndexOperationStrategy::CleanRebuild,
    }
}

const fn first_slice_planning_dependency_key(key: InputKey) -> FirstSlicePlanningDependencyKey {
    match key {
        InputKey::FileContent(file) => FirstSlicePlanningDependencyKey::FileContent(file),
        InputKey::FilePath(file) => FirstSlicePlanningDependencyKey::FilePath(file),
        InputKey::FileParserRoute(file) => FirstSlicePlanningDependencyKey::FileParserRoute(file),
        InputKey::PublicSurface(unit) => {
            FirstSlicePlanningDependencyKey::PublicSurface(unit.as_fact_id())
        }
        InputKey::BodySummary(unit) => {
            FirstSlicePlanningDependencyKey::BodySummary(unit.as_fact_id())
        }
        InputKey::ImportSet(unit) => FirstSlicePlanningDependencyKey::ImportSet(unit.as_fact_id()),
        InputKey::BuildTarget(fact) => FirstSlicePlanningDependencyKey::BuildTarget(fact),
        InputKey::CompilerOptions(fact) => FirstSlicePlanningDependencyKey::CompilerOptions(fact),
        InputKey::DependencyVersion(fact) => {
            FirstSlicePlanningDependencyKey::DependencyVersion(fact)
        }
        InputKey::GrammarVersion(fact) => FirstSlicePlanningDependencyKey::GrammarVersion(fact),
        InputKey::AdapterVersion(fact) => FirstSlicePlanningDependencyKey::AdapterVersion(fact),
        InputKey::ResolverVersion => FirstSlicePlanningDependencyKey::ResolverVersion,
        InputKey::ConfigurationRevision => FirstSlicePlanningDependencyKey::ConfigurationRevision,
        InputKey::SearchRevision => FirstSlicePlanningDependencyKey::SearchRevision,
        InputKey::DerivedPlan(fact) => FirstSlicePlanningDependencyKey::DerivedPlan(fact),
    }
}

fn incremental_planning_limits(
    input_count: usize,
    artifact_count: usize,
    node_count: usize,
    edge_count: usize,
) -> Result<PlanningLimits, FirstSliceError> {
    let max_trace_entries = input_count
        .checked_add(node_count)
        .and_then(|entries| entries.checked_add(artifact_count))
        .and_then(|entries| entries.checked_add(1))
        .ok_or(FirstSliceError::Limits)?;
    PlanningLimits::new(
        input_count.max(1),
        artifact_count.max(1),
        node_count.max(1),
        edge_count.max(1),
        max_trace_entries.max(1),
    )
    .map_err(|_| FirstSliceError::Limits)
}

struct FirstSlicePasses {
    parser: PassId,
    lowering: PassId,
    resolver: PassId,
    derived: PassId,
    search: PassId,
}

impl FirstSlicePasses {
    fn declarations(&self) -> Result<Vec<PassDeclaration>, FirstSliceError> {
        Ok(vec![
            PassDeclaration::new(
                self.parser.clone(),
                [
                    InputKind::FileContent,
                    InputKind::FilePath,
                    InputKind::FileParserRoute,
                    InputKind::GrammarVersion,
                    InputKind::AdapterVersion,
                    InputKind::ConfigurationRevision,
                ],
                FactDomainSet::default(),
                FactDomainSet::new([FactDomain::Syntax]),
            )
            .map_err(|_| FirstSliceError::Incremental)?,
            PassDeclaration::new(
                self.lowering.clone(),
                [
                    InputKind::FileContent,
                    InputKind::FilePath,
                    InputKind::FileParserRoute,
                    InputKind::AdapterVersion,
                    InputKind::CompilerOptions,
                    InputKind::ConfigurationRevision,
                ],
                FactDomainSet::new([FactDomain::Syntax]),
                local_semantic_domains(),
            )
            .map_err(|_| FirstSliceError::Incremental)?,
            PassDeclaration::new(
                self.resolver.clone(),
                [
                    InputKind::PublicSurface,
                    InputKind::BodySummary,
                    InputKind::ImportSet,
                    InputKind::BuildTarget,
                    InputKind::CompilerOptions,
                    InputKind::DependencyVersion,
                    InputKind::ResolverVersion,
                    InputKind::ConfigurationRevision,
                ],
                local_semantic_domains(),
                FactDomainSet::new([FactDomain::Resolution]),
            )
            .map_err(|_| FirstSliceError::Incremental)?,
            PassDeclaration::new(
                self.derived.clone(),
                [InputKind::DerivedPlan, InputKind::ConfigurationRevision],
                FactDomainSet::new([FactDomain::Resolution]),
                FactDomainSet::new([FactDomain::DerivedGraph]),
            )
            .map_err(|_| FirstSliceError::Incremental)?,
            PassDeclaration::new(
                self.search.clone(),
                [
                    InputKind::PublicSurface,
                    InputKind::BodySummary,
                    InputKind::SearchRevision,
                    InputKind::ConfigurationRevision,
                ],
                FactDomainSet::new([
                    FactDomain::PublicSurface,
                    FactDomain::Body,
                    FactDomain::Resolution,
                ]),
                FactDomainSet::new([FactDomain::Search]),
            )
            .map_err(|_| FirstSliceError::Incremental)?,
        ])
    }
}

fn first_slice_passes() -> Result<FirstSlicePasses, FirstSliceError> {
    Ok(FirstSlicePasses {
        parser: PassId::parse(PARSER_PASS_ID).map_err(|_| FirstSliceError::Incremental)?,
        lowering: PassId::parse(LOWERING_PASS_ID).map_err(|_| FirstSliceError::Incremental)?,
        resolver: PassId::parse(RESOLVER_PASS_ID).map_err(|_| FirstSliceError::Incremental)?,
        derived: PassId::parse(DERIVED_PASS_ID).map_err(|_| FirstSliceError::Incremental)?,
        search: PassId::parse(SEARCH_PASS_ID).map_err(|_| FirstSliceError::Incremental)?,
    })
}

fn local_semantic_domains() -> FactDomainSet {
    FactDomainSet::new([
        FactDomain::PublicSurface,
        FactDomain::Body,
        FactDomain::Tests,
        FactDomain::Services,
    ])
}

fn verify_first_slice_observations(
    registry: &DependencyRegistry,
    passes: &FirstSlicePasses,
) -> Result<(), IncrementalError> {
    let observations = [
        (
            &passes.parser,
            PassObservation::new(
                [
                    InputKind::FileContent,
                    InputKind::FilePath,
                    InputKind::FileParserRoute,
                    InputKind::GrammarVersion,
                    InputKind::AdapterVersion,
                    InputKind::ConfigurationRevision,
                ],
                FactDomainSet::default(),
                FactDomainSet::new([FactDomain::Syntax]),
            ),
        ),
        (
            &passes.lowering,
            PassObservation::new(
                [
                    InputKind::FileContent,
                    InputKind::FilePath,
                    InputKind::FileParserRoute,
                    InputKind::AdapterVersion,
                    InputKind::CompilerOptions,
                    InputKind::ConfigurationRevision,
                ],
                FactDomainSet::new([FactDomain::Syntax]),
                local_semantic_domains(),
            ),
        ),
        (
            &passes.resolver,
            PassObservation::new(
                [
                    InputKind::PublicSurface,
                    InputKind::BodySummary,
                    InputKind::ImportSet,
                    InputKind::BuildTarget,
                    InputKind::CompilerOptions,
                    InputKind::DependencyVersion,
                    InputKind::ResolverVersion,
                    InputKind::ConfigurationRevision,
                ],
                local_semantic_domains(),
                FactDomainSet::new([FactDomain::Resolution]),
            ),
        ),
        (
            &passes.derived,
            PassObservation::new(
                [InputKind::DerivedPlan, InputKind::ConfigurationRevision],
                FactDomainSet::new([FactDomain::Resolution]),
                FactDomainSet::new([FactDomain::DerivedGraph]),
            ),
        ),
        (
            &passes.search,
            PassObservation::new(
                [
                    InputKind::PublicSurface,
                    InputKind::BodySummary,
                    InputKind::SearchRevision,
                    InputKind::ConfigurationRevision,
                ],
                FactDomainSet::new([
                    FactDomain::PublicSurface,
                    FactDomain::Body,
                    FactDomain::Resolution,
                ]),
                FactDomainSet::new([FactDomain::Search]),
            ),
        ),
    ];
    for (pass, observation) in observations {
        registry.verify_observation(pass, &observation)?;
    }
    Ok(())
}

fn first_slice_input_snapshot(
    discovery: &IncrementalDiscovery,
    source_files: &BTreeSet<FileId>,
    parser_route_inputs: &BTreeMap<FileId, ContentHash>,
    semantic_inputs: &[InputFingerprint],
    cancellation: &Cancellation,
) -> Result<InputSnapshot, FirstSliceError> {
    let mut inputs = Vec::new();
    let expected = source_files
        .len()
        .checked_mul(2)
        .and_then(|count| count.checked_add(parser_route_inputs.len()))
        .and_then(|count| count.checked_add(semantic_inputs.len()))
        .and_then(|count| count.checked_add(7))
        .ok_or(FirstSliceError::Limits)?;
    inputs
        .try_reserve_exact(expected)
        .map_err(|_| FirstSliceError::Limits)?;
    let mut configuration_present = false;
    let mut adapter_present = false;
    for input in discovery.baseline().inputs().iter() {
        check_cancellation(cancellation)?;
        let include = match input.key() {
            InputKey::FileContent(file) | InputKey::FilePath(file) => source_files.contains(&file),
            InputKey::ConfigurationRevision => {
                configuration_present = true;
                true
            }
            InputKey::AdapterVersion(_) => {
                adapter_present = true;
                true
            }
            _ => false,
        };
        if include {
            inputs.push(input);
        }
    }
    if !configuration_present || !adapter_present {
        return Err(FirstSliceError::Incremental);
    }
    for (file, route) in parser_route_inputs {
        if !source_files.contains(file) {
            return Err(FirstSliceError::Incremental);
        }
        // Peer/project evidence can change a route without changing this file's
        // path or bytes. Unknown routes also retain negative project evidence.
        inputs.push(InputFingerprint::new(
            InputKey::FileParserRoute(*file),
            *route,
        ));
    }

    inputs.extend([
        InputFingerprint::new(
            InputKey::GrammarVersion(
                derive_fact("rootlight.first-slice.grammar-input", GRAMMAR_REVISION_SEED).id(),
            ),
            first_slice_grammar_revision_hash()?,
        ),
        InputFingerprint::new(
            InputKey::CompilerOptions(
                derive_fact(
                    "rootlight.first-slice.compiler-input",
                    COMPILER_CONTEXT_INPUT_SEED,
                )
                .id(),
            ),
            first_slice_build_context(),
        ),
        InputFingerprint::new(
            InputKey::ResolverVersion,
            content_hash(RESOLVER_BINARY_SEED),
        ),
        InputFingerprint::new(InputKey::SearchRevision, content_hash(SEARCH_REVISION_SEED)),
        InputFingerprint::new(
            InputKey::DerivedPlan(
                derive_fact(
                    "rootlight.first-slice.derived-plan-input",
                    DERIVED_PLAN_REVISION_SEED,
                )
                .id(),
            ),
            first_slice_incremental_plan_hash()?,
        ),
    ]);
    inputs.extend_from_slice(semantic_inputs);
    let snapshot = InputSnapshot::new(inputs, PlanningLimits::default(), cancellation)
        .map_err(|error| map_incremental_error(error, cancellation))?;
    for file in source_files {
        check_cancellation(cancellation)?;
        if snapshot.value(InputKey::FileContent(*file)).is_none()
            || snapshot.value(InputKey::FilePath(*file)).is_none()
        {
            return Err(FirstSliceError::Incremental);
        }
    }
    Ok(snapshot)
}

struct SemanticFingerprintState {
    public_surface: Vec<ContentHash>,
    body: Vec<ContentHash>,
    imports: Vec<ContentHash>,
}

impl SemanticFingerprintState {
    fn new() -> Self {
        Self {
            public_surface: Vec::new(),
            body: Vec::new(),
            imports: Vec::new(),
        }
    }
}

struct SemanticHashWriter<'a>(&'a mut blake3::Hasher);

impl std::io::Write for SemanticHashWriter<'_> {
    fn write(&mut self, buffer: &[u8]) -> std::io::Result<usize> {
        self.0.update(buffer);
        Ok(buffer.len())
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

fn semantic_fingerprint_hasher(domain: &[u8]) -> blake3::Hasher {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rootlight.first-slice.semantic-fingerprint/1\0");
    hasher.update(domain);
    hasher
}

fn semantic_value_fingerprint(
    label: &[u8],
    value: &impl Serialize,
) -> Result<ContentHash, FirstSliceError> {
    let mut hasher = semantic_fingerprint_hasher(b"value");
    let length = u64::try_from(label.len()).map_err(|_| FirstSliceError::Limits)?;
    hasher.update(&length.to_be_bytes());
    hasher.update(label);
    serde_json::to_writer(SemanticHashWriter(&mut hasher), value)
        .map_err(|_| FirstSliceError::Limits)?;
    Ok(ContentHash::from_bytes(*hasher.finalize().as_bytes()))
}

fn aggregate_semantic_fingerprint(
    domain: &[u8],
    mut values: Vec<ContentHash>,
) -> Result<ContentHash, FirstSliceError> {
    values.sort_unstable();
    let mut hasher = semantic_fingerprint_hasher(domain);
    let count = u64::try_from(values.len()).map_err(|_| FirstSliceError::Limits)?;
    hasher.update(&count.to_be_bytes());
    for value in values {
        hasher.update(value.as_bytes());
    }
    Ok(ContentHash::from_bytes(*hasher.finalize().as_bytes()))
}

fn evidence_file(evidence: &FactEvidence) -> Option<FileId> {
    evidence
        .source
        .as_ref()
        .map(|source| source.span().file())
        .or_else(|| {
            evidence.derivation.iter().find_map(|fact| match fact {
                FactRef::File(file) => Some(*file),
                FactRef::Entity(_) | FactRef::Fact(_) => None,
            })
        })
}

fn relation_has_stable_endpoints(subject: RelationEndpoint, object: RelationEndpoint) -> bool {
    !matches!(subject, RelationEndpoint::Occurrence(_))
        && !matches!(object, RelationEndpoint::Occurrence(_))
}

fn first_slice_semantic_inputs(
    document: &NormalizedIrDocument,
    source_files: &BTreeSet<FileId>,
    cancellation: &Cancellation,
) -> Result<Vec<InputFingerprint>, FirstSliceError> {
    let mut by_file = source_files
        .iter()
        .copied()
        .map(|file| (file, SemanticFingerprintState::new()))
        .collect::<BTreeMap<_, _>>();

    for entity in &document.entities {
        check_cancellation(cancellation)?;
        let Some(file) = evidence_file(&entity.evidence) else {
            continue;
        };
        let Some(state) = by_file.get_mut(&file) else {
            continue;
        };
        state.public_surface.push(semantic_value_fingerprint(
            b"entity",
            &(
                entity.id,
                entity.kind,
                &entity.language,
                entity.tier,
                &entity.canonical_name,
                &entity.display_name,
                &entity.qualified_name,
                entity.container,
                entity.visibility,
                &entity.flags,
            ),
        )?);
    }

    for occurrence in &document.occurrences {
        check_cancellation(cancellation)?;
        let Some(state) = by_file.get_mut(&occurrence.file) else {
            continue;
        };
        let value = (
            occurrence.role,
            occurrence.enclosing,
            &occurrence.target,
            occurrence.syntactic_text_hash,
            &occurrence.syntax_kind,
            occurrence.confidence,
        );
        if occurrence.role == OccurrenceRole::ImportUse {
            state
                .imports
                .push(semantic_value_fingerprint(b"occurrence", &value)?);
        } else if occurrence.role == OccurrenceRole::Documentation {
            continue;
        } else {
            state
                .body
                .push(semantic_value_fingerprint(b"occurrence", &value)?);
        }
    }

    for relation in &document.relations {
        check_cancellation(cancellation)?;
        if !relation_has_stable_endpoints(relation.subject, relation.object) {
            continue;
        }
        let Some(file) = evidence_file(&relation.evidence) else {
            continue;
        };
        let Some(state) = by_file.get_mut(&file) else {
            continue;
        };
        let value = (
            relation.subject,
            relation.predicate,
            relation.object,
            relation.confidence,
            relation.evidence_kind,
        );
        match relation.predicate {
            RelationPredicate::Imports => {
                state
                    .imports
                    .push(semantic_value_fingerprint(b"relation", &value)?);
            }
            RelationPredicate::Exports => {
                state
                    .public_surface
                    .push(semantic_value_fingerprint(b"relation", &value)?);
            }
            RelationPredicate::Contains
            | RelationPredicate::Declares
            | RelationPredicate::DefinesAt => {}
            _ => {
                state
                    .body
                    .push(semantic_value_fingerprint(b"relation", &value)?);
            }
        }
    }

    for envelope in &document.extensions {
        check_cancellation(cancellation)?;
        if envelope.namespace != rootlight_ir::FSHARP_BINDING_NAMESPACE {
            continue;
        }
        let claim = rootlight_ir::decode_fsharp_binding_envelope(envelope)
            .map_err(|_| FirstSliceError::Identity)?;
        let Some(state) = by_file.get_mut(&claim.scope().file()) else {
            continue;
        };
        let value = semantic_value_fingerprint(b"fsharp-binding", claim.binding())?;
        match claim.binding() {
            rootlight_ir::FSharpBinding::Context
            | rootlight_ir::FSharpBinding::Export { .. }
            | rootlight_ir::FSharpBinding::SignatureValue { .. }
            | rootlight_ir::FSharpBinding::SignatureType { .. }
            | rootlight_ir::FSharpBinding::SignatureAlias { .. }
            | rootlight_ir::FSharpBinding::Container { .. } => {
                state.public_surface.push(value);
            }
            rootlight_ir::FSharpBinding::Reference { .. }
            | rootlight_ir::FSharpBinding::Call { .. }
            | rootlight_ir::FSharpBinding::ImportedReference { .. }
            | rootlight_ir::FSharpBinding::ImportedCall { .. }
            | rootlight_ir::FSharpBinding::OpenedReference { .. }
            | rootlight_ir::FSharpBinding::OpenedCall { .. } => {
                state.body.push(value);
            }
            rootlight_ir::FSharpBinding::Open { .. }
            | rootlight_ir::FSharpBinding::ImportContext { .. } => {
                let source = envelope
                    .evidence
                    .source
                    .as_ref()
                    .ok_or(FirstSliceError::Identity)?;
                state.imports.push(semantic_value_fingerprint(
                    b"fsharp-import-context",
                    &(value, source.content_hash()),
                )?);
            }
            rootlight_ir::FSharpBinding::Project { .. } => {
                let source = envelope
                    .evidence
                    .source
                    .as_ref()
                    .ok_or(FirstSliceError::Identity)?;
                state.imports.push(semantic_value_fingerprint(
                    b"fsharp-project",
                    &(value, source.content_hash()),
                )?);
            }
        }
    }

    let expected = by_file
        .len()
        .checked_mul(3)
        .ok_or(FirstSliceError::Limits)?;
    let mut inputs = Vec::new();
    inputs
        .try_reserve_exact(expected)
        .map_err(|_| FirstSliceError::Limits)?;
    for (file, state) in by_file {
        check_cancellation(cancellation)?;
        let unit = file_analysis_unit(file);
        inputs.extend([
            InputFingerprint::new(
                InputKey::PublicSurface(unit),
                aggregate_semantic_fingerprint(b"public-surface", state.public_surface)?,
            ),
            InputFingerprint::new(
                InputKey::BodySummary(unit),
                aggregate_semantic_fingerprint(b"body", state.body)?,
            ),
            InputFingerprint::new(
                InputKey::ImportSet(unit),
                aggregate_semantic_fingerprint(b"imports", state.imports)?,
            ),
        ]);
    }
    Ok(inputs)
}

fn incremental_input_keys(
    parent: &InputSnapshot,
    current: &InputSnapshot,
    cancellation: &Cancellation,
) -> Result<BTreeSet<InputKey>, FirstSliceError> {
    let mut keys = BTreeSet::new();
    for input in parent.iter().chain(current.iter()) {
        check_cancellation(cancellation)?;
        keys.insert(input.key());
    }
    Ok(keys)
}

fn incremental_file_ids(
    inputs: &BTreeSet<InputKey>,
    cancellation: &Cancellation,
) -> Result<BTreeSet<FileId>, FirstSliceError> {
    let mut files = BTreeSet::new();
    for input in inputs {
        check_cancellation(cancellation)?;
        match input {
            InputKey::FileContent(file)
            | InputKey::FilePath(file)
            | InputKey::FileParserRoute(file) => {
                files.insert(*file);
            }
            _ => {}
        }
    }
    Ok(files)
}

fn first_slice_dependency_parts(
    repository: RepositoryId,
    files: &BTreeSet<FileId>,
    inputs: &BTreeSet<InputKey>,
    passes: &FirstSlicePasses,
    cancellation: &Cancellation,
) -> Result<(Vec<FactNode>, Vec<DependencyEdge>), FirstSliceError> {
    let repository_unit =
        AnalysisUnitId::new(derive_fact(INCREMENTAL_UNIT_SEED, repository.as_bytes()).id());
    let resolution = FactNode::new(repository_unit, FactDomain::Resolution);
    let derived = FactNode::new(repository_unit, FactDomain::DerivedGraph);
    let search = FactNode::new(repository_unit, FactDomain::Search);
    let mut nodes = vec![resolution, derived, search];
    let mut edges = Vec::new();
    for file in files {
        check_cancellation(cancellation)?;
        let unit = file_analysis_unit(*file);
        let syntax = FactNode::new(unit, FactDomain::Syntax);
        nodes.push(syntax);
        for domain in local_semantic_domains().iter() {
            let target = FactNode::new(unit, domain);
            nodes.push(target);
            edges.push(DependencyEdge::new(
                DependencySource::Fact(syntax),
                target,
                passes.lowering.clone(),
            ));
        }
    }
    edges.push(DependencyEdge::new(
        DependencySource::Fact(resolution),
        derived,
        passes.derived.clone(),
    ));
    edges.push(DependencyEdge::new(
        DependencySource::Fact(resolution),
        search,
        passes.search.clone(),
    ));

    for input in inputs {
        check_cancellation(cancellation)?;
        match *input {
            InputKey::FileContent(file)
            | InputKey::FilePath(file)
            | InputKey::FileParserRoute(file) => {
                add_file_input_edges(*input, file, passes, &mut edges);
            }
            InputKey::GrammarVersion(_) | InputKey::AdapterVersion(_) => {
                add_all_file_parser_edges(*input, files, passes, &mut edges);
                if matches!(input, InputKey::AdapterVersion(_)) {
                    add_all_file_lowering_edges(*input, files, passes, &mut edges);
                }
            }
            InputKey::CompilerOptions(_) => {
                add_all_file_lowering_edges(*input, files, passes, &mut edges);
                edges.push(DependencyEdge::new(
                    DependencySource::Input(*input),
                    resolution,
                    passes.resolver.clone(),
                ));
            }
            InputKey::ConfigurationRevision => {
                add_all_file_parser_edges(*input, files, passes, &mut edges);
                add_all_file_lowering_edges(*input, files, passes, &mut edges);
                for (target, pass) in [
                    (resolution, passes.resolver.clone()),
                    (derived, passes.derived.clone()),
                    (search, passes.search.clone()),
                ] {
                    edges.push(DependencyEdge::new(
                        DependencySource::Input(*input),
                        target,
                        pass,
                    ));
                }
            }
            InputKey::PublicSurface(_) | InputKey::BodySummary(_) => {
                edges.push(DependencyEdge::new(
                    DependencySource::Input(*input),
                    resolution,
                    passes.resolver.clone(),
                ));
                edges.push(DependencyEdge::new(
                    DependencySource::Input(*input),
                    search,
                    passes.search.clone(),
                ));
            }
            InputKey::ImportSet(_)
            | InputKey::BuildTarget(_)
            | InputKey::DependencyVersion(_)
            | InputKey::ResolverVersion => {
                edges.push(DependencyEdge::new(
                    DependencySource::Input(*input),
                    resolution,
                    passes.resolver.clone(),
                ));
            }
            InputKey::SearchRevision => {
                edges.push(DependencyEdge::new(
                    DependencySource::Input(*input),
                    search,
                    passes.search.clone(),
                ));
            }
            InputKey::DerivedPlan(_) => {
                edges.push(DependencyEdge::new(
                    DependencySource::Input(*input),
                    derived,
                    passes.derived.clone(),
                ));
            }
        }
    }
    Ok((nodes, edges))
}

fn add_file_input_edges(
    input: InputKey,
    file: FileId,
    passes: &FirstSlicePasses,
    edges: &mut Vec<DependencyEdge>,
) {
    let unit = file_analysis_unit(file);
    edges.push(DependencyEdge::new(
        DependencySource::Input(input),
        FactNode::new(unit, FactDomain::Syntax),
        passes.parser.clone(),
    ));
    for domain in local_semantic_domains().iter() {
        edges.push(DependencyEdge::new(
            DependencySource::Input(input),
            FactNode::new(unit, domain),
            passes.lowering.clone(),
        ));
    }
}

fn add_all_file_parser_edges(
    input: InputKey,
    files: &BTreeSet<FileId>,
    passes: &FirstSlicePasses,
    edges: &mut Vec<DependencyEdge>,
) {
    for file in files {
        edges.push(DependencyEdge::new(
            DependencySource::Input(input),
            FactNode::new(file_analysis_unit(*file), FactDomain::Syntax),
            passes.parser.clone(),
        ));
    }
}

fn add_all_file_lowering_edges(
    input: InputKey,
    files: &BTreeSet<FileId>,
    passes: &FirstSlicePasses,
    edges: &mut Vec<DependencyEdge>,
) {
    for file in files {
        let unit = file_analysis_unit(*file);
        for domain in local_semantic_domains().iter() {
            edges.push(DependencyEdge::new(
                DependencySource::Input(input),
                FactNode::new(unit, domain),
                passes.lowering.clone(),
            ));
        }
    }
}

fn parent_artifact_summaries(
    inputs: &InputSnapshot,
    artifacts: Option<&StructuralGenerationArtifacts>,
    limits: PlanningLimits,
    cancellation: &Cancellation,
) -> Result<Vec<ArtifactSummary>, FirstSliceError> {
    let Some(artifacts) = artifacts else {
        return Ok(Vec::new());
    };
    let mut summaries = Vec::new();
    summaries
        .try_reserve_exact(artifacts.len())
        .map_err(|_| FirstSliceError::Retention)?;
    for (file, entry) in artifacts.iter() {
        check_cancellation(cancellation)?;
        let dependencies: Vec<_> = inputs
            .iter()
            .filter(|input| parser_artifact_depends_on(input.key(), *file))
            .collect();
        if !dependencies
            .iter()
            .any(|input| input.key() == InputKey::FileContent(*file))
            || !dependencies
                .iter()
                .any(|input| input.key() == InputKey::FilePath(*file))
        {
            return Err(FirstSliceError::Incremental);
        }
        summaries.push(
            ArtifactSummary::new(
                entry.id,
                [FactNode::new(file_analysis_unit(*file), FactDomain::Syntax)],
                dependencies,
                limits,
                cancellation,
            )
            .map_err(|error| map_incremental_error(error, cancellation))?,
        );
    }
    Ok(summaries)
}

fn parser_artifact_depends_on(key: InputKey, file: FileId) -> bool {
    match key {
        InputKey::FileContent(candidate)
        | InputKey::FilePath(candidate)
        | InputKey::FileParserRoute(candidate) => candidate == file,
        InputKey::GrammarVersion(_)
        | InputKey::AdapterVersion(_)
        | InputKey::ConfigurationRevision => true,
        _ => false,
    }
}

fn file_analysis_unit(file: FileId) -> AnalysisUnitId {
    AnalysisUnitId::new(derive_fact(INCREMENTAL_FILE_UNIT_SEED, file.as_bytes()).id())
}

fn parser_artifact_id(file: FileId) -> ArtifactId {
    ArtifactId::new(derive_fact(PARSER_ARTIFACT_SEED, file.as_bytes()).id())
}

fn first_slice_parser_provider_hash() -> Result<ContentHash, FirstSliceError> {
    let grammar_revision = first_slice_grammar_revision_hash()?;
    hash_static_components(&[
        PARSER_PROVIDER_SET_SEED,
        TREE_SITTER_ADAPTER_VERSION.as_bytes(),
        TREE_SITTER_RUNTIME_VERSION.as_bytes(),
        ANALYZER_BINARY_SEED,
        grammar_revision.as_bytes(),
    ])
}

fn first_slice_grammar_revision_hash() -> Result<ContentHash, FirstSliceError> {
    let registry = GrammarRegistry::audited().map_err(|_| FirstSliceError::Adapter)?;
    let mut hasher = blake3::Hasher::new();
    hash_component(&mut hasher, GRAMMAR_REVISION_SEED)?;
    hash_component(&mut hasher, TREE_SITTER_RUNTIME_VERSION.as_bytes())?;
    for descriptor in registry.descriptors() {
        hash_component(&mut hasher, descriptor.language().as_str().as_bytes())?;
        hash_component(&mut hasher, descriptor.grammar_version().as_bytes())?;
        hash_component(&mut hasher, descriptor.grammar_source_sha256().as_bytes())?;
        hash_component(&mut hasher, descriptor.parser_sha256().as_bytes())?;
        match descriptor.scanner_sha256() {
            Some(scanner) => {
                hash_component(&mut hasher, b"scanner")?;
                hash_component(&mut hasher, scanner.as_bytes())?;
            }
            None => hash_component(&mut hasher, b"no-scanner")?,
        }
        hash_component(
            &mut hasher,
            &u64::try_from(descriptor.abi_version())
                .map_err(|_| FirstSliceError::Limits)?
                .to_be_bytes(),
        )?;
    }
    Ok(ContentHash::from_bytes(*hasher.finalize().as_bytes()))
}

fn grammar_binary_digest(descriptor: &GrammarDescriptor) -> Result<ContentHash, FirstSliceError> {
    let scanner = descriptor.scanner_sha256().unwrap_or("no-scanner");
    hash_static_components(&[
        ANALYZER_BINARY_SEED,
        descriptor.language().as_str().as_bytes(),
        descriptor.grammar_version().as_bytes(),
        descriptor.grammar_source_sha256().as_bytes(),
        descriptor.parser_sha256().as_bytes(),
        scanner.as_bytes(),
    ])
}

fn first_slice_provider_set_hash() -> Result<ContentHash, FirstSliceError> {
    let parser = first_slice_parser_provider_hash()?;
    hash_static_components(&[
        PROVIDER_SET_SEED,
        parser.as_bytes(),
        DISCOVERY_MANIFEST_VERSION.as_bytes(),
        RESOLVER_PROVIDER_VERSION.as_bytes(),
        RESOLVER_BINARY_SEED,
        SEARCH_REVISION_SEED,
        INCREMENTAL_SCHEMA_VERSION.as_bytes(),
        DERIVED_PLAN_REVISION_SEED,
        LANGUAGE_DISPOSITION_PROVIDER_SEED,
        SOURCE_FILE_FALLBACK_PROVIDER_SEED,
        container_sources::REVISION,
    ])
}

fn first_slice_incremental_plan_hash() -> Result<ContentHash, FirstSliceError> {
    hash_static_components(&[
        DERIVED_PLAN_REVISION_SEED,
        INCREMENTAL_SCHEMA_VERSION.as_bytes(),
    ])
}

fn first_slice_build_context() -> ContentHash {
    content_hash(BUILD_CONTEXT_SEED)
}

fn hash_static_components(components: &[&[u8]]) -> Result<ContentHash, FirstSliceError> {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rootlight.first-slice.static-components/1\0");
    for component in components {
        hash_component(&mut hasher, component)?;
    }
    Ok(ContentHash::from_bytes(*hasher.finalize().as_bytes()))
}

fn hash_component(hasher: &mut blake3::Hasher, component: &[u8]) -> Result<(), FirstSliceError> {
    let length = u64::try_from(component.len()).map_err(|_| FirstSliceError::Limits)?;
    hasher.update(&length.to_be_bytes());
    hasher.update(component);
    Ok(())
}

fn summarize_incremental_evidence(
    has_parent: bool,
    reuse_policy: FirstSliceReusePolicy,
    discovery: &IncrementalDiscovery,
    source_files: &BTreeSet<FileId>,
    plan: &InvalidationPlan,
) -> Result<FirstSliceIncrementalEvidence, FirstSliceError> {
    let mut input_counts = BTreeMap::new();
    for change in plan.changes().changes() {
        increment_evidence_count(&mut input_counts, change.class())?;
    }
    let input_changes = input_counts
        .into_iter()
        .map(|(class, inputs)| FirstSliceInputChangeCount { class, inputs })
        .collect();

    let mut file_counts = BTreeMap::new();
    for change in discovery.file_changes() {
        increment_evidence_count(&mut file_counts, change.kind())?;
    }
    let file_changes = file_counts
        .into_iter()
        .map(|(kind, files)| FirstSliceFileChangeCount { kind, files })
        .collect();

    let fallback_reason = if reuse_policy == FirstSliceReusePolicy::Incremental && has_parent {
        plan.fallback().map(|fallback| fallback.reason())
    } else {
        None
    };
    let strategy = if reuse_policy == FirstSliceReusePolicy::CleanRebuild {
        FirstSliceBuildStrategy::CleanRebuild
    } else if !has_parent {
        FirstSliceBuildStrategy::Initial
    } else if fallback_reason.is_some() {
        FirstSliceBuildStrategy::ConservativeRepositoryRebuild
    } else {
        FirstSliceBuildStrategy::DependencyDirected
    };
    Ok(FirstSliceIncrementalEvidence {
        strategy,
        input_changes,
        file_changes,
        hashed_files: u64::try_from(discovery.hashed_files().len())
            .map_err(|_| FirstSliceError::Limits)?,
        invalidated_domains: plan.rerun_domains().iter().collect(),
        invalidated_units: u64::try_from(plan.reanalyze().count())
            .map_err(|_| FirstSliceError::Limits)?,
        fallback_reason,
        trace_entries: u64::try_from(plan.trace().entries().len())
            .map_err(|_| FirstSliceError::Limits)?,
        invalidation_trace: plan.trace().entries().to_vec(),
        parsed_files: 0,
        reused_parser_artifacts: 0,
        reused_parser_artifact_bytes: 0,
        reused_durable_artifact_bytes: 0,
        lowered_files: 0,
        reused_normalized_facts: 0,
        rebuilt_normalized_facts: 0,
        planned_fact_work: planned_fact_work(has_parent, reuse_policy, source_files, plan)?,
        normalized_fact_work: Vec::new(),
        structural_cache_retained: false,
    })
}

fn planned_fact_work(
    has_parent: bool,
    reuse_policy: FirstSliceReusePolicy,
    source_files: &BTreeSet<FileId>,
    plan: &InvalidationPlan,
) -> Result<Vec<FirstSlicePlannedFactWork>, FirstSliceError> {
    let units_to_files = source_files
        .iter()
        .copied()
        .map(|file| (file_analysis_unit(file), file))
        .collect::<BTreeMap<_, _>>();
    let rebuild_cause = if reuse_policy == FirstSliceReusePolicy::CleanRebuild {
        FirstSliceFactWorkCause::UserRequestedCleanRebuild
    } else if !has_parent {
        FirstSliceFactWorkCause::InitialGeneration
    } else if plan.fallback().is_some() {
        FirstSliceFactWorkCause::ConservativeFallback
    } else {
        FirstSliceFactWorkCause::DependencyClosure
    };
    let mut groups = BTreeMap::<
        (
            FirstSliceFactWorkDisposition,
            FactDomain,
            String,
            FirstSliceFactWorkCause,
        ),
        (BTreeSet<AnalysisUnitId>, BTreeSet<FileId>),
    >::new();
    let reusable_disposition = if reuse_policy == FirstSliceReusePolicy::CleanRebuild {
        FirstSliceFactWorkDisposition::Rebuild
    } else {
        FirstSliceFactWorkDisposition::Reuse
    };
    let reusable_cause = if reuse_policy == FirstSliceReusePolicy::CleanRebuild {
        FirstSliceFactWorkCause::UserRequestedCleanRebuild
    } else {
        FirstSliceFactWorkCause::CompleteDependencyMatch
    };
    for (disposition, cause, nodes) in [
        (
            FirstSliceFactWorkDisposition::Rebuild,
            rebuild_cause,
            plan.invalidated_nodes().collect::<Vec<_>>(),
        ),
        (
            reusable_disposition,
            reusable_cause,
            plan.reusable_nodes().collect::<Vec<_>>(),
        ),
    ] {
        for node in nodes {
            let group = groups
                .entry((
                    disposition,
                    node.domain(),
                    incremental_pass_for_domain(node.domain()).to_owned(),
                    cause,
                ))
                .or_default();
            group.0.insert(node.unit());
            if let Some(file) = units_to_files.get(&node.unit()) {
                group.1.insert(*file);
            }
        }
    }
    groups
        .into_iter()
        .map(
            |((disposition, domain, provider_pass, cause), (units, files))| {
                Ok(FirstSlicePlannedFactWork {
                    disposition,
                    domain,
                    provider_pass,
                    cause,
                    files: u64::try_from(files.len()).map_err(|_| FirstSliceError::Limits)?,
                    analysis_units: u64::try_from(units.len())
                        .map_err(|_| FirstSliceError::Limits)?,
                    file_ids: files,
                    analysis_unit_ids: units,
                })
            },
        )
        .collect()
}

fn incremental_pass_for_domain(domain: FactDomain) -> &'static str {
    match domain {
        FactDomain::Syntax => PARSER_PASS_ID,
        FactDomain::PublicSurface | FactDomain::Body | FactDomain::Tests | FactDomain::Services => {
            LOWERING_PASS_ID
        }
        FactDomain::Resolution => RESOLVER_PASS_ID,
        FactDomain::Search => SEARCH_PASS_ID,
        FactDomain::DerivedGraph | FactDomain::History => DERIVED_PASS_ID,
    }
}

fn increment_evidence_count<Key: Ord>(
    counts: &mut BTreeMap<Key, u64>,
    key: Key,
) -> Result<(), FirstSliceError> {
    let count = counts.entry(key).or_insert(0);
    *count = count.checked_add(1).ok_or(FirstSliceError::Limits)?;
    Ok(())
}

fn supported_source_language<'a>(
    input: &'a ManifestInput,
    analyzers: &BTreeMap<String, TreeSitterAnalyzer>,
) -> Option<&'a str> {
    let language = source_language_route(input, analyzers)?;
    let encoding = EncodingId::new(&input.encoding).ok()?;
    analyzers
        .get(language)?
        .supports_encoding(&encoding)
        .then_some(language)
}

fn source_language_route<'a>(
    input: &'a ManifestInput,
    analyzers: &BTreeMap<String, TreeSitterAnalyzer>,
) -> Option<&'a str> {
    if input
        .language_signals
        .iter()
        .any(|signal| signal.evidence == LanguageEvidence::Configuration)
    {
        if Path::new(&input.path)
            .extension()
            .and_then(|extension| extension.to_str())
            .is_some_and(|extension| extension.eq_ignore_ascii_case("mlx"))
        {
            return None;
        }
        let language = detected_source_language(input)?;
        return analyzers.contains_key(language).then_some(language);
    }
    // Static template text can contain a complete host document or reader header.
    if source_language_from_path(&input.path) == Some("liquid") {
        return analyzers.contains_key("liquid").then_some("liquid");
    }
    if has_haxe_language_conflict(input) || has_qml_shebang_conflict(input) {
        return None;
    }
    if has_json_schema_content_signal(input) {
        let language = json_schema_content_language(input)?;
        return analyzers.contains_key(language).then_some(language);
    }
    if is_shared_modelica_source(&input.path) {
        let language = modelica_content_language(input)?;
        return analyzers.contains_key(language).then_some(language);
    }
    if has_racket_reader_signal(input) {
        let language = racket_reader_content_language(input)?;
        return analyzers.contains_key(language).then_some(language);
    }
    if is_ambiguous_basic_source(&input.path) {
        let language = shared_classic_source_language(input)?;
        return analyzers.contains_key(language).then_some(language);
    }
    if is_shared_v_source(&input.path) {
        let language = shared_v_source_language(input)?;
        return analyzers.contains_key(language).then_some(language);
    }
    if is_shared_v_script(&input.path) {
        let language = v_script_source_language(input)?;
        return analyzers.contains_key(language).then_some(language);
    }
    if is_shared_fsharp_source(&input.path) {
        let language = fsharp_source_language(input)?;
        return analyzers.contains_key(language).then_some(language);
    }
    if is_ambiguous_perl_prolog_source(&input.path) && prolog_content_language(input).is_some() {
        let language = detected_source_language(input)?;
        return analyzers.contains_key(language).then_some(language);
    }
    // Live scripts are containers, not MATLAB text. A native .m grammar does
    // not provide the container reader required to analyze their embedded source.
    if Path::new(&input.path)
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("mlx"))
    {
        return None;
    }
    if let Some(language) = source_language_from_path(&input.path) {
        // A known source format must not fall through to another parser merely
        // because its contents include a shebang or embedded language signal.
        return analyzers.contains_key(language).then_some(language);
    }
    // A header's C-family evidence can override its C extension default.
    // An unsupported C-family language must retain source evidence, not enter the C parser.
    if let Some(language) = c_header_content_language(input) {
        return analyzers.contains_key(language).then_some(language);
    }
    // `.m` also denotes MATLAB. Parser admission must honor the same content
    // evidence as source provenance, even when the detected parser is absent.
    if extension_language(&input.path) == Some("objective-c") {
        let language = detected_source_language(input)?;
        return analyzers.contains_key(language).then_some(language);
    }
    if input
        .language_signals
        .iter()
        .any(|signal| signal.language == "thinkscript")
    {
        let language = thinkscript_content_language(input)?;
        return analyzers.contains_key(language).then_some(language);
    }
    for evidence in [
        LanguageEvidence::Filename,
        LanguageEvidence::Extension,
        LanguageEvidence::Shebang,
    ] {
        if let Some(language) = unique_supported_language(input, analyzers, evidence) {
            return Some(language);
        }
    }
    None
}

fn unique_supported_language<'a>(
    input: &'a ManifestInput,
    analyzers: &BTreeMap<String, TreeSitterAnalyzer>,
    evidence: LanguageEvidence,
) -> Option<&'a str> {
    let mut matched = input
        .language_signals
        .iter()
        .filter(|signal| signal.evidence == evidence)
        .filter(|signal| analyzers.contains_key(signal.language.as_str()));
    let language = matched.next()?;
    if matched.any(|candidate| candidate.language != language.language) {
        return None;
    }
    Some(language.language.as_str())
}

fn is_ambiguous_c_header(path: &str) -> bool {
    Path::new(path)
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("h"))
}

fn has_json_schema_content_signal(input: &ManifestInput) -> bool {
    input.language_signals.iter().any(|signal| {
        signal.language == "json-schema" && signal.evidence == LanguageEvidence::Content
    })
}

fn json_schema_content_language(input: &ManifestInput) -> Option<&str> {
    let written = input.language_signals.iter().find(|signal| {
        signal.language == "json-schema" && signal.evidence == LanguageEvidence::Content
    })?;
    (!input.language_signals.iter().any(|signal| {
        matches!(
            signal.evidence,
            LanguageEvidence::Content | LanguageEvidence::Shebang
        ) && signal.language != written.language
    }))
    .then_some(written.language.as_str())
}

fn thinkscript_content_language(input: &ManifestInput) -> Option<&str> {
    if !Path::new(&input.path)
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("txt"))
    {
        return None;
    }
    let written = input.language_signals.iter().find(|signal| {
        signal.language == "thinkscript" && signal.evidence == LanguageEvidence::Content
    })?;
    input
        .language_signals
        .iter()
        .all(|signal| {
            signal.language == written.language && signal.evidence == LanguageEvidence::Content
        })
        .then_some(written.language.as_str())
}

fn has_haxe_language_conflict(input: &ManifestInput) -> bool {
    rootlight_discovery::extension_language(&input.path) == Some("haxe")
        && input.language_signals.iter().any(|signal| {
            matches!(
                signal.evidence,
                LanguageEvidence::Shebang | LanguageEvidence::Content
            ) && signal.language != "haxe"
        })
}

fn has_qml_shebang_conflict(input: &ManifestInput) -> bool {
    rootlight_discovery::extension_language(&input.path) == Some("qml")
        && input
            .language_signals
            .iter()
            .any(|signal| signal.evidence == LanguageEvidence::Shebang && signal.language != "qml")
}

fn is_shared_modelica_source(path: &str) -> bool {
    Path::new(path)
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("mo"))
}

fn modelica_content_language(input: &ManifestInput) -> Option<&str> {
    let written = input.language_signals.iter().find(|signal| {
        signal.evidence == LanguageEvidence::Content && signal.language == "modelica"
    })?;
    // `.mo` is shared with other formats. Neither its suffix nor the set of
    // installed analyzers can settle missing or conflicting source evidence.
    (!input.language_signals.iter().any(|signal| {
        matches!(
            signal.evidence,
            LanguageEvidence::Content | LanguageEvidence::Shebang
        ) && signal.language != written.language
    }))
    .then_some(written.language.as_str())
}

fn c_header_content_language(input: &ManifestInput) -> Option<&str> {
    if !is_ambiguous_c_header(&input.path) {
        return None;
    }
    let mut languages = input.language_signals.iter().filter(|signal| {
        signal.evidence == LanguageEvidence::Content
            && matches!(
                signal.language.as_str(),
                "c" | "cpp" | "objective-c" | "objective-cpp"
            )
    });
    let language = languages.next()?;
    if languages.any(|other| other.language != language.language) {
        return None;
    }
    Some(language.language.as_str())
}

fn detected_source_language(input: &ManifestInput) -> Option<&str> {
    let mut configured = input
        .language_signals
        .iter()
        .filter(|signal| signal.evidence == LanguageEvidence::Configuration);
    if let Some(language) = configured.next() {
        return (!configured.any(|other| other.language != language.language))
            .then_some(language.language.as_str());
    }
    // The outer template format precedes content hints; configuration stays first.
    if source_language_from_path(&input.path) == Some("liquid") {
        return Some("liquid");
    }
    if has_haxe_language_conflict(input) || has_qml_shebang_conflict(input) {
        return None;
    }
    if has_json_schema_content_signal(input) {
        return json_schema_content_language(input);
    }
    if is_shared_modelica_source(&input.path) {
        return modelica_content_language(input);
    }
    if has_racket_reader_signal(input) {
        return racket_reader_content_language(input);
    }
    if is_ambiguous_basic_source(&input.path) {
        return shared_classic_source_language(input);
    }
    if is_shared_v_source(&input.path) {
        return shared_v_source_language(input);
    }
    if is_shared_v_script(&input.path) {
        return v_script_source_language(input);
    }
    if is_shared_fsharp_source(&input.path) {
        return fsharp_source_language(input);
    }
    if is_ambiguous_perl_prolog_source(&input.path)
        && let Some(language) = prolog_content_language(input)
    {
        return Some(language);
    }
    if let Some(language) = source_language_from_path(&input.path) {
        return Some(language);
    }
    if let Some(language) = c_header_content_language(input) {
        return Some(language);
    }
    // `.m` is shared by Objective-C and MATLAB, so explicit content and
    // unanimous peer context resolve it before the fallback extension claim.
    // Manifest signals describe the toolchain, never the manifest's own syntax.
    let evidence_order = if extension_language(&input.path) == Some("objective-c") {
        [
            LanguageEvidence::Filename,
            LanguageEvidence::Content,
            LanguageEvidence::Context,
            LanguageEvidence::Extension,
            LanguageEvidence::Shebang,
        ]
    } else {
        [
            LanguageEvidence::Filename,
            LanguageEvidence::Extension,
            LanguageEvidence::Shebang,
            LanguageEvidence::Content,
            LanguageEvidence::Context,
        ]
    };
    for evidence in evidence_order {
        let mut matched = input
            .language_signals
            .iter()
            .filter(|signal| signal.evidence == evidence);
        if let Some(language) = matched.next() {
            if matched.any(|candidate| candidate.language != language.language) {
                return None;
            }
            return Some(language.language.as_str());
        }
    }
    None
}

fn has_racket_reader_signal(input: &ManifestInput) -> bool {
    input
        .language_signals
        .iter()
        .any(|signal| signal.evidence == LanguageEvidence::Content && signal.language == "racket")
}

fn racket_reader_content_language(input: &ManifestInput) -> Option<&str> {
    // A verified reader declaration owns its syntax; keep conflicting evidence
    // unresolved instead of picking whichever installed parser happens to exist.
    (!input.language_signals.iter().any(|signal| {
        matches!(
            signal.evidence,
            LanguageEvidence::Content | LanguageEvidence::Shebang
        ) && signal.language != "racket"
    }))
    .then_some("racket")
}

fn source_language_from_path(path: &str) -> Option<&'static str> {
    if is_ambiguous_c_header(path) {
        return None;
    }
    filename_language(path).or_else(|| {
        // Discovery fences Tree-sitter queries from Scheme extension evidence.
        // A path-only fallback must not bypass that content decision.
        extension_language(path).filter(|language| !matches!(*language, "objective-c" | "scheme"))
    })
}

fn shared_classic_source_language(input: &ManifestInput) -> Option<&str> {
    let class_suffix = Path::new(&input.path)
        .extension()
        .and_then(|suffix| suffix.to_str())
        .is_some_and(|suffix| suffix.eq_ignore_ascii_case("cls"));
    // Only .cls shares the Apex format. .bas/.frm remain classic exports;
    // neither extension fallback nor analyzer availability resolves a conflict.
    let mut matched = input.language_signals.iter().filter(|signal| {
        signal.evidence == LanguageEvidence::Content
            && (matches!(signal.language.as_str(), "vba" | "visual-basic-classic")
                || (class_suffix && signal.language == "apex"))
    });
    let language = matched.next()?;
    (!matched.any(|other| other.language != language.language))
        .then_some(language.language.as_str())
}

fn prolog_content_language(input: &ManifestInput) -> Option<&str> {
    input.language_signals.iter().find_map(|signal| {
        (signal.evidence == LanguageEvidence::Content && signal.language == "prolog")
            .then_some(signal.language.as_str())
    })
}

fn is_shared_v_source(path: &str) -> bool {
    Path::new(path)
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("v"))
}

fn is_shared_v_script(path: &str) -> bool {
    Path::new(path)
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("vsh"))
}

fn v_script_source_language(input: &ManifestInput) -> Option<&str> {
    let written = || {
        input.language_signals.iter().filter(|signal| {
            matches!(
                signal.evidence,
                LanguageEvidence::Content | LanguageEvidence::Shebang
            )
        })
    };
    if written().any(|signal| signal.language == "v") {
        return written()
            .all(|signal| signal.language == "v")
            .then_some("v");
    }
    Some("glsl")
}

fn shared_v_source_language(input: &ManifestInput) -> Option<&str> {
    // Verilog, V and Coq share .v. Neither an extension default nor the set of
    // installed analyzers can substitute for unambiguous source evidence.
    let mut content = input
        .language_signals
        .iter()
        .filter(|signal| signal.evidence == LanguageEvidence::Content);
    let language = content.next()?;
    (matches!(
        language.language.as_str(),
        "verilog" | "systemverilog" | "v" | "coq"
    ) && !content.any(|other| other.language != language.language))
    .then_some(language.language.as_str())
}

fn is_shared_fsharp_source(path: &str) -> bool {
    Path::new(path)
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("fs"))
}

fn fsharp_content_language(input: &ManifestInput) -> Option<&str> {
    let mut content = input
        .language_signals
        .iter()
        .filter(|signal| signal.evidence == LanguageEvidence::Content);
    let language = content.next()?;
    if language.language != "fsharp"
        || content.any(|other| other.language != language.language)
        || input.language_signals.iter().any(|signal| {
            matches!(
                signal.evidence,
                LanguageEvidence::Extension
                    | LanguageEvidence::Filename
                    | LanguageEvidence::Shebang
            ) && signal.language != language.language
        })
    {
        return None;
    }
    Some(language.language.as_str())
}

fn fsharp_source_language(input: &ManifestInput) -> Option<&str> {
    if input
        .language_signals
        .iter()
        .any(|signal| signal.evidence == LanguageEvidence::Content)
    {
        // Project declarations cannot override contradictory source syntax.
        return fsharp_content_language(input);
    }
    let mut projects = input
        .language_signals
        .iter()
        .filter(|signal| signal.evidence == LanguageEvidence::Project);
    let language = projects.next()?;
    if language.language != "fsharp"
        || projects.any(|other| other.language != language.language)
        || input.project_language_witnesses.is_empty()
        || input.project_language_witnesses.iter().any(|witness| {
            witness.language != language.language
                || witness.project_file == input.file
                || !Path::new(&witness.project_path)
                    .extension()
                    .and_then(|extension| extension.to_str())
                    .is_some_and(|extension| extension.eq_ignore_ascii_case("fsproj"))
                || !RelativePath::parse(Path::new(&witness.project_path))
                    .is_ok_and(|path| path.as_str() == witness.project_path)
        })
        || input.language_signals.iter().any(|signal| {
            matches!(
                signal.evidence,
                LanguageEvidence::Extension
                    | LanguageEvidence::Filename
                    | LanguageEvidence::Shebang
            ) && signal.language != language.language
        })
    {
        return None;
    }
    Some(language.language.as_str())
}

fn prepared_file_parser_route_hash(
    input: &ManifestInput,
    language: Option<&str>,
    admission: &NativeFSharpAdmission,
) -> Result<Option<ContentHash>, FirstSliceError> {
    let route = file_parser_route_hash(input, language)?;
    let state: &[u8] = match admission {
        NativeFSharpAdmission::NotAttempted => return Ok(route),
        NativeFSharpAdmission::NoEvidence => b"no-evidence",
        NativeFSharpAdmission::Accepted { .. } => b"accepted",
        NativeFSharpAdmission::ResourceBounded => b"resource-bounded",
        NativeFSharpAdmission::InvalidEncoding => b"invalid-encoding",
    };
    let route = route.ok_or(FirstSliceError::Identity)?;
    let mut hasher = blake3::Hasher::new();
    hash_component(&mut hasher, b"rootlight.file-parser-route/native-fsharp/1")?;
    hash_component(&mut hasher, route.as_bytes())?;
    hash_component(&mut hasher, state)?;
    if let NativeFSharpAdmission::Accepted {
        declaration,
        sample,
    } = admission
    {
        // Content identity is already a file input. Keep generation out of the
        // route key so an unchanged witness remains reusable across generations.
        hash_component(&mut hasher, &declaration.start_byte().to_le_bytes())?;
        hash_component(&mut hasher, &declaration.end_byte().to_le_bytes())?;
        hash_component(&mut hasher, &sample.end_byte().to_le_bytes())?;
    }
    Ok(Some(ContentHash::from_bytes(*hasher.finalize().as_bytes())))
}

fn file_parser_route_hash(
    input: &ManifestInput,
    language: Option<&str>,
) -> Result<Option<ContentHash>, FirstSliceError> {
    if input.path.rsplit_once('.').is_some_and(|(_, suffix)| {
        suffix.eq_ignore_ascii_case("m")
            || suffix.eq_ignore_ascii_case("v")
            || suffix.eq_ignore_ascii_case("vsh")
    }) {
        return language
            .map(|language| {
                hash_static_components(&[b"rootlight.file-parser-route/1", language.as_bytes()])
            })
            .transpose();
    }
    if !is_shared_fsharp_source(&input.path) {
        return Ok(None);
    }
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"rootlight.first-slice.static-components/1\0");
    hash_component(
        &mut hasher,
        b"rootlight.file-parser-route/project-language/1",
    )?;
    hash_component(&mut hasher, language.unwrap_or("unknown").as_bytes())?;
    let independent = input.language_signals.iter().any(|signal| {
        matches!(
            signal.evidence,
            LanguageEvidence::Configuration | LanguageEvidence::Content
        )
    });
    hash_component(
        &mut hasher,
        if independent {
            b"independent"
        } else {
            b"project"
        },
    )?;
    if !independent {
        // Discovery attests complete local declaration bytes and canonicalizes
        // witnesses. Bind only member-specific evidence, never a global project hash.
        for witness in &input.project_language_witnesses {
            hash_component(&mut hasher, witness.language.as_bytes())?;
            hash_component(&mut hasher, witness.project_file.as_bytes())?;
            hash_component(&mut hasher, witness.project_path.as_bytes())?;
            hash_component(&mut hasher, witness.project_content_hash.as_bytes())?;
        }
    }
    Ok(Some(ContentHash::from_bytes(*hasher.finalize().as_bytes())))
}

fn analysis_tier_for_language(language: &str) -> AnalysisTier {
    if language == "rust" {
        AnalysisTier::TierB
    } else {
        AnalysisTier::TierD
    }
}

fn unsupported_source_document(
    repository: RepositoryId,
    generation: GenerationId,
    input: &UnsupportedSourceInput,
) -> Result<NormalizedIrDocument, FirstSliceError> {
    let (code, message, reason) = match input.disposition {
        UnsupportedSourceDisposition::Language => (
            "unsupported-language",
            "source language has no configured analyzer",
            SkippedRegionReason::UnsupportedConstruct,
        ),
        UnsupportedSourceDisposition::Encoding => (
            "unsupported-encoding",
            if input.encoding == "binary" {
                "container bytes have no direct structural analyzer and derived source coverage is reported separately"
            } else if input.encoding == "bytes" {
                "raw source bytes remain readable but unsupported text encoding prevents structural analysis and lexical vocabulary projection and literal text matching"
            } else {
                "source encoding has no configured structural analyzer"
            },
            SkippedRegionReason::UnsupportedEncoding,
        ),
        UnsupportedSourceDisposition::AdmissionResourceBounded => (
            "language-admission-resource-bounded",
            "bounded native language admission exhausted its analysis resources and source remains available without a language determination",
            SkippedRegionReason::ResourceLimit,
        ),
        UnsupportedSourceDisposition::IntrinsicIdentityWorkLimit { .. } => (
            "native-identity-work-limit",
            "source remains exact and readable; intrinsic native identity work prevented structural analysis",
            SkippedRegionReason::ResourceLimit,
        ),
        UnsupportedSourceDisposition::NativeIdentityRefusal { .. } => (
            "native-query-refusal",
            "source remains exact and readable; native identity query refused complete structural analysis",
            SkippedRegionReason::ResourceLimit,
        ),
        UnsupportedSourceDisposition::NativeScannerRefusal { details } => match details {
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::LeanScannerCapacity => (
                "native-scanner-capacity", "source remains exact and readable; a finite native scanner state or delimiter bound prevented structural analysis", SkippedRegionReason::ResourceLimit,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::LeanExternalWork { .. } => (
                "native-scanner-external-work-limit", "source remains exact and readable; intrinsic external scanner work prevented structural analysis", SkippedRegionReason::ResourceLimit,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::DockerfileStateCapacity => (
                "native-scanner-capacity", "source remains exact and readable; native scanner state cannot fit its complete serialized format", SkippedRegionReason::ResourceLimit,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::DockerfileMarkerSemantics => (
                "native-scanner-unsupported-marker", "source remains exact and readable; written marker semantics lack complete native scanner support", SkippedRegionReason::UnsupportedConstruct,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::IdrisStateCapacity => (
                "native-scanner-capacity", "source remains exact and readable; complete native token, state or indentation exceeded fixed capacity", SkippedRegionReason::ResourceLimit,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::IdrisExternalWork { .. } => (
                "native-scanner-external-work-limit", "source remains exact and readable; intrinsic external scanner work prevented structural analysis", SkippedRegionReason::ResourceLimit,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::SedGroupCapacity => (
                "native-scanner-capacity", "source remains exact and readable; native regex group state exceeded its fixed uint32 capacity", SkippedRegionReason::ResourceLimit,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::SedExternalWork { .. } => (
                "native-scanner-external-work-limit", "source remains exact and readable; intrinsic external scanner work prevented structural analysis", SkippedRegionReason::ResourceLimit,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::WolframCommentDepth => (
                "native-scanner-capacity", "source remains exact and readable; nested native comments exceeded the finite depth policy", SkippedRegionReason::ResourceLimit,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::WolframExternalWork { .. } => (
                "native-scanner-external-work-limit", "source remains exact and readable; intrinsic external scanner work prevented structural analysis", SkippedRegionReason::ResourceLimit,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::PugStateCapacity => (
                "native-scanner-capacity", "source remains exact and readable; complete native scanner state or indentation width exceeded capacity", SkippedRegionReason::ResourceLimit,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::PugExternalWork { .. } => (
                "native-scanner-external-work-limit", "source remains exact and readable; intrinsic external scanner work prevented structural analysis", SkippedRegionReason::ResourceLimit,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::CoffeescriptStateCapacity => (
                "native-scanner-capacity", "source remains exact and readable; complete native scanner state or indentation width exceeded capacity", SkippedRegionReason::ResourceLimit,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::CoffeescriptNulSemantics => (
                "native-scanner-unsupported-nul", "source remains exact and readable; native scanner cannot interpret embedded NUL", SkippedRegionReason::UnsupportedConstruct,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::CoffeescriptIndentationSemantics => (
                "native-scanner-unsupported-indentation", "source remains exact and readable; written dedentation has no complete native scanner interpretation", SkippedRegionReason::UnsupportedConstruct,
            ),
            rootlight_adapter_treesitter::NativeScannerRefusalDetails::CoffeescriptExternalWork { .. } => (
                "native-scanner-external-work-limit", "source remains exact and readable; intrinsic external scanner work prevented structural analysis", SkippedRegionReason::ResourceLimit,
            ),
            _ => return Err(FirstSliceError::Adapter),
        },
        UnsupportedSourceDisposition::AggregateFileCapacity => (
            "aggregate-file-capacity",
            "combined structural capacity prevented this file's analysis; exact original source remains available",
            SkippedRegionReason::ResourceLimit,
        ),
        UnsupportedSourceDisposition::ParserSizeLimit => (
            "source-parser-snapshot-size-limit",
            "streamed source remains available for exact reads and literal matching but parser memory limits prevent structural analysis and lexical vocabulary projection",
            SkippedRegionReason::ResourceLimit,
        ),
    };
    let relative = RelativePath::parse(Path::new(&input.claim.path))
        .map_err(|_| FirstSliceError::Repository)?;
    let span = SourceSpan::new(input.claim.file, 0, input.claim.byte_length)
        .map_err(|_| FirstSliceError::Identity)?;
    let source = SourceRef::new(repository, generation, span, input.claim.content_hash, None);
    let producer = ProducerIdentity::new(
        "rootlight-language-disposition",
        "1.0.0",
        first_slice_build_context(),
    )
    .map_err(|_| FirstSliceError::Identity)?;
    let mut provenance = ProvenanceRecord {
        id: FactId::from_bytes([0; 20]),
        repository,
        generation,
        producer_kind: ProducerKind::Rule,
        producer,
        binary_digest: content_hash(LANGUAGE_DISPOSITION_PROVIDER_SEED),
        frontend_version: Some("disposition-1".to_owned()),
        language: input.language.clone(),
        tier: AnalysisTier::TierD,
        build_context: BuildContextIdentity::new(first_slice_build_context()),
        input_sources: vec![source.clone()],
        evidence_sources: vec![source.clone()],
        derivation_parents: Vec::new(),
        rule: Some(code.to_owned()),
    };
    provenance.id =
        derive_provenance_record_id(&provenance).map_err(|_| FirstSliceError::Identity)?;
    let provenance_id = provenance.id;
    let evidence = || FactEvidence {
        source: Some(source.clone()),
        derivation: Vec::new(),
    };
    let file = FileRecord {
        id: input.claim.file,
        repository,
        generation,
        path: input.claim.path.clone(),
        path_locator: Some(relative.to_locator()),
        content_hash: input.claim.content_hash,
        byte_length: input.claim.byte_length,
        language: input.language.clone(),
        encoding: input.encoding.clone(),
        generated: input.generated,
        provenance: provenance_id,
        evidence: evidence(),
    };
    let mut document = NormalizedIrDocument::empty(repository, generation);
    document.files.push(file);
    document.provenance.push(provenance);
    for (domain, status, discovered, indexed, skipped) in [
        (IrFactDomain::Files, CoverageStatus::Complete, 1, 1, 0),
        (IrFactDomain::Entities, CoverageStatus::Unknown, 1, 0, 1),
        (IrFactDomain::Occurrences, CoverageStatus::Unknown, 1, 0, 1),
        (IrFactDomain::Relations, CoverageStatus::Unknown, 1, 0, 1),
        (IrFactDomain::Provenance, CoverageStatus::Complete, 1, 1, 0),
        (
            IrFactDomain::SourceMappings,
            CoverageStatus::Complete,
            0,
            0,
            0,
        ),
        if input.disposition == UnsupportedSourceDisposition::AggregateFileCapacity {
            (IrFactDomain::Diagnostics, CoverageStatus::Unknown, 0, 0, 0)
        } else {
            (IrFactDomain::Diagnostics, CoverageStatus::Complete, 1, 1, 0)
        },
        (IrFactDomain::Extensions, CoverageStatus::Complete, 1, 1, 0),
    ] {
        let mut coverage = CoverageRecord {
            id: FactId::from_bytes([0; 20]),
            repository,
            generation,
            scope: CoverageScope::File(input.claim.file),
            domain,
            tier: AnalysisTier::TierD,
            status,
            discovered,
            indexed,
            skipped,
            provenance: provenance_id,
            evidence: evidence(),
        };
        coverage.id =
            derive_coverage_record_id(&coverage).map_err(|_| FirstSliceError::Identity)?;
        document.coverage_records.push(coverage);
    }
    for domain in [
        IrFactDomain::Entities,
        IrFactDomain::Occurrences,
        IrFactDomain::Relations,
    ] {
        let mut skipped = SkippedRegion {
            id: FactId::from_bytes([0; 20]),
            repository,
            generation,
            source: source.clone(),
            domain,
            reason,
            detail: code.to_owned(),
            provenance: provenance_id,
            evidence: evidence(),
        };
        skipped.id = derive_skipped_region_id(&skipped).map_err(|_| FirstSliceError::Identity)?;
        document.skipped_regions.push(skipped);
    }
    if input.disposition != UnsupportedSourceDisposition::AggregateFileCapacity {
        let mut diagnostic = DiagnosticRecord {
            id: FactId::from_bytes([0; 20]),
            repository,
            generation,
            code: code.to_owned(),
            message: match input.disposition {
                UnsupportedSourceDisposition::IntrinsicIdentityWorkLimit { observed, limit } => {
                    format!("{message}; resource Records observed {observed} above {limit}")
                }
                UnsupportedSourceDisposition::NativeIdentityRefusal { details } => {
                    details.diagnostic(message)
                }
                UnsupportedSourceDisposition::NativeScannerRefusal { details } => {
                    details.diagnostic(message)
                }
                _ => message.to_owned(),
            },
            severity: DiagnosticSeverity::Warning,
            source: Some(source.clone()),
            coverage_effect: CoverageStatus::Unknown,
            provenance: provenance_id,
            evidence: evidence(),
        };
        diagnostic.id =
            derive_diagnostic_record_id(&diagnostic).map_err(|_| FirstSliceError::Identity)?;
        document.diagnostics.push(diagnostic);
    }
    document.extensions.push(
        new_file_identity_claim_envelope(&input.claim, generation, provenance_id, source)
            .map_err(|_| FirstSliceError::Identity)?,
    );
    Ok(document)
}

fn source_file_fallback_document_and_catalog(
    repository: RepositoryId,
    generation: GenerationId,
    inputs: &[ManifestInput],
    mut claims: Vec<FileIdentityClaim>,
    cancellation: &Cancellation,
) -> Result<(NormalizedIrDocument, SourceFileCatalog), FirstSliceError> {
    check_cancellation(cancellation)?;
    if inputs.is_empty() || inputs.len() != claims.len() {
        return Err(FirstSliceError::Identity);
    }
    let inputs_by_file = inputs
        .iter()
        .map(|input| (input.file, input))
        .collect::<BTreeMap<_, _>>();
    if inputs_by_file.len() != inputs.len() {
        return Err(FirstSliceError::Identity);
    }
    claims.sort_unstable_by_key(|claim| claim.file);
    if claims.windows(2).any(|pair| pair[0].file == pair[1].file) {
        return Err(FirstSliceError::Identity);
    }
    let mut claims = claims.into_iter();
    let anchor_claim = claims.next().ok_or(FirstSliceError::FixtureShape)?;
    let anchor_input = inputs_by_file
        .get(&anchor_claim.file)
        .copied()
        .ok_or(FirstSliceError::Identity)?;
    let anchor_source = SourceRef::new(
        repository,
        generation,
        SourceSpan::new(anchor_claim.file, 0, anchor_claim.byte_length)
            .map_err(|_| FirstSliceError::Identity)?,
        anchor_claim.content_hash,
        None,
    );
    let mut provenance = ProvenanceRecord {
        id: FactId::from_bytes([0; 20]),
        repository,
        generation,
        producer_kind: ProducerKind::Rule,
        producer: ProducerIdentity::new(
            "rootlight-source-file-fallback",
            "1.0.0",
            first_slice_build_context(),
        )
        .map_err(|_| FirstSliceError::Identity)?,
        binary_digest: content_hash(SOURCE_FILE_FALLBACK_PROVIDER_SEED),
        frontend_version: Some("source-file-fallback-1".to_owned()),
        language: "multi".to_owned(),
        tier: AnalysisTier::TierD,
        build_context: BuildContextIdentity::new(first_slice_build_context()),
        input_sources: vec![anchor_source.clone()],
        evidence_sources: vec![anchor_source.clone()],
        derivation_parents: Vec::new(),
        rule: Some("resource-bounded-file-only".to_owned()),
    };
    provenance.id =
        derive_provenance_record_id(&provenance).map_err(|_| FirstSliceError::Identity)?;
    let provenance_id = provenance.id;
    let anchor_file = source_file_fallback_record(
        repository,
        generation,
        &anchor_claim,
        anchor_input,
        provenance_id,
    )?;
    let evidence = || FactEvidence {
        source: Some(anchor_source.clone()),
        derivation: Vec::new(),
    };
    let total_files = u64::try_from(inputs.len()).map_err(|_| FirstSliceError::Limits)?;
    let generated_files = inputs.iter().try_fold(0_u64, |count, input| {
        count
            .checked_add(u64::from(matches!(input.class, InputClass::Generated)))
            .ok_or(FirstSliceError::Limits)
    })?;
    let mut document = NormalizedIrDocument::empty(repository, generation);
    document.files.push(anchor_file);
    document.provenance.push(provenance);
    for (domain, status, discovered, indexed, skipped) in [
        (
            IrFactDomain::Files,
            CoverageStatus::Complete,
            total_files,
            total_files,
            0,
        ),
        (
            IrFactDomain::Entities,
            CoverageStatus::Unknown,
            total_files,
            0,
            total_files,
        ),
        (
            IrFactDomain::Occurrences,
            CoverageStatus::Unknown,
            total_files,
            0,
            total_files,
        ),
        (
            IrFactDomain::Relations,
            CoverageStatus::Unknown,
            total_files,
            0,
            total_files,
        ),
        (IrFactDomain::Provenance, CoverageStatus::Complete, 1, 1, 0),
        (
            IrFactDomain::SourceMappings,
            if generated_files == 0 {
                CoverageStatus::Complete
            } else {
                CoverageStatus::Unknown
            },
            generated_files,
            0,
            generated_files,
        ),
        (IrFactDomain::Diagnostics, CoverageStatus::Complete, 1, 1, 0),
        (IrFactDomain::Extensions, CoverageStatus::Complete, 1, 1, 0),
    ] {
        let mut coverage = CoverageRecord {
            id: FactId::from_bytes([0; 20]),
            repository,
            generation,
            scope: CoverageScope::Repository(repository),
            domain,
            tier: AnalysisTier::TierD,
            status,
            discovered,
            indexed,
            skipped,
            provenance: provenance_id,
            evidence: evidence(),
        };
        coverage.id =
            derive_coverage_record_id(&coverage).map_err(|_| FirstSliceError::Identity)?;
        document.coverage_records.push(coverage);
    }
    let mut diagnostic = DiagnosticRecord {
        id: FactId::from_bytes([0; 20]),
        repository,
        generation,
        code: SOURCE_FILE_FALLBACK_DIAGNOSTIC_CODE.to_owned(),
        message: "repository analysis exceeded a bounded resource - exact file bounded lexical and source retrieval remain available".to_owned(),
        severity: DiagnosticSeverity::Warning,
        source: None,
        coverage_effect: CoverageStatus::Unknown,
        provenance: provenance_id,
        evidence: evidence(),
    };
    diagnostic.id =
        derive_diagnostic_record_id(&diagnostic).map_err(|_| FirstSliceError::Identity)?;
    document.diagnostics.push(diagnostic);
    document.extensions.push(
        new_file_identity_claim_envelope(&anchor_claim, generation, provenance_id, anchor_source)
            .map_err(|_| FirstSliceError::Identity)?,
    );

    let mut catalog_entries = Vec::new();
    catalog_entries
        .try_reserve_exact(inputs.len().saturating_sub(1))
        .map_err(|_| FirstSliceError::Limits)?;
    for claim in claims {
        check_cancellation(cancellation)?;
        let input = inputs_by_file
            .get(&claim.file)
            .copied()
            .ok_or(FirstSliceError::Identity)?;
        let file =
            source_file_fallback_record(repository, generation, &claim, input, provenance_id)?;
        catalog_entries
            .push(SourceFileCatalogEntry::new(file, claim).map_err(|_| FirstSliceError::Identity)?);
    }
    let catalog = SourceFileCatalog::new(catalog_entries).map_err(|_| FirstSliceError::Identity)?;
    Ok((document, catalog))
}

fn source_file_fallback_record(
    repository: RepositoryId,
    generation: GenerationId,
    claim: &FileIdentityClaim,
    input: &ManifestInput,
    provenance: FactId,
) -> Result<FileRecord, FirstSliceError> {
    if claim.repository != repository
        || claim.file != input.file
        || claim.path != input.path
        || claim.content_hash != input.content_hash
        || claim.byte_length != input.bytes
    {
        return Err(FirstSliceError::Identity);
    }
    let relative =
        RelativePath::parse(Path::new(&claim.path)).map_err(|_| FirstSliceError::Repository)?;
    if relative.identity_bytes() != claim.path_identity {
        return Err(FirstSliceError::Identity);
    }
    let source = SourceRef::new(
        repository,
        generation,
        SourceSpan::new(claim.file, 0, claim.byte_length).map_err(|_| FirstSliceError::Identity)?,
        claim.content_hash,
        None,
    );
    Ok(FileRecord {
        id: claim.file,
        repository,
        generation,
        path: claim.path.clone(),
        path_locator: Some(relative.to_locator()),
        content_hash: claim.content_hash,
        byte_length: claim.byte_length,
        language: detected_source_language(input)
            .unwrap_or("unknown")
            .to_owned(),
        // Discovery classifies containers as binary; the retrieval catalog uses
        // bytes to preserve their exact content without claiming text support.
        encoding: if input.encoding == "binary" {
            "bytes".to_owned()
        } else {
            input.encoding.clone()
        },
        generated: matches!(input.class, InputClass::Generated),
        provenance,
        evidence: FactEvidence {
            source: Some(source),
            derivation: Vec::new(),
        },
    })
}

fn source_file_fallback_preflight_memory_bytes(
    claims: &[FileIdentityClaim],
) -> Result<u64, FirstSliceError> {
    let entry_bytes = u64::try_from(claims.len())
        .map_err(|_| FirstSliceError::Limits)?
        .checked_mul(SOURCE_FILE_FALLBACK_ENTRY_MEMORY_BYTES)
        .ok_or(FirstSliceError::Limits)?;
    let path_bytes = claims.iter().try_fold(0_u64, |total, claim| {
        let path = u64::try_from(claim.path.len()).map_err(|_| FirstSliceError::Limits)?;
        let identity =
            u64::try_from(claim.path_identity.len()).map_err(|_| FirstSliceError::Limits)?;
        total
            .checked_add(path)
            .and_then(|bytes| bytes.checked_add(identity))
            .ok_or(FirstSliceError::Limits)
    })?;
    let observed = GENERATION_MEMORY_FIXED_OVERHEAD_BYTES
        .checked_add(entry_bytes)
        .and_then(|bytes| bytes.checked_add(path_bytes.saturating_mul(8)))
        .ok_or(FirstSliceError::Limits)?;
    ensure_generation_memory_admission(observed)
}

fn source_file_fallback_resident_memory_bytes(
    serialized_document_bytes: u64,
    snapshot: &rootlight_storage::GenerationSnapshot,
    cancellation: &Cancellation,
) -> Result<u64, FirstSliceError> {
    let serialized_document_bytes = serialized_document_bytes
        .checked_add(snapshot.retained_symbol_explain_index_bytes())
        .ok_or(FirstSliceError::Limits)?
        .checked_add(source_lexical_coverage_memory_bytes(
            snapshot.file_count(),
            snapshot.document(),
            cancellation,
        )?)
        .ok_or(FirstSliceError::Limits)?;
    let entry_bytes = u64::try_from(snapshot.file_count())
        .map_err(|_| FirstSliceError::Limits)?
        .checked_mul(SOURCE_FILE_FALLBACK_ENTRY_MEMORY_BYTES)
        .ok_or(FirstSliceError::Limits)?;
    let normalized_path_bytes =
        snapshot
            .document()
            .files
            .iter()
            .try_fold(0_u64, |total, file| {
                total
                    .checked_add(
                        u64::try_from(file.path.len()).map_err(|_| FirstSliceError::Limits)?,
                    )
                    .ok_or(FirstSliceError::Limits)
            })?;
    let catalog_path_bytes =
        snapshot
            .source_files()
            .entries()
            .iter()
            .try_fold(0_u64, |total, entry| {
                let path =
                    u64::try_from(entry.file().path.len()).map_err(|_| FirstSliceError::Limits)?;
                let identity = u64::try_from(entry.path_identity().len())
                    .map_err(|_| FirstSliceError::Limits)?;
                total
                    .checked_add(path)
                    .and_then(|bytes| bytes.checked_add(identity))
                    .ok_or(FirstSliceError::Limits)
            })?;
    let observed = serialized_document_bytes
        .checked_add(GENERATION_MEMORY_FIXED_OVERHEAD_BYTES)
        .and_then(|bytes| bytes.checked_add(entry_bytes))
        .and_then(|bytes| {
            bytes.checked_add(
                normalized_path_bytes
                    .checked_add(catalog_path_bytes)?
                    .checked_mul(8)?,
            )
        })
        .ok_or(FirstSliceError::Limits)?;
    ensure_generation_memory_admission(observed)
}

fn source_lexical_coverage_memory_bytes(
    file_count: usize,
    document: &NormalizedIrDocument,
    cancellation: &Cancellation,
) -> Result<u64, FirstSliceError> {
    check_cancellation(cancellation)?;
    // The lexical reader retains a compact sorted accounting entry per file;
    // reserve it for legacy generations too so hydration cannot undercharge.
    let source_entry = u64::try_from(std::mem::size_of::<(
        FileId,
        rootlight_search::SourceLexicalCoverage,
    )>())
    .map_err(|_| FirstSliceError::Limits)?;
    let mut name_scope_bound = 0usize;
    for entity in &document.entities {
        check_cancellation(cancellation)?;
        let alias = (entity.canonical_name != entity.display_name)
            .then_some(entity.canonical_name.as_str());
        if rootlight_search::project_symbol_name_projection(
            &entity.display_name,
            alias,
            &entity.qualified_name,
        ) == rootlight_search::SymbolNameProjection::Segmented
            && !rootlight_search::symbol_name_term_omissions(
                &entity.display_name,
                alias,
                &entity.qualified_name,
            )
            .map_err(|_| FirstSliceError::Limits)?
            .is_empty()
        {
            name_scope_bound = name_scope_bound
                .checked_add(1)
                .ok_or(FirstSliceError::Limits)?;
        }
    }
    let name_entries = rootlight_search::symbol_name_omission_memory_bytes(name_scope_bound)
        .map_err(|_| FirstSliceError::Limits)?;
    let entries = u64::try_from(file_count)
        .map_err(|_| FirstSliceError::Limits)?
        .checked_mul(source_entry)
        .ok_or(FirstSliceError::Limits)?;
    entries
        .checked_add(name_entries)
        .ok_or(FirstSliceError::Limits)
}

fn generation_resident_memory_bytes(
    serialized_document_bytes: u64,
    snapshot: &rootlight_storage::GenerationSnapshot,
    cancellation: &Cancellation,
) -> Result<u64, FirstSliceError> {
    if snapshot.source_files().is_empty() {
        let serialized_document_bytes = serialized_document_bytes
            .checked_add(snapshot.retained_symbol_explain_index_bytes())
            .ok_or(FirstSliceError::Limits)?
            .checked_add(source_lexical_coverage_memory_bytes(
                snapshot.file_count(),
                snapshot.document(),
                cancellation,
            )?)
            .ok_or(FirstSliceError::Limits)?;
        ensure_generation_memory_admission(serialized_document_bytes)
    } else {
        source_file_fallback_resident_memory_bytes(
            serialized_document_bytes,
            snapshot,
            cancellation,
        )
    }
}

fn attach_generated_origin_mappings(
    sources: &mut [RustSourceInput],
    source_languages: &BTreeMap<FileId, String>,
    cancellation: &Cancellation,
) -> Result<(), FirstSliceError> {
    let mut indexed_paths = BTreeMap::new();
    for (index, source) in sources.iter().enumerate() {
        if indexed_paths
            .insert(source.snapshot.path().identity_bytes(), index)
            .is_some()
        {
            return Err(FirstSliceError::Identity);
        }
    }

    let mut detected = Vec::new();
    detected
        .try_reserve_exact(sources.len())
        .map_err(|_| FirstSliceError::Limits)?;
    for (index, source) in sources.iter().enumerate() {
        check_cancellation(cancellation)?;
        detected.push(detect_generated_origin_mapping(
            index,
            source,
            sources,
            &indexed_paths,
            source_languages,
        )?);
    }
    drop(indexed_paths);

    for (source, mapping) in sources.iter_mut().zip(detected) {
        if let Some(mapping) = mapping {
            source
                .origins
                .try_reserve_exact(1)
                .map_err(|_| FirstSliceError::Limits)?;
            source.origins.push(mapping);
        }
    }
    Ok(())
}

fn detect_generated_origin_mapping(
    generated_index: usize,
    generated: &RustSourceInput,
    sources: &[RustSourceInput],
    indexed_paths: &BTreeMap<&[u8], usize>,
    source_languages: &BTreeMap<FileId, String>,
) -> Result<Option<GeneratedOriginMapping>, FirstSliceError> {
    if !generated.generated {
        return Ok(None);
    }
    let Some(evidence) = generated_header_evidence(generated.snapshot.content()) else {
        return Ok(None);
    };
    let Ok(origin_path) = RelativePath::parse(Path::new(evidence.origin_path)) else {
        return Ok(None);
    };
    if origin_path.as_str() != evidence.origin_path {
        return Ok(None);
    }
    let Some(origin_index) = indexed_paths
        .get(origin_path.identity_bytes())
        .copied()
        .filter(|origin_index| *origin_index != generated_index)
    else {
        return Ok(None);
    };
    let Some(origin) = sources.get(origin_index) else {
        return Err(FirstSliceError::Identity);
    };
    if source_languages.get(&generated.snapshot.file())
        != source_languages.get(&origin.snapshot.file())
    {
        return Ok(None);
    }
    let Ok(transformation) = TransformationId::new(evidence.generator) else {
        return Ok(None);
    };
    let generated_length =
        u64::try_from(generated.snapshot.content().len()).map_err(|_| FirstSliceError::Limits)?;
    let origin_length =
        u64::try_from(origin.snapshot.content().len()).map_err(|_| FirstSliceError::Limits)?;
    let (Ok(generated_span), Ok(origin_span)) = (
        SourceSpan::new(generated.snapshot.file(), 0, generated_length),
        SourceSpan::new(origin.snapshot.file(), 0, origin_length),
    ) else {
        return Ok(None);
    };
    if generated_span.start_byte() == generated_span.end_byte()
        || origin_span.start_byte() == origin_span.end_byte()
    {
        return Ok(None);
    }
    Ok(Some(GeneratedOriginMapping::new(
        generated_span,
        origin_path,
        origin_span,
        transformation,
        None,
    )))
}

struct GeneratedHeaderEvidence<'a> {
    generator: &'a str,
    origin_path: &'a str,
}

fn generated_header_evidence(source: &[u8]) -> Option<GeneratedHeaderEvidence<'_>> {
    let scan_length = source.len().min(GENERATED_HEADER_MAX_BYTES);
    let bounded = source.get(..scan_length)?;
    let scan = if source.len() > scan_length && !bounded.ends_with(b"\n") {
        let complete_end = bounded
            .iter()
            .rposition(|byte| *byte == b'\n')
            .map_or(0, |position| position.saturating_add(1));
        bounded.get(..complete_end)?
    } else {
        bounded
    };

    let mut generator = None;
    let mut origin_path = None;
    for line in scan
        .split(|byte| *byte == b'\n')
        .take(GENERATED_HEADER_MAX_LINES)
        .map(trim_ascii_whitespace)
    {
        if let Some(value) = generated_by_marker(line)
            && generator.replace(value).is_some()
        {
            return None;
        }
        if let Some(value) = generated_source_marker(line)
            && origin_path.replace(value).is_some()
        {
            return None;
        }
    }

    let generator = std::str::from_utf8(generator?).ok()?;
    let origin_path = std::str::from_utf8(origin_path?).ok()?;
    (!generator.is_empty() && !origin_path.is_empty()).then_some(GeneratedHeaderEvidence {
        generator,
        origin_path,
    })
}

fn generated_by_marker(line: &[u8]) -> Option<&[u8]> {
    line.strip_prefix(b"// Code generated by ")
        .and_then(|value| value.strip_suffix(b". DO NOT EDIT."))
        .or_else(|| {
            line.strip_prefix(b"# Code generated by ")
                .and_then(|value| value.strip_suffix(b". DO NOT EDIT."))
        })
        .or_else(|| {
            line.strip_prefix(b"/* Code generated by ")
                .and_then(|value| value.strip_suffix(b". DO NOT EDIT. */"))
        })
}

fn generated_source_marker(line: &[u8]) -> Option<&[u8]> {
    line.strip_prefix(b"// source: ")
        .or_else(|| line.strip_prefix(b"# source: "))
        .or_else(|| {
            line.strip_prefix(b"/* source: ")
                .and_then(|value| value.strip_suffix(b" */"))
        })
}

fn trim_ascii_whitespace(mut value: &[u8]) -> &[u8] {
    while let Some((first, rest)) = value.split_first()
        && first.is_ascii_whitespace()
    {
        value = rest;
    }
    while let Some((last, rest)) = value.split_last()
        && last.is_ascii_whitespace()
    {
        value = rest;
    }
    value
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SourceInputPreflight {
    supported_file_count: usize,
    source_bytes: u64,
}

fn summarize_source_inputs(
    inputs: &[ManifestInput],
    analyzers: &BTreeMap<String, TreeSitterAnalyzer>,
    cancellation: &Cancellation,
) -> Result<SourceInputPreflight, FirstSliceError> {
    check_cancellation(cancellation)?;
    let mut supported_file_count = 0usize;
    let mut source_bytes = 0_u64;
    for input in inputs {
        check_cancellation(cancellation)?;
        if supported_source_language(input, analyzers).is_some() {
            supported_file_count = supported_file_count
                .checked_add(1)
                .ok_or(FirstSliceError::Limits)?;
        }
        source_bytes = source_bytes
            .checked_add(input.bytes)
            .ok_or(FirstSliceError::Limits)?;
    }
    check_cancellation(cancellation)?;
    if inputs.is_empty() {
        return Err(FirstSliceError::FixtureShape);
    }
    Ok(SourceInputPreflight {
        supported_file_count,
        source_bytes,
    })
}

fn enforce_source_input_bounds(
    preflight: &SourceInputPreflight,
    file_count: usize,
    maximum_files: usize,
    maximum_source_bytes: usize,
) -> Result<(), FirstSliceError> {
    if file_count > maximum_files {
        return Err(resource_limit(
            FirstSliceResource::SourceFiles,
            file_count,
            maximum_files,
        ));
    }
    let maximum_source_bytes =
        u64::try_from(maximum_source_bytes).map_err(|_| FirstSliceError::Limits)?;
    if preflight.source_bytes > maximum_source_bytes {
        return Err(FirstSliceError::ResourceLimit {
            resource: FirstSliceResource::SourceBytes,
            observed: preflight.source_bytes,
            limit: maximum_source_bytes,
        });
    }
    Ok(())
}

fn source_file_identity_claims(
    inputs: &[ManifestInput],
    repository: RepositoryId,
    cancellation: &Cancellation,
) -> Result<Vec<FileIdentityClaim>, FirstSliceError> {
    let mut claims = Vec::new();
    claims
        .try_reserve_exact(inputs.len())
        .map_err(|_| FirstSliceError::Limits)?;
    for input in inputs {
        check_cancellation(cancellation)?;
        let relative =
            RelativePath::parse(Path::new(&input.path)).map_err(|_| FirstSliceError::Repository)?;
        claims.push(FileIdentityClaim {
            file: input.file,
            repository,
            path: fallible_copy_string(&input.path)?,
            path_identity: fallible_copy_bytes(relative.identity_bytes())?,
            content_hash: input.content_hash,
            byte_length: input.bytes,
        });
    }
    Ok(claims)
}

fn discovery_incomplete_resource(
    truncation: Option<DiscoveryTruncation>,
    config: &ConfigSnapshot,
) -> (FirstSliceResource, u64, u64) {
    let Some(truncation) = truncation else {
        let limit = u64::from(config.max_discovery_entries());
        return (
            FirstSliceResource::DiscoveryEntries,
            limit.saturating_add(1),
            limit,
        );
    };
    let resource = match truncation.resource {
        DiscoveryTruncationResource::Entries => FirstSliceResource::DiscoveryEntries,
        DiscoveryTruncationResource::RetainedSourceBytes => FirstSliceResource::SourceBytes,
    };
    (resource, truncation.observed, truncation.limit)
}

#[cfg(test)]
fn durable_initial_admission_reservation(source_bytes: u64) -> Result<u64, FirstSliceError> {
    source_bytes
        .checked_mul(2)
        .and_then(|bytes| bytes.checked_add(DURABLE_STAGING_FIXED_OVERHEAD_BYTES))
        .and_then(|bytes| bytes.checked_add(DURABLE_DISK_SAFETY_MARGIN_BYTES))
        .ok_or(FirstSliceError::Limits)
}

fn storage_admission_error(failure: DurableStorageAdmissionFailure) -> FirstSliceError {
    let scope = match failure.scope {
        DurableStorageAdmissionScope::RepositoryBudget => FirstSliceStorageScope::Repository,
        DurableStorageAdmissionScope::RepositoryAmplification => {
            FirstSliceStorageScope::RepositoryAmplification
        }
        DurableStorageAdmissionScope::CatalogBudget => FirstSliceStorageScope::Catalog,
        DurableStorageAdmissionScope::FilesystemFreeSpace => FirstSliceStorageScope::Filesystem,
    };
    let repository_amplification =
        failure
            .repository_amplification
            .map(|amplification| FirstSliceRepositoryAmplification {
                examined_source_bytes: amplification.examined_source_bytes,
                emitted_fact_bytes: amplification.emitted_fact_bytes,
                effective_factor: amplification.effective_factor,
                retained_generations: amplification.retained_generations,
                absolute_limit_bytes: amplification.absolute_limit_bytes,
                amplification_limit_bytes: amplification.amplification_limit_bytes,
            });
    FirstSliceError::StorageResourceExhausted {
        scope,
        required_bytes: failure.required_bytes,
        observed_bytes: failure.observed_bytes,
        projected_bytes: failure.projected_bytes,
        limit_bytes: failure.limit_bytes,
        minimum_free_bytes: failure.minimum_free_bytes,
        repository_amplification,
    }
}

#[cfg(test)]
fn durable_staging_reservation(source_bytes: u64) -> Result<u64, FirstSliceError> {
    source_bytes
        .checked_mul(DURABLE_SOURCE_WRITE_AMPLIFICATION_FACTOR)
        .and_then(|bytes| bytes.checked_add(DURABLE_STAGING_FIXED_OVERHEAD_BYTES))
        .and_then(|bytes| bytes.checked_add(DURABLE_DISK_SAFETY_MARGIN_BYTES))
        .ok_or(FirstSliceError::Limits)
}

#[derive(Default)]
struct SerializedSizeCounter {
    bytes: u64,
}

impl std::io::Write for SerializedSizeCounter {
    fn write(&mut self, buffer: &[u8]) -> std::io::Result<usize> {
        let length =
            u64::try_from(buffer.len()).map_err(|_| std::io::Error::other("size overflow"))?;
        self.bytes = self
            .bytes
            .checked_add(length)
            .ok_or_else(|| std::io::Error::other("size overflow"))?;
        Ok(buffer.len())
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

fn normalized_document_serialized_bytes(
    document: &NormalizedIrDocument,
) -> Result<u64, FirstSliceError> {
    let mut serialized = SerializedSizeCounter::default();
    serde_json::to_writer(&mut serialized, document).map_err(|_| FirstSliceError::Limits)?;
    Ok(serialized.bytes)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PendingGenerationMemory {
    Reserved,
    Staged,
}

fn generation_memory_limit(
    retained_bytes: u64,
    pending_bytes: u64,
    pending: PendingGenerationMemory,
) -> FirstSliceError {
    let (reserved_bytes, staged_bytes) = match pending {
        PendingGenerationMemory::Reserved => (pending_bytes, 0),
        PendingGenerationMemory::Staged => (0, pending_bytes),
    };
    FirstSliceError::GenerationMemoryLimit {
        breakdown: GenerationMemoryBreakdown {
            retained_bytes,
            reserved_bytes,
            owned_bytes: retained_bytes,
            referenced_bytes: 0,
            mapped_bytes: 0,
            staged_bytes,
            shared_bytes: 0,
        },
        observed: retained_bytes.saturating_add(pending_bytes),
        limit: generation_memory_ceiling(),
    }
}

fn ensure_generation_memory_preflight(source_bytes: u64) -> Result<u64, FirstSliceError> {
    let observed = source_bytes
        .checked_mul(GENERATION_MEMORY_SOURCE_PREFLIGHT_FACTOR)
        .and_then(|bytes| bytes.checked_add(GENERATION_MEMORY_FIXED_OVERHEAD_BYTES))
        .ok_or(FirstSliceError::Limits)?;
    #[cfg(test)]
    generation_admission_observation::observe_source_floor(observed);
    if observed > generation_memory_ceiling() {
        return Err(generation_memory_limit(
            0,
            observed,
            PendingGenerationMemory::Reserved,
        ));
    }
    Ok(observed)
}

#[cfg(test)]
fn maximum_generation_preflight_source_bytes() -> Result<u64, FirstSliceError> {
    MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES
        .checked_sub(GENERATION_MEMORY_FIXED_OVERHEAD_BYTES)
        .and_then(|bytes| bytes.checked_div(GENERATION_MEMORY_SOURCE_PREFLIGHT_FACTOR))
        .ok_or(FirstSliceError::Limits)
}

fn ensure_generation_memory_admission(
    serialized_document_bytes: u64,
) -> Result<u64, FirstSliceError> {
    let observed = serialized_document_bytes;
    if observed > generation_memory_ceiling() {
        return Err(generation_memory_limit(
            0,
            observed,
            PendingGenerationMemory::Staged,
        ));
    }
    Ok(observed)
}

fn logical_projection_staged_memory_bytes(
    serialized_document_bytes: u64,
    compact_graph_workspace_bytes: u64,
) -> Result<u64, FirstSliceError> {
    serialized_document_bytes
        .checked_mul(3)
        .and_then(|documents| documents.checked_add(compact_graph_workspace_bytes))
        .ok_or(FirstSliceError::Limits)
}

fn project_context_manifest(
    language: &str,
    configuration: ContentHash,
    sources: &[RustSourceInput],
) -> Result<Vec<u8>, FirstSliceError> {
    let capacity = PROJECT_CONTEXT_SEED
        .len()
        .checked_add(configuration.as_bytes().len())
        .and_then(|length| length.checked_add(language.len()))
        .and_then(|length| length.checked_add(2))
        .ok_or(FirstSliceError::Limits)?;
    let mut manifest = Vec::new();
    manifest
        .try_reserve_exact(capacity)
        .map_err(|_| FirstSliceError::Limits)?;
    manifest.extend_from_slice(PROJECT_CONTEXT_SEED);
    manifest.push(0);
    manifest.extend_from_slice(configuration.as_bytes());
    manifest.push(0);
    manifest.extend_from_slice(language.as_bytes());
    if !matches!(language, "typescript" | "javascript") {
        return Ok(manifest);
    }
    let mut encoded = b"{\"configs\":[".to_vec();
    let maximum_encoded_bytes = MAX_PROJECT_CONTEXT_BYTES
        .checked_sub(manifest.len())
        .and_then(|bytes| bytes.checked_sub(PROJECT_MODULE_RESOLUTION_MARKER.len()))
        .ok_or(FirstSliceError::Limits)?;
    let mut config_count = 0_usize;
    for source in sources {
        let path = source.snapshot.path().as_str();
        if !matches!(
            path.rsplit('/').next(),
            Some("tsconfig.json" | "jsconfig.json")
        ) {
            continue;
        }
        let Ok(content) = std::str::from_utf8(source.snapshot.content()) else {
            continue;
        };
        if content.len() > maximum_encoded_bytes {
            continue;
        }
        let entry = serde_json::to_vec(&ProjectModuleConfigSnapshot {
            path,
            content_hash: source.snapshot.content_hash(),
            content,
        })
        .map_err(|_| FirstSliceError::Limits)?;
        let Some(next_length) = encoded
            .len()
            .checked_add(usize::from(config_count > 0))
            .and_then(|length| length.checked_add(entry.len()))
            .and_then(|length| length.checked_add(2))
        else {
            continue;
        };
        if next_length > maximum_encoded_bytes {
            continue;
        }
        encoded
            .try_reserve(next_length - encoded.len())
            .map_err(|_| FirstSliceError::Limits)?;
        if config_count > 0 {
            encoded.push(b',');
        }
        encoded.extend_from_slice(&entry);
        config_count += 1;
    }
    if config_count > 0 {
        encoded.extend_from_slice(b"]}");
        manifest
            .try_reserve_exact(PROJECT_MODULE_RESOLUTION_MARKER.len() + encoded.len())
            .map_err(|_| FirstSliceError::Limits)?;
        manifest.extend_from_slice(PROJECT_MODULE_RESOLUTION_MARKER);
        manifest.extend_from_slice(&encoded);
    }
    Ok(manifest)
}

#[derive(Serialize)]
struct ProjectModuleConfigSnapshot<'a> {
    path: &'a str,
    content_hash: ContentHash,
    content: &'a str,
}

#[cfg(test)]
fn project_document_matches_inputs(
    document: &NormalizedIrDocument,
    repository: RepositoryId,
    generation: GenerationId,
    provider_identity: ContentHash,
    inputs: &[FirstSliceProjectInput<'_>],
) -> bool {
    project_documents_match_inputs(
        std::slice::from_ref(document),
        repository,
        generation,
        provider_identity,
        inputs,
    )
}

fn project_documents_match_inputs(
    documents: &[NormalizedIrDocument],
    repository: RepositoryId,
    generation: GenerationId,
    provider_identity: ContentHash,
    inputs: &[FirstSliceProjectInput<'_>],
) -> bool {
    if documents.is_empty()
        || documents.iter().any(|document| {
            document.repository != repository
                || document.generation != generation
                || document.provenance.is_empty()
                || document.provenance.iter().any(|provenance| {
                    provenance.tier != AnalysisTier::TierB
                        || provenance.binary_digest != provider_identity
                })
        })
    {
        return false;
    }
    let expected_files = inputs
        .iter()
        .map(|input| (input.file(), input))
        .collect::<BTreeMap<_, _>>();
    if expected_files.len() != inputs.len() {
        return false;
    }
    let mut observed_files = BTreeMap::new();
    for file in documents.iter().flat_map(|document| &document.files) {
        if observed_files.insert(file.id, file).is_some() {
            return false;
        }
        let Some(input) = expected_files.get(&file.id) else {
            return false;
        };
        if file.repository != repository
            || file.generation != generation
            || file.path != input.path()
            || file.content_hash != input.content_hash()
            || usize::try_from(file.byte_length) != Ok(input.source().len())
            || file.generated != input.generated()
        {
            return false;
        }
    }
    if observed_files.len() != inputs.len() {
        return false;
    }

    let expected_mappings = inputs
        .iter()
        .flat_map(FirstSliceProjectInput::origins)
        .map(|mapping| ((mapping.generated(), mapping.origin()), mapping))
        .collect::<BTreeMap<_, _>>();
    let expected_mapping_count = inputs
        .iter()
        .map(|input| input.origins().len())
        .sum::<usize>();
    if expected_mappings.len() != expected_mapping_count {
        return false;
    }
    let mut provenance = BTreeMap::new();
    for record in documents.iter().flat_map(|document| &document.provenance) {
        if provenance.insert(record.id, record).is_some() {
            return false;
        }
    }
    let mut observed_mapping_keys = BTreeSet::new();
    let mut observed_mapping_count = 0_usize;
    for observed in documents
        .iter()
        .flat_map(|document| &document.source_mappings)
        .filter(|mapping| mapping.kind == SourceMappingKind::GeneratedToOrigin)
    {
        observed_mapping_count = match observed_mapping_count.checked_add(1) {
            Some(count) => count,
            None => return false,
        };
        let key = (observed.from.span(), observed.to.span());
        if !observed_mapping_keys.insert(key) {
            return false;
        }
        let Some(expected) = expected_mappings.get(&key) else {
            return false;
        };
        let Some(mapping_provenance) = provenance.get(&observed.provenance) else {
            return false;
        };
        if mapping_provenance.producer_kind != ProducerKind::Derivation
            || mapping_provenance.rule.as_deref() != Some(expected.provenance_rule().as_str())
            || mapping_provenance.evidence_sources != [observed.from.clone(), observed.to.clone()]
            || observed.evidence.source.as_ref() != Some(&observed.from)
            || observed.evidence.derivation != [FactRef::File(observed.to.span().file())]
        {
            return false;
        }
    }
    observed_mapping_count == expected_mapping_count
}

fn missing_structural_declaration_count(
    structural_documents: &[NormalizedIrDocument],
    project_document: &NormalizedIrDocument,
    require_explicit_check: bool,
) -> Result<u64, FirstSliceError> {
    let entity_coverage_is_bounded = project_document.coverage_records.iter().any(|coverage| {
        coverage.domain == IrFactDomain::Entities
            && coverage.status != CoverageStatus::Complete
            && coverage.skipped > 0
    });
    if !require_explicit_check && !entity_coverage_is_bounded {
        return Ok(0);
    }
    let structural = structural_declaration_keys(
        structural_documents
            .iter()
            .flat_map(|document| document.entities.iter()),
    );
    let project = project_declaration_index(project_document);
    u64::try_from(
        structural
            .iter()
            .filter(|declaration| !project.preserves(declaration))
            .count(),
    )
    .map_err(|_| FirstSliceError::Limits)
}

#[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
struct ProjectDeclarationKey {
    source: SourceSpan,
    kind: EntityKind,
    canonical_name: String,
}

fn structural_declaration_keys<'a>(
    entities: impl Iterator<Item = &'a rootlight_ir::EntityRecord>,
) -> BTreeSet<ProjectDeclarationKey> {
    let mut declarations = BTreeSet::new();
    for entity in entities {
        let Some(key) = project_declaration_key(entity) else {
            continue;
        };
        declarations.insert(key);
    }
    declarations
}

#[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
struct ProjectDeclarationIdentity {
    file: FileId,
    kind: EntityKind,
    canonical_name: String,
}

#[derive(Debug, Default)]
struct ProjectDeclarationIndex {
    exact: BTreeSet<ProjectDeclarationKey>,
    definition_sites: BTreeMap<ProjectDeclarationIdentity, BTreeSet<(u64, u64)>>,
}

impl ProjectDeclarationIndex {
    fn preserves(&self, declaration: &ProjectDeclarationKey) -> bool {
        if self.exact.contains(declaration) {
            return true;
        }
        let identity = ProjectDeclarationIdentity {
            file: declaration.source.file(),
            kind: declaration.kind,
            canonical_name: declaration.canonical_name.clone(),
        };
        let Some(sites) = self.definition_sites.get(&identity) else {
            return false;
        };
        sites
            .range((declaration.source.start_byte(), 0)..=(declaration.source.end_byte(), u64::MAX))
            .any(|(_, end)| *end <= declaration.source.end_byte())
    }
}

fn project_declaration_index(document: &NormalizedIrDocument) -> ProjectDeclarationIndex {
    let mut declarations = ProjectDeclarationIndex::default();
    let mut identity = BTreeMap::new();
    for entity in &document.entities {
        let Some(key) = project_declaration_key(entity) else {
            continue;
        };
        identity.insert(entity.id, (entity.kind, entity.canonical_name.clone()));
        declarations.exact.insert(key);
    }
    for occurrence in &document.occurrences {
        if occurrence.role != OccurrenceRole::Definition {
            continue;
        }
        // Repeated declarations can retain a complete ambiguity set when
        // bounded structural and project passes choose different representatives.
        // Treat it as one declaration identity only when every candidate agrees.
        let definition_identity = match &occurrence.target {
            rootlight_ir::OccurrenceTarget::Resolved { symbol } => identity.get(symbol),
            rootlight_ir::OccurrenceTarget::Candidates {
                symbols,
                total_count,
                completeness,
            } if *completeness == CoverageStatus::Complete
                && u64::try_from(symbols.len()) == Ok(*total_count) =>
            {
                let Some((first, remaining)) = symbols.split_first() else {
                    continue;
                };
                let Some(expected) = identity.get(first) else {
                    continue;
                };
                remaining
                    .iter()
                    .all(|symbol| identity.get(symbol) == Some(expected))
                    .then_some(expected)
            }
            rootlight_ir::OccurrenceTarget::Candidates { .. }
            | rootlight_ir::OccurrenceTarget::Unresolved { .. } => None,
        };
        let Some((kind, canonical_name)) = definition_identity else {
            continue;
        };
        // Project analysis intentionally unifies repeated declarations under
        // one stable entity. Its definition occurrence identifies the name
        // token inside every declaration span that structural output may keep.
        let source = occurrence.source.span();
        declarations
            .definition_sites
            .entry(ProjectDeclarationIdentity {
                file: source.file(),
                kind: *kind,
                canonical_name: canonical_name.clone(),
            })
            .or_default()
            .insert((source.start_byte(), source.end_byte()));
    }
    declarations
}

fn project_declaration_key(entity: &rootlight_ir::EntityRecord) -> Option<ProjectDeclarationKey> {
    if entity.kind == EntityKind::ExternalSymbol
        || entity.flags.contains(&rootlight_ir::EntityFlag::Synthetic)
    {
        return None;
    }
    let source = entity.evidence.source.as_ref()?;
    Some(ProjectDeclarationKey {
        source: source.span(),
        kind: entity.kind,
        canonical_name: entity.canonical_name.clone(),
    })
}

fn merge_project_documents(
    documents: Vec<NormalizedIrDocument>,
    diagnostic_capacity: usize,
) -> Result<(NormalizedIrDocument, ProjectMergeTruncation), FirstSliceError> {
    let mut documents = documents.into_iter();
    let mut merged = documents.next().ok_or(FirstSliceError::Identity)?;
    let mut external_symbols = project_external_symbols(&merged);
    let mut truncation = ProjectMergeTruncation {
        diagnostics: merged.diagnostics.len() > diagnostic_capacity,
        facts: false,
    };
    merged.diagnostics.truncate(diagnostic_capacity);
    for document in documents {
        truncation.merge(merge_project_document(
            &mut merged,
            document,
            &mut external_symbols,
            diagnostic_capacity,
            &IrLimits::default(),
        )?);
    }
    Ok((merged, truncation))
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct ProjectMergeTruncation {
    diagnostics: bool,
    facts: bool,
}

impl ProjectMergeTruncation {
    fn merge(&mut self, other: Self) {
        self.diagnostics |= other.diagnostics;
        self.facts |= other.facts;
    }
}

fn project_external_symbols(document: &NormalizedIrDocument) -> BTreeSet<SymbolId> {
    document
        .entities
        .iter()
        .filter_map(|entity| (entity.kind == EntityKind::ExternalSymbol).then_some(entity.id))
        .collect()
}

fn map_supplemental_project_error(error: FirstSliceError) -> FirstSliceProjectAnalysisError {
    match error {
        FirstSliceError::Cancelled(reason) => FirstSliceProjectAnalysisError::Cancelled(reason),
        _ => FirstSliceProjectAnalysisError::Analysis,
    }
}

fn collect_supplemental_cancellable<I, T, C, F>(
    items: I,
    cancellation: &Cancellation,
    mut select: F,
) -> Result<C, FirstSliceError>
where
    I: IntoIterator,
    C: Default + Extend<T>,
    F: FnMut(I::Item) -> Option<T>,
{
    let mut output = C::default();
    for item in items {
        check_cancellation(cancellation)?;
        output.extend(select(item));
    }
    Ok(output)
}

fn remap_supplemental_prefix_relations(
    merged: &NormalizedIrDocument,
    document: &mut NormalizedIrDocument,
    prefixes: &[FirstSliceSupplementalPrefix],
    cancellation: &Cancellation,
) -> Result<(), FirstSliceError> {
    check_cancellation(cancellation)?;
    if prefixes.is_empty() {
        return Ok(());
    }
    let mut by_file = BTreeMap::new();
    for prefix in prefixes {
        check_cancellation(cancellation)?;
        if by_file.insert(prefix.file, *prefix).is_some() {
            return Err(FirstSliceError::Identity);
        }
    }
    let primary_files: BTreeMap<_, _> =
        collect_supplemental_cancellable(&merged.files, cancellation, |file| {
            by_file
                .contains_key(&file.id)
                .then_some((file.id, (file.content_hash, file.byte_length)))
        })?;
    let projected_files: BTreeMap<_, _> =
        collect_supplemental_cancellable(&document.files, cancellation, |file| {
            by_file
                .contains_key(&file.id)
                .then_some((file.id, (file.content_hash, file.byte_length)))
        })?;
    if primary_files.len() != by_file.len() || projected_files.len() != by_file.len() {
        return Err(FirstSliceError::Identity);
    }
    for (file, prefix) in &by_file {
        check_cancellation(cancellation)?;
        if primary_files.get(file) != Some(&(prefix.primary_content_hash, prefix.primary_bytes))
            || projected_files.get(file)
                != Some(&(prefix.projected_content_hash, prefix.projected_bytes))
        {
            return Err(FirstSliceError::Identity);
        }
    }

    let mut required_provenance = BTreeSet::new();
    for relation in &document.relations {
        check_cancellation(cancellation)?;
        required_provenance.insert(relation.provenance);
        for reference in &relation.evidence.derivation {
            check_cancellation(cancellation)?;
            if let FactRef::Fact(fact) = reference {
                required_provenance.insert(*fact);
            }
        }
    }
    let mut provenance_needing_projection = BTreeSet::new();
    for record in &document.provenance {
        check_cancellation(cancellation)?;
        if !required_provenance.contains(&record.id) {
            continue;
        }
        for source in record.input_sources.iter().chain(&record.evidence_sources) {
            check_cancellation(cancellation)?;
            if by_file.contains_key(&source.span().file()) {
                provenance_needing_projection.insert(record.id);
                break;
            }
        }
    }
    let mut expected_provenance = Vec::new();
    expected_provenance
        .try_reserve_exact(provenance_needing_projection.len())
        .map_err(|_| FirstSliceError::Adapter)?;
    for record in document
        .provenance
        .iter()
        .filter(|record| provenance_needing_projection.contains(&record.id))
    {
        check_cancellation(cancellation)?;
        // Projected derivation parents would need their own transitive identity
        // proof. Supplemental recovery is optional, so reject that unsupported
        // shape instead of treating changed parent IDs as equivalent.
        if !record.derivation_parents.is_empty() {
            continue;
        }
        let Some(primary) = project_provenance_to_primary(record, &by_file, cancellation)? else {
            continue;
        };
        expected_provenance.push((record.id, primary));
    }
    let expected_ids: BTreeSet<_> =
        collect_supplemental_cancellable(&expected_provenance, cancellation, |(_, primary)| {
            Some(primary.id)
        })?;
    let retained_provenance: BTreeMap<_, _> =
        collect_supplemental_cancellable(&merged.provenance, cancellation, |record| {
            expected_ids
                .contains(&record.id)
                .then_some((record.id, record))
        })?;
    let projected_provenance: BTreeMap<_, _> = collect_supplemental_cancellable(
        expected_provenance,
        cancellation,
        |(projected, primary)| {
            retained_provenance
                .get(&primary.id)
                .is_some_and(|retained| **retained == primary)
                .then_some((projected, primary.id))
        },
    )?;

    let mut required_occurrences = BTreeSet::new();
    for relation in &document.relations {
        check_cancellation(cancellation)?;
        for endpoint in [relation.subject, relation.object] {
            check_cancellation(cancellation)?;
            if let RelationEndpoint::Occurrence(occurrence) = endpoint {
                required_occurrences.insert(occurrence);
            }
        }
        for reference in &relation.evidence.derivation {
            check_cancellation(cancellation)?;
            if let FactRef::Fact(fact) = reference {
                required_occurrences.insert(*fact);
            }
        }
    }
    let projected_occurrences: BTreeSet<_> =
        collect_supplemental_cancellable(&document.occurrences, cancellation, |occurrence| {
            (required_occurrences.contains(&occurrence.id)
                && source_projects_to_primary(&occurrence.source, &by_file).is_some())
            .then_some(occurrence.id)
        })?;
    let required_consumer_files: BTreeSet<_> =
        collect_supplemental_cancellable(&document.occurrences, cancellation, |occurrence| {
            required_occurrences
                .contains(&occurrence.id)
                .then_some(occurrence.file)
        })?;
    let retained_consumer_files: BTreeMap<_, _> =
        collect_supplemental_cancellable(&merged.files, cancellation, |file| {
            required_consumer_files
                .contains(&file.id)
                .then_some((file.id, (file.content_hash, file.byte_length)))
        })?;
    let exact_consumer_occurrences: BTreeMap<_, _> =
        collect_supplemental_cancellable(&document.occurrences, cancellation, |occurrence| {
            let rootlight_ir::OccurrenceTarget::Resolved { symbol } = &occurrence.target else {
                return None;
            };
            let (primary_hash, primary_bytes) = retained_consumer_files.get(&occurrence.file)?;
            let source = &occurrence.source;
            (required_occurrences.contains(&occurrence.id)
                && occurrence.role == OccurrenceRole::CallSite
                && occurrence.repository == merged.repository
                && occurrence.generation == merged.generation
                && occurrence.file == source.span().file()
                && source.repository() == merged.repository
                && source.generation() == merged.generation
                && source.content_hash() == *primary_hash
                && source.span().end_byte() <= *primary_bytes)
                .then_some((occurrence.id, (*symbol, source)))
        })?;

    let mut remapped = Vec::new();
    remapped
        .try_reserve_exact(document.relations.len())
        .map_err(|_| FirstSliceError::Adapter)?;
    for mut relation in std::mem::take(&mut document.relations) {
        check_cancellation(cancellation)?;
        for _ in &relation.evidence.derivation {
            check_cancellation(cancellation)?;
        }
        // Prefix equality proves source bytes, not JavaScript or TypeScript
        // binding equivalence. Relations and occurrence facts must therefore
        // come from exact full-source consumers; projection is allowed only in
        // the provider provenance that is remapped below.
        if relation
            .evidence
            .source
            .as_ref()
            .is_some_and(|source| source_projects_to_primary(source, &by_file).is_some())
            || [relation.subject, relation.object]
                .into_iter()
                .any(|endpoint| {
                    matches!(
                        endpoint,
                        RelationEndpoint::Occurrence(occurrence)
                            if projected_occurrences.contains(&occurrence)
                    )
                })
            || relation.evidence.derivation.iter().any(|reference| {
                matches!(
                    reference,
                    FactRef::Fact(fact) if projected_occurrences.contains(fact)
                )
            })
        {
            continue;
        }
        let mut changed = false;
        let provenance_was_projected = provenance_needing_projection.contains(&relation.provenance);
        let derivation_uses_projected_provenance =
            relation.evidence.derivation.iter().any(|reference| {
                matches!(
                    reference,
                    FactRef::Fact(fact) if provenance_needing_projection.contains(fact)
                )
            });
        if provenance_was_projected || derivation_uses_projected_provenance {
            let (
                RelationPredicate::Calls,
                RelationEndpoint::Occurrence(occurrence),
                RelationEndpoint::Entity(target),
            ) = (relation.predicate, relation.subject, relation.object)
            else {
                continue;
            };
            let Some((resolved_target, occurrence_source)) =
                exact_consumer_occurrences.get(&occurrence)
            else {
                continue;
            };
            if target != *resolved_target
                || relation.evidence.source.as_ref() != Some(*occurrence_source)
            {
                continue;
            }
        }
        if provenance_was_projected {
            let Some(provenance) = projected_provenance.get(&relation.provenance).copied() else {
                continue;
            };
            relation.provenance = provenance;
            changed = true;
        }
        let mut unresolved_projection = false;
        for reference in &mut relation.evidence.derivation {
            check_cancellation(cancellation)?;
            let FactRef::Fact(fact) = reference else {
                continue;
            };
            if provenance_needing_projection.contains(fact) {
                let Some(primary) = projected_provenance.get(fact) else {
                    unresolved_projection = true;
                    break;
                };
                *fact = *primary;
                changed = true;
            }
        }
        if unresolved_projection {
            continue;
        }
        if changed {
            relation.id =
                derive_relation_record_id(&relation).map_err(|_| FirstSliceError::Adapter)?;
        }
        remapped.push(relation);
    }
    document.relations = remapped;
    Ok(())
}

fn project_provenance_to_primary(
    projected: &ProvenanceRecord,
    prefixes: &BTreeMap<FileId, FirstSliceSupplementalPrefix>,
    cancellation: &Cancellation,
) -> Result<Option<ProvenanceRecord>, FirstSliceError> {
    let Some(input_sources) =
        project_provenance_sources(&projected.input_sources, prefixes, cancellation)?
    else {
        return Ok(None);
    };
    let Some(evidence_sources) =
        project_provenance_sources(&projected.evidence_sources, prefixes, cancellation)?
    else {
        return Ok(None);
    };
    check_cancellation(cancellation)?;
    let mut primary = projected.clone();
    primary.id = FactId::from_bytes([0; 20]);
    primary.input_sources = input_sources;
    primary.evidence_sources = evidence_sources;
    primary.id = derive_provenance_record_id(&primary).map_err(|_| FirstSliceError::Adapter)?;
    Ok(Some(primary))
}

fn project_provenance_sources(
    sources: &[SourceRef],
    prefixes: &BTreeMap<FileId, FirstSliceSupplementalPrefix>,
    cancellation: &Cancellation,
) -> Result<Option<Vec<SourceRef>>, FirstSliceError> {
    let mut primary = Vec::new();
    primary
        .try_reserve_exact(sources.len())
        .map_err(|_| FirstSliceError::Adapter)?;
    for source in sources {
        check_cancellation(cancellation)?;
        let Some(prefix) = prefixes.get(&source.span().file()) else {
            primary.push(source.clone());
            continue;
        };
        let exact_primary = source.span().start_byte() == 0
            && source.span().end_byte() == prefix.primary_bytes
            && source.content_hash() == prefix.primary_content_hash;
        if exact_primary {
            primary.push(source.clone());
            continue;
        }
        let exact_projection = source.span().start_byte() == 0
            && source.span().end_byte() == prefix.projected_bytes
            && source.content_hash() == prefix.projected_content_hash;
        if !exact_projection {
            return Ok(None);
        }
        let span = SourceSpan::new(source.span().file(), 0, prefix.primary_bytes)
            .map_err(|_| FirstSliceError::Identity)?;
        primary.push(SourceRef::new(
            source.repository(),
            source.generation(),
            span,
            prefix.primary_content_hash,
            source.line_hint(),
        ));
    }
    Ok(Some(primary))
}

fn source_projects_to_primary(
    source: &SourceRef,
    prefixes: &BTreeMap<FileId, FirstSliceSupplementalPrefix>,
) -> Option<ContentHash> {
    let prefix = prefixes.get(&source.span().file())?;
    (source.content_hash() == prefix.projected_content_hash
        && source.span().end_byte() <= prefix.retained_prefix_bytes)
        .then_some(prefix.primary_content_hash)
}

fn remap_supplemental_occurrence_endpoints(
    merged: &NormalizedIrDocument,
    document: &mut NormalizedIrDocument,
    cancellation: &Cancellation,
) -> Result<(), FirstSliceError> {
    check_cancellation(cancellation)?;
    let mut call_targets = BTreeMap::new();
    let mut ambiguous_calls = BTreeSet::new();
    for relation in &document.relations {
        check_cancellation(cancellation)?;
        let (
            RelationPredicate::Calls,
            RelationEndpoint::Occurrence(occurrence),
            RelationEndpoint::Entity(target),
        ) = (relation.predicate, relation.subject, relation.object)
        else {
            continue;
        };
        if call_targets
            .insert(occurrence, target)
            .is_some_and(|previous| previous != target)
        {
            ambiguous_calls.insert(occurrence);
        }
    }
    for occurrence in &ambiguous_calls {
        check_cancellation(cancellation)?;
        call_targets.remove(occurrence);
    }

    let mut candidates = Vec::new();
    candidates
        .try_reserve_exact(call_targets.len())
        .map_err(|_| FirstSliceError::Adapter)?;
    for occurrence in document
        .occurrences
        .iter()
        .filter(|occurrence| call_targets.contains_key(&occurrence.id))
    {
        check_cancellation(cancellation)?;
        let Some(enclosing) = occurrence.enclosing else {
            continue;
        };
        let rootlight_ir::OccurrenceTarget::Resolved { symbol } = &occurrence.target else {
            continue;
        };
        if occurrence.role != OccurrenceRole::CallSite
            || call_targets.get(&occurrence.id) != Some(symbol)
            || occurrence.repository != merged.repository
            || occurrence.generation != merged.generation
            || occurrence.file != occurrence.source.span().file()
        {
            continue;
        }
        candidates.push((occurrence, enclosing, *symbol));
    }
    let required_files: BTreeSet<_> =
        collect_supplemental_cancellable(&candidates, cancellation, |(occurrence, _, _)| {
            Some(occurrence.file)
        })?;
    let mut required_entities = BTreeSet::new();
    for (_, enclosing, target) in &candidates {
        check_cancellation(cancellation)?;
        required_entities.insert(*enclosing);
        required_entities.insert(*target);
    }
    let retained_files: BTreeMap<_, _> =
        collect_supplemental_cancellable(&merged.files, cancellation, |file| {
            required_files
                .contains(&file.id)
                .then_some((file.id, (file.content_hash, file.byte_length)))
        })?;
    let retained_entities: BTreeSet<_> =
        collect_supplemental_cancellable(&merged.entities, cancellation, |entity| {
            required_entities.contains(&entity.id).then_some(entity.id)
        })?;
    let occurrences: BTreeMap<_, _> = collect_supplemental_cancellable(
        candidates,
        cancellation,
        |(occurrence, enclosing, target)| {
            if !retained_entities.contains(&enclosing) || !retained_entities.contains(&target) {
                return None;
            }
            let (primary_hash, primary_bytes) = retained_files.get(&occurrence.file)?;
            let source = &occurrence.source;
            let exact_primary = source.repository() == merged.repository
                && source.generation() == merged.generation
                && source.content_hash() == *primary_hash
                && source.span().end_byte() <= *primary_bytes;
            exact_primary.then_some((occurrence.id, (enclosing, target, source.clone())))
        },
    )?;

    let mut remapped = Vec::new();
    remapped
        .try_reserve_exact(document.relations.len())
        .map_err(|_| FirstSliceError::Adapter)?;
    for mut relation in std::mem::take(&mut document.relations) {
        check_cancellation(cancellation)?;
        let endpoint_occurrence = match (relation.subject, relation.object) {
            (RelationEndpoint::Occurrence(occurrence), RelationEndpoint::Entity(target))
                if relation.predicate == RelationPredicate::Calls =>
            {
                Some((occurrence, target))
            }
            (RelationEndpoint::Occurrence(_), _) | (_, RelationEndpoint::Occurrence(_)) => continue,
            _ => None,
        };
        let Some((occurrence, target)) = endpoint_occurrence else {
            remapped.push(relation);
            continue;
        };
        let Some((enclosing, resolved_target, occurrence_source)) = occurrences.get(&occurrence)
        else {
            continue;
        };
        if target != *resolved_target
            || relation.evidence.source.as_ref() != Some(occurrence_source)
        {
            continue;
        }
        relation.subject = RelationEndpoint::Entity(*enclosing);
        for reference in &mut relation.evidence.derivation {
            check_cancellation(cancellation)?;
            if *reference == FactRef::Fact(occurrence) {
                *reference = FactRef::Entity(*enclosing);
            }
        }
        relation.id = derive_relation_record_id(&relation).map_err(|_| FirstSliceError::Adapter)?;
        remapped.push(relation);
    }
    document.relations = remapped;
    Ok(())
}

fn supplemental_project_relations(
    merged: &NormalizedIrDocument,
    mut document: NormalizedIrDocument,
    prefixes: &[FirstSliceSupplementalPrefix],
    cancellation: &Cancellation,
) -> Result<Vec<RelationRecord>, FirstSliceError> {
    check_cancellation(cancellation)?;
    merged_document_version(merged, &document)?;
    remap_supplemental_prefix_relations(merged, &mut document, prefixes, cancellation)?;
    remap_supplemental_occurrence_endpoints(merged, &mut document, cancellation)?;

    let mut candidate_ids = BTreeSet::new();
    let mut relations = Vec::new();
    relations
        .try_reserve_exact(document.relations.len())
        .map_err(|_| FirstSliceError::Adapter)?;
    for relation in document.relations {
        check_cancellation(cancellation)?;
        if relation.repository == merged.repository
            && relation.generation == merged.generation
            && (relation.evidence.source.is_some() || !relation.evidence.derivation.is_empty())
            && candidate_ids.insert(relation.id)
        {
            relations.push(relation);
        }
    }
    if relations.is_empty() {
        return Ok(relations);
    }

    let mut required_files = BTreeSet::new();
    let mut required_entities = BTreeSet::new();
    let mut required_occurrences = BTreeSet::new();
    let mut required_facts = BTreeSet::new();
    let mut required_provenance = BTreeSet::new();
    for relation in &relations {
        check_cancellation(cancellation)?;
        for endpoint in [relation.subject, relation.object] {
            check_cancellation(cancellation)?;
            match endpoint {
                RelationEndpoint::Repository(_) => {}
                RelationEndpoint::File(file) => {
                    required_files.insert(file);
                }
                RelationEndpoint::Entity(entity) => {
                    required_entities.insert(entity);
                }
                RelationEndpoint::Occurrence(occurrence) => {
                    required_occurrences.insert(occurrence);
                }
            }
        }
        if let Some(source) = &relation.evidence.source {
            required_files.insert(source.span().file());
        }
        for reference in &relation.evidence.derivation {
            check_cancellation(cancellation)?;
            match reference {
                FactRef::File(file) => {
                    required_files.insert(*file);
                }
                FactRef::Entity(entity) => {
                    required_entities.insert(*entity);
                }
                FactRef::Fact(fact) => {
                    required_facts.insert(*fact);
                }
            }
        }
        required_provenance.insert(relation.provenance);
    }

    let retained_files: BTreeMap<_, _> =
        collect_supplemental_cancellable(&merged.files, cancellation, |file| {
            required_files
                .contains(&file.id)
                .then_some((file.id, (file.content_hash, file.byte_length)))
        })?;
    let retained_entities: BTreeSet<_> =
        collect_supplemental_cancellable(&merged.entities, cancellation, |entity| {
            required_entities.contains(&entity.id).then_some(entity.id)
        })?;
    let retained_occurrences: BTreeSet<_> =
        collect_supplemental_cancellable(&merged.occurrences, cancellation, |occurrence| {
            required_occurrences
                .contains(&occurrence.id)
                .then_some(occurrence.id)
        })?;
    let retained_provenance: BTreeSet<_> =
        collect_supplemental_cancellable(&merged.provenance, cancellation, |record| {
            required_provenance
                .contains(&record.id)
                .then_some(record.id)
        })?;
    let merged_fact_ids = merged
        .occurrences
        .iter()
        .map(|record| record.id)
        .chain(merged.relations.iter().map(|record| record.id))
        .chain(merged.provenance.iter().map(|record| record.id))
        .chain(merged.source_mappings.iter().map(|record| record.id))
        .chain(merged.coverage_records.iter().map(|record| record.id))
        .chain(merged.skipped_regions.iter().map(|record| record.id))
        .chain(merged.diagnostics.iter().map(|record| record.id))
        .chain(merged.extensions.iter().map(|record| record.id));
    let mut retained_facts = BTreeSet::new();
    let mut colliding_relation_ids = BTreeSet::new();
    for fact in merged_fact_ids {
        check_cancellation(cancellation)?;
        if required_facts.contains(&fact) {
            retained_facts.insert(fact);
        }
        if candidate_ids.contains(&fact) {
            colliding_relation_ids.insert(fact);
        }
    }

    let mut retained_relations = Vec::new();
    retained_relations
        .try_reserve_exact(relations.len())
        .map_err(|_| FirstSliceError::Adapter)?;
    for relation in relations {
        check_cancellation(cancellation)?;
        for _ in &relation.evidence.derivation {
            check_cancellation(cancellation)?;
        }
        if !colliding_relation_ids.contains(&relation.id)
            && retained_provenance.contains(&relation.provenance)
            && supplemental_relation_endpoint_resolves(
                relation.subject,
                merged.repository,
                &retained_files,
                &retained_entities,
                &retained_occurrences,
            )
            && supplemental_relation_endpoint_resolves(
                relation.object,
                merged.repository,
                &retained_files,
                &retained_entities,
                &retained_occurrences,
            )
            && relation.evidence.source.as_ref().is_none_or(|source| {
                source.repository() == merged.repository
                    && source.generation() == merged.generation
                    && retained_files.get(&source.span().file()).is_some_and(
                        |(content_hash, byte_length)| {
                            source.content_hash() == *content_hash
                                && source.span().end_byte() <= *byte_length
                        },
                    )
            })
            && relation
                .evidence
                .derivation
                .iter()
                .all(|reference| match reference {
                    FactRef::File(file) => retained_files.contains_key(file),
                    FactRef::Entity(entity) => retained_entities.contains(entity),
                    FactRef::Fact(fact) => retained_facts.contains(fact),
                })
        {
            retained_relations.push(relation);
        }
    }
    Ok(retained_relations)
}

fn supplemental_relation_endpoint_resolves(
    endpoint: RelationEndpoint,
    repository: RepositoryId,
    files: &BTreeMap<FileId, (ContentHash, u64)>,
    entities: &BTreeSet<SymbolId>,
    occurrences: &BTreeSet<FactId>,
) -> bool {
    match endpoint {
        RelationEndpoint::Repository(endpoint_repository) => endpoint_repository == repository,
        RelationEndpoint::File(file) => files.contains_key(&file),
        RelationEndpoint::Entity(entity) => entities.contains(&entity),
        RelationEndpoint::Occurrence(occurrence) => occurrences.contains(&occurrence),
    }
}

fn merge_project_document(
    merged: &mut NormalizedIrDocument,
    mut document: NormalizedIrDocument,
    external_symbols: &mut BTreeSet<SymbolId>,
    diagnostic_capacity: usize,
    limits: &IrLimits,
) -> Result<ProjectMergeTruncation, FirstSliceError> {
    let version = merged_document_version(merged, &document)?;
    let mut duplicate_external_symbols = BTreeSet::new();
    let mut new_external_symbols = BTreeSet::new();
    document.entities.retain(|entity| {
        entity.kind != EntityKind::ExternalSymbol
            || if !external_symbols.contains(&entity.id) && new_external_symbols.insert(entity.id) {
                true
            } else {
                duplicate_external_symbols.insert(entity.id);
                false
            }
    });
    if !duplicate_external_symbols.is_empty() {
        document.extensions.retain(|extension| {
            if extension.namespace != SYMBOL_IDENTITY_CLAIM_NAMESPACE {
                return true;
            }
            let [FactRef::Entity(symbol)] = extension.evidence.derivation.as_slice() else {
                return true;
            };
            !duplicate_external_symbols.contains(symbol)
        });
    }
    drop(new_external_symbols);
    let mut diagnostics_truncated = merged.diagnostics.len() > diagnostic_capacity;
    merged.diagnostics.truncate(diagnostic_capacity);
    let remaining_diagnostics = diagnostic_capacity.saturating_sub(merged.diagnostics.len());
    diagnostics_truncated |= document.diagnostics.len() > remaining_diagnostics;
    document.diagnostics.truncate(remaining_diagnostics);
    let mut facts_truncated = false;
    match preflight_normalized_document_append(merged, &document, limits) {
        Ok(()) => {}
        Err(FirstSliceError::ResourceLimit { .. }) => {
            retain_project_capacity_summary(&mut document)?;
            facts_truncated = true;
            preflight_normalized_document_append(merged, &document, limits)?;
            validate_project_capacity_summary(&document, limits)?;
        }
        Err(error) => return Err(error),
    }
    if let Err(error) = reserve_project_merge(merged, &document) {
        if error != FirstSliceError::Limits || facts_truncated {
            return Err(error);
        }
        retain_project_capacity_summary(&mut document)?;
        facts_truncated = true;
        preflight_normalized_document_append(merged, &document, limits)?;
        validate_project_capacity_summary(&document, limits)?;
        reserve_project_merge(merged, &document)?;
    }
    external_symbols.extend(
        document
            .entities
            .iter()
            .filter_map(|entity| (entity.kind == EntityKind::ExternalSymbol).then_some(entity.id)),
    );
    merged.version = version;
    merged.files.append(&mut document.files);
    merged.entities.append(&mut document.entities);
    merged.occurrences.append(&mut document.occurrences);
    merged.relations.append(&mut document.relations);
    merged.provenance.append(&mut document.provenance);
    merged.source_mappings.append(&mut document.source_mappings);
    merged
        .coverage_records
        .append(&mut document.coverage_records);
    merged.skipped_regions.append(&mut document.skipped_regions);
    merged.diagnostics.append(&mut document.diagnostics);
    merged.extensions.append(&mut document.extensions);
    Ok(ProjectMergeTruncation {
        diagnostics: diagnostics_truncated,
        facts: facts_truncated,
    })
}

fn reserve_project_merge(
    merged: &mut NormalizedIrDocument,
    document: &NormalizedIrDocument,
) -> Result<(), FirstSliceError> {
    merged
        .files
        .try_reserve_exact(document.files.len())
        .map_err(|_| FirstSliceError::Limits)?;
    merged
        .entities
        .try_reserve_exact(document.entities.len())
        .map_err(|_| FirstSliceError::Limits)?;
    merged
        .occurrences
        .try_reserve_exact(document.occurrences.len())
        .map_err(|_| FirstSliceError::Limits)?;
    merged
        .relations
        .try_reserve_exact(document.relations.len())
        .map_err(|_| FirstSliceError::Limits)?;
    merged
        .provenance
        .try_reserve_exact(document.provenance.len())
        .map_err(|_| FirstSliceError::Limits)?;
    merged
        .source_mappings
        .try_reserve_exact(document.source_mappings.len())
        .map_err(|_| FirstSliceError::Limits)?;
    merged
        .coverage_records
        .try_reserve_exact(document.coverage_records.len())
        .map_err(|_| FirstSliceError::Limits)?;
    merged
        .skipped_regions
        .try_reserve_exact(document.skipped_regions.len())
        .map_err(|_| FirstSliceError::Limits)?;
    merged
        .diagnostics
        .try_reserve_exact(document.diagnostics.len())
        .map_err(|_| FirstSliceError::Limits)?;
    merged
        .extensions
        .try_reserve_exact(document.extensions.len())
        .map_err(|_| FirstSliceError::Limits)?;
    Ok(())
}

fn prepare_project_analysis_document(
    documents: Vec<NormalizedIrDocument>,
    language: &str,
    partitioned: bool,
    diagnostics_truncated: bool,
    facts_truncated: bool,
    existing_target_diagnostics: usize,
    limits: &IrLimits,
) -> Result<NormalizedIrDocument, FirstSliceError> {
    // The project document is appended to the structural target, so its local
    // quota must account for diagnostics already owned by earlier providers.
    let available_diagnostics = limits
        .max_diagnostics
        .checked_sub(existing_target_diagnostics)
        .ok_or(FirstSliceError::Limits)?;
    let requested_reserve = if partitioned {
        PROJECT_PARTITION_DIAGNOSTIC_RESERVE
    } else {
        1
    };
    let diagnostic_reserve = available_diagnostics.min(requested_reserve);
    let diagnostic_capacity = available_diagnostics - diagnostic_reserve;
    let (mut document, merge_truncation) = merge_project_documents(documents, diagnostic_capacity)?;
    let diagnostics_truncated = diagnostics_truncated || merge_truncation.diagnostics;
    let facts_truncated = facts_truncated || merge_truncation.facts;
    if partitioned || diagnostics_truncated || facts_truncated {
        bound_project_coverage(&mut document)?;
    }
    let mut remaining_reserve = diagnostic_reserve;
    if facts_truncated && remaining_reserve > 0 {
        append_project_facts_truncated(&mut document, limits)?;
        remaining_reserve -= 1;
    }
    if diagnostics_truncated && remaining_reserve > 0 {
        append_project_diagnostics_truncated(&mut document, limits)?;
        remaining_reserve -= 1;
    }
    if partitioned && remaining_reserve > 0 {
        append_project_partition_diagnostic(&mut document, language, limits)?;
    }
    let combined_diagnostics = existing_target_diagnostics
        .checked_add(document.diagnostics.len())
        .ok_or(FirstSliceError::Limits)?;
    if combined_diagnostics > limits.max_diagnostics {
        return Err(FirstSliceError::Limits);
    }
    Ok(document)
}

fn bound_project_coverage(document: &mut NormalizedIrDocument) -> Result<(), FirstSliceError> {
    for coverage in &mut document.coverage_records {
        if coverage.tier == AnalysisTier::TierB && coverage.status == CoverageStatus::Complete {
            coverage.status = CoverageStatus::Bounded;
            coverage.id =
                derive_coverage_record_id(coverage).map_err(|_| FirstSliceError::Identity)?;
        }
    }
    Ok(())
}

