#[derive(Debug, Default, Clone, PartialEq, Eq)]
struct DocumentAppendState {
    aggregate_recovery: bool,
    usage: Option<IrDocumentUsage>,
    extension_payload_bytes: usize,
    // None invalidates all extension totals, including the cached byte scalar.
    required_extension_usage: Option<(usize, usize)>,
    // Repeated admission pressure otherwise rescans and decodes an unchanged
    // aggregate. Only a completed canonical search proves this prefix safe.
    summary_free_prefix: usize,
    optional_metadata: Option<optional_extension_metadata::Cache>,
    truncated_diagnostics: u64,
    truncated_extensions: u64,
    truncated_skipped_regions: u64,
}

impl DocumentAppendState {
    fn from_document(document: &NormalizedIrDocument) -> Result<Self, FirstSliceError> {
        let (extension_payload_bytes, required_extension_usage) =
            measure_target_extension_usage(&document.extensions, &Cancellation::new())?;
        Ok(Self {
            aggregate_recovery: false,
            usage: None,
            extension_payload_bytes,
            required_extension_usage: Some(required_extension_usage),
            summary_free_prefix: 0,
            optional_metadata: None,
            truncated_diagnostics: 0,
            truncated_extensions: 0,
            truncated_skipped_regions: 0,
        })
    }

    fn invalidate_usage(&mut self) {
        self.usage = None;
        self.required_extension_usage = None;
        self.summary_free_prefix = 0;
        if let Some(metadata) = &mut self.optional_metadata {
            metadata.invalidate();
        }
    }
}

fn merged_document_version(
    target: &NormalizedIrDocument,
    source: &NormalizedIrDocument,
) -> Result<NormalizedIrVersion, FirstSliceError> {
    if source.repository != target.repository || source.generation != target.generation {
        return Err(FirstSliceError::Identity);
    }
    if target.version == source.version {
        return Ok(target.version);
    }
    // Only the lower-version partition needs a transition check. Rescanning
    // the growing higher-version aggregate for every file would be quadratic.
    let lower = if target.version < source.version {
        target
    } else {
        source
    };
    if lower
        .entities
        .iter()
        .any(|entity| entity.kind.minimum_ir_version() > lower.version)
    {
        return Err(FirstSliceError::Identity);
    }
    Ok(target.version.max(source.version))
}

