struct PreparedDocumentAppend {
    source: NormalizedIrDocument,
    version: NormalizedIrVersion,
    target_usage: IrDocumentUsage,
    source_usage: IrDocumentUsage,
    dropped_target_diagnostic: Option<usize>,
    extension_plan: OptionalExtensionPlan,
    profile_file: Option<FileId>,
    context_free_source: bool,
}

fn append_optional_planning_limits(
    limits: &IrLimits,
    reserved: Option<&IrDocumentUsage>,
) -> Result<IrLimits, FirstSliceError> {
    let mut planning = limits.clone();
    if let Some(reserved) = reserved {
        planning.max_diagnostics = planning
            .max_diagnostics
            .checked_sub(reserved.diagnostics())
            .ok_or(FirstSliceError::Limits)?;
        planning.max_skipped_regions = planning
            .max_skipped_regions
            .checked_sub(reserved.skipped_regions())
            .ok_or(FirstSliceError::Limits)?;
        planning.max_extensions = planning
            .max_extensions
            .checked_sub(reserved.extensions())
            .ok_or(FirstSliceError::Limits)?;
        planning.max_total_extension_bytes = planning
            .max_total_extension_bytes
            .checked_sub(reserved.total_extension_bytes())
            .ok_or(FirstSliceError::Limits)?;
    }
    Ok(planning)
}

fn append_usage_error(
    error: IrDocumentUsageError,
    aggregate_recovery: bool,
    cancellation: &Cancellation,
) -> FirstSliceError {
    if let Some(cancelled) = current_cancellation(cancellation) {
        return cancelled;
    }
    if aggregate_recovery && let Some(cause) = AggregateCapacityFailure::from_combined_usage(&error)
    {
        return FirstSliceError::AggregateCapacity(cause);
    }
    map_ir_usage_error(error, cancellation)
}

fn reserved_optional_planning_error(
    original: FirstSliceError,
    target: &NormalizedIrDocument,
    source: &NormalizedIrDocument,
    reserved: Option<&IrDocumentUsage>,
    limits: &IrLimits,
    aggregate_recovery: bool,
    cancellation: &Cancellation,
) -> FirstSliceError {
    // Only a required-extension refusal can arise from the smaller optional
    // planning room. Measure real required envelopes under generation limits;
    // no cause is minted from the local limit or a generic numeric error.
    if !matches!(
        original,
        FirstSliceError::ResourceLimit {
            resource: FirstSliceResource::Extensions | FirstSliceResource::ExtensionBytes,
            ..
        }
    ) {
        return original;
    }
    let Some(reserved) = reserved else {
        return original;
    };
    let combined = target
        .extensions
        .iter()
        .chain(&source.extensions)
        .filter(|extension| extension.namespace != LEXICAL_EXTENSION_NAMESPACE)
        .try_fold(IrDocumentUsage::default(), |usage, extension| {
            check_cancellation(cancellation)?;
            let required = IrDocumentUsage::measure_extension(extension, limits)
                .map_err(|error| append_usage_error(error, aggregate_recovery, cancellation))?;
            usage
                .checked_add(required, limits)
                .map_err(|error| append_usage_error(error, aggregate_recovery, cancellation))
        })
        .and_then(|usage| {
            usage
                .checked_add(reserved.clone(), limits)
                .map_err(|error| append_usage_error(error, aggregate_recovery, cancellation))
        });

    match combined {
        Ok(_) => original,
        Err(actual) => actual,
    }
}

fn append_normalized_document_with_metadata_admission(
    target: &mut NormalizedIrDocument,
    source: NormalizedIrDocument,
    limits: &IrLimits,
    append_state: &mut DocumentAppendState,
    cancellation: &Cancellation,
    admission: optional_extension_metadata::Admission<'_>,
) -> Result<(), FirstSliceError> {
    let prepared = prepare_normalized_document_append(
        target,
        source,
        limits,
        append_state,
        cancellation,
        admission,
        None,
    )?;
    commit_prepared_document_append(target, prepared, limits, append_state, cancellation)
}

fn prepare_normalized_document_append(
    target: &NormalizedIrDocument,
    mut source: NormalizedIrDocument,
    limits: &IrLimits,
    append_state: &DocumentAppendState,
    cancellation: &Cancellation,
    admission: optional_extension_metadata::Admission<'_>,
    reserved: Option<&IrDocumentUsage>,
) -> Result<PreparedDocumentAppend, FirstSliceError> {
    check_cancellation(cancellation)?;
    let version = merged_document_version(target, &source)?;
    let planning_limits = append_optional_planning_limits(limits, reserved)?;
    let profile_file = if analysis_profile_enabled() && source.files.len() == 1 {
        source.files.first().map(|file| file.id)
    } else {
        None
    };
    let profile =
        AnalysisProfileGuard::begin(AnalysisProfilePhase::AppendLexicalCompaction, profile_file);
    compact_lexical_summaries_with_cancellation(&mut source, limits, cancellation)?;
    profile.finish();
    let profile =
        AnalysisProfileGuard::begin(AnalysisProfilePhase::AppendTargetUsage, profile_file);
    let mut target_usage = match &append_state.usage {
        Some(usage) => {
            with_analysis_profile(|profile| {
                increment_profile_count(
                    &mut profile.append.target_usage_cache_hits,
                    &mut profile.counts_complete,
                )
            });
            usage.clone()
        }
        None => {
            with_analysis_profile(|profile| {
                increment_profile_count(
                    &mut profile.append.target_usage_cache_misses,
                    &mut profile.counts_complete,
                )
            });
            measure_append_usage(target, limits, cancellation)?
        }
    };
    profile.finish();
    let profile = AnalysisProfileGuard::begin(
        AnalysisProfilePhase::AppendGapAndDiagnosticPlanning,
        profile_file,
    );
    let truncated_skipped_regions =
        truncate_skipped_regions(target, &mut source, &planning_limits)?;
    let diagnostic_plan = plan_aggregate_diagnostics(
        target,
        &mut source,
        append_state,
        &planning_limits,
        cancellation,
    )?;
    let dropped_target_diagnostic = diagnostic_plan.dropped_target_index;
    if let Some(index) = dropped_target_diagnostic {
        let removed = IrDocumentUsage::measure_diagnostic(&target.diagnostics[index], limits)
            .map_err(|error| map_ir_usage_error(error, cancellation))?;
        target_usage = target_usage
            .checked_sub(removed)
            .map_err(|error| map_ir_usage_error(error, cancellation))?;
    }
    profile.finish();
    let profile = AnalysisProfileGuard::begin(
        AnalysisProfilePhase::AppendOptionalExtensionPlanning,
        profile_file,
    );
    let extension_plan = plan_optional_extensions_with_metadata_admission(
        target,
        &mut source,
        append_state,
        diagnostic_plan,
        truncated_skipped_regions,
        &planning_limits,
        optional_extension_metadata::PlanningContext {
            cancellation,
            admission,
        },
    )
    .map_err(|error| {
        reserved_optional_planning_error(
            error,
            target,
            &source,
            reserved,
            limits,
            append_state.aggregate_recovery,
            cancellation,
        )
    })?;
    for &index in &extension_plan.dropped_target_indices {
        check_cancellation(cancellation)?;
        let removed = IrDocumentUsage::measure_extension(&target.extensions[index], limits)
            .map_err(|error| map_ir_usage_error(error, cancellation))?;
        target_usage = target_usage
            .checked_sub(removed)
            .map_err(|error| map_ir_usage_error(error, cancellation))?;
    }
    profile.finish();
    let profile = AnalysisProfileGuard::begin(
        AnalysisProfilePhase::AppendSourceUsageAndQuota,
        profile_file,
    );
    let source_usage = measure_append_usage(&source, limits, cancellation)?;
    let combined_usage = target_usage
        .clone()
        .checked_add(source_usage.clone(), limits)
        .map_err(|error| {
            if let Some(cancelled) = current_cancellation(cancellation) {
                return cancelled;
            }
            if append_state.aggregate_recovery
                && let Some(cause) = AggregateCapacityFailure::from_combined_usage(&error)
            {
                return FirstSliceError::AggregateCapacity(cause);
            }
            map_ir_usage_error(error, cancellation)
        })?;
    if let Some(reserved) = reserved {
        combined_usage
            .clone()
            .checked_add(reserved.clone(), limits)
            .map_err(|error| {
                append_usage_error(error, append_state.aggregate_recovery, cancellation)
            })?;
    }
    profile.finish();

    let context_free_source = extension_plan.next_state.truncated_diagnostics == 0
        && extension_plan.next_state.truncated_extensions == 0
        && extension_plan.next_state.truncated_skipped_regions == 0;
    Ok(PreparedDocumentAppend {
        source,
        version,
        target_usage,
        source_usage,
        dropped_target_diagnostic,
        extension_plan,
        profile_file,
        context_free_source,
    })
}

fn commit_prepared_document_append(
    target: &mut NormalizedIrDocument,
    prepared: PreparedDocumentAppend,
    limits: &IrLimits,
    append_state: &mut DocumentAppendState,
    cancellation: &Cancellation,
) -> Result<(), FirstSliceError> {
    check_cancellation(cancellation)?;
    let PreparedDocumentAppend {
        source,
        version,
        target_usage,
        source_usage,
        dropped_target_diagnostic,
        extension_plan,
        profile_file,
        ..
    } = prepared;
    let combined_usage = target_usage
        .checked_add(source_usage, limits)
        .map_err(|error| {
            append_usage_error(error, append_state.aggregate_recovery, cancellation)
        })?;
    // Plans and quota checks leave target facts untouched. Reserve every append
    // before applying removals or coverage patches; commit then cannot fail.
    let profile =
        AnalysisProfileGuard::begin(AnalysisProfilePhase::AppendReservations, profile_file);
    reserve_resource_records(
        &mut target.files,
        source.files.len(),
        limits.max_files,
        FirstSliceResource::Files,
    )?;
    reserve_resource_records(
        &mut target.entities,
        source.entities.len(),
        limits.max_entities,
        FirstSliceResource::Entities,
    )?;
    reserve_resource_records(
        &mut target.occurrences,
        source.occurrences.len(),
        limits.max_occurrences,
        FirstSliceResource::Occurrences,
    )?;
    reserve_resource_records(
        &mut target.relations,
        source.relations.len(),
        limits.max_relations,
        FirstSliceResource::Relations,
    )?;
    reserve_resource_records(
        &mut target.provenance,
        source.provenance.len(),
        limits.max_provenance_records,
        FirstSliceResource::Provenance,
    )?;
    reserve_resource_records(
        &mut target.source_mappings,
        source.source_mappings.len(),
        limits.max_source_mappings,
        FirstSliceResource::SourceMappings,
    )?;
    reserve_resource_records(
        &mut target.coverage_records,
        source.coverage_records.len(),
        limits.max_coverage_records,
        FirstSliceResource::Coverage,
    )?;
    reserve_resource_records(
        &mut target.skipped_regions,
        source.skipped_regions.len(),
        limits.max_skipped_regions,
        FirstSliceResource::SkippedRegions,
    )?;
    reserve_resource_records(
        &mut target.diagnostics,
        source.diagnostics.len(),
        limits.max_diagnostics,
        FirstSliceResource::Diagnostics,
    )?;
    target
        .extensions
        .try_reserve(source.extensions.len())
        .map_err(|_| FirstSliceError::Limits)?;
    check_cancellation(cancellation)?;
    profile.finish();

    let profile = AnalysisProfileGuard::begin(AnalysisProfilePhase::AppendCommit, profile_file);
    if let Some(index) = dropped_target_diagnostic {
        target.diagnostics.remove(index);
    }
    let mut next_append_state = extension_plan.apply(target, &mut append_state.optional_metadata);
    next_append_state.aggregate_recovery = append_state.aggregate_recovery;
    next_append_state.usage = Some(combined_usage);

    let NormalizedIrDocument {
        mut files,
        mut entities,
        mut occurrences,
        mut relations,
        mut provenance,
        mut source_mappings,
        mut coverage_records,
        mut skipped_regions,
        mut diagnostics,
        mut extensions,
        ..
    } = source;
    target.version = version;
    target.files.append(&mut files);
    target.entities.append(&mut entities);
    target.occurrences.append(&mut occurrences);
    target.relations.append(&mut relations);
    target.provenance.append(&mut provenance);
    target.source_mappings.append(&mut source_mappings);
    target.coverage_records.append(&mut coverage_records);
    target.skipped_regions.append(&mut skipped_regions);
    target.diagnostics.append(&mut diagnostics);
    target.extensions.append(&mut extensions);
    *append_state = next_append_state;
    profile.finish();
    Ok(())
}

#[cfg(test)]
fn append_project_document_with_capacity(
    target: &mut NormalizedIrDocument,
    source: NormalizedIrDocument,
    limits: &IrLimits,
    append_state: &mut DocumentAppendState,
) -> Result<(), FirstSliceError> {
    append_project_document_with_capacity_with_cancellation(
        target,
        source,
        limits,
        append_state,
        &Cancellation::new(),
    )
}

#[cfg(test)]
fn append_project_document_with_capacity_with_cancellation(
    target: &mut NormalizedIrDocument,
    source: NormalizedIrDocument,
    limits: &IrLimits,
    append_state: &mut DocumentAppendState,
    cancellation: &Cancellation,
) -> Result<(), FirstSliceError> {
    append_project_document_with_metadata_admission(
        target,
        source,
        limits,
        append_state,
        cancellation,
        None,
    )
}

fn append_project_document_with_metadata_admission(
    target: &mut NormalizedIrDocument,
    source: NormalizedIrDocument,
    limits: &IrLimits,
    append_state: &mut DocumentAppendState,
    cancellation: &Cancellation,
    admission: optional_extension_metadata::Admission<'_>,
) -> Result<(), FirstSliceError> {
    check_cancellation(cancellation)?;
    // Decide whether to retain full project facts before the shared append path
    // can reserve or truncate any target-owned collection.
    preflight_normalized_document_append(target, &source, limits)?;
    append_normalized_document_with_metadata_admission(
        target,
        source,
        limits,
        append_state,
        cancellation,
        admission,
    )?;
    Ok(())
}

fn measure_append_usage(
    document: &NormalizedIrDocument,
    limits: &IrLimits,
    cancellation: &Cancellation,
) -> Result<IrDocumentUsage, FirstSliceError> {
    IrDocumentUsage::measure_with_checkpoint(document, limits, || cancellation.check().is_ok())
        .map_err(|error| map_ir_usage_error(error, cancellation))
}

fn map_ir_usage_error(error: IrDocumentUsageError, cancellation: &Cancellation) -> FirstSliceError {
    if let Some(cancelled) = current_cancellation(cancellation) {
        return cancelled;
    }
    match error {
        IrDocumentUsageError::AccountingOverflow => FirstSliceError::Limits,
        IrDocumentUsageError::Interrupted => {
            FirstSliceError::Cancelled(CancellationReason::ParentCancelled)
        }
        IrDocumentUsageError::Validation(error) => match error {
            IrDocumentValidationError::CollectionLimit {
                collection,
                observed,
                limit,
            } => resource_limit(
                ir_collection_resource(collection).unwrap_or(FirstSliceResource::NestedItems),
                observed,
                limit,
            ),
            IrDocumentValidationError::TotalRecordLimit { observed, limit } => {
                resource_limit(FirstSliceResource::Records, observed, limit)
            }
            IrDocumentValidationError::TotalNestedItemLimit { observed, limit } => {
                resource_limit(FirstSliceResource::NestedItems, observed, limit)
            }
            IrDocumentValidationError::StringLimit {
                observed, limit, ..
            }
            | IrDocumentValidationError::TotalStringLimit { observed, limit } => {
                resource_limit(FirstSliceResource::StringBytes, observed, limit)
            }
            IrDocumentValidationError::ExtensionPayloadLimit {
                observed, limit, ..
            }
            | IrDocumentValidationError::TotalExtensionBytesLimit { observed, limit } => {
                resource_limit(FirstSliceResource::ExtensionBytes, observed, limit)
            }
            IrDocumentValidationError::DiagnosticMessageLimit {
                observed, limit, ..
            }
            | IrDocumentValidationError::TotalDiagnosticBytesLimit { observed, limit } => {
                resource_limit(FirstSliceResource::DiagnosticBytes, observed, limit)
            }
            _ => FirstSliceError::Identity,
        },
    }
}

fn preflight_normalized_document_append(
    target: &NormalizedIrDocument,
    source: &NormalizedIrDocument,
    limits: &IrLimits,
) -> Result<(), FirstSliceError> {
    merged_document_version(target, source)?;
    for (current, additional, maximum, resource) in [
        (
            target.files.len(),
            source.files.len(),
            limits.max_files,
            FirstSliceResource::Files,
        ),
        (
            target.entities.len(),
            source.entities.len(),
            limits.max_entities,
            FirstSliceResource::Entities,
        ),
        (
            target.occurrences.len(),
            source.occurrences.len(),
            limits.max_occurrences,
            FirstSliceResource::Occurrences,
        ),
        (
            target.relations.len(),
            source.relations.len(),
            limits.max_relations,
            FirstSliceResource::Relations,
        ),
        (
            target.provenance.len(),
            source.provenance.len(),
            limits.max_provenance_records,
            FirstSliceResource::Provenance,
        ),
        (
            target.source_mappings.len(),
            source.source_mappings.len(),
            limits.max_source_mappings,
            FirstSliceResource::SourceMappings,
        ),
        (
            target.coverage_records.len(),
            source.coverage_records.len(),
            limits.max_coverage_records,
            FirstSliceResource::Coverage,
        ),
        (
            target.diagnostics.len(),
            source.diagnostics.len(),
            limits.max_diagnostics,
            FirstSliceResource::Diagnostics,
        ),
    ] {
        checked_resource_length(current, additional, maximum, resource)?;
    }
    checked_resource_length(
        target.skipped_regions.len(),
        0,
        limits.max_skipped_regions,
        FirstSliceResource::SkippedRegions,
    )?;

    let target_required_extensions = target
        .extensions
        .iter()
        .filter(|extension| extension.namespace != LEXICAL_EXTENSION_NAMESPACE)
        .count();
    let source_required_extensions = source
        .extensions
        .iter()
        .filter(|extension| extension.namespace != LEXICAL_EXTENSION_NAMESPACE)
        .count();
    checked_resource_length(
        target_required_extensions,
        source_required_extensions,
        limits.max_extensions,
        FirstSliceResource::Extensions,
    )?;
    let target_required_extension_bytes = extension_payload_bytes(
        target
            .extensions
            .iter()
            .filter(|extension| extension.namespace != LEXICAL_EXTENSION_NAMESPACE),
    )?;
    let source_required_extension_bytes = extension_payload_bytes(
        source
            .extensions
            .iter()
            .filter(|extension| extension.namespace != LEXICAL_EXTENSION_NAMESPACE),
    )?;
    checked_resource_length(
        target_required_extension_bytes,
        source_required_extension_bytes,
        limits.max_total_extension_bytes,
        FirstSliceResource::ExtensionBytes,
    )?;

    let available_skipped_regions = limits
        .max_skipped_regions
        .checked_sub(target.skipped_regions.len())
        .ok_or_else(|| {
            resource_limit(
                FirstSliceResource::SkippedRegions,
                target.skipped_regions.len(),
                limits.max_skipped_regions,
            )
        })?;
    let retained_source_skipped_regions =
        source.skipped_regions.len().min(available_skipped_regions);
    let target_non_extensions = normalized_record_count(target)?
        .checked_sub(target.extensions.len())
        .ok_or(FirstSliceError::Limits)?;
    let source_non_extensions = normalized_record_count(source)?
        .checked_sub(source.extensions.len())
        .and_then(|total| total.checked_sub(source.skipped_regions.len()))
        .and_then(|total| total.checked_add(retained_source_skipped_regions))
        .ok_or(FirstSliceError::Limits)?;
    let maximum_merged_extensions = target
        .extensions
        .len()
        .checked_add(source.extensions.len())
        .ok_or(FirstSliceError::Limits)?
        .min(limits.max_extensions);
    let maximum_total = target_non_extensions
        .checked_add(source_non_extensions)
        .and_then(|total| total.checked_add(maximum_merged_extensions))
        .ok_or(FirstSliceError::Limits)?;
    if maximum_total > limits.max_total_records {
        return Err(resource_limit(
            FirstSliceResource::Records,
            maximum_total,
            limits.max_total_records,
        ));
    }
    Ok(())
}

fn retain_project_capacity_summary(
    document: &mut NormalizedIrDocument,
) -> Result<(), FirstSliceError> {
    document.entities = Vec::new();
    document.occurrences = Vec::new();
    document.relations = Vec::new();
    document.source_mappings = Vec::new();
    document.skipped_regions = Vec::new();
    document.diagnostics = Vec::new();
    // File claims remain required for generation identity verification. Other
    // extensions can name entities or mappings omitted by this summary.
    document.extensions = std::mem::take(&mut document.extensions)
        .into_iter()
        .filter(|extension| extension.namespace == FILE_IDENTITY_CLAIM_NAMESPACE)
        .collect();
    for coverage in &mut document.coverage_records {
        coverage.status = CoverageStatus::Bounded;
        if !matches!(
            coverage.domain,
            IrFactDomain::Files | IrFactDomain::Provenance
        ) {
            coverage.indexed = 0;
            coverage.skipped = coverage.discovered;
        }
        coverage.evidence.derivation.clear();
        coverage.id = derive_coverage_record_id(coverage).map_err(|_| FirstSliceError::Identity)?;
    }
    Ok(())
}

fn validate_project_capacity_summary(
    document: &NormalizedIrDocument,
    limits: &IrLimits,
) -> Result<(), FirstSliceError> {
    // Callers preflight first so aggregate collection exhaustion keeps its
    // typed capacity error; a broken retained reference instead triggers fallback.
    rootlight_ir::validate_ir_document(document, limits, &ExtensionSupport::default())
        .map_err(|_| FirstSliceError::Identity)
}

fn truncate_skipped_regions(
    target: &NormalizedIrDocument,
    source: &mut NormalizedIrDocument,
    limits: &IrLimits,
) -> Result<u64, FirstSliceError> {
    let available = limits
        .max_skipped_regions
        .checked_sub(target.skipped_regions.len())
        .ok_or_else(|| {
            resource_limit(
                FirstSliceResource::SkippedRegions,
                target.skipped_regions.len(),
                limits.max_skipped_regions,
            )
        })?;
    let retained = source.skipped_regions.len().min(available);
    let truncated = source
        .skipped_regions
        .len()
        .checked_sub(retained)
        .ok_or(FirstSliceError::Limits)?;
    source.skipped_regions.truncate(retained);
    u64::try_from(truncated).map_err(|_| FirstSliceError::Limits)
}

struct CoverageAdjustment {
    index: usize,
    id: FactId,
    indexed: u64,
    skipped: u64,
    status: CoverageStatus,
}

#[derive(Default)]
struct CoverageAdjustmentPlan {
    patches: Vec<CoverageAdjustment>,
}

impl CoverageAdjustmentPlan {
    fn extend(
        &mut self,
        existing: &[CoverageRecord],
        domain: IrFactDomain,
        dropped_by_file: &BTreeMap<(FileId, FactId), u64>,
        source_free_dropped: u64,
        cancellation: &Cancellation,
    ) -> Result<(), FirstSliceError> {
        check_cancellation(cancellation)?;
        if dropped_by_file.is_empty() && source_free_dropped == 0 {
            return Ok(());
        }
        let mut keys = Vec::new();
        keys.try_reserve_exact(dropped_by_file.len())
            .map_err(|_| FirstSliceError::Limits)?;
        for (&key, &dropped) in dropped_by_file {
            check_cancellation(cancellation)?;
            keys.push((key, dropped, false));
        }
        // BTreeMap iteration supplies sorted keys. Match a growing aggregate
        // once, rather than rescan every coverage row for each omitted file.
        for (index, coverage) in existing.iter().enumerate() {
            check_cancellation(cancellation)?;
            if coverage.domain != domain {
                continue;
            }
            let dropped = match coverage.scope {
                CoverageScope::File(file) => {
                    match keys.binary_search_by_key(&(file, coverage.provenance), |entry| entry.0) {
                        Ok(position) => {
                            let entry = &mut keys[position];
                            if entry.2 {
                                return Err(FirstSliceError::Identity);
                            }
                            entry.2 = true;
                            entry.1
                        }
                        Err(_) => 0,
                    }
                }
                _ => 0,
            };
            if dropped == 0
                && (source_free_dropped == 0 || coverage.status == CoverageStatus::Unknown)
            {
                continue;
            }
            // Only the changed record is copied for its identity recipe; the
            // plan retains scalars, not another growing coverage collection.
            let mut adjusted = coverage.clone();
            adjusted.indexed = adjusted
                .indexed
                .checked_sub(dropped)
                .ok_or(FirstSliceError::Identity)?;
            adjusted.skipped = adjusted
                .skipped
                .checked_add(dropped)
                .ok_or(FirstSliceError::Limits)?;
            if adjusted.status != CoverageStatus::Unknown {
                adjusted.status = CoverageStatus::Bounded;
            }
            let id = rootlight_ir::derive_coverage_record_id_with_checkpoint(&adjusted, || {
                cancellation.check().is_ok()
            })
            .map_err(|_| current_cancellation(cancellation).unwrap_or(FirstSliceError::Identity))?;
            self.patches
                .try_reserve(1)
                .map_err(|_| FirstSliceError::Limits)?;
            self.patches.push(CoverageAdjustment {
                index,
                id,
                indexed: adjusted.indexed,
                skipped: adjusted.skipped,
                status: adjusted.status,
            });
        }
        for (_, _, matched) in keys {
            check_cancellation(cancellation)?;
            if !matched {
                return Err(FirstSliceError::Identity);
            }
        }
        check_cancellation(cancellation)
    }

    fn apply(self, existing: &mut [CoverageRecord]) {
        for patch in self.patches {
            // The private plan was built from this unchanged slice. Applying
            // validated scalar edits cannot allocate or introduce a late error.
            let coverage = &mut existing[patch.index];
            coverage.id = patch.id;
            coverage.indexed = patch.indexed;
            coverage.skipped = patch.skipped;
            coverage.status = patch.status;
        }
    }
}

struct DiagnosticTruncationPlan {
    truncated: u64,
    dropped_target_index: Option<usize>,
    coverage: CoverageAdjustmentPlan,
}

fn plan_aggregate_diagnostics(
    target: &NormalizedIrDocument,
    source: &mut NormalizedIrDocument,
    append_state: &DocumentAppendState,
    limits: &IrLimits,
    cancellation: &Cancellation,
) -> Result<DiagnosticTruncationPlan, FirstSliceError> {
    check_cancellation(cancellation)?;
    let mut available = limits
        .max_diagnostics
        .checked_sub(target.diagnostics.len())
        .ok_or_else(|| {
            resource_limit(
                FirstSliceResource::Diagnostics,
                target.diagnostics.len(),
                limits.max_diagnostics,
            )
        })?;
    let requested_total = source
        .diagnostics
        .len()
        .checked_add(usize::from(append_state.truncated_diagnostics > 0))
        .ok_or(FirstSliceError::Limits)?;
    if requested_total <= available {
        return Ok(DiagnosticTruncationPlan {
            truncated: 0,
            dropped_target_index: None,
            coverage: CoverageAdjustmentPlan::default(),
        });
    }

    let mut truncated_by_file = BTreeMap::<(FileId, FactId), u64>::new();
    let mut source_free = 0_u64;
    let mut truncated = 0_usize;
    let mut dropped_target_index = None;
    let mut target_coverage = CoverageAdjustmentPlan::default();
    if available == 0 {
        let mut replacement = None;
        for (index, diagnostic) in target.diagnostics.iter().enumerate().rev() {
            check_cancellation(cancellation)?;
            if !is_priority_aggregate_diagnostic(&diagnostic.code) {
                replacement = Some(index);
                break;
            }
        }
        let replacement = replacement.ok_or(FirstSliceError::Limits)?;
        record_truncated_diagnostic(
            &target.diagnostics[replacement],
            &mut truncated_by_file,
            &mut source_free,
        )?;
        dropped_target_index = Some(replacement);
        truncated = 1;
        available = 1;
        target_coverage.extend(
            &target.coverage_records,
            IrFactDomain::Diagnostics,
            &truncated_by_file,
            source_free,
            cancellation,
        )?;
        truncated_by_file.clear();
        source_free = 0;
    }

    let retained = available.saturating_sub(1).min(source.diagnostics.len());
    truncated = truncated
        .checked_add(
            source
                .diagnostics
                .len()
                .checked_sub(retained)
                .ok_or(FirstSliceError::Limits)?,
        )
        .ok_or(FirstSliceError::Limits)?;
    for diagnostic in source.diagnostics.drain(retained..) {
        check_cancellation(cancellation)?;
        record_truncated_diagnostic(&diagnostic, &mut truncated_by_file, &mut source_free)?;
    }
    let mut source_coverage = CoverageAdjustmentPlan::default();
    source_coverage.extend(
        &source.coverage_records,
        IrFactDomain::Diagnostics,
        &truncated_by_file,
        source_free,
        cancellation,
    )?;
    source_coverage.apply(&mut source.coverage_records);
    Ok(DiagnosticTruncationPlan {
        truncated: u64::try_from(truncated).map_err(|_| FirstSliceError::Limits)?,
        dropped_target_index,
        coverage: target_coverage,
    })
}

fn record_truncated_diagnostic(
    diagnostic: &DiagnosticRecord,
    truncated_by_file: &mut BTreeMap<(FileId, FactId), u64>,
    source_free: &mut u64,
) -> Result<(), FirstSliceError> {
    if let Some(source) = diagnostic.source.as_ref() {
        let truncated = truncated_by_file
            .entry((source.span().file(), diagnostic.provenance))
            .or_default();
        *truncated = truncated.checked_add(1).ok_or(FirstSliceError::Limits)?;
    } else {
        *source_free = source_free.checked_add(1).ok_or(FirstSliceError::Limits)?;
    }
    Ok(())
}

struct OptionalExtensionPlan {
    dropped_target_indices: Vec<usize>,
    coverage: CoverageAdjustmentPlan,
    next_state: DocumentAppendState,
    metadata: optional_extension_metadata::Workspace,
    previous_target_len: usize,
}

impl OptionalExtensionPlan {
    fn apply(
        mut self,
        target: &mut NormalizedIrDocument,
        previous_metadata: &mut Option<optional_extension_metadata::Cache>,
    ) -> DocumentAppendState {
        self.next_state.optional_metadata = self.metadata.commit(
            &self.dropped_target_indices,
            self.previous_target_len,
            previous_metadata.take(),
        );
        for index in self.dropped_target_indices {
            target.extensions.remove(index);
        }
        self.coverage.apply(&mut target.coverage_records);
        self.next_state
    }
}

#[cfg(test)]
fn truncate_optional_extensions(
    target: &mut NormalizedIrDocument,
    source: &mut NormalizedIrDocument,
    append_state: &DocumentAppendState,
    truncated_diagnostics: u64,
    truncated_skipped_regions: u64,
    limits: &IrLimits,
) -> Result<DocumentAppendState, FirstSliceError> {
    let mut previous_metadata = append_state.optional_metadata.clone();
    plan_optional_extensions(
        target,
        source,
        append_state,
        DiagnosticTruncationPlan {
            truncated: truncated_diagnostics,
            dropped_target_index: None,
            coverage: CoverageAdjustmentPlan::default(),
        },
        truncated_skipped_regions,
        limits,
        &Cancellation::new(),
    )
    .map(|plan| plan.apply(target, &mut previous_metadata))
}

#[cfg(test)]
fn plan_optional_extensions(
    target: &NormalizedIrDocument,
    source: &mut NormalizedIrDocument,
    append_state: &DocumentAppendState,
    diagnostics: DiagnosticTruncationPlan,
    truncated_skipped_regions: u64,
    limits: &IrLimits,
    cancellation: &Cancellation,
) -> Result<OptionalExtensionPlan, FirstSliceError> {
    plan_optional_extensions_with_metadata_admission(
        target,
        source,
        append_state,
        diagnostics,
        truncated_skipped_regions,
        limits,
        optional_extension_metadata::PlanningContext {
            cancellation,
            admission: None,
        },
    )
}

fn plan_optional_extensions_with_metadata_admission(
    target: &NormalizedIrDocument,
    source: &mut NormalizedIrDocument,
    append_state: &DocumentAppendState,
    diagnostics: DiagnosticTruncationPlan,
    truncated_skipped_regions: u64,
    limits: &IrLimits,
    context: optional_extension_metadata::PlanningContext<'_, '_>,
) -> Result<OptionalExtensionPlan, FirstSliceError> {
    let optional_extension_metadata::PlanningContext {
        cancellation,
        mut admission,
    } = context;
    check_cancellation(cancellation)?;
    let mut metadata = optional_extension_metadata::Workspace::new(
        append_state.optional_metadata.as_ref(),
        &mut admission,
        cancellation,
    )?;
    let profiled_source_extensions = if analysis_profile_enabled() {
        Some(source.extensions.len())
    } else {
        None
    };
    let DiagnosticTruncationPlan {
        truncated: truncated_diagnostics,
        mut coverage,
        ..
    } = diagnostics;
    let (required_count, required_bytes) =
        required_extension_usage(&source.extensions, cancellation)?;
    let (target_extension_payload_bytes, (retained_required_count, retained_required_bytes)) =
        match append_state.required_extension_usage {
            Some(required) => (append_state.extension_payload_bytes, required),
            None => measure_target_extension_usage(&target.extensions, cancellation)?,
        };
    check_cancellation(cancellation)?;
    let observed_required_count = retained_required_count
        .checked_add(required_count)
        .ok_or(FirstSliceError::Limits)?;
    if observed_required_count > limits.max_extensions {
        return Err(resource_limit(
            FirstSliceResource::Extensions,
            observed_required_count,
            limits.max_extensions,
        ));
    }
    let observed_required_bytes = retained_required_bytes
        .checked_add(required_bytes)
        .ok_or(FirstSliceError::Limits)?;
    if observed_required_bytes > limits.max_total_extension_bytes {
        #[cfg(test)]
        extension_admission_observation::observe(
            &target.extensions,
            &source.extensions,
            observed_required_bytes,
            limits.max_total_extension_bytes,
            cancellation,
        );
        return Err(resource_limit(
            FirstSliceResource::ExtensionBytes,
            observed_required_bytes,
            limits.max_total_extension_bytes,
        ));
    }
    let optional_count_limit = limits
        .max_extensions
        .checked_sub(observed_required_count)
        .ok_or(FirstSliceError::Limits)?
        .min(MAX_RETAINED_OPTIONAL_EXTENSIONS);
    let optional_bytes_limit = limits
        .max_total_extension_bytes
        .checked_sub(observed_required_bytes)
        .ok_or(FirstSliceError::Limits)?
        .min(MAX_RETAINED_OPTIONAL_EXTENSION_BYTES);
    let (source_signature_count, source_signature_bytes) = source
        .extensions
        .iter()
        .enumerate()
        .filter(|(_, extension)| extension.namespace == LEXICAL_EXTENSION_NAMESPACE)
        .try_fold(
            (0_usize, 0_usize),
            |(count, bytes), (index, extension)| -> Result<_, FirstSliceError> {
                check_cancellation(cancellation)?;
                let position = target
                    .extensions
                    .len()
                    .checked_add(index)
                    .ok_or(FirstSliceError::Limits)?;
                if !metadata.signature(position, extension, &mut admission, cancellation)? {
                    return Ok((count, bytes));
                }
                Ok((
                    count.checked_add(1).ok_or(FirstSliceError::Limits)?,
                    bytes
                        .checked_add(extension.payload.len())
                        .ok_or(FirstSliceError::Limits)?,
                ))
            },
        )?;

    let mut dropped_from_target = BTreeMap::<(FileId, FactId), u64>::new();
    let mut dropped_target_indices = Vec::new();
    dropped_target_indices
        .try_reserve_exact(
            target
                .extensions
                .len()
                .checked_sub(retained_required_count)
                .ok_or(FirstSliceError::Limits)?,
        )
        .map_err(|_| FirstSliceError::Limits)?;
    let mut target_extension_count = target.extensions.len();
    let mut target_extension_bytes = target_extension_payload_bytes;
    let mut target_optional_count = target
        .extensions
        .len()
        .checked_sub(retained_required_count)
        .ok_or(FirstSliceError::Limits)?;
    let mut target_optional_bytes = target_extension_payload_bytes
        .checked_sub(retained_required_bytes)
        .ok_or(FirstSliceError::Limits)?;
    let mut summary_cursor = target.extensions.len();
    let mut signature_cursor = target.extensions.len();
    let mut summary_free_prefix = append_state.summary_free_prefix;
    if summary_free_prefix > target.extensions.len() {
        return Err(FirstSliceError::Limits);
    }
    loop {
        check_cancellation(cancellation)?;
        let target_over_limit = target_optional_count > optional_count_limit
            || target_optional_bytes > optional_bytes_limit;
        let signatures_need_room = target_optional_count
            .checked_add(source_signature_count)
            .is_none_or(|count| count > optional_count_limit)
            || target_optional_bytes
                .checked_add(source_signature_bytes)
                .is_none_or(|bytes| bytes > optional_bytes_limit);
        if !target_over_limit && !signatures_need_room {
            break;
        }
        let summary = previous_optional_extension_with_classifier(
            &target.extensions,
            &mut summary_cursor,
            append_state.summary_free_prefix,
            LexicalRetentionClass::Summary,
            cancellation,
            |index, extension| metadata.signature(index, extension, &mut admission, cancellation),
        )?;
        if summary.is_none() {
            // Every summary encountered earlier in this search is already
            // scheduled for removal; retained entries contain no summaries.
            summary_free_prefix = target.extensions.len();
        }
        let index = match summary {
            Some(index) => index,
            None if target_over_limit => previous_optional_extension_with_classifier(
                &target.extensions,
                &mut signature_cursor,
                0,
                LexicalRetentionClass::Signature,
                cancellation,
                |index, extension| {
                    metadata.signature(index, extension, &mut admission, cancellation)
                },
            )?
            .ok_or(FirstSliceError::Limits)?,
            None => break,
        };
        let extension = &target.extensions[index];
        target_extension_count = target_extension_count
            .checked_sub(1)
            .ok_or(FirstSliceError::Limits)?;
        target_extension_bytes = target_extension_bytes
            .checked_sub(extension.payload.len())
            .ok_or(FirstSliceError::Limits)?;
        target_optional_count = target_optional_count
            .checked_sub(1)
            .ok_or(FirstSliceError::Limits)?;
        target_optional_bytes = target_optional_bytes
            .checked_sub(extension.payload.len())
            .ok_or(FirstSliceError::Limits)?;
        let file = extension_file(extension)?;
        let dropped = dropped_from_target
            .entry((file, extension.provenance))
            .or_default();
        *dropped = dropped
            .checked_add(metadata.logical_count(index, extension, &mut admission, cancellation)?)
            .ok_or(FirstSliceError::Limits)?;
        dropped_target_indices.push(index);
    }
    coverage.extend(
        &target.coverage_records,
        IrFactDomain::Extensions,
        &dropped_from_target,
        0,
        cancellation,
    )?;

    let available_count = limits
        .max_extensions
        .checked_sub(target_extension_count)
        .ok_or(FirstSliceError::Limits)?;
    let available_bytes = limits
        .max_total_extension_bytes
        .checked_sub(target_extension_bytes)
        .ok_or(FirstSliceError::Limits)?;
    let available_optional_count = available_count
        .checked_sub(required_count)
        .ok_or(FirstSliceError::Limits)?
        .min(
            MAX_RETAINED_OPTIONAL_EXTENSIONS
                .checked_sub(target_optional_count)
                .ok_or(FirstSliceError::Limits)?,
        );
    let available_optional_bytes = available_bytes
        .checked_sub(required_bytes)
        .ok_or(FirstSliceError::Limits)?
        .min(
            MAX_RETAINED_OPTIONAL_EXTENSION_BYTES
                .checked_sub(target_optional_bytes)
                .ok_or(FirstSliceError::Limits)?,
        );
    let mut retained = Vec::new();
    retained
        .try_reserve_exact(source.extensions.len().min(available_count))
        .map_err(|_| FirstSliceError::Limits)?;
    let mut retained_optional_count = 0_usize;
    let mut retained_optional_bytes = 0_usize;
    let mut retained_bytes = 0_usize;
    let mut dropped_by_file = BTreeMap::<(FileId, FactId), u64>::new();
    let mut pending_signature_count = source_signature_count;
    let mut pending_signature_bytes = source_signature_bytes;

    for (index, extension) in source.extensions.drain(..).enumerate() {
        check_cancellation(cancellation)?;
        let position = target
            .extensions
            .len()
            .checked_add(index)
            .ok_or(FirstSliceError::Limits)?;
        let payload_bytes = extension.payload.len();
        let optional = extension.namespace == LEXICAL_EXTENSION_NAMESPACE;
        let signature =
            optional && metadata.signature(position, &extension, &mut admission, cancellation)?;
        if signature {
            pending_signature_count = pending_signature_count
                .checked_sub(1)
                .ok_or(FirstSliceError::Limits)?;
            pending_signature_bytes = pending_signature_bytes
                .checked_sub(payload_bytes)
                .ok_or(FirstSliceError::Limits)?;
        }
        let next_optional_bytes = retained_optional_bytes
            .checked_add(payload_bytes)
            .ok_or(FirstSliceError::Limits)?;
        // Signatures serve symbol.explain directly; reserve their remaining
        // capacity before admitting summaries that are also in exact source.
        let keep = !optional
            || (retained_optional_count
                .checked_add(1)
                .and_then(|count| {
                    count.checked_add(if signature {
                        0
                    } else {
                        pending_signature_count
                    })
                })
                .is_some_and(|count| count <= available_optional_count)
                && next_optional_bytes
                    .checked_add(if signature {
                        0
                    } else {
                        pending_signature_bytes
                    })
                    .is_some_and(|bytes| bytes <= available_optional_bytes));
        if keep {
            metadata.retain_source(
                position,
                Some(
                    target_extension_count
                        .checked_add(retained.len())
                        .ok_or(FirstSliceError::Limits)?,
                ),
            );
            if optional {
                retained_optional_count = retained_optional_count
                    .checked_add(1)
                    .ok_or(FirstSliceError::Limits)?;
                retained_optional_bytes = next_optional_bytes;
            }
            retained_bytes = retained_bytes
                .checked_add(payload_bytes)
                .ok_or(FirstSliceError::Limits)?;
            retained.push(extension);
            continue;
        }

        let file = extension_file(&extension)?;
        let dropped = dropped_by_file
            .entry((file, extension.provenance))
            .or_default();
        *dropped = dropped
            .checked_add(metadata.logical_count(
                position,
                &extension,
                &mut admission,
                cancellation,
            )?)
            .ok_or(FirstSliceError::Limits)?;
        metadata.retain_source(position, None);
    }
    let mut source_coverage = CoverageAdjustmentPlan::default();
    source_coverage.extend(
        &source.coverage_records,
        IrFactDomain::Extensions,
        &dropped_by_file,
        0,
        cancellation,
    )?;
    let truncated_extensions = dropped_from_target
        .values()
        .chain(dropped_by_file.values())
        .try_fold(0_u64, |total, dropped| {
            check_cancellation(cancellation)?;
            total.checked_add(*dropped).ok_or(FirstSliceError::Limits)
        })?;
    let next_state = DocumentAppendState {
        aggregate_recovery: append_state.aggregate_recovery,
        usage: None,
        optional_metadata: None,
        summary_free_prefix: summary_free_prefix
            .checked_sub(
                dropped_target_indices
                    .iter()
                    .filter(|&&index| index < summary_free_prefix)
                    .count(),
            )
            .ok_or(FirstSliceError::Limits)?,
        extension_payload_bytes: target_extension_bytes
            .checked_add(retained_bytes)
            .ok_or(FirstSliceError::Limits)?,
        required_extension_usage: Some((observed_required_count, observed_required_bytes)),
        truncated_diagnostics: append_state
            .truncated_diagnostics
            .checked_add(truncated_diagnostics)
            .ok_or(FirstSliceError::Limits)?,
        truncated_extensions: append_state
            .truncated_extensions
            .checked_add(truncated_extensions)
            .ok_or(FirstSliceError::Limits)?,
        truncated_skipped_regions: append_state
            .truncated_skipped_regions
            .checked_add(truncated_skipped_regions)
            .ok_or(FirstSliceError::Limits)?,
    };

    check_cancellation(cancellation)?;
    dropped_target_indices.sort_unstable_by(|left, right| right.cmp(left));
    check_cancellation(cancellation)?;
    source.extensions = retained;
    if let Some(previous) = profiled_source_extensions {
        with_analysis_profile(|profile| {
            add_profile_total(
                &mut profile.append.planned_target_extension_drops,
                dropped_target_indices.len() as u128,
                &mut profile.counts_complete,
            );
            if let Some(dropped) = previous.checked_sub(source.extensions.len()) {
                add_profile_total(
                    &mut profile.append.planned_source_extension_drops,
                    dropped as u128,
                    &mut profile.counts_complete,
                );
            } else {
                profile.counts_complete = false;
            }
        });
    }
    source_coverage.apply(&mut source.coverage_records);
    Ok(OptionalExtensionPlan {
        dropped_target_indices,
        coverage,
        next_state,
        metadata,
        previous_target_len: target.extensions.len(),
    })
}

fn measure_target_extension_usage(
    extensions: &[ExtensionEnvelope],
    cancellation: &Cancellation,
) -> Result<(usize, (usize, usize)), FirstSliceError> {
    extensions.iter().try_fold(
        (0_usize, (0_usize, 0_usize)),
        |(total, (required_count, required_bytes)), extension| {
            check_cancellation(cancellation)?;
            let payload_bytes = extension.payload.len();
            let total = total
                .checked_add(payload_bytes)
                .ok_or(FirstSliceError::Limits)?;
            let required = if extension.namespace == LEXICAL_EXTENSION_NAMESPACE {
                (required_count, required_bytes)
            } else {
                (
                    required_count
                        .checked_add(1)
                        .ok_or(FirstSliceError::Limits)?,
                    required_bytes
                        .checked_add(payload_bytes)
                        .ok_or(FirstSliceError::Limits)?,
                )
            };
            Ok((total, required))
        },
    )
}

fn required_extension_usage(
    extensions: &[ExtensionEnvelope],
    cancellation: &Cancellation,
) -> Result<(usize, usize), FirstSliceError> {
    extensions
        .iter()
        .try_fold((0_usize, 0_usize), |(count, bytes), extension| {
            check_cancellation(cancellation)?;
            if extension.namespace == LEXICAL_EXTENSION_NAMESPACE {
                return Ok((count, bytes));
            }
            Ok((
                count.checked_add(1).ok_or(FirstSliceError::Limits)?,
                bytes
                    .checked_add(extension.payload.len())
                    .ok_or(FirstSliceError::Limits)?,
            ))
        })
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum LexicalRetentionClass {
    Signature,
    Summary,
}

#[derive(Deserialize)]
struct LexicalKindProbe {
    kind: rootlight_ir::LexicalEvidenceKind,
}

fn is_lexical_signature(extension: &ExtensionEnvelope) -> Result<bool, FirstSliceError> {
    if extension.version == rootlight_ir::LEXICAL_SIGNATURE_BATCH_VERSION {
        let profile = SignatureBatchProfileGuard::begin(extension.payload.len());
        let children = rootlight_ir::decode_lexical_signature_batch_envelope(extension)
            .map_err(|_| FirstSliceError::Identity)?;
        profile.finish(children.len());
        return Ok(true);
    }
    if extension.version == rootlight_ir::LEXICAL_SUMMARY_BATCH_VERSION {
        with_analysis_profile(|profile| {
            increment_profile_count(
                &mut profile.append.summary_batch_classifications,
                &mut profile.counts_complete,
            )
        });
        return Ok(false);
    }
    with_analysis_profile(|profile| {
        increment_profile_count(
            &mut profile.append.atomic_lexical_classifications,
            &mut profile.counts_complete,
        )
    });
    // The retention decision needs only the kind; generation verification
    // subsequently validates the complete retained lexical envelope.
    serde_json::from_str::<LexicalKindProbe>(&extension.payload)
        .map(|evidence| evidence.kind == rootlight_ir::LexicalEvidenceKind::Signature)
        .map_err(|_| FirstSliceError::Identity)
}

fn optional_extension_logical_count(extension: &ExtensionEnvelope) -> Result<u64, FirstSliceError> {
    if extension.version == rootlight_ir::LEXICAL_SIGNATURE_BATCH_VERSION {
        let entries = rootlight_ir::decode_lexical_signature_batch_envelope(extension)
            .map_err(|_| FirstSliceError::Identity)?;
        return u64::try_from(entries.len()).map_err(|_| FirstSliceError::Limits);
    }
    if extension.version == rootlight_ir::LEXICAL_SUMMARY_BATCH_VERSION {
        let entries = rootlight_ir::decode_lexical_summary_batch_envelope(extension)
            .map_err(|_| FirstSliceError::Identity)?;
        u64::try_from(entries.len()).map_err(|_| FirstSliceError::Limits)
    } else {
        Ok(1)
    }
}

#[cfg(test)]
fn compact_lexical_summaries(
    source: &mut NormalizedIrDocument,
    limits: &IrLimits,
) -> Result<(), FirstSliceError> {
    compact_lexical_summaries_with_cancellation(source, limits, &Cancellation::new())
}

fn compact_lexical_summaries_with_cancellation(
    source: &mut NormalizedIrDocument,
    limits: &IrLimits,
    cancellation: &Cancellation,
) -> Result<(), FirstSliceError> {
    check_cancellation(cancellation)?;
    let mut grouped = BTreeMap::<(FileId, FactId, bool), Vec<ExtensionEnvelope>>::new();
    let mut retained = Vec::new();
    retained
        .try_reserve_exact(source.extensions.len())
        .map_err(|_| FirstSliceError::Limits)?;
    for extension in source.extensions.drain(..) {
        check_cancellation(cancellation)?;
        if extension.namespace != LEXICAL_EXTENSION_NAMESPACE
            || extension.version == rootlight_ir::LEXICAL_SUMMARY_BATCH_VERSION
            || extension.version == rootlight_ir::LEXICAL_SIGNATURE_BATCH_VERSION
        {
            if extension.namespace == LEXICAL_EXTENSION_NAMESPACE
                && extension.version == rootlight_ir::LEXICAL_SIGNATURE_BATCH_VERSION
            {
                let result = rootlight_ir::decode_lexical_signature_batch_envelope_with_checkpoint(
                    &extension,
                    || cancellation.check().is_ok(),
                );
                check_cancellation(cancellation)?;
                result.map_err(|_| FirstSliceError::Identity)?;
            }
            retained.push(extension);
            continue;
        }
        let signature = is_lexical_signature(&extension)?;
        if signature {
            let evidence = rootlight_ir::decode_lexical_evidence_envelope(&extension)
                .map_err(|_| FirstSliceError::Identity)?;
            if evidence.is_truncated() || !matches!(evidence.subject(), FactRef::Entity(_)) {
                retained.push(extension);
                continue;
            }
        }
        let file = extension_file(&extension)?;
        let entries = grouped
            .entry((file, extension.provenance, signature))
            .or_default();
        entries
            .try_reserve(1)
            .map_err(|_| FirstSliceError::Limits)?;
        entries.push(extension);
    }
    for ((_, _, signature), mut entries) in grouped {
        check_cancellation(cancellation)?;
        // Fact IDs change with the generation. Partition by source location so
        // clean rebuilds pack the same logical evidence into the same batches.
        entries.sort_unstable_by_key(lexical_summary_span);
        check_cancellation(cancellation)?;
        let mut offset = 0;
        while offset < entries.len() {
            check_cancellation(cancellation)?;
            let mut count =
                (entries.len() - offset).min(rootlight_ir::MAX_LEXICAL_SUMMARY_BATCH_ENTRIES);
            let batch = loop {
                check_cancellation(cancellation)?;
                // Co-located evidence can refer to different generation-bound
                // facts. Never let their incidental ID order choose membership
                // on opposite sides of a batch or payload-size boundary.
                while count > 0
                    && offset + count < entries.len()
                    && lexical_summary_span(&entries[offset + count - 1])
                        == lexical_summary_span(&entries[offset + count])
                {
                    check_cancellation(cancellation)?;
                    count -= 1;
                }
                if count == 0 {
                    let span = lexical_summary_span(&entries[offset]);
                    count = entries[offset..]
                        .partition_point(|entry| lexical_summary_span(entry) == span);
                    break None;
                }
                if count < 8 {
                    break None;
                }
                let batch = if signature {
                    rootlight_ir::new_lexical_signature_batch_envelope(
                        &entries[offset..offset + count],
                    )
                } else {
                    rootlight_ir::new_lexical_summary_batch_envelope(
                        &entries[offset..offset + count],
                    )
                };
                match batch {
                    Ok(batch) if batch.payload.len() <= limits.max_extension_payload_bytes => {
                        break Some(batch);
                    }
                    Ok(_) | Err(rootlight_ir::LexicalExtensionError::PayloadTooLarge { .. }) => {
                        count /= 2;
                    }
                    Err(_) => return Err(FirstSliceError::Identity),
                }
            };
            if let Some(batch) = batch {
                retained.push(batch);
            } else {
                retained.extend_from_slice(&entries[offset..offset + count]);
            }
            offset += count;
        }
    }
    check_cancellation(cancellation)?;
    source.extensions = retained;
    Ok(())
}

fn lexical_summary_span(extension: &ExtensionEnvelope) -> Option<SourceSpan> {
    extension.evidence.source.as_ref().map(SourceRef::span)
}

#[cfg(test)]
fn previous_optional_extension(
    extensions: &[ExtensionEnvelope],
    cursor: &mut usize,
    lower_bound: usize,
    class: LexicalRetentionClass,
    cancellation: &Cancellation,
) -> Result<Option<usize>, FirstSliceError> {
    previous_optional_extension_with_classifier(
        extensions,
        cursor,
        lower_bound,
        class,
        cancellation,
        |_, extension| is_lexical_signature(extension),
    )
}

fn previous_optional_extension_with_classifier(
    extensions: &[ExtensionEnvelope],
    cursor: &mut usize,
    lower_bound: usize,
    class: LexicalRetentionClass,
    cancellation: &Cancellation,
    mut signature: impl FnMut(usize, &ExtensionEnvelope) -> Result<bool, FirstSliceError>,
) -> Result<Option<usize>, FirstSliceError> {
    check_cancellation(cancellation)?;
    if lower_bound > *cursor || *cursor > extensions.len() {
        return Err(FirstSliceError::Limits);
    }
    let profiled = analysis_profile_enabled();
    let profile = AnalysisProfileGuard::begin(
        if class == LexicalRetentionClass::Summary {
            AnalysisProfilePhase::AppendSummarySearch
        } else {
            AnalysisProfilePhase::AppendSignatureSearch
        },
        None,
    );
    if profiled {
        with_analysis_profile(|profile| {
            let calls = if class == LexicalRetentionClass::Summary {
                &mut profile.append.summary_search_calls
            } else {
                &mut profile.append.signature_search_calls
            };
            increment_profile_count(calls, &mut profile.counts_complete);
        });
    }
    while *cursor > lower_bound {
        check_cancellation(cancellation)?;
        *cursor -= 1;
        let extension = extensions.get(*cursor).ok_or(FirstSliceError::Limits)?;
        if profiled {
            with_analysis_profile(|profile| {
                let visits = if class == LexicalRetentionClass::Summary {
                    &mut profile.append.summary_search_entries_visited
                } else {
                    &mut profile.append.signature_search_entries_visited
                };
                increment_profile_count(visits, &mut profile.counts_complete);
            });
        }
        if extension.namespace != LEXICAL_EXTENSION_NAMESPACE {
            continue;
        }
        let signature = signature(*cursor, extension)?;
        if signature == (class == LexicalRetentionClass::Signature) {
            profile.finish();
            return Ok(Some(*cursor));
        }
    }
    profile.finish();
    Ok(None)
}

fn extension_payload_bytes<'a>(
    mut extensions: impl Iterator<Item = &'a rootlight_ir::ExtensionEnvelope>,
) -> Result<usize, FirstSliceError> {
    extensions.try_fold(0_usize, |total, extension| {
        total
            .checked_add(extension.payload.len())
            .ok_or(FirstSliceError::Limits)
    })
}

fn extension_file(extension: &rootlight_ir::ExtensionEnvelope) -> Result<FileId, FirstSliceError> {
    extension
        .evidence
        .source
        .as_ref()
        .map(|source| source.span().file())
        .ok_or(FirstSliceError::Identity)
}

#[cfg(test)]
fn adjusted_extension_coverage(
    existing: &[rootlight_ir::CoverageRecord],
    dropped_by_file: &BTreeMap<(FileId, FactId), u64>,
) -> Result<Vec<rootlight_ir::CoverageRecord>, FirstSliceError> {
    let mut coverage_records = existing.to_vec();
    for ((file, provenance), dropped) in dropped_by_file {
        let mut matching_records = coverage_records.iter_mut().filter(|coverage| {
            coverage.domain == rootlight_ir::FactDomain::Extensions
                && coverage.scope == rootlight_ir::CoverageScope::File(*file)
                && coverage.provenance == *provenance
        });
        let coverage = matching_records.next().ok_or(FirstSliceError::Identity)?;
        if matching_records.next().is_some() {
            return Err(FirstSliceError::Identity);
        }
        coverage.indexed = coverage
            .indexed
            .checked_sub(*dropped)
            .ok_or(FirstSliceError::Identity)?;
        coverage.skipped = coverage
            .skipped
            .checked_add(*dropped)
            .ok_or(FirstSliceError::Limits)?;
        if coverage.status != CoverageStatus::Unknown {
            coverage.status = CoverageStatus::Bounded;
        }
        coverage.id = derive_coverage_record_id(coverage).map_err(|_| FirstSliceError::Identity)?;
    }
    Ok(coverage_records)
}

#[cfg(test)]
fn adjusted_diagnostic_coverage(
    existing: &[CoverageRecord],
    dropped_by_file: &BTreeMap<(FileId, FactId), u64>,
    source_free_dropped: u64,
) -> Result<Vec<CoverageRecord>, FirstSliceError> {
    let mut coverage_records = existing.to_vec();
    for ((file, provenance), dropped) in dropped_by_file {
        let mut matching_records = coverage_records.iter_mut().filter(|coverage| {
            coverage.domain == IrFactDomain::Diagnostics
                && coverage.scope == CoverageScope::File(*file)
                && coverage.provenance == *provenance
        });
        let coverage = matching_records.next().ok_or(FirstSliceError::Identity)?;
        if matching_records.next().is_some() {
            return Err(FirstSliceError::Identity);
        }
        coverage.indexed = coverage
            .indexed
            .checked_sub(*dropped)
            .ok_or(FirstSliceError::Identity)?;
        coverage.skipped = coverage
            .skipped
            .checked_add(*dropped)
            .ok_or(FirstSliceError::Limits)?;
        if coverage.status != CoverageStatus::Unknown {
            coverage.status = CoverageStatus::Bounded;
        }
        coverage.id = derive_coverage_record_id(coverage).map_err(|_| FirstSliceError::Identity)?;
    }
    if source_free_dropped > 0 {
        for coverage in &mut coverage_records {
            if coverage.domain == IrFactDomain::Diagnostics
                && coverage.status != CoverageStatus::Unknown
            {
                coverage.status = CoverageStatus::Bounded;
                coverage.id =
                    derive_coverage_record_id(coverage).map_err(|_| FirstSliceError::Identity)?;
            }
        }
    }
    Ok(coverage_records)
}

fn normalized_record_count(document: &NormalizedIrDocument) -> Result<usize, FirstSliceError> {
    [
        document.files.len(),
        document.entities.len(),
        document.occurrences.len(),
        document.relations.len(),
        document.provenance.len(),
        document.source_mappings.len(),
        document.coverage_records.len(),
        document.skipped_regions.len(),
        document.diagnostics.len(),
        document.extensions.len(),
    ]
    .into_iter()
    .try_fold(0_usize, |total, length| {
        total.checked_add(length).ok_or(FirstSliceError::Limits)
    })
}

#[derive(Serialize)]
#[serde(deny_unknown_fields)]
struct LogicalLexicalDocument<'document> {
    symbol_id: Option<SymbolId>,
    file_id: FileId,
    identifier: &'document str,
    qualified_name: &'document str,
    path: &'document str,
    kind: &'document str,
    language: &'document str,
    tier: &'document str,
    package: &'document Option<String>,
    build_target: &'document Option<String>,
    signature: &'document Option<String>,
    type_names: &'document [String],
    documentation: &'document Option<String>,
    source_identifiers: &'document [String],
    source_text: &'document Option<String>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    source_term_chunks: &'document Vec<Vec<String>>,
    generated: bool,
    test: bool,
    declaration_only: bool,
}

impl<'document> From<&'document LexicalDocument> for LogicalLexicalDocument<'document> {
    fn from(document: &'document LexicalDocument) -> Self {
        Self {
            symbol_id: document.symbol_id,
            file_id: document.file_id,
            identifier: &document.identifier,
            qualified_name: &document.qualified_name,
            path: &document.path,
            kind: &document.kind,
            language: &document.language,
            tier: &document.tier,
            package: &document.package,
            build_target: &document.build_target,
            signature: &document.signature,
            type_names: &document.type_names,
            documentation: &document.documentation,
            source_identifiers: &document.source_identifiers,
            source_text: &document.source_text,
            source_term_chunks: &document.source_term_chunks,
            generated: document.generated,
            test: document.test,
            declaration_only: document.declaration_only,
        }
    }
}

struct LogicalLexicalProjection<'document>(&'document [LexicalDocument]);

impl Serialize for LogicalLexicalProjection<'_> {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        let mut sequence = serializer.serialize_seq(Some(self.0.len()))?;
        for document in self.0 {
            sequence.serialize_element(&LogicalLexicalDocument::from(document))?;
        }
        sequence.end()
    }
}

struct LogicalDiscoveryProjection<'inputs>(&'inputs InputSnapshot);

impl Serialize for LogicalDiscoveryProjection<'_> {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        let mut sequence = serializer.serialize_seq(Some(self.0.len()))?;
        for input in self.0.iter() {
            sequence.serialize_element(&input)?;
        }
        sequence.end()
    }
}

fn logical_component(
    domain: LogicalDomain,
    value: &impl Serialize,
    records: u64,
    cancellation: &Cancellation,
) -> Result<LogicalComponent, FirstSliceError> {
    LogicalComponent::from_canonical_value(
        domain,
        value,
        records,
        MAX_LOGICAL_SNAPSHOT_COMPONENT_BYTES,
        cancellation,
    )
    .map_err(|error| map_incremental_error(error, cancellation))
}

fn logical_snapshot_identity(
    normalized_ir: CanonicalGenerationNeutralDigests,
    lexical_documents: &[LexicalDocument],
    inputs: &InputSnapshot,
    cancellation: &Cancellation,
) -> Result<FirstSliceLogicalSnapshotIdentity, FirstSliceError> {
    check_cancellation(cancellation)?;
    let query_projection = LogicalLexicalProjection(lexical_documents);
    let query_component = logical_component(
        LogicalDomain::QueryOutputs,
        &query_projection,
        u64::try_from(lexical_documents.len()).map_err(|_| FirstSliceError::Limits)?,
        cancellation,
    )?;
    logical_snapshot_identity_with_query_component(
        normalized_ir,
        query_component,
        inputs,
        cancellation,
    )
}

fn logical_snapshot_identity_with_query_component(
    normalized_ir: CanonicalGenerationNeutralDigests,
    query_component: LogicalComponent,
    inputs: &InputSnapshot,
    cancellation: &Cancellation,
) -> Result<FirstSliceLogicalSnapshotIdentity, FirstSliceError> {
    check_cancellation(cancellation)?;
    if query_component.domain() != LogicalDomain::QueryOutputs {
        return Err(FirstSliceError::Incremental);
    }
    let discovery_inputs = LogicalDiscoveryProjection(inputs);
    let normalized_ir_component = logical_component(
        LogicalDomain::NormalizedIr,
        &normalized_ir.complete(),
        normalized_ir.records(),
        cancellation,
    )?;
    // LogicalStore is the backend-neutral intended store projection. Catalog
    // and recovery round-trip correctness is tested separately, so ordinary
    // publication does not traverse the same generation twice.
    let logical_store_component = logical_component(
        LogicalDomain::LogicalStore,
        &normalized_ir.complete(),
        normalized_ir.records(),
        cancellation,
    )?;
    let components = [
        logical_component(
            LogicalDomain::Discovery,
            &discovery_inputs,
            u64::try_from(inputs.len()).map_err(|_| FirstSliceError::Limits)?,
            cancellation,
        )?,
        normalized_ir_component,
        logical_store_component,
        query_component,
        logical_component(
            LogicalDomain::Coverage,
            &normalized_ir.coverage(),
            normalized_ir.coverage_records(),
            cancellation,
        )?,
        logical_component(
            LogicalDomain::Provenance,
            &normalized_ir.provenance(),
            normalized_ir.provenance_records(),
            cancellation,
        )?,
        logical_component(
            LogicalDomain::StableIds,
            &normalized_ir.stable_identities(),
            normalized_ir.stable_identities_records(),
            cancellation,
        )?,
    ];
    let snapshot = EquivalenceSnapshot::new(components, cancellation)
        .map_err(|error| map_incremental_error(error, cancellation))?;
    Ok(FirstSliceLogicalSnapshotIdentity::new(
        snapshot.logical_snapshot_hash(),
    ))
}

fn source_fallback_text_limit(
    snapshot: &rootlight_storage::GenerationSnapshot,
) -> Result<usize, FirstSliceError> {
    // Older file-only generations derive their prefix projection from this
    // aggregate budget. Reopening must preserve that published lexical identity.
    const LEGACY_AGGREGATE_TEXT_BYTES: usize = 2 * 1024 * 1024 * 1024;
    let file_count = snapshot.file_count();
    if file_count == 0 {
        return Ok(0);
    }
    let mut fixed_text_bytes = 0usize;
    for file in snapshot.document().files.iter().chain(
        snapshot
            .source_files()
            .entries()
            .iter()
            .map(|entry| entry.file()),
    ) {
        let identifier = file
            .path
            .rsplit('/')
            .next()
            .filter(|name| !name.is_empty() && name.len() <= 512)
            .unwrap_or("file");
        fixed_text_bytes = fixed_text_bytes
            .checked_add(identifier.len().saturating_mul(2))
            .and_then(|bytes| bytes.checked_add(file.path.len()))
            .and_then(|bytes| bytes.checked_add("file".len()))
            .and_then(|bytes| bytes.checked_add(file.language.len()))
            .and_then(|bytes| bytes.checked_add("tier_d".len()))
            .ok_or(FirstSliceError::Limits)?;
    }
    let variable_text_bytes = LEGACY_AGGREGATE_TEXT_BYTES
        .checked_sub(fixed_text_bytes)
        .ok_or(FirstSliceError::Search)?;
    Ok((variable_text_bytes / file_count / 2).min(SOURCE_FALLBACK_TEXT_BYTES))
}

fn normalized_fact_work(
    document: &NormalizedIrDocument,
    reused_records: &ReusedNormalizedRecords,
    cancellation: &Cancellation,
) -> Result<Vec<FirstSliceNormalizedFactWork>, FirstSliceError> {
    let provenance = document
        .provenance
        .iter()
        .map(|record| (record.id, record))
        .collect::<BTreeMap<_, _>>();
    let mut groups =
        BTreeMap::<(IrFactDomain, String, FirstSliceFactWorkCause), (u64, BTreeSet<FileId>)>::new();
    let mut record = |domain: IrFactDomain,
                      provenance_id: FactId,
                      files: BTreeSet<FileId>,
                      reused: bool|
     -> Result<(), FirstSliceError> {
        check_cancellation(cancellation)?;
        let producer = provenance
            .get(&provenance_id)
            .ok_or(FirstSliceError::Identity)?
            .producer
            .name();
        let (provider_pass, rebuilt_cause) = normalized_provider_work(producer);
        let cause = if reused {
            FirstSliceFactWorkCause::CompleteDependencyMatch
        } else {
            rebuilt_cause
        };
        let group = groups
            .entry((domain, provider_pass.to_owned(), cause))
            .or_default();
        group.0 = group.0.checked_add(1).ok_or(FirstSliceError::Limits)?;
        group.1.extend(files);
        Ok(())
    };
    let evidence_files =
        |evidence: &FactEvidence| evidence_file(evidence).into_iter().collect::<BTreeSet<_>>();

    for file in &document.files {
        record(
            IrFactDomain::Files,
            file.provenance,
            BTreeSet::from([file.id]),
            reused_records.contains_file(file),
        )?;
    }
    for entity in &document.entities {
        record(
            IrFactDomain::Entities,
            entity.provenance,
            evidence_files(&entity.evidence),
            reused_records.contains_entity(entity),
        )?;
    }
    for occurrence in &document.occurrences {
        record(
            IrFactDomain::Occurrences,
            occurrence.provenance,
            BTreeSet::from([occurrence.file]),
            reused_records.contains_occurrence(occurrence),
        )?;
    }
    for relation in &document.relations {
        record(
            IrFactDomain::Relations,
            relation.provenance,
            evidence_files(&relation.evidence),
            reused_records.contains_relation(relation),
        )?;
    }
    for provenance_record in &document.provenance {
        let files = provenance_record
            .input_sources
            .iter()
            .chain(&provenance_record.evidence_sources)
            .map(|source| source.span().file())
            .collect();
        record(
            IrFactDomain::Provenance,
            provenance_record.id,
            files,
            reused_records.contains_provenance(provenance_record),
        )?;
    }
    for mapping in &document.source_mappings {
        record(
            IrFactDomain::SourceMappings,
            mapping.provenance,
            BTreeSet::from([mapping.from.span().file(), mapping.to.span().file()]),
            reused_records.contains_source_mapping(mapping),
        )?;
    }
    for coverage in &document.coverage_records {
        let mut files = evidence_files(&coverage.evidence);
        if let CoverageScope::File(file) = coverage.scope {
            files.insert(file);
        }
        record(
            coverage.domain,
            coverage.provenance,
            files,
            reused_records.contains_coverage(coverage),
        )?;
    }
    for skipped in &document.skipped_regions {
        record(
            IrFactDomain::Diagnostics,
            skipped.provenance,
            BTreeSet::from([skipped.source.span().file()]),
            reused_records.contains_skipped(skipped),
        )?;
    }
    for diagnostic in &document.diagnostics {
        record(
            IrFactDomain::Diagnostics,
            diagnostic.provenance,
            evidence_files(&diagnostic.evidence),
            reused_records.contains_diagnostic(diagnostic),
        )?;
    }
    for extension in &document.extensions {
        record(
            IrFactDomain::Extensions,
            extension.provenance,
            evidence_files(&extension.evidence),
            reused_records.contains_extension(extension),
        )?;
    }

    groups
        .into_iter()
        .map(|((domain, provider_pass, cause), (facts, files))| {
            Ok(FirstSliceNormalizedFactWork {
                domain,
                provider_pass,
                cause,
                files: u64::try_from(files.len()).map_err(|_| FirstSliceError::Limits)?,
                facts,
                file_ids: files,
            })
        })
        .collect()
}

fn normalized_provider_work(producer: &str) -> (&str, FirstSliceFactWorkCause) {
    if producer == RESOLVER_PROVIDER_NAME {
        (RESOLVER_PASS_ID, FirstSliceFactWorkCause::Resolution)
    } else if producer == "rootlight-first-slice-treesitter" {
        (
            LOWERING_PASS_ID,
            FirstSliceFactWorkCause::GenerationBoundLowering,
        )
    } else {
        (producer, FirstSliceFactWorkCause::GenerationBoundLowering)
    }
}

fn index_diagnostic_summaries(
    document: &NormalizedIrDocument,
    discovery_complete: bool,
    discovery_truncation: Option<DiscoveryTruncation>,
) -> Result<Vec<FirstSliceIndexDiagnostic>, FirstSliceError> {
    const REDACTED_CODE: &str = "diagnostic-redacted";
    const REDACTED_MESSAGE: &str = "an index diagnostic was omitted because it was not source free";
    const TRUNCATED_CODE: &str = "diagnostics-truncated";
    const TRUNCATED_MESSAGE: &str =
        "additional index diagnostics were omitted by the response limit";

    let mut summaries = BTreeSet::new();
    for diagnostic in &document.diagnostics {
        let summary = if public_diagnostic_code(&diagnostic.code)
            && public_diagnostic_message(&diagnostic.message)
        {
            FirstSliceIndexDiagnostic {
                code: diagnostic.code.clone(),
                message: diagnostic.message.clone(),
            }
        } else {
            FirstSliceIndexDiagnostic {
                code: REDACTED_CODE.to_owned(),
                message: REDACTED_MESSAGE.to_owned(),
            }
        };
        summaries.insert(summary);
    }
    if let Some(truncation) = discovery_truncation {
        let diagnostic = match truncation.resource {
            DiscoveryTruncationResource::Entries => FirstSliceIndexDiagnostic {
                code: "discovery-entries-truncated".to_owned(),
                message: "repository discovery stopped at the configured entry limit".to_owned(),
            },
            DiscoveryTruncationResource::RetainedSourceBytes => FirstSliceIndexDiagnostic {
                code: "discovery-source-bytes-truncated".to_owned(),
                message: format!(
                    "repository discovery retained a deterministic prefix of at most {} source bytes after observing at least {} bytes",
                    truncation.limit, truncation.observed
                ),
            },
        };
        summaries.insert(diagnostic);
    } else if !discovery_complete {
        summaries.insert(FirstSliceIndexDiagnostic {
            code: "discovery-incomplete".to_owned(),
            message: "repository discovery retained an incomplete deterministic prefix".to_owned(),
        });
    }

    let truncated = summaries.len() > MAX_FIRST_SLICE_INDEX_DIAGNOSTICS;
    let retained = if truncated {
        MAX_FIRST_SLICE_INDEX_DIAGNOSTICS.saturating_sub(1)
    } else {
        summaries.len()
    };
    let mut result = Vec::new();
    result
        .try_reserve_exact(retained.saturating_add(usize::from(truncated)))
        .map_err(|_| FirstSliceError::Limits)?;
    result.extend(summaries.into_iter().take(retained));
    if truncated {
        result.push(FirstSliceIndexDiagnostic {
            code: TRUNCATED_CODE.to_owned(),
            message: TRUNCATED_MESSAGE.to_owned(),
        });
        result.sort();
    }
    Ok(result)
}

fn public_diagnostic_code(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 128
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-' | b'.' | b':'))
}

fn public_diagnostic_message(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 1_024
        && value.bytes().all(|byte| {
            byte.is_ascii_lowercase() || byte.is_ascii_digit() || matches!(byte, b' ' | b'-')
        })
}

fn reserve_records<T>(
    target: &mut Vec<T>,
    additional: usize,
    maximum: usize,
) -> Result<(), FirstSliceError> {
    checked_combined_length(target.len(), additional, maximum)?;
    target
        .try_reserve(additional)
        .map_err(|_| FirstSliceError::Limits)
}

fn reserve_resource_records<T>(
    target: &mut Vec<T>,
    additional: usize,
    maximum: usize,
    resource: FirstSliceResource,
) -> Result<(), FirstSliceError> {
    checked_resource_length(target.len(), additional, maximum, resource)?;
    target
        .try_reserve(additional)
        .map_err(|_| FirstSliceError::Limits)
}

fn checked_resource_length(
    current: usize,
    additional: usize,
    maximum: usize,
    resource: FirstSliceResource,
) -> Result<usize, FirstSliceError> {
    let observed = current
        .checked_add(additional)
        .ok_or(FirstSliceError::Limits)?;
    if observed > maximum {
        return Err(resource_limit(resource, observed, maximum));
    }
    Ok(observed)
}

fn resource_limit(resource: FirstSliceResource, observed: usize, limit: usize) -> FirstSliceError {
    FirstSliceError::ResourceLimit {
        resource,
        observed: u64::try_from(observed).unwrap_or(u64::MAX),
        limit: u64::try_from(limit).unwrap_or(u64::MAX),
    }
}

fn estimated_resource_limit(
    resource: FirstSliceResource,
    estimated: u64,
    limit: u64,
) -> FirstSliceError {
    FirstSliceError::EstimatedResourceLimit {
        resource,
        estimated,
        limit,
    }
}

fn checked_combined_length(
    current: usize,
    additional: usize,
    maximum: usize,
) -> Result<usize, FirstSliceError> {
    let combined = current
        .checked_add(additional)
        .ok_or(FirstSliceError::Limits)?;
    if combined > maximum {
        return Err(FirstSliceError::Limits);
    }
    Ok(combined)
}

fn default_generation_payload_cancellation() -> Result<Cancellation, FirstSliceError> {
    let deadline = Instant::now()
        .checked_add(DEFAULT_GENERATION_PAYLOAD_TIMEOUT)
        .ok_or(FirstSliceError::Limits)?;
    Ok(Cancellation::with_deadline(deadline))
}

fn check_cancellation(cancellation: &Cancellation) -> Result<(), FirstSliceError> {
    cancellation
        .check()
        .map_err(|cancelled| FirstSliceError::Cancelled(cancelled.reason()))
}

fn current_cancellation(cancellation: &Cancellation) -> Option<FirstSliceError> {
    cancellation
        .check()
        .err()
        .map(|cancelled| FirstSliceError::Cancelled(cancelled.reason()))
}

fn map_discovery_error(error: DiscoveryError, cancellation: &Cancellation) -> FirstSliceError {
    if let Some(cancelled) = current_cancellation(cancellation) {
        return cancelled;
    }
    match error {
        DiscoveryError::InvalidLimits => FirstSliceError::Limits,
        DiscoveryError::StreamedCaptureUnavailable => FirstSliceError::ResourceUnavailable {
            resource: FirstSliceResource::SourceBytes,
        },
        DiscoveryError::InvalidPolicy | DiscoveryError::InvalidPattern { .. } => {
            FirstSliceError::Configuration
        }
        DiscoveryError::EntryLimit { maximum } => resource_limit(
            FirstSliceResource::DiscoveryEntries,
            maximum.saturating_add(1),
            maximum,
        ),
        DiscoveryError::RetainedSnapshotByteLimit { observed, maximum } => {
            FirstSliceError::ResourceLimit {
                resource: FirstSliceResource::SourceBytes,
                observed,
                limit: maximum,
            }
        }
        DiscoveryError::Vfs(error) => map_vfs_error(error, cancellation),
        DiscoveryError::Cancelled(cancelled) => FirstSliceError::Cancelled(cancelled.reason()),
        DiscoveryError::Incremental(error) => map_incremental_error(error, cancellation),
        DiscoveryError::IncrementalDrift => FirstSliceError::DiscoveryDrift,
        DiscoveryError::SerializeManifest(_) => FirstSliceError::Discovery,
    }
}

fn repository_capacity_limit(
    observed: usize,
    limit: usize,
    configuration: FirstSliceRepositoryCapacityConfiguration,
    pending_repositories: usize,
    reclaimable_repositories: usize,
) -> FirstSliceError {
    FirstSliceError::RepositoryCapacityLimit {
        observed: u64::try_from(observed)
            .unwrap_or(u64::MAX)
            .saturating_add(1),
        limit: u64::try_from(limit).unwrap_or(u64::MAX),
        configuration,
        pending_repositories: u64::try_from(pending_repositories).unwrap_or(u64::MAX),
        reclaimable_repositories: u64::try_from(reclaimable_repositories).unwrap_or(u64::MAX),
    }
}

fn maximum_repositories_for_retention(
    maximum_generations: usize,
    configured_maximum_repositories: usize,
) -> Result<usize, FirstSliceError> {
    // One slot remains available for transactional publication while every
    // configured repository retains its complete recovery generations.
    HARD_MAX_FIRST_SLICE_GENERATIONS
        .checked_sub(1)
        .and_then(|capacity| capacity.checked_div(maximum_generations))
        .map(|capacity| capacity.min(configured_maximum_repositories))
        .filter(|capacity| *capacity > 0)
        .ok_or(FirstSliceError::Retention)
}

fn map_incremental_error(error: IncrementalError, cancellation: &Cancellation) -> FirstSliceError {
    if let Some(cancelled) = current_cancellation(cancellation) {
        return cancelled;
    }
    match error {
        IncrementalError::Cancelled(cancelled) => FirstSliceError::Cancelled(cancelled.reason()),
        IncrementalError::InvalidLimit { .. } => FirstSliceError::Limits,
        IncrementalError::ResourceLimit {
            resource,
            observed,
            limit,
        } => resource_limit(incremental_resource(resource), observed, limit),
        IncrementalError::InvalidPassId
        | IncrementalError::DuplicateInput { .. }
        | IncrementalError::DuplicateArtifact { .. }
        | IncrementalError::DuplicateArtifactOutput { .. }
        | IncrementalError::DuplicateArtifactDependency { .. }
        | IncrementalError::EmptyArtifactPart { .. }
        | IncrementalError::ArtifactDependencyMismatch { .. }
        | IncrementalError::ArtifactUnknownOutput { .. }
        | IncrementalError::DuplicatePass { .. }
        | IncrementalError::EmptyPassOutputs { .. }
        | IncrementalError::UndeclaredInputKind { .. }
        | IncrementalError::UndeclaredInputDomain { .. }
        | IncrementalError::UndeclaredOutputDomain { .. }
        | IncrementalError::UnknownPass { .. }
        | IncrementalError::UnknownFactNode { .. }
        | IncrementalError::DuplicateFile { .. }
        | IncrementalError::PathIdentityCollision { .. }
        | IncrementalError::MissingHash { .. }
        | IncrementalError::UnexpectedHash { .. }
        | IncrementalError::DuplicateLogicalDomain { .. }
        | IncrementalError::MissingLogicalDomain { .. }
        | IncrementalError::LogicalInequality
        | IncrementalError::SerializeTrace(_)
        | IncrementalError::DuplicateIdentity { .. } => FirstSliceError::Incremental,
        _ => FirstSliceError::Incremental,
    }
}

fn map_vfs_error(error: VfsError, cancellation: &Cancellation) -> FirstSliceError {
    if let Some(cancelled) = current_cancellation(cancellation) {
        return cancelled;
    }
    match error {
        VfsError::Cancelled(reason) => FirstSliceError::Cancelled(reason),
        VfsError::PathTooLong { maximum } => estimated_resource_limit(
            FirstSliceResource::PathBytes,
            u64::try_from(maximum).unwrap_or(u64::MAX).saturating_add(1),
            u64::try_from(maximum).unwrap_or(u64::MAX),
        ),
        VfsError::TooManyPathComponents { maximum } => estimated_resource_limit(
            FirstSliceResource::PathComponents,
            u64::try_from(maximum).unwrap_or(u64::MAX).saturating_add(1),
            u64::try_from(maximum).unwrap_or(u64::MAX),
        ),
        VfsError::DirectoryEntryLimit { maximum } => resource_limit(
            FirstSliceResource::Files,
            maximum.saturating_add(1),
            maximum,
        ),
        VfsError::FileTooLarge { maximum } => estimated_resource_limit(
            FirstSliceResource::SourceBytes,
            maximum.saturating_add(1),
            maximum,
        ),
        VfsError::InvalidByteLimit | VfsError::SnapshotBatchLimit { .. } => FirstSliceError::Limits,
        VfsError::MemoryUnavailable => FirstSliceError::ResourceUnavailable {
            resource: FirstSliceResource::MemoryBytes,
        },
        VfsError::SnapshotWorkerUnavailable => FirstSliceError::ResourceUnavailable {
            resource: FirstSliceResource::ProcessResources,
        },
        VfsError::OpenRoot { .. }
        | VfsError::OpenDirectory { .. }
        | VfsError::ReadDirectory { .. }
        | VfsError::OpenFile { .. }
        | VfsError::ReadFile { .. } => FirstSliceError::RepositoryIo,
        VfsError::RootNotDirectory => FirstSliceError::Repository,
        VfsError::LinkedPath
        | VfsError::NotRegularFile
        | VfsError::UnstableFile
        | VfsError::StaleContentHash => FirstSliceError::DiscoveryDrift,
        VfsError::InvalidRelativePath
        | VfsError::InvalidRootPath
        | VfsError::SourceReferenceMismatch
        | VfsError::InvalidSourceSpan
        | VfsError::PersistedFileIdentityMismatch
        | VfsError::PersistedContentHashMismatch => FirstSliceError::Discovery,
    }
}

const fn incremental_resource(resource: rootlight_incremental::ResourceKind) -> FirstSliceResource {
    match resource {
        rootlight_incremental::ResourceKind::Files => FirstSliceResource::IncrementalFiles,
        rootlight_incremental::ResourceKind::Inputs => FirstSliceResource::IncrementalInputs,
        rootlight_incremental::ResourceKind::Artifacts => FirstSliceResource::IncrementalArtifacts,
        rootlight_incremental::ResourceKind::ArtifactOutputs => {
            FirstSliceResource::IncrementalArtifactOutputs
        }
        rootlight_incremental::ResourceKind::Passes => FirstSliceResource::IncrementalPasses,
        rootlight_incremental::ResourceKind::DependencyNodes => {
            FirstSliceResource::IncrementalDependencyNodes
        }
        rootlight_incremental::ResourceKind::DependencyEdges => {
            FirstSliceResource::IncrementalDependencyEdges
        }
        rootlight_incremental::ResourceKind::ClosureWork => {
            FirstSliceResource::IncrementalClosureWork
        }
        rootlight_incremental::ResourceKind::TraceEntries => {
            FirstSliceResource::IncrementalTraceEntries
        }
        rootlight_incremental::ResourceKind::LogicalBytes => {
            FirstSliceResource::IncrementalLogicalBytes
        }
    }
}

