    #[test]
    fn generation_phase_hook_preserves_the_original_result() {
        use generation_admission_observation::{CaptureGuard, MAX_OBSERVATION_BYTES};

        let capture = CaptureGuard::arm(MAX_OBSERVATION_BYTES).unwrap();
        let calls = std::cell::Cell::new(0);
        let original = FirstSliceError::ResourceLimit {
            resource: FirstSliceResource::TextBytes,
            observed: 17,
            limit: 16,
        };
        let result = observe_generation_phase!(FinalVerification, {
            calls.set(calls.get() + 1);
            Err::<(), _>(original)
        });
        assert_eq!(calls.get(), 1);
        assert_eq!(result, Err(original));
        let report: serde_json::Value =
            serde_json::from_slice(&capture.finish(&Cancellation::new()).unwrap()).unwrap();
        assert_eq!(report["failure_phase"], "final_verification");
        assert_eq!(report["failure_phase_classified_by_caller"], true);
        assert_eq!(report["original_error"]["code"], "resource_limit");
        assert_eq!(
            report["original_error"]["resource_limit"]["resource"],
            "text_bytes"
        );
        assert_eq!(report["original_error"]["resource_limit"]["observed"], 17);
        assert_eq!(report["original_error"]["resource_limit"]["limit"], 16);
    }

    #[test]
    fn generation_phase_hook_does_not_seal_successful_work() {
        use generation_admission_observation::{CaptureGuard, MAX_OBSERVATION_BYTES};

        let capture = CaptureGuard::arm(MAX_OBSERVATION_BYTES).unwrap();
        let result = observe_generation_phase!(FileDocument, Ok::<_, FirstSliceError>(37));
        assert_eq!(result, Ok(37));
        assert!(!capture.reached());
        assert_eq!(
            capture.finish(&Cancellation::new()),
            Err(FirstSliceError::Identity)
        );
    }

    #[test]
    fn identity_allocation_failure_is_not_invalid_generation() {
        let cancellation = Cancellation::new();
        assert_eq!(
            map_identity_error(
                IdentityVerificationError::ResourceUnavailable,
                &cancellation
            ),
            FirstSliceError::ResourceUnavailable {
                resource: FirstSliceResource::MemoryBytes,
            }
        );
        assert_eq!(
            map_identity_error(IdentityVerificationError::InvalidGeneration, &cancellation),
            FirstSliceError::IdentityVerification(FirstSliceIdentityFailure::InvalidGeneration)
        );
        cancellation.cancel(CancellationReason::ClientRequest);
        assert_eq!(
            map_identity_error(
                IdentityVerificationError::ResourceUnavailable,
                &cancellation
            ),
            FirstSliceError::Cancelled(CancellationReason::ClientRequest)
        );
    }

    #[test]
    fn project_manifest_carries_source_bound_tsconfig_snapshots() {
        let fixture = TempDir::new().expect("fixture root exists");
        write_language_fixture(
            fixture.path(),
            &[
                ("tsconfig.json", r#"{"compilerOptions":{"baseUrl":"."}}"#),
                ("src/main.ts", "export const value = 1;"),
            ],
        );
        let root = RepositoryRoot::open(
            derive_repository(b"module-config-fixture").id(),
            fixture.path(),
        )
        .expect("fixture root opens");
        let snapshot = root
            .snapshot(
                &RelativePath::parse(Path::new("tsconfig.json"))
                    .expect("configuration path is valid"),
                1024,
            )
            .expect("configuration snapshot captures");
        let expected_hash = snapshot.content_hash();
        let sources = [RustSourceInput {
            snapshot,
            encoding: "utf-8".to_owned(),
            generated: false,
            origins: Vec::new(),
        }];
        let manifest =
            project_context_manifest("typescript", content_hash(b"configuration"), &sources)
                .expect("project manifest encodes");
        let marker = manifest
            .windows(PROJECT_MODULE_RESOLUTION_MARKER.len())
            .position(|window| window == PROJECT_MODULE_RESOLUTION_MARKER)
            .expect("module metadata marker exists");
        let encoded = &manifest[marker + PROJECT_MODULE_RESOLUTION_MARKER.len()..];
        let metadata: serde_json::Value =
            serde_json::from_slice(encoded).expect("module metadata decodes");
        assert_eq!(metadata["configs"][0]["path"], "tsconfig.json");
        assert_eq!(metadata["configs"][0]["content_hash"], json!(expected_hash));
        assert_eq!(
            metadata["configs"][0]["content"],
            r#"{"compilerOptions":{"baseUrl":"."}}"#
        );
        assert_eq!(
            project_context_manifest("rust", content_hash(b"configuration"), &sources)
                .expect("non-ECMAScript manifest encodes")
                .windows(PROJECT_MODULE_RESOLUTION_MARKER.len())
                .position(|window| window == PROJECT_MODULE_RESOLUTION_MARKER),
            None
        );
    }

    #[test]
    fn storage_policy_distinguishes_current_defaults_user_overrides_and_legacy_config() {
        let current = FirstSliceStoragePolicy::resolve_user_config(None, 8)
            .expect("absent config resolves current defaults");
        assert_eq!(current.retained_generations(), 2);
        assert_eq!(current.minimum_free_disk_bytes(), 64 * 1024 * 1024);
        assert_eq!(
            current
                .effective_maximum_repositories(current.retained_generations())
                .expect("current repository capacity resolves"),
            4_096
        );

        let configured = FirstSliceStoragePolicy::resolve_user_config(
            Some(
                "version = \"1.2\"\n[storage]\nmaximum_repository_bytes = 1073741824\nmaximum_catalog_bytes = 2147483648\nretained_generations = 3\nminimum_free_disk_bytes = 134217728\nsource_reservation_factor = 32\noracle_reservation_factor = 12\n",
            ),
            8,
        )
        .expect("valid user storage policy resolves");
        assert_eq!(configured.retained_generations(), 3);
        assert_eq!(configured.maximum_repository_bytes(), 1024 * 1024 * 1024);
        assert_eq!(configured.minimum_free_disk_bytes(), 128 * 1024 * 1024);
        assert_eq!(configured.source_reservation_factor(), 32);
        assert_eq!(
            configured
                .effective_maximum_repositories(configured.retained_generations())
                .expect("configuration 1.2 repository capacity resolves"),
            2_730
        );

        let legacy = FirstSliceStoragePolicy::resolve_user_config(Some("version = \"1.1\""), 8)
            .expect("legacy config keeps compatibility policy");
        assert_eq!(legacy.retained_generations(), 8);
        assert_eq!(legacy.minimum_free_disk_bytes(), 0);
        assert_eq!(legacy.maximum_repository_bytes(), u64::MAX);
        assert_eq!(
            legacy
                .effective_maximum_repositories(legacy.retained_generations())
                .expect("legacy repository capacity resolves"),
            1_024
        );
    }

    #[test]
    fn storage_policy_clamps_configured_repository_capacity_to_generation_capacity() {
        let configured = FirstSliceStoragePolicy::resolve_user_config(
            Some(
                "version = \"1.3\"\n[storage]\nmaximum_repositories = 176\nretained_generations = 2\n",
            ),
            8,
        )
        .expect("configured repository capacity resolves");
        assert_eq!(
            configured
                .effective_maximum_repositories(configured.retained_generations())
                .expect("configured repository capacity is representable"),
            176
        );

        let generation_bound = FirstSliceStoragePolicy::resolve_user_config(
            Some(
                "version = \"1.3\"\n[storage]\nmaximum_repositories = 4096\nretained_generations = 8\n",
            ),
            2,
        )
        .expect("generation-bound repository capacity resolves");
        assert_eq!(
            generation_bound
                .effective_maximum_repositories(generation_bound.retained_generations())
                .expect("generation-bound repository capacity is representable"),
            1_024
        );
    }

