    #[test]
    fn resolution_work_overflow_publishes_unresolved_bounded_facts() {
        let repository = derive_repository(b"resolution-work-bounded-repository").id();
        let generation = GenerationId::from_bytes([73; 20]);
        let file = derive_file(FileIdentity {
            repository,
            path_identity: b"src/lib.rs",
        })
        .id();
        let source_hash = content_hash(b"resolution-work-bounded-source");
        let source = SourceRef::new(
            repository,
            generation,
            SourceSpan::new(file, 0, 64).expect("fixture source span is valid"),
            source_hash,
            None,
        );
        let producer = ProducerIdentity::new(
            "rootlight-resolution-work-fixture",
            "1.0",
            content_hash(b"resolution-work-fixture-producer"),
        )
        .expect("fixture producer is valid");
        let mut provenance = ProvenanceRecord {
            id: FactId::from_bytes([0; 20]),
            repository,
            generation,
            producer_kind: ProducerKind::Parser,
            producer,
            binary_digest: content_hash(b"resolution-work-fixture-binary"),
            frontend_version: Some("fixture-1".to_owned()),
            language: "rust".to_owned(),
            tier: AnalysisTier::TierB,
            build_context: BuildContextIdentity::new(content_hash(
                b"resolution-work-fixture-context",
            )),
            input_sources: vec![source.clone()],
            evidence_sources: vec![source.clone()],
            derivation_parents: Vec::new(),
            rule: None,
        };
        provenance.id =
            derive_provenance_record_id(&provenance).expect("fixture provenance identity derives");
        let provenance_id = provenance.id;
        let mut document = NormalizedIrDocument::empty(repository, generation);
        document.provenance.push(provenance);
        document.files.push(FileRecord {
            id: file,
            repository,
            generation,
            path: "src/lib.rs".to_owned(),
            path_locator: None,
            content_hash: source_hash,
            byte_length: 64,
            language: "rust".to_owned(),
            encoding: "utf-8".to_owned(),
            generated: false,
            provenance: provenance_id,
            evidence: FactEvidence {
                source: Some(source.clone()),
                derivation: Vec::new(),
            },
        });
        let file_claim = FileIdentityClaim {
            file,
            repository,
            path: "src/lib.rs".to_owned(),
            path_identity: b"src/lib.rs".to_vec(),
            content_hash: source_hash,
            byte_length: 64,
        };
        document.extensions.push(
            new_file_identity_claim_envelope(
                &file_claim,
                generation,
                provenance_id,
                source.clone(),
            )
            .expect("fixture file identity claim encodes"),
        );
        for identity in [75_u8, 76, 77] {
            let declared_identity = format!("shared-{identity}");
            let mut container_identity = vec![0];
            container_identity.extend_from_slice(file.as_bytes());
            let claim = SymbolIdentityClaim {
                symbol: SymbolId::from_bytes([0; 20]),
                repository,
                language: "rust".to_owned(),
                kind: EntityKind::Function,
                container: Some(ContainerRef::File(file)),
                container_identity,
                declared_identity,
                signature_discriminator: Vec::new(),
                build_context_discriminator: content_hash(b"resolution-work-fixture-context")
                    .as_bytes()
                    .to_vec(),
            };
            let claim = SymbolIdentityClaim {
                symbol: claim.derived_symbol(),
                ..claim
            };
            document.entities.push(EntityRecord {
                id: claim.symbol,
                repository,
                generation,
                kind: EntityKind::Function,
                language: "rust".to_owned(),
                tier: AnalysisTier::TierB,
                canonical_name: "shared".to_owned(),
                display_name: "shared".to_owned(),
                qualified_name: format!("fixture::shared::{identity}"),
                container: Some(ContainerRef::File(file)),
                visibility: rootlight_ir::EntityVisibility::Private,
                flags: Vec::new(),
                provenance: provenance_id,
                evidence: FactEvidence {
                    source: Some(source.clone()),
                    derivation: Vec::new(),
                },
            });
            document.extensions.push(
                new_symbol_identity_claim_envelope(
                    &claim,
                    generation,
                    provenance_id,
                    source.clone(),
                )
                .expect("fixture symbol identity claim encodes"),
            );
        }
        let text_hash = content_hash(b"shared");
        let mut occurrence = rootlight_ir::OccurrenceRecord {
            id: FactId::from_bytes([78; 20]),
            repository,
            generation,
            file,
            source: source.clone(),
            role: rootlight_ir::OccurrenceRole::Reference,
            enclosing: None,
            target: rootlight_ir::OccurrenceTarget::Unresolved { text_hash },
            syntactic_text_hash: text_hash,
            syntax_kind: "identifier".to_owned(),
            provenance: provenance_id,
            confidence: rootlight_ir::Confidence::new(0).expect("zero fixture confidence is valid"),
            evidence: FactEvidence {
                source: Some(source.clone()),
                derivation: Vec::new(),
            },
        };
        occurrence.id = rootlight_ir::derive_occurrence_record_id(&occurrence)
            .expect("fixture occurrence identity derives");
        document.occurrences.push(occurrence);
        for domain in [IrFactDomain::Occurrences, IrFactDomain::Relations] {
            let mut coverage = CoverageRecord {
                id: FactId::from_bytes([0; 20]),
                repository,
                generation,
                scope: CoverageScope::File(file),
                domain,
                tier: AnalysisTier::TierB,
                status: CoverageStatus::Complete,
                discovered: 1,
                indexed: 1,
                skipped: 0,
                provenance: provenance_id,
                evidence: FactEvidence {
                    source: Some(source.clone()),
                    derivation: Vec::new(),
                },
            };
            coverage.id =
                derive_coverage_record_id(&coverage).expect("fixture coverage identity derives");
            document.coverage_records.push(coverage);
        }
        let limits =
            ResolutionLimits::with_work_limit(1, 3).expect("fixture resolver limits are valid");
        rootlight_ir::validate_ir_document(
            &document,
            &IrLimits::default(),
            &ExtensionSupport::default(),
        )
        .expect("fixture normalized document is valid");

        let bounded = apply_bounded_resolution(
            document,
            limits,
            ResolverFactContext::new(content_hash(b"resolution-work-fixture-context")),
            &Cancellation::new(),
        )
        .expect("over-limit resolution publishes bounded structural facts");

        assert!(matches!(
            bounded.occurrences[0].target,
            rootlight_ir::OccurrenceTarget::Unresolved { .. }
        ));
        assert!(bounded.relations.is_empty());
        assert!(bounded.coverage_records.iter().all(|coverage| {
            !matches!(
                coverage.domain,
                IrFactDomain::Occurrences | IrFactDomain::Relations
            ) || coverage.status == CoverageStatus::Bounded
        }));
        assert!(bounded.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "resolution-work-bounded"
                && diagnostic.message
                    == "resolution required at least 4 work units above the configured limit 3"
        }));
    }

    #[test]
    fn project_partition_merge_unifies_external_symbol_claims() {
        fn document(
            repository: RepositoryId,
            generation: GenerationId,
            file: FileId,
        ) -> NormalizedIrDocument {
            let source = SourceRef::new(
                repository,
                generation,
                SourceSpan::new(file, 0, 1).expect("external symbol source span is valid"),
                content_hash(file.as_bytes()),
                None,
            );
            let build_context =
                BuildContextIdentity::new(content_hash(b"partition-merge-build-context"));
            let producer = ProducerIdentity::new(
                "rootlight-test-project",
                "1.0",
                content_hash(b"partition-merge-producer"),
            )
            .expect("project producer is valid");
            let mut provenance = ProvenanceRecord {
                id: FactId::from_bytes([0; 20]),
                repository,
                generation,
                producer_kind: ProducerKind::Derivation,
                producer,
                binary_digest: content_hash(b"partition-merge-binary"),
                frontend_version: Some("test-project-1".to_owned()),
                language: "rust".to_owned(),
                tier: AnalysisTier::TierB,
                build_context,
                input_sources: vec![source.clone()],
                evidence_sources: vec![source.clone()],
                derivation_parents: Vec::new(),
                rule: None,
            };
            provenance.id = derive_provenance_record_id(&provenance)
                .expect("project provenance identity derives");
            let mut container_identity = vec![0];
            container_identity.extend_from_slice(repository.as_bytes());
            let mut claim = SymbolIdentityClaim {
                symbol: SymbolId::from_bytes([0; 20]),
                repository,
                language: "rust".to_owned(),
                kind: EntityKind::ExternalSymbol,
                container: Some(ContainerRef::Repository(repository)),
                container_identity,
                declared_identity: "external_api".to_owned(),
                signature_discriminator: content_hash(b"external_api").as_bytes().to_vec(),
                build_context_discriminator: build_context.digest().as_bytes().to_vec(),
            };
            claim.symbol = claim.derived_symbol();
            let entity = EntityRecord {
                id: claim.symbol,
                repository,
                generation,
                kind: EntityKind::ExternalSymbol,
                language: "rust".to_owned(),
                tier: AnalysisTier::TierB,
                canonical_name: "external_api".to_owned(),
                display_name: "external_api".to_owned(),
                qualified_name: "external_api".to_owned(),
                container: Some(ContainerRef::Repository(repository)),
                visibility: EntityVisibility::Unknown,
                flags: Vec::new(),
                provenance: provenance.id,
                evidence: FactEvidence {
                    source: Some(source.clone()),
                    derivation: Vec::new(),
                },
            };
            let identity_claim =
                new_symbol_identity_claim_envelope(&claim, generation, provenance.id, source)
                    .expect("external symbol identity claim encodes");
            let mut document = NormalizedIrDocument::empty(repository, generation);
            document.provenance.push(provenance);
            document.entities.push(entity);
            document.extensions.push(identity_claim);
            document
        }

        let repository = derive_repository(b"partition-merge-repository").id();
        let generation = GenerationId::from_bytes([21; 20]);
        let mut analysis = FirstSliceProjectAnalysis::new(
            document(repository, generation, FileId::from_bytes([1; 20])),
            true,
        );
        analysis
            .append_partition(
                document(repository, generation, FileId::from_bytes([2; 20])),
                false,
            )
            .expect("the next project partition merges immediately");
        let (
            documents,
            isolation_permits_deep_adapter,
            partitioned,
            diagnostics_truncated,
            facts_truncated,
        ) = analysis.into_parts();
        assert!(!isolation_permits_deep_adapter);
        assert!(partitioned);
        assert!(!diagnostics_truncated);
        assert!(!facts_truncated);
        assert_eq!(documents.len(), 1);
        let merged = &documents[0];

        assert_eq!(merged.entities.len(), 1);
        assert_eq!(
            merged
                .extensions
                .iter()
                .filter(|extension| extension.namespace == SYMBOL_IDENTITY_CLAIM_NAMESPACE)
                .count(),
            1
        );
        assert_eq!(merged.provenance.len(), 2);
    }

    #[test]
    fn supplemental_project_relations_reuse_primary_fact_closure() {
        struct InputFixture<'a> {
            file: FileId,
            path: &'a str,
            source: &'a [u8],
            symbol: SymbolId,
            symbol_name: &'a str,
        }

        fn document(
            repository: RepositoryId,
            generation: GenerationId,
            provider_identity: ContentHash,
            fixture: &InputFixture<'_>,
        ) -> (NormalizedIrDocument, SourceRef) {
            let source = SourceRef::new(
                repository,
                generation,
                SourceSpan::new(
                    fixture.file,
                    0,
                    u64::try_from(fixture.source.len()).expect("fixture source length fits"),
                )
                .expect("fixture source span is valid"),
                content_hash(fixture.source),
                None,
            );
            let producer = ProducerIdentity::new(
                "rootlight-test-project",
                "1.0",
                content_hash(b"supplemental-relation-producer"),
            )
            .expect("project producer is valid");
            let mut provenance = ProvenanceRecord {
                id: FactId::from_bytes([0; 20]),
                repository,
                generation,
                producer_kind: ProducerKind::Derivation,
                producer,
                binary_digest: provider_identity,
                frontend_version: Some("test-project-1".to_owned()),
                language: "cpp".to_owned(),
                tier: AnalysisTier::TierB,
                build_context: BuildContextIdentity::new(content_hash(
                    b"supplemental-relation-context",
                )),
                input_sources: vec![source.clone()],
                evidence_sources: vec![source.clone()],
                derivation_parents: Vec::new(),
                rule: None,
            };
            provenance.id = derive_provenance_record_id(&provenance)
                .expect("project provenance identity derives");
            let file_record = FileRecord {
                id: fixture.file,
                repository,
                generation,
                path: fixture.path.to_owned(),
                path_locator: None,
                content_hash: source.content_hash(),
                byte_length: u64::try_from(fixture.source.len())
                    .expect("fixture source length fits"),
                language: "cpp".to_owned(),
                encoding: "utf-8".to_owned(),
                generated: false,
                provenance: provenance.id,
                evidence: FactEvidence {
                    source: Some(source.clone()),
                    derivation: Vec::new(),
                },
            };
            let entity = EntityRecord {
                id: fixture.symbol,
                repository,
                generation,
                kind: EntityKind::Function,
                language: "cpp".to_owned(),
                tier: AnalysisTier::TierB,
                canonical_name: fixture.symbol_name.to_owned(),
                display_name: fixture.symbol_name.to_owned(),
                qualified_name: fixture.symbol_name.to_owned(),
                container: Some(ContainerRef::File(fixture.file)),
                visibility: EntityVisibility::Unknown,
                flags: Vec::new(),
                provenance: provenance.id,
                evidence: FactEvidence {
                    source: Some(source.clone()),
                    derivation: Vec::new(),
                },
            };
            let mut document = NormalizedIrDocument::empty(repository, generation);
            document.files.push(file_record);
            document.entities.push(entity);
            document.provenance.push(provenance);
            (document, source)
        }

        let repository = derive_repository(b"supplemental-relation-repository").id();
        let generation = GenerationId::from_bytes([31; 20]);
        let provider_identity = content_hash(b"supplemental-relation-binary");
        let declaration_bytes = b"void execute();\n";
        let test_bytes = b"void verifies_execute();\n";
        let declaration_file = FileId::from_bytes([32; 20]);
        let test_file = FileId::from_bytes([33; 20]);
        let declaration_symbol = SymbolId::from_bytes([34; 20]);
        let test_symbol = SymbolId::from_bytes([35; 20]);
        let declaration_fixture = InputFixture {
            file: declaration_file,
            path: "include/execute.hpp",
            source: declaration_bytes,
            symbol: declaration_symbol,
            symbol_name: "execute",
        };
        let test_fixture = InputFixture {
            file: test_file,
            path: "tests/execute_case.cpp",
            source: test_bytes,
            symbol: test_symbol,
            symbol_name: "verifies_execute",
        };
        let (declaration_document, _) = document(
            repository,
            generation,
            provider_identity,
            &declaration_fixture,
        );
        let (test_document, test_source) =
            document(repository, generation, provider_identity, &test_fixture);
        let test_provenance = test_document.provenance[0].id;

        let mut bridge = declaration_document.clone();
        bridge.files.extend(test_document.files.clone());
        bridge.entities.extend(test_document.entities.clone());
        bridge.provenance.extend(test_document.provenance.clone());
        let mut relation = RelationRecord {
            id: FactId::from_bytes([0; 20]),
            repository,
            generation,
            subject: RelationEndpoint::Entity(test_symbol),
            predicate: RelationPredicate::Tests,
            object: RelationEndpoint::Entity(declaration_symbol),
            confidence: rootlight_ir::Confidence::new(1000).expect("fixture confidence is valid"),
            evidence_kind: rootlight_ir::EvidenceKind::Derived,
            provenance: test_provenance,
            evidence: FactEvidence {
                source: Some(test_source),
                derivation: Vec::new(),
            },
        };
        relation.id = rootlight_ir::derive_relation_record_id(&relation)
            .expect("fixture relation identity derives");
        bridge.relations.push(relation.clone());
        rootlight_ir::validate_ir_document(
            &bridge,
            &IrLimits::default(),
            &ExtensionSupport::default(),
        )
        .expect("overlapping supplemental output is valid in isolation");

        let inputs = [
            FirstSliceProjectInput {
                file: declaration_file,
                path: "include/execute.hpp",
                content_hash: content_hash(declaration_bytes),
                source: declaration_bytes,
                generated: false,
                origins: &[],
            },
            FirstSliceProjectInput {
                file: test_file,
                path: "tests/execute_case.cpp",
                content_hash: content_hash(test_bytes),
                source: test_bytes,
                generated: false,
                origins: &[],
            },
        ];

        let mut overlapping = FirstSliceProjectAnalysis::new(declaration_document.clone(), true);
        overlapping
            .append_partition(test_document.clone(), true)
            .expect("primary partition merges");
        overlapping
            .append_partition(bridge.clone(), true)
            .expect("an overlapping ordinary partition merges mechanically");
        let (overlapping_documents, ..) = overlapping.into_parts();
        assert!(!project_documents_match_inputs(
            &overlapping_documents,
            repository,
            generation,
            provider_identity,
            &inputs,
        ));

        let mut cancelled_analysis =
            FirstSliceProjectAnalysis::new(declaration_document.clone(), true);
        cancelled_analysis
            .append_partition(test_document.clone(), true)
            .expect("primary partition merges");
        let cancelled = deadline();
        assert!(cancelled.cancel(CancellationReason::ClientRequest));
        assert!(matches!(
            cancelled_analysis.append_supplemental_relations_with_cancellation(
                bridge.clone(),
                true,
                &cancelled
            ),
            Err(FirstSliceProjectAnalysisError::Cancelled(
                CancellationReason::ClientRequest
            ))
        ));

        let mut analysis = FirstSliceProjectAnalysis::new(declaration_document, true);
        analysis
            .append_partition(test_document, true)
            .expect("primary partition merges");
        analysis
            .append_supplemental_relations(bridge, true)
            .expect("supplemental relation closure merges");
        let (documents, isolated, partitioned, diagnostics_truncated, facts_truncated) =
            analysis.into_parts();
        assert!(isolated);
        assert!(partitioned);
        assert!(!diagnostics_truncated);
        assert!(!facts_truncated);
        assert!(project_documents_match_inputs(
            &documents,
            repository,
            generation,
            provider_identity,
            &inputs,
        ));
        let [merged] = documents.as_slice() else {
            panic!("one merged project document is expected");
        };
        assert_eq!(merged.files.len(), 2);
        assert_eq!(merged.entities.len(), 2);
        assert_eq!(merged.provenance.len(), 2);
        assert_eq!(merged.relations, [relation]);
        rootlight_ir::validate_ir_document(
            merged,
            &IrLimits::default(),
            &ExtensionSupport::default(),
        )
        .expect("supplemental relation merge remains valid normalized IR");
    }

    #[test]
    fn supplemental_prefix_rejects_projected_consumer_call() {
        fn document(
            repository: RepositoryId,
            generation: GenerationId,
            file: FileId,
            path: &str,
            source_bytes: &[u8],
            symbol: SymbolId,
            symbol_name: &str,
        ) -> (NormalizedIrDocument, SourceRef, FactId) {
            let source = SourceRef::new(
                repository,
                generation,
                SourceSpan::new(
                    file,
                    0,
                    u64::try_from(source_bytes.len()).expect("fixture source length fits"),
                )
                .expect("fixture source span is valid"),
                content_hash(source_bytes),
                None,
            );
            let producer = ProducerIdentity::new(
                "rootlight-prefix-test",
                "1.0",
                content_hash(b"supplemental-prefix-producer"),
            )
            .expect("fixture producer is valid");
            let mut provenance = ProvenanceRecord {
                id: FactId::from_bytes([0; 20]),
                repository,
                generation,
                producer_kind: ProducerKind::Derivation,
                producer,
                binary_digest: content_hash(b"supplemental-prefix-binary"),
                frontend_version: Some("prefix-test-1".to_owned()),
                language: "javascript".to_owned(),
                tier: AnalysisTier::TierB,
                build_context: BuildContextIdentity::new(content_hash(
                    b"supplemental-prefix-context",
                )),
                input_sources: vec![source.clone()],
                evidence_sources: vec![source.clone()],
                derivation_parents: Vec::new(),
                rule: None,
            };
            provenance.id = derive_provenance_record_id(&provenance)
                .expect("fixture provenance identity derives");
            let file_record = FileRecord {
                id: file,
                repository,
                generation,
                path: path.to_owned(),
                path_locator: None,
                content_hash: source.content_hash(),
                byte_length: u64::try_from(source_bytes.len()).expect("fixture source length fits"),
                language: "javascript".to_owned(),
                encoding: "utf-8".to_owned(),
                generated: false,
                provenance: provenance.id,
                evidence: FactEvidence {
                    source: Some(source.clone()),
                    derivation: Vec::new(),
                },
            };
            let entity = EntityRecord {
                id: symbol,
                repository,
                generation,
                kind: EntityKind::Function,
                language: "javascript".to_owned(),
                tier: AnalysisTier::TierB,
                canonical_name: symbol_name.to_owned(),
                display_name: symbol_name.to_owned(),
                qualified_name: symbol_name.to_owned(),
                container: Some(ContainerRef::File(file)),
                visibility: EntityVisibility::Unknown,
                flags: Vec::new(),
                provenance: provenance.id,
                evidence: FactEvidence {
                    source: Some(source.clone()),
                    derivation: Vec::new(),
                },
            };
            let provenance_id = provenance.id;
            let mut document = NormalizedIrDocument::empty(repository, generation);
            document.files.push(file_record);
            document.entities.push(entity);
            document.provenance.push(provenance);
            (document, source, provenance_id)
        }

        let repository = derive_repository(b"supplemental-prefix-repository").id();
        let generation = GenerationId::from_bytes([61; 20]);
        let provider_file = FileId::from_bytes([62; 20]);
        let consumer_file = FileId::from_bytes([63; 20]);
        let target_symbol = SymbolId::from_bytes([64; 20]);
        let caller_symbol = SymbolId::from_bytes([65; 20]);
        let provider_source = b"export function target() {}\n";
        let consumer_prefix = b"export function caller() { return target(); }\n";
        let consumer_source =
            b"export function caller() { return target(); }\nconst retained = true;\n";
        let mut projected_consumer_source = consumer_prefix.to_vec();
        projected_consumer_source.extend_from_slice(b"}\n");
        let (provider_document, _, _) = document(
            repository,
            generation,
            provider_file,
            "src/provider.js",
            provider_source,
            target_symbol,
            "target",
        );
        let (consumer_document, _, _) = document(
            repository,
            generation,
            consumer_file,
            "src/consumer.js",
            consumer_source,
            caller_symbol,
            "caller",
        );
        let (projected_consumer, _, projected_provenance) = document(
            repository,
            generation,
            consumer_file,
            "src/consumer.js",
            &projected_consumer_source,
            caller_symbol,
            "caller",
        );
        let call_start = consumer_prefix
            .windows(b"target".len())
            .position(|window| window == b"target")
            .expect("fixture call is present");
        let call_span = SourceSpan::new(
            consumer_file,
            u64::try_from(call_start).expect("fixture offset fits"),
            u64::try_from(call_start + "target".len()).expect("fixture offset fits"),
        )
        .expect("fixture call span is valid");
        let call_source = SourceRef::new(
            repository,
            generation,
            call_span,
            content_hash(&projected_consumer_source),
            None,
        );
        let mut occurrence = OccurrenceRecord {
            id: FactId::from_bytes([0; 20]),
            repository,
            generation,
            file: consumer_file,
            source: call_source.clone(),
            role: OccurrenceRole::CallSite,
            enclosing: Some(caller_symbol),
            target: OccurrenceTarget::Resolved {
                symbol: target_symbol,
            },
            syntactic_text_hash: content_hash(b"target"),
            syntax_kind: "call_expression".to_owned(),
            provenance: projected_provenance,
            confidence: rootlight_ir::Confidence::new(1000).expect("fixture confidence is valid"),
            evidence: FactEvidence {
                source: Some(call_source.clone()),
                derivation: Vec::new(),
            },
        };
        occurrence.id = rootlight_ir::derive_occurrence_record_id(&occurrence)
            .expect("fixture occurrence identity derives");
        let mut relation = RelationRecord {
            id: FactId::from_bytes([0; 20]),
            repository,
            generation,
            subject: RelationEndpoint::Occurrence(occurrence.id),
            predicate: RelationPredicate::Calls,
            object: RelationEndpoint::Entity(target_symbol),
            confidence: occurrence.confidence,
            evidence_kind: rootlight_ir::EvidenceKind::Derived,
            provenance: projected_provenance,
            evidence: FactEvidence {
                source: Some(call_source),
                derivation: Vec::new(),
            },
        };
        relation.id =
            derive_relation_record_id(&relation).expect("fixture relation identity derives");
        let mut bridge = provider_document.clone();
        bridge.files.extend(projected_consumer.files);
        bridge.entities.extend(projected_consumer.entities);
        bridge.provenance.extend(projected_consumer.provenance);
        bridge.occurrences.push(occurrence);
        bridge.relations.push(relation);
        let prefix = FirstSliceSupplementalPrefix::new(
            consumer_file,
            content_hash(consumer_source),
            consumer_source,
            &projected_consumer_source,
            consumer_prefix.len(),
        )
        .expect("closed prefix proof is valid");

        let mut analysis = FirstSliceProjectAnalysis::new(provider_document, true);
        analysis
            .append_partition(consumer_document, true)
            .expect("primary consumer partition merges");
        analysis
            .append_supplemental_prefix_relations(bridge, true, &[prefix])
            .expect("unsafe projected relation is ignored");
        let (documents, ..) = analysis.into_parts();
        let [merged] = documents.as_slice() else {
            panic!("one merged document is expected");
        };
        assert!(merged.relations.is_empty());
        rootlight_ir::validate_ir_document(
            merged,
            &IrLimits::default(),
            &ExtensionSupport::default(),
        )
        .expect("rejecting projected evidence preserves valid normalized IR");
    }

