    #[test]
    fn matlab_bindings_survive_noop_incremental_clean_rebuild_and_restart() {
        use rootlight_ir::{OccurrenceRole, OccurrenceTarget, RelationEndpoint, RelationPredicate};

        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let fixture = durable_test_tempdir();
        let path = fixture.path().join("update.m");
        let source = "function result = update(value)\nlocal = value;\nlocal = local + 1;\nresult = helper(local);\nend\nfunction out = helper(item)\nout = item;\nend\n";
        fs::write(&path, source).unwrap();
        fs::write(
            fixture.path().join("companion.rs"),
            "pub fn companion() {}\n",
        )
        .unwrap();
        let mut service =
            FirstSliceService::new_durable(4, paths.state_dir(), &deadline()).unwrap();
        let initial = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(initial.indexed_files, 2);
        let noop = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(noop, initial);
        let changed = source.replace("+ 1", "+ 2");
        fs::write(&path, &changed).unwrap();
        let updated = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_ne!(updated.generation, initial.generation);
        let evidence = service.incremental_evidence(updated.generation).unwrap();
        assert_eq!(evidence.parsed_files(), 1);
        assert_eq!(evidence.reused_parser_artifacts(), 1);
        let prepared = service
            .prepare_repository_with_options(
                fixture.path(),
                FirstSliceIndexOptions::clean_rebuild(FirstSliceIndexMode::Structural),
                &deadline(),
            )
            .unwrap();
        let committed = service
            .publish_prepared_with_metrics(prepared, &deadline())
            .unwrap();
        let clean = committed.receipt();
        assert!(updated.logical_snapshot.is_some());
        assert_eq!(clean.logical_snapshot, updated.logical_snapshot);
        drop(service);
        let restored = FirstSliceService::new_durable(4, paths.state_dir(), &deadline()).unwrap();
        let mut initial_ids = None;
        for (receipt, expected) in [
            (&initial, source),
            (&updated, changed.as_str()),
            (clean, changed.as_str()),
        ] {
            let snapshot = restored
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            let helper = document
                .entities
                .iter()
                .find(|entity| entity.language == "matlab" && entity.canonical_name == "helper")
                .unwrap();
            let calls: Vec<_> = document
                .occurrences
                .iter()
                .filter(|site| {
                    site.role == OccurrenceRole::CallSite
                        && site.target == OccurrenceTarget::Resolved { symbol: helper.id }
                })
                .collect();
            assert_eq!(calls.len(), 1);
            let call = calls[0];
            assert_eq!(call.source.generation(), receipt.generation);
            assert!(
                document
                    .relations
                    .iter()
                    .any(|edge| edge.predicate == RelationPredicate::Calls
                        && edge.subject == RelationEndpoint::Occurrence(call.id)
                        && edge.object == RelationEndpoint::Entity(helper.id))
            );
            let call_source = restored
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![call.source.clone()],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .unwrap();
            assert_eq!(call_source.data.chunks[0].bytes, b"helper(local)");
            let variables: Vec<_> = document
                .entities
                .iter()
                .filter(|entity| {
                    entity.language == "matlab"
                        && matches!(entity.canonical_name.as_str(), "value" | "local" | "result")
                })
                .collect();
            assert_eq!(variables.len(), 3);
            let ids: BTreeSet<_> = variables.iter().map(|entity| entity.id).collect();
            if let Some(previous) = &initial_ids {
                assert_eq!(&ids, previous);
            } else {
                initial_ids = Some(ids);
            }
            let mut reads = 0;
            let mut writes = 0;
            for variable in variables {
                let located = restored
                    .code_locate(
                        receipt.generation,
                        variable.canonical_name.clone(),
                        LocateMode::Exact,
                        10,
                        0,
                        &deadline(),
                    )
                    .unwrap();
                assert!(
                    located
                        .data
                        .hits
                        .iter()
                        .any(|hit| hit.symbol == Some(variable.id))
                );
                for site in document.occurrences.iter().filter(|site| {
                    site.target
                        == OccurrenceTarget::Resolved {
                            symbol: variable.id,
                        }
                }) {
                    if site.role == OccurrenceRole::Reference {
                        reads += 1;
                        assert!(
                            document
                                .relations
                                .iter()
                                .any(|relation| relation.predicate == RelationPredicate::RefersTo
                                    && relation.subject == RelationEndpoint::Occurrence(site.id)
                                    && relation.object == RelationEndpoint::Entity(variable.id))
                        );
                    }
                    writes += usize::from(site.role == OccurrenceRole::Write);
                    assert_eq!(site.source.generation(), receipt.generation);
                    let span = site.source.span();
                    let written = expected
                        .get(
                            usize::try_from(span.start_byte()).unwrap()
                                ..usize::try_from(span.end_byte()).unwrap(),
                        )
                        .unwrap();
                    assert_eq!(written, variable.canonical_name);
                    let read = restored
                        .source_read_with_options_and_budget(
                            receipt.generation,
                            vec![site.source.clone()],
                            SourceReadOptions::new()
                                .with_context_lines_before(0)
                                .with_context_lines_after(0),
                            FirstSliceBudget::default(),
                            &deadline(),
                        )
                        .unwrap();
                    assert_eq!(read.data.chunks[0].bytes, written.as_bytes());
                }
            }
            assert_eq!((reads, writes), (3, 2));
        }
    }

    #[test]
    fn shared_m_suffix_preserves_objc_and_matlab_native_symbols() {
        let fixture = TempDir::new().expect("fixture root exists");
        let objc = "@interface Meter\n- (int)read:(int)value;\n@end\n";
        let matlab = "function result = measure(value)\nresult = value;\nend\n";
        write_language_fixture(fixture.path(), &[("meter.m", objc), ("measure.m", matlab)]);
        let mut service = FirstSliceService::new(2).expect("service initializes");
        let receipt = service
            .index_repository(fixture.path(), &deadline())
            .expect("shared-suffix sources publish");
        let generation = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("generation remains retained");
        for (path, content, language, reason) in [
            ("meter.m", objc, "objective-c", None),
            ("measure.m", matlab, "matlab", None),
        ] {
            let file = generation
                .document()
                .files
                .iter()
                .find(|file| file.path == path)
                .expect("source is retained");
            assert_eq!(file.language, language);
            let coverage = service
                .source_file_coverage_until(receipt.generation, file.id, &deadline())
                .expect("source coverage resolves");
            assert_eq!(coverage.reason, reason);
            let reference = file.evidence.source.clone().expect("source is bound");
            assert_eq!(reference.generation(), receipt.generation);
            let read = service
                .source_read(receipt.generation, vec![reference], &deadline())
                .expect("exact source reads");
            assert_eq!(read.data.chunks[0].bytes, content.as_bytes());
        }
        let located = service
            .code_locate(
                receipt.generation,
                "read:".to_owned(),
                LocateMode::Exact,
                10,
                0,
                &deadline(),
            )
            .expect("Objective-C selector locates");
        assert!(located.data.hits.iter().any(|hit| {
            hit.identifier == "read:"
                && hit.path == "meter.m"
                && hit.language == "objective-c"
                && hit.symbol.is_some()
        }));
        let located = service
            .code_locate(
                receipt.generation,
                "measure".to_owned(),
                LocateMode::Exact,
                10,
                0,
                &deadline(),
            )
            .expect("MATLAB function locates");
        assert!(
            located
                .data
                .hits
                .iter()
                .any(|hit| hit.identifier == "measure"
                    && hit.path == "measure.m"
                    && hit.language == "matlab"
                    && hit.symbol.is_some())
        );
        let repeated = service
            .index_repository(fixture.path(), &deadline())
            .expect("mixed-language no-op succeeds");
        assert_eq!(repeated, receipt);
    }

    #[test]
    fn ambiguous_m_script_tracks_unanimous_sibling_language_changes() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("runtime paths resolve");
        paths.prepare_owner().expect("runtime owner prepares");
        let fixture = TempDir::new().expect("fixture root exists");
        let script = "addpath(genpath(pwd));\n";
        write_language_fixture(
            fixture.path(),
            &[
                ("src/lib.rs", "pub fn companion() {}\n"),
                ("startup.m", script),
                (
                    "measure.m",
                    "function result = measure(value)\nresult = value;\nend\n",
                ),
                (
                    "estimate.m",
                    "function result = estimate(value)\nresult = value;\nend\n",
                ),
            ],
        );
        let mut service = FirstSliceService::new_durable(4, paths.state_dir(), &deadline())
            .expect("durable service initializes");
        let initial = service
            .index_repository(fixture.path(), &deadline())
            .expect("MATLAB source publishes");
        let initial_document = service
            .loaded_generation_snapshot(initial.generation)
            .expect("generation remains retained");
        let startup = initial_document
            .document()
            .files
            .iter()
            .find(|file| file.path == "startup.m")
            .expect("script is retained");
        assert_eq!(startup.language, "matlab");
        let reference = startup.evidence.source.clone().expect("source is bound");
        assert_eq!(reference.generation(), initial.generation);
        assert_eq!(
            service
                .source_read(initial.generation, vec![reference], &deadline())
                .expect("script source reads")
                .data
                .chunks[0]
                .bytes,
            script.as_bytes()
        );

        fs::write(
            fixture.path().join("estimate.m"),
            "@interface Estimate\n@end\n",
        )
        .expect("one peer changes language");
        let mixed = service
            .index_repository(fixture.path(), &deadline())
            .expect("mixed-language source publishes");
        assert_ne!(mixed.generation, initial.generation);
        let mixed_document = service
            .loaded_generation_snapshot(mixed.generation)
            .expect("mixed generation remains retained");
        let startup = mixed_document
            .document()
            .files
            .iter()
            .find(|file| file.path == "startup.m")
            .expect("script is retained");
        assert_eq!(startup.language, "objective-c");
        let evidence = service
            .incremental_evidence(mixed.generation)
            .expect("incremental evidence exists");
        assert_eq!(evidence.parsed_files(), 2);
        assert_eq!(evidence.reused_parser_artifacts(), 2);
        assert_eq!(
            service
                .index_repository(fixture.path(), &deadline())
                .expect("mixed-language no-op succeeds"),
            mixed
        );
        drop(service);
        let mut restored = FirstSliceService::new_durable(4, paths.state_dir(), &deadline())
            .expect("durable service restores");
        let restored_script = restored
            .loaded_generation_snapshot(mixed.generation)
            .expect("mixed generation restores");
        assert_eq!(
            restored_script
                .document()
                .files
                .iter()
                .find(|file| file.path == "startup.m")
                .expect("script restores")
                .language,
            "objective-c"
        );
        assert_eq!(
            restored
                .index_repository(fixture.path(), &deadline())
                .expect("restored no-op succeeds"),
            mixed
        );
    }

