    #[test]
    fn bounded_project_syntax_accepts_an_exact_unified_definition_site() {
        let repository = derive_repository(b"unified-declaration-repository").id();
        let generation = GenerationId::from_bytes([71; 20]);
        let file = FileId::from_bytes([72; 20]);
        let symbol = SymbolId::from_bytes([73; 20]);
        let provenance = FactId::from_bytes([74; 20]);
        let entity = |evidence_start: u64, evidence_end: u64, symbol| EntityRecord {
            id: symbol,
            repository,
            generation,
            kind: EntityKind::Function,
            language: "javascript".to_owned(),
            tier: AnalysisTier::TierB,
            canonical_name: "App".to_owned(),
            display_name: "App".to_owned(),
            qualified_name: "App".to_owned(),
            container: Some(ContainerRef::Repository(repository)),
            visibility: EntityVisibility::Unknown,
            flags: Vec::new(),
            provenance,
            evidence: FactEvidence {
                source: Some(SourceRef::new(
                    repository,
                    generation,
                    SourceSpan::new(file, evidence_start, evidence_end)
                        .expect("fixture declaration span is valid"),
                    content_hash(b"function App() {}"),
                    None,
                )),
                derivation: Vec::new(),
            },
        };
        let mut structural = NormalizedIrDocument::empty(repository, generation);
        structural.entities.push(entity(100, 120, symbol));
        let mut project = NormalizedIrDocument::empty(repository, generation);
        project.entities.push(entity(10, 30, symbol));

        assert_eq!(
            missing_structural_declaration_count(&[structural.clone()], &project, true)
                .expect("different declaration representative compares"),
            1
        );

        let definition_source = SourceRef::new(
            repository,
            generation,
            SourceSpan::new(file, 109, 112).expect("fixture definition span is valid"),
            content_hash(b"function App() {}"),
            None,
        );
        project.occurrences.push(OccurrenceRecord {
            id: FactId::from_bytes([75; 20]),
            repository,
            generation,
            file,
            source: definition_source.clone(),
            role: OccurrenceRole::Definition,
            enclosing: None,
            target: OccurrenceTarget::Resolved { symbol },
            syntactic_text_hash: content_hash(b"App"),
            syntax_kind: "identifier.definition".to_owned(),
            provenance,
            confidence: rootlight_ir::Confidence::new(1000).expect("fixture confidence is valid"),
            evidence: FactEvidence {
                source: Some(definition_source),
                derivation: Vec::new(),
            },
        });
        assert_eq!(
            missing_structural_declaration_count(&[structural.clone()], &project, true)
                .expect("unified definition comparison succeeds"),
            0
        );

        let candidate_symbol = SymbolId::from_bytes([76; 20]);
        project.entities.push(entity(10, 30, candidate_symbol));
        project.occurrences[0].target = OccurrenceTarget::Candidates {
            symbols: vec![symbol, candidate_symbol],
            total_count: 2,
            completeness: CoverageStatus::Complete,
        };
        assert_eq!(
            missing_structural_declaration_count(&[structural.clone()], &project, true)
                .expect("uniform complete candidates compare"),
            0
        );

        project.entities[1].kind = EntityKind::Method;
        assert_eq!(
            missing_structural_declaration_count(&[structural.clone()], &project, true)
                .expect("mixed candidate identities compare"),
            1
        );
        project.entities[1].kind = EntityKind::Function;
        project.occurrences[0].target = OccurrenceTarget::Candidates {
            symbols: vec![symbol, candidate_symbol],
            total_count: 2,
            completeness: CoverageStatus::Bounded,
        };
        assert_eq!(
            missing_structural_declaration_count(&[structural.clone()], &project, true)
                .expect("bounded candidates compare"),
            1
        );
        project.entities.pop();
        project.occurrences[0].target = OccurrenceTarget::Resolved { symbol };

        project.occurrences[0].source = SourceRef::new(
            repository,
            generation,
            SourceSpan::new(file, 121, 124).expect("fixture outside span is valid"),
            content_hash(b"function App() {}"),
            None,
        );
        project.occurrences[0].evidence.source = Some(project.occurrences[0].source.clone());
        assert_eq!(
            missing_structural_declaration_count(&[structural.clone()], &project, true)
                .expect("outside definition comparison succeeds"),
            1
        );

        project.occurrences[0].source = SourceRef::new(
            repository,
            generation,
            SourceSpan::new(file, 109, 112).expect("fixture definition span is valid"),
            content_hash(b"function App() {}"),
            None,
        );
        project.occurrences[0].evidence.source = Some(project.occurrences[0].source.clone());
        project.occurrences[0].target = OccurrenceTarget::Resolved {
            symbol: SymbolId::from_bytes([76; 20]),
        };
        assert_eq!(
            missing_structural_declaration_count(&[structural], &project, true)
                .expect("unresolved declaration identity compares"),
            1
        );
    }

    #[test]
    fn bounded_project_syntax_publishes_when_no_declarations_are_lost() {
        let fixture = TempDir::new().expect("fixture root exists");
        write_language_fixture(
            fixture.path(),
            &[("src/value.py", "print('bounded project syntax')\n")],
        );
        let calls = Arc::new(AtomicUsize::new(0));
        let analyzer = Arc::new(SuccessfulProjectAnalyzer {
            identity: content_hash(b"bounded-syntax-project-adapter"),
            calls: Arc::clone(&calls),
            partitioned: false,
            syntax_facts_bounded: true,
        });
        let mut service =
            FirstSliceService::new_with_storage(2, MAX_RETAINED_SOURCE_BYTES, None, Some(analyzer))
                .expect("service initializes with a project adapter");

        let structural = service
            .index_repository_with_mode(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &deadline(),
            )
            .expect("original structural evidence publishes before bounded refinement");
        let unsupported = |document: &NormalizedIrDocument| {
            let mut gaps: Vec<_> = document
                .skipped_regions
                .iter()
                .filter(|gap| gap.reason == SkippedRegionReason::UnsupportedConstruct)
                .map(|gap| (gap.domain, gap.detail.clone(), gap.source.span()))
                .collect();
            gaps.sort();
            gaps
        };
        let expected_unsupported = {
            let baseline = service
                .loaded_generation_snapshot(structural.generation)
                .expect("structural baseline remains retained");
            let file = &baseline.document().files[0];
            let span = SourceSpan::new(file.id, 0, 32).expect("original source span is exact");
            let expected: Vec<_> = [
                IrFactDomain::Entities,
                IrFactDomain::Occurrences,
                IrFactDomain::Relations,
            ]
            .into_iter()
            .map(|domain| {
                (
                    domain,
                    "python-module-read-proof-is-lexical-only-values-calls-and-dynamic-namespace-semantics-unqualified".to_owned(),
                    span,
                )
            })
            .collect();
            assert_eq!(unsupported(baseline.document()), expected);
            assert!(baseline.document().skipped_regions.iter().all(|gap| {
                gap.source.content_hash() == content_hash(b"print('bounded project syntax')\n")
                    && gap.source.generation() == structural.generation
            }));
            expected
        };

        let receipt = service
            .index_repository_with_mode(fixture.path(), FirstSliceIndexMode::Deep, &deadline())
            .expect("bounded project output publishes when it preserves declarations");
        let status = service
            .repository_status(receipt.repository, Some(receipt.generation))
            .expect("bounded project status resolves");
        let bounded_snapshot = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("bounded project generation remains retained");
        assert!(
            bounded_snapshot
                .document()
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == PROJECT_SYNTAX_FACT_LIMIT_DIAGNOSTIC)
        );
        let gaps = service
            .coverage_gaps_until(receipt.repository, receipt.generation, &deadline())
            .expect("bounded project gaps resolve");
        assert!(gaps.iter().any(|gap| {
            gap.reason == FirstSliceCoverageGapReason::Truncated
                && gap.language.as_deref() == Some("python")
                && gap.files == 1
        }));
        assert!(gaps.iter().any(|gap| {
            gap.reason == FirstSliceCoverageGapReason::Unsupported
                && gap.language.as_deref() == Some("python")
                && gap.files == 1
        }));
        // Project records replace entity/relation metadata; refinement keeps
        // the structural occurrence limitation at its original source span.
        let expected_deep_unsupported: Vec<_> = expected_unsupported
            .into_iter()
            .filter(|(domain, _, _)| *domain == IrFactDomain::Occurrences)
            .collect();
        assert_eq!(
            unsupported(bounded_snapshot.document()),
            expected_deep_unsupported
        );
        assert!(
            bounded_snapshot
                .document()
                .skipped_regions
                .iter()
                .all(|gap| {
                    gap.source.content_hash() == content_hash(b"print('bounded project syntax')\n")
                        && gap.source.generation() == receipt.generation
                })
        );

        assert_eq!(calls.load(Ordering::Relaxed), 1);
        assert!(status.coverage.iter().any(|coverage| {
            coverage.language == "python"
                && coverage.tier == "tier_b"
                && coverage.status == "bounded"
        }));
        assert!(
            receipt
                .diagnostics
                .iter()
                .all(|diagnostic| { diagnostic.code != "project-adapter-capacity-fallback" })
        );
    }

    #[test]
    fn bounded_project_refinement_preserves_structural_call_evidence() {
        let fixture = TempDir::new().expect("fixture root exists");
        write_language_fixture(
            fixture.path(),
            &[("src/value.py", "print('bounded project syntax')\n")],
        );
        let calls = Arc::new(AtomicUsize::new(0));
        let analyzer = Arc::new(SuccessfulProjectAnalyzer {
            identity: content_hash(b"bounded-call-project-adapter"),
            calls: Arc::clone(&calls),
            partitioned: false,
            syntax_facts_bounded: true,
        });
        let mut service =
            FirstSliceService::new_with_storage(2, MAX_RETAINED_SOURCE_BYTES, None, Some(analyzer))
                .expect("service initializes with a project adapter");
        let structural = service
            .index_repository_with_mode(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &deadline(),
            )
            .expect("structural indexing succeeds");
        let structural_calls = service
            .loaded_generation_snapshot(structural.generation)
            .expect("structural snapshot is retained")
            .document()
            .occurrences
            .iter()
            .filter(|occurrence| occurrence.role == OccurrenceRole::CallSite)
            .map(|occurrence| occurrence.source.span())
            .collect::<Vec<_>>();
        assert!(
            !structural_calls.is_empty(),
            "structural call evidence exists before refinement"
        );
        let refined = service
            .index_repository_with_mode(fixture.path(), FirstSliceIndexMode::Deep, &deadline())
            .expect("bounded project refinement publishes");
        assert_eq!(calls.load(Ordering::Relaxed), 1);
        let snapshot = service
            .loaded_generation_snapshot(refined.generation)
            .expect("refined snapshot is retained");
        assert!(
            snapshot
                .document()
                .diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == PROJECT_SYNTAX_FACT_LIMIT_DIAGNOSTIC })
        );
        assert!(
            refined
                .diagnostics
                .iter()
                .all(|diagnostic| { !diagnostic.code.ends_with("-fallback") }),
            "retaining structural evidence must not discard the accepted project result"
        );
        for span in structural_calls {
            assert!(
                snapshot.document().occurrences.iter().any(|occurrence| {
                    occurrence.role == OccurrenceRole::CallSite
                        && occurrence.source.span() == span
                        && occurrence.source.generation() == refined.generation
                }),
                "bounded semantic refinement must not erase existing call evidence"
            );
        }
    }

