    #[test]
    fn structural_refinement_keeps_project_calls_and_unknown_targets() {
        let (structural, metadata) = structural_refinement_fixture(
            "rs",
            "fn leaf() {}\nfn entry() { leaf(); unknown(); }\nfn second() { leaf(); }\n",
        );
        let mut project = structural.clone();
        let mut preferred = structural
            .occurrences
            .iter()
            .find(|record| {
                record.role == OccurrenceRole::CallSite
                    && matches!(record.target, OccurrenceTarget::Resolved { .. })
            })
            .expect("fixture includes a resolved call")
            .clone();
        let previous = preferred.id;
        preferred.confidence =
            rootlight_ir::Confidence::new(1000).expect("project confidence is valid");
        preferred.source = SourceRef::new(
            preferred.repository,
            preferred.generation,
            preferred.source.span(),
            preferred.source.content_hash(),
            Some(rootlight_ir::LineRange::new(1, 3).expect("presentation hint is valid")),
        );
        preferred.id = rootlight_ir::derive_occurrence_record_id(&preferred)
            .expect("project occurrence identity derives");
        let omitted = structural
            .occurrences
            .iter()
            .filter(|record| record.role == OccurrenceRole::CallSite && record.id != previous)
            .map(|record| record.id)
            .collect::<BTreeSet<_>>();
        assert!(!omitted.is_empty(), "fixture also includes an unknown call");
        project
            .occurrences
            .retain(|record| !omitted.contains(&record.id) && record.id != previous);
        project.occurrences.push(preferred.clone());
        project.relations.retain(|relation| [relation.subject, relation.object].iter()
            .all(|endpoint| !matches!(endpoint, RelationEndpoint::Occurrence(id) if omitted.contains(id))));
        for relation in &mut project.relations {
            for endpoint in [&mut relation.subject, &mut relation.object] {
                if *endpoint == RelationEndpoint::Occurrence(previous) {
                    *endpoint = RelationEndpoint::Occurrence(preferred.id);
                }
            }
            for reference in &mut relation.evidence.derivation {
                if *reference == FactRef::Fact(previous) {
                    *reference = FactRef::Fact(preferred.id);
                }
            }
            relation.id =
                derive_relation_record_id(relation).expect("project edge identity derives");
        }
        let refined = refinement::retain_structural_occurrences(
            project,
            std::slice::from_ref(&structural),
            &IrLimits::default(),
            &deadline(),
        )
        .expect("missing calls are supplemented");
        assert_eq!(
            refined
                .occurrences
                .iter()
                .filter(|record| record.role == preferred.role
                    && record.source.span() == preferred.source.span())
                .count(),
            1
        );
        assert!(refined.occurrences.contains(&preferred));
        for occurrence in structural
            .occurrences
            .iter()
            .filter(|record| omitted.contains(&record.id))
        {
            assert!(refined.occurrences.contains(occurrence));
            if matches!(occurrence.target, OccurrenceTarget::Unresolved { .. }) {
                assert!(
                    !refined
                        .relations
                        .iter()
                        .any(|relation| relation.predicate == RelationPredicate::Calls
                            && relation.subject == RelationEndpoint::Occurrence(occurrence.id))
                );
            } else {
                let edges = structural
                    .relations
                    .iter()
                    .filter(|relation| {
                        relation.predicate == RelationPredicate::Calls
                            && relation.subject == RelationEndpoint::Occurrence(occurrence.id)
                    })
                    .collect::<Vec<_>>();
                assert!(
                    !edges.is_empty(),
                    "omitted resolved call has structural edges"
                );
                assert!(
                    edges
                        .into_iter()
                        .all(|edge| refined.relations.contains(edge))
                );
            }
        }
        assert!(
            refined
                .occurrences
                .iter()
                .any(|record| omitted.contains(&record.id)
                    && matches!(record.target, OccurrenceTarget::Unresolved { .. }))
        );
        assert!(
            refined
                .occurrences
                .iter()
                .any(|record| omitted.contains(&record.id)
                    && matches!(record.target, OccurrenceTarget::Resolved { .. }))
        );
        assert_eq!(
            refinement::retain_structural_occurrences(
                refined.clone(),
                std::slice::from_ref(&structural),
                &IrLimits::default(),
                &deadline()
            )
            .expect("repeated refinement succeeds"),
            refined
        );
        let cancellation = deadline();
        IdentityVerifiedGeneration::verify(
            metadata,
            refined,
            &IrLimits::default(),
            &ExtensionSupport::default(),
            &GenerationContext::new(&cancellation, GenerationBudget::default()),
        )
        .expect("preferred project and retained structural identities verify together");
    }

    #[test]
    fn structural_refinement_rejects_missing_evidence_limits_and_cancellation() {
        let (mut structural, _) = structural_refinement_fixture("py", "print('probe')\n");
        let project = file_only_refinement_project(&structural);
        let mut limits = IrLimits::default();
        limits.max_occurrences = 0;
        assert!(matches!(
            refinement::retain_structural_occurrences(
                project.clone(),
                std::slice::from_ref(&structural),
                &limits,
                &deadline()
            ),
            Err(FirstSliceError::ResourceLimit {
                resource: FirstSliceResource::Occurrences,
                ..
            })
        ));
        let cancellation = Cancellation::new();
        cancellation.cancel(CancellationReason::ClientRequest);
        assert!(matches!(
            refinement::retain_structural_occurrences(
                project.clone(),
                std::slice::from_ref(&structural),
                &IrLimits::default(),
                &cancellation
            ),
            Err(FirstSliceError::Cancelled(_))
        ));
        let occurrence = structural
            .occurrences
            .iter_mut()
            .find(|record| record.role == OccurrenceRole::CallSite)
            .expect("fixture includes a call");
        occurrence
            .evidence
            .derivation
            .push(FactRef::Fact(FactId::from_bytes([37; 20])));
        assert_eq!(
            refinement::retain_structural_occurrences(
                project,
                &[structural],
                &IrLimits::default(),
                &deadline()
            ),
            Err(FirstSliceError::Identity)
        );
    }

    #[test]
    fn unsafe_bounded_semantic_output_stops_before_durable_persistence() {
        let temporary = durable_test_tempdir();
        let paths = RuntimePaths::new(
            temporary.path().join("state"),
            temporary.path().join("runtime"),
        )
        .expect("runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let repository_root = temporary.path().join("repository");
        fs::create_dir(&repository_root).expect("repository root creates");
        fs::write(
            repository_root.join("value.py"),
            "def structural_survivor():\n    return 1\n",
        )
        .expect("bounded semantic fixture writes");
        let calls = Arc::new(AtomicUsize::new(0));
        let analyzer: Arc<dyn FirstSliceProjectAnalyzer> = Arc::new(CapacityProjectAnalyzer {
            identity: content_hash(b"unsafe-bounded-project-adapter"),
            calls: Arc::clone(&calls),
        });
        let cancellation = deadline();
        let mut service = FirstSliceService::new_durable_with_project_analyzer(
            3,
            paths.state_dir(),
            analyzer,
            &cancellation,
        )
        .expect("durable project service initializes");
        limit_service_ir_entities(&mut service, 2);
        let structural = service
            .index_repository_with_mode(
                &repository_root,
                FirstSliceIndexMode::Structural,
                &cancellation,
            )
            .expect("structural generation publishes");
        let before = service
            .support_inventory_snapshot()
            .expect("pre-refinement storage inventory verifies");
        let mut progress = Vec::new();

        let error = match service.prepare_semantic_refinement_with_progress(
            &repository_root,
            structural.generation,
            &cancellation,
            |observed| progress.push(observed),
        ) {
            Ok(_) => panic!("unsafe bounded output cannot refine the structural generation"),
            Err(error) => error,
        };
        let after = service
            .support_inventory_snapshot()
            .expect("post-refinement storage inventory verifies");

        assert!(matches!(
            error,
            FirstSliceError::ResourceLimit {
                resource: FirstSliceResource::Entities,
                observed: 3,
                limit: 2,
            }
        ));
        assert_eq!(calls.load(Ordering::Relaxed), 1);
        assert!(progress.iter().all(|observed| observed.stage
            != FirstSliceIndexStage::Persistence
            && observed.written_bytes == 0));
        assert_eq!(after.generations, before.generations);
        assert_eq!(after.total_storage_bytes, before.total_storage_bytes);
        assert_eq!(after.unreclaimed_temporary_bytes, 0);
        assert_eq!(
            service.active_generation_for(structural.repository),
            Some(structural.generation)
        );
    }

    #[test]
    fn deep_project_path_forwards_only_reliable_generated_origin_headers() {
        let fixture = TempDir::new().expect("fixture root exists");
        write_language_fixture(
            fixture.path(),
            &[
                ("src/generator.rs", "pub fn generate() {}\n"),
                (
                    "src/mapped.generated.rs",
                    "// Code generated by fixture-gen. DO NOT EDIT.\n// source: src/generator.rs\npub fn mapped() {}\n",
                ),
                (
                    "src/missing-source.generated.rs",
                    "// Code generated by fixture-gen. DO NOT EDIT.\npub fn missing_source() {}\n",
                ),
                (
                    "src/traversal.generated.rs",
                    "// Code generated by fixture-gen. DO NOT EDIT.\n// source: ../generator.rs\npub fn traversal() {}\n",
                ),
                (
                    "src/duplicate.generated.rs",
                    "// Code generated by fixture-gen. DO NOT EDIT.\n// source: src/generator.rs\n// source: src/generator.rs\npub fn duplicate() {}\n",
                ),
                (
                    "src/unknown.generated.rs",
                    "// Code generated by fixture-gen. DO NOT EDIT.\n// source: src/not-indexed.rs\npub fn unknown() {}\n",
                ),
            ],
        );
        let observations = Arc::new(Mutex::new(Vec::new()));
        let analyzer = Arc::new(CapturingProjectAnalyzer {
            identity: content_hash(b"generated-origin-capture"),
            observations: Arc::clone(&observations),
            manifests: Arc::new(Mutex::new(Vec::new())),
        });
        let mut service =
            FirstSliceService::new_with_storage(2, MAX_RETAINED_SOURCE_BYTES, None, Some(analyzer))
                .expect("service initializes with a project adapter");

        service
            .index_repository_with_mode(fixture.path(), FirstSliceIndexMode::Deep, &deadline())
            .expect("structural fallback remains publishable");

        let observed = observations.lock().expect("capture mutex is not poisoned");
        let mapped = observed
            .iter()
            .find(|input| input.path == "src/mapped.generated.rs")
            .expect("mapped generated input is captured");
        assert!(mapped.generated);
        assert_eq!(mapped.origins.len(), 1);
        assert_eq!(mapped.origins[0].origin_path, "src/generator.rs");
        assert_eq!(mapped.origins[0].transformation, "fixture-gen");
        assert_eq!(mapped.origins[0].generator_digest, None);
        assert_eq!(mapped.origins[0].generated.start_byte(), 0);
        assert_eq!(
            mapped.origins[0].generated.end_byte(),
            u64::try_from(
                "// Code generated by fixture-gen. DO NOT EDIT.\n// source: src/generator.rs\npub fn mapped() {}\n"
                    .len()
            )
            .expect("fixture length is representable")
        );
        assert_eq!(mapped.origins[0].origin.start_byte(), 0);
        assert_eq!(
            mapped.origins[0].origin.end_byte(),
            u64::try_from("pub fn generate() {}\n".len()).expect("fixture length is representable")
        );
        assert!(
            observed
                .iter()
                .filter(|input| input.path != "src/mapped.generated.rs")
                .all(|input| input.origins.is_empty())
        );
    }

