    #[test]
    fn shared_classic_routes_preserve_conflicts_and_analyzer_absence() {
        let mut input = ManifestInput {
            file: FileId::from_bytes([3; 20]),
            path: "written.CLS".to_owned(),
            content_hash: content_hash(b""),
            bytes: 0,
            encoding: "utf-8".to_owned(),
            class: InputClass::Source,
            language_signals: vec![rootlight_discovery::LanguageSignal {
                language: "apex".to_owned(),
                evidence: LanguageEvidence::Content,
            }],
            project_language_witnesses: Vec::new(),
            decisive_rule: None,
        };
        assert_eq!(detected_source_language(&input), Some("apex"));
        let service = FirstSliceService::new(2).unwrap();
        assert_eq!(
            source_language_route(&input, &service.analyzers),
            Some("apex")
        );
        let mut absent = service.analyzers;
        absent.remove("apex");
        assert_eq!(source_language_route(&input, &absent), None);
        input
            .language_signals
            .push(rootlight_discovery::LanguageSignal {
                language: "visual-basic-classic".to_owned(),
                evidence: LanguageEvidence::Content,
            });
        assert_eq!(detected_source_language(&input), None);
        assert_eq!(source_language_route(&input, &absent), None);
        for suffix in ["bas", "frm"] {
            input.path = format!("written.{suffix}");
            assert_eq!(
                shared_classic_source_language(&input),
                Some("visual-basic-classic")
            );
        }
        input.path = "written.cls".to_owned();
        input
            .language_signals
            .push(rootlight_discovery::LanguageSignal {
                language: "visual-basic-classic".to_owned(),
                evidence: LanguageEvidence::Configuration,
            });
        assert_eq!(
            source_language_route(&input, &absent),
            Some("visual-basic-classic")
        );
    }

    #[test]
    fn ambiguous_basic_sources_do_not_enter_an_unproven_parser() {
        let fixture = TempDir::new().unwrap();
        write_language_fixture(
            fixture.path(),
            &[
                ("module.bas", "Sub Update()\nEnd Sub\n"),
                ("class.cls", "Public Class Example\nEnd Class\n"),
                (
                    "form.frm",
                    "' Declare PtrSafe Function ReadClock Lib \"clock\" ()\n",
                ),
                (
                    "notes.txt",
                    "Declare PtrSafe Function ReadClock Lib \"clock\" ()\n",
                ),
            ],
        );
        let mut service = FirstSliceService::new(2).unwrap();
        let receipt = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(receipt.indexed_files, 4);
        let status = service.repository_status(receipt.repository, None).unwrap();
        assert_eq!(
            status
                .coverage
                .iter()
                .map(|entry| entry.discovered_files)
                .sum::<u64>(),
            4
        );
        assert!(status.coverage.iter().all(|entry| entry.indexed_files == 0));
        let generation = service
            .loaded_generation_snapshot(receipt.generation)
            .unwrap();
        assert_eq!(generation.document().files.len(), 4);
        assert!(generation.document().entities.is_empty());
        for file in &generation.document().files {
            let coverage = service
                .source_file_coverage_until(receipt.generation, file.id, &deadline())
                .unwrap();
            assert_eq!(coverage.status, CoverageStatus::Unknown);
            assert_eq!(
                coverage.reason,
                Some(FirstSliceSourceCoverageReason::UnsupportedLanguage)
            );
            let reference = file.evidence.source.clone().unwrap();
            assert_eq!(reference.generation(), receipt.generation);
            let read = service
                .source_read(receipt.generation, vec![reference], &deadline())
                .unwrap();
            assert_eq!(
                read.data.chunks[0].bytes,
                fs::read(fixture.path().join(&file.path)).unwrap()
            );
        }
    }

    #[test]
    fn configured_source_languages_reindex_unchanged_sources_after_restart() {
        let fixture = TempDir::new().unwrap();
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let source = "Attribute VB_Name = \"Metrics\"\nFunction Measure() As Long\nMeasure = 1\nEnd Function\n";
        fs::write(fixture.path().join("module.bas"), source).unwrap();
        let mut previous_generation = None;
        for language in ["vba", "unsupported-language", "vba"] {
            let contents = format!(
                "version='1.3'\n[extensions.source-languages]\nversion='1.0'\ncritical=true\n[extensions.source-languages.data.extensions]\nbas='{language}'\n"
            );
            let policy = FirstSliceStoragePolicy::resolve_user_config(Some(&contents), 2).unwrap();
            let expected_hash = policy.config.hash();
            let mut service =
                FirstSliceService::new_durable_with_policy(policy, paths.state_dir(), &deadline())
                    .unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            if let Some(previous) = previous_generation {
                assert_ne!(receipt.generation, previous);
            }
            previous_generation = Some(receipt.generation);
            assert_eq!(
                service
                    .generation_metadata(receipt.generation)
                    .unwrap()
                    .configuration_hash(),
                expected_hash
            );
            let no_op = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(no_op.generation, receipt.generation);
            let status = service.repository_status(receipt.repository, None).unwrap();
            assert_eq!(
                status
                    .coverage
                    .iter()
                    .map(|entry| entry.indexed_files)
                    .sum::<u64>(),
                u64::from(language == "vba")
            );
            let generation = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = generation.document();
            assert_eq!(document.files.len(), 1);
            let source_ref = document.files[0].evidence.source.clone().unwrap();
            assert_eq!(source_ref.generation(), receipt.generation);
            let read = service
                .source_read(receipt.generation, vec![source_ref], &deadline())
                .unwrap();
            assert_eq!(read.data.chunks[0].bytes, source.as_bytes());
            let module = document.entities.iter().find(|entity| {
                entity.kind == EntityKind::Module && entity.canonical_name == "Metrics"
            });
            assert_eq!(module.is_some(), language == "vba");
            let hits = service
                .code_locate(
                    receipt.generation,
                    "Metrics".to_owned(),
                    LocateMode::Exact,
                    10,
                    0,
                    &deadline(),
                )
                .unwrap();
            if let Some(module) = module {
                assert!(
                    hits.data
                        .hits
                        .iter()
                        .any(|hit| hit.symbol == Some(module.id))
                );
            } else {
                assert!(document.entities.is_empty());
                assert!(hits.data.hits.iter().all(|hit| hit.symbol.is_none()));
            }
        }
    }

    #[test]
    fn vba_compilation_constants_do_not_shadow_project_members() {
        let fixture = durable_test_tempdir();
        fs::write(
            fixture.path().join("project.vbp"),
            "Type=OleDll\nName=\"Primary\"\nModule=Client; Client.bas\nModule=Catalog; Catalog.bas\n",
        )
        .unwrap();
        let client = "Attribute VB_Name = \"Client\"\nPrivate Declare PtrSafe Function Clock Lib \"clock\" () As LongPtr\n#Const Catalog = True\nSub Run()\nDim value As Long\nvalue = Catalog.Enabled\nvalue = Catalog.CompilerOnly\nEnd Sub\n";
        fs::write(fixture.path().join("Client.bas"), client).unwrap();
        fs::write(
            fixture.path().join("Catalog.bas"),
            "Attribute VB_Name = \"Catalog\"\nPrivate Declare PtrSafe Function Clock Lib \"clock\" () As LongPtr\n#Const Enabled = True\n#Const CompilerOnly = True\nPublic Const Enabled = 7\n",
        )
        .unwrap();
        let mut service = FirstSliceService::new(2).unwrap();
        let receipt = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        let snapshot = service
            .loaded_generation_snapshot(receipt.generation)
            .unwrap();
        let document = snapshot.document();
        let file = document
            .files
            .iter()
            .find(|file| file.path == "Client.bas")
            .unwrap();
        for (text, resolved) in [("Catalog.Enabled", true), ("Catalog.CompilerOnly", false)] {
            let start = u64::try_from(client.find(text).unwrap()).unwrap();
            let site = document
                .occurrences
                .iter()
                .find(|site| {
                    site.file == file.id
                        && site.syntax_kind == "vba.get_member.reference"
                        && site.source.span().start_byte() == start
                })
                .unwrap();
            assert_eq!(
                matches!(site.target, OccurrenceTarget::Resolved { .. }),
                resolved,
                "{text}"
            );
            if let OccurrenceTarget::Resolved { symbol } = site.target {
                let target = document
                    .entities
                    .iter()
                    .find(|entity| entity.id == symbol)
                    .unwrap();
                assert_eq!(target.canonical_name, "Enabled");
                assert_eq!(target.visibility, rootlight_ir::EntityVisibility::Public);
            }
        }
    }

    #[test]
    fn vba_compilation_constants_follow_rename_and_restart() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let fixture = durable_test_tempdir();
        let mut previous = None;
        for (name, resolved) in [("Enabled", true), ("Other", false), ("Enabled", true)] {
            let source = format!(
                "Attribute VB_Name = \"Options\"\nPrivate Declare PtrSafe Function Clock Lib \"clock\" () As LongPtr\n#Const {name} = True\nSub Run()\n#If ENABLED Then\nDim item As Long\nitem = 1\n#End If\nEnd Sub\n"
            );
            fs::write(fixture.path().join("options.bas"), &source).unwrap();
            let mut service =
                FirstSliceService::new_durable(2, paths.state_dir(), &deadline()).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(
                service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap(),
                receipt
            );
            assert_ne!(previous, Some(receipt.generation));
            previous = Some(receipt.generation);
            drop(service);
            let service =
                FirstSliceService::new_durable(2, paths.state_dir(), &deadline()).unwrap();
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            let reference = document
                .occurrences
                .iter()
                .find(|site| site.syntax_kind == "vba.compilation_identifier.reference")
                .unwrap();
            assert_eq!(
                matches!(reference.target, OccurrenceTarget::Resolved { .. }),
                resolved
            );
            if let OccurrenceTarget::Resolved { symbol } = reference.target {
                let entity = document
                    .entities
                    .iter()
                    .find(|entity| entity.id == symbol)
                    .unwrap();
                assert_eq!(entity.canonical_name, name);
                assert_eq!(entity.visibility, rootlight_ir::EntityVisibility::Private);
                let relationships = service
                    .symbol_relationships(
                        receipt.generation,
                        BTreeSet::from([symbol]),
                        vec![RelationFamily::References],
                        Some(RelationDirection::Inbound),
                        0,
                        10,
                        0,
                        &deadline(),
                    )
                    .unwrap();
                assert!(
                    relationships
                        .data
                        .groups
                        .iter()
                        .flat_map(|group| &group.items)
                        .flat_map(|edge| &edge.source_refs)
                        .any(|source| source == &reference.source)
                );
            }
            assert_eq!(
                document.skipped_regions.iter().any(|gap| {
                    gap.source == reference.source
                        && gap.detail == "vba-compilation-constant-target-unavailable"
                }),
                !resolved
            );
            let inventories: Vec<_> = document
                .extensions
                .iter()
                .filter(|extension| extension.namespace == rootlight_ir::VBA_COMPILATION_NAMESPACE)
                .map(|extension| rootlight_ir::decode_vba_compilation_envelope(extension).unwrap())
                .collect();
            assert_eq!(inventories.len(), 1);
            let inventory = &inventories[0];
            assert!(inventory.complete);
            assert_eq!(inventory.branches.len(), 1);
            let branch = &inventory.branches[0];
            assert_eq!(
                branch.activity,
                if resolved {
                    rootlight_ir::VbaCompilationActivity::Active
                } else {
                    rootlight_ir::VbaCompilationActivity::Unproven
                }
            );
            let evaluation_gaps: Vec<_> = document
                .skipped_regions
                .iter()
                .filter(|gap| gap.detail == "vba-conditional-compilation-evaluation-unavailable")
                .collect();
            assert_eq!(evaluation_gaps.len(), usize::from(!resolved));
            if !resolved {
                assert_eq!(evaluation_gaps[0].source.span(), branch.group);
            }
            assert_eq!(reference.source.generation(), receipt.generation);
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![reference.source.clone()],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .unwrap();
            assert_eq!(read.data.chunks[0].bytes, b"ENABLED");
        }
    }

