    #[test]
    fn vba_statement_named_arguments_follow_parameter_renames_and_restart() {
        for invocation in ["Me.Visit size:=size", "Me.Visit _\r\n size:=size"] {
            vba_named_arguments_follow_parameter_renames_and_restart(invocation);
        }
    }

    fn vba_named_arguments_follow_parameter_renames_and_restart(invocation: &str) {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let fixture = durable_test_tempdir();
        let mut previous_generation = None;
        for (parameter_name, resolved) in [("size", true), ("other", false), ("size", true)] {
            let source = format!(
                "VERSION 1.0 CLASS\nAttribute VB_Name = \"Receiver\"\nPrivate Declare PtrSafe Function ReadClock Lib \"clock\" () As LongPtr\nPublic Sub Visit(ByVal {parameter_name} As Long)\nEnd Sub\nPublic Sub Run(ByVal size As Long, ByVal Visit As Object)\n{invocation}\nEnd Sub\n"
            );
            fs::write(fixture.path().join("receiver.bas"), &source).unwrap();
            let mut service =
                FirstSliceService::new_durable(2, paths.state_dir(), &deadline()).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(receipt.indexed_files, 1);
            assert_eq!(
                service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap(),
                receipt
            );
            if let Some(previous) = previous_generation {
                assert_ne!(receipt.generation, previous);
            }
            previous_generation = Some(receipt.generation);
            drop(service);
            let service =
                FirstSliceService::new_durable(2, paths.state_dir(), &deadline()).unwrap();
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            let method = document
                .entities
                .iter()
                .find(|entity| {
                    entity.kind == EntityKind::Method && entity.canonical_name == "Visit"
                })
                .unwrap();
            let parameter = document
                .entities
                .iter()
                .find(|entity| {
                    entity.kind == EntityKind::Parameter
                        && entity.canonical_name == parameter_name
                        && entity.container == Some(rootlight_ir::ContainerRef::Entity(method.id))
                })
                .unwrap();
            let start = u64::try_from(source.find("size:=size").unwrap()).unwrap();
            let label = document
                .occurrences
                .iter()
                .find(|site| {
                    site.syntax_kind == "vba.nonvalue_identifier.reference"
                        && site.source.span().start_byte() == start
                })
                .unwrap();
            if resolved {
                assert_eq!(
                    label.target,
                    OccurrenceTarget::Resolved {
                        symbol: parameter.id
                    }
                );
            } else {
                assert!(matches!(label.target, OccurrenceTarget::Unresolved { .. }));
            }
            assert_eq!(
                document
                    .skipped_regions
                    .iter()
                    .any(|gap| gap.source == label.source
                        && gap.detail == "vba-nonvalue-target-unavailable"),
                !resolved
            );
            let relationships = service
                .symbol_relationships(
                    receipt.generation,
                    BTreeSet::from([parameter.id]),
                    vec![RelationFamily::References],
                    Some(RelationDirection::Inbound),
                    0,
                    10,
                    0,
                    &deadline(),
                )
                .unwrap();
            assert_eq!(
                relationships
                    .data
                    .groups
                    .iter()
                    .flat_map(|group| &group.items)
                    .flat_map(|edge| &edge.source_refs)
                    .any(|reference| reference == &label.source),
                resolved
            );
            assert_eq!(label.source.generation(), receipt.generation);
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![label.source.clone()],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .unwrap();
            assert_eq!(read.data.chunks[0].bytes, b"size");
        }
    }

