    fn assert_vba_array_references_follow_mutation_and_restart(
        separator: &str,
        declaration_separator: &str,
    ) {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let fixture = durable_test_tempdir();
        let mut previous_generation = None;
        for (declaration, resolved, self_field, write_prefix) in [
            ("ByRef items() As Long", true, false, None),
            ("ByRef items As Variant", false, false, None),
            ("ParamArray items() As Variant", true, false, None),
            ("Private items(1) As Long", true, true, None),
            ("Private items As Variant", false, true, None),
            ("Private items() As Long", true, true, None),
            ("ByRef items() As Variant", true, false, Some("Let ")),
            ("ByRef items As Variant", false, false, Some("Let ")),
            ("ParamArray items() As Variant", true, false, Some("Set ")),
            ("Private items(1) As Variant", true, true, Some("Let ")),
            ("Private items As Variant", false, true, Some("Let ")),
            ("Private items() As Variant", true, true, Some("")),
        ] {
            let declaration = declaration
                .replace("items(", &format!("items{declaration_separator}("))
                .replace("()", &format!("({declaration_separator})"));
            let header = if self_field {
                format!("VERSION 1.0 CLASS\nAttribute VB_Name = \"Counter\"\n{declaration}\n")
            } else {
                String::new()
            };
            let parameter = if self_field {
                "ByVal items As Object"
            } else {
                &declaration
            };
            let callee = format!("items{separator}(0)");
            let expression = if self_field {
                format!("Me.{callee}")
            } else {
                callee.clone()
            };
            let statement = match write_prefix {
                Some(prefix) => format!("{prefix}{expression} = first"),
                None => format!("first = {expression}"),
            };
            let source = format!(
                "{header}Private Declare PtrSafe Function ReadClock Lib \"clock\" () As LongPtr\nSub Run({parameter})\nDim first As Variant\n{statement}\nEnd Sub\n"
            );
            fs::write(fixture.path().join("module.bas"), &source).unwrap();
            let mut service =
                FirstSliceService::new_durable(2, paths.state_dir(), &deadline()).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(receipt.indexed_files, 1);
            assert_eq!(
                service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap(),
                receipt
            );
            if let Some(previous) = previous_generation {
                assert_ne!(receipt.generation, previous);
            }
            previous_generation = Some(receipt.generation);
            drop(service);
            let service =
                FirstSliceService::new_durable(2, paths.state_dir(), &deadline()).unwrap();
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            let target = document
                .entities
                .iter()
                .find(|entity| {
                    entity.kind
                        == if self_field {
                            EntityKind::Field
                        } else {
                            EntityKind::Parameter
                        }
                        && entity.canonical_name == "items"
                })
                .unwrap();
            let start = u64::try_from(source.find(&expression).unwrap()).unwrap();
            let callee_start = u64::try_from(source.find(&callee).unwrap()).unwrap();
            let expression_end = start + u64::try_from(expression.len()).unwrap();
            let statement_end = expression_end
                + if write_prefix.is_some() {
                    u64::try_from(" = first".len()).unwrap()
                } else {
                    0
                };
            let application = document
                .occurrences
                .iter()
                .find(|site| {
                    site.syntax_kind == "vba.application.reference"
                        && site.source.span().start_byte() == start
                        && matches!(site.source.span().end_byte(), at if at == expression_end || at == statement_end)
                })
                .unwrap();
            let end = application.source.span().end_byte();
            if resolved {
                assert_eq!(
                    application.target,
                    OccurrenceTarget::Resolved { symbol: target.id }
                );
            } else {
                assert!(matches!(
                    application.target,
                    OccurrenceTarget::Unresolved { .. }
                ));
            }
            assert_eq!(
                document.skipped_regions.iter().any(|gap| {
                    ((gap.source.span().start_byte() == start
                        && gap.source.span().end_byte() == end)
                        || (gap.source.span().start_byte() == callee_start
                            && gap.source.span().end_byte() == callee_start + 5))
                        && gap.detail == "vba-call-or-index-target-unavailable"
                }),
                !resolved
            );
            let relationships = service
                .symbol_relationships(
                    receipt.generation,
                    BTreeSet::from([target.id]),
                    vec![RelationFamily::References],
                    Some(RelationDirection::Inbound),
                    0,
                    10,
                    0,
                    &deadline(),
                )
                .unwrap();
            assert_eq!(
                relationships
                    .data
                    .groups
                    .iter()
                    .flat_map(|group| &group.items)
                    .flat_map(|edge| &edge.source_refs)
                    .any(|reference| reference == &application.source),
                resolved
            );
            assert_eq!(application.source.generation(), receipt.generation);
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![application.source.clone()],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .unwrap();
            assert_eq!(
                read.data.chunks[0].bytes,
                &source.as_bytes()[usize::try_from(start).unwrap()..usize::try_from(end).unwrap()]
            );
        }
    }

    #[test]
    fn vba_function_value_calls_follow_parameter_changes_after_restart() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let fixture = durable_test_tempdir();
        let path = fixture.path().join("meter.bas");
        let mut previous_generation = None;
        for (parameters, expected_calls) in [
            ("()", 1),
            ("(ByVal input As Long)", 0),
            ("(Optional ByVal input As Long = 1)", 1),
            ("(ParamArray items() As Variant)", 1),
        ] {
            let source = format!(
                "VERSION 1.0 CLASS\nAttribute VB_Name = \"Meter\"\nPrivate Declare PtrSafe Function ReadClock Lib \"clock\" () As LongPtr\nFunction Measure{parameters} As Long\nMeasure = 1\nEnd Function\nSub Run()\nDim value As Long\nvalue = Me.mEaSuRe\nEnd Sub\n"
            );
            fs::write(&path, &source).unwrap();
            let mut service =
                FirstSliceService::new_durable(4, paths.state_dir(), &deadline()).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(receipt.indexed_files, 1);
            assert_eq!(
                service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap(),
                receipt
            );
            if let Some(previous) = previous_generation {
                assert_ne!(receipt.generation, previous);
            }
            previous_generation = Some(receipt.generation);
            drop(service);
            let service =
                FirstSliceService::new_durable(4, paths.state_dir(), &deadline()).unwrap();
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            let run = document
                .entities
                .iter()
                .find(|entity| entity.kind == EntityKind::Method && entity.canonical_name == "Run")
                .unwrap()
                .id;
            let measure = document
                .entities
                .iter()
                .find(|entity| {
                    entity.kind == EntityKind::Method && entity.canonical_name == "Measure"
                })
                .unwrap()
                .id;
            let relationships = service
                .symbol_relationships(
                    receipt.generation,
                    BTreeSet::from([run]),
                    vec![RelationFamily::Calls],
                    Some(RelationDirection::Outbound),
                    0,
                    10,
                    0,
                    &deadline(),
                )
                .unwrap();
            let edges: Vec<_> = relationships
                .data
                .groups
                .iter()
                .flat_map(|group| &group.items)
                .collect();
            assert_eq!(edges.len(), expected_calls, "{parameters}");
            let start = u64::try_from(source.find("mEaSuRe").unwrap()).unwrap();
            let site = document
                .occurrences
                .iter()
                .find(|site| {
                    site.source.span().start_byte() == start
                        && site.source.span().end_byte() == start + 7
                })
                .unwrap();
            if expected_calls == 0 {
                assert!(matches!(site.target, OccurrenceTarget::Unresolved { .. }));
            } else {
                assert_eq!(site.target, OccurrenceTarget::Resolved { symbol: measure });
                assert_eq!(site.role, OccurrenceRole::CallSite);
                assert_eq!(edges[0].symbol, measure);
                assert_eq!(edges[0].source_refs.len(), 1);
                let reference = &edges[0].source_refs[0];
                assert_eq!(reference.generation(), receipt.generation);
                assert_eq!(reference.span().start_byte(), start);
                let read = service
                    .source_read_with_options_and_budget(
                        receipt.generation,
                        vec![reference.clone()],
                        SourceReadOptions::new()
                            .with_context_lines_before(0)
                            .with_context_lines_after(0),
                        FirstSliceBudget::default(),
                        &deadline(),
                    )
                    .unwrap();
                assert_eq!(read.data.chunks.len(), 1);
                assert_eq!(read.data.chunks[0].bytes, b"mEaSuRe");
            }
        }
    }

    #[test]
    fn vba_instance_owner_references_survive_restart_and_class_removal() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let fixture = durable_test_tempdir();
        let path = fixture.path().join("holder.bas");
        let source = "VERSION 1.0 CLASS\nAttribute VB_Name = \"Holder\"\nPrivate Declare PtrSafe Function ReadClock Lib \"clock\" () As LongPtr\nPublic Item As Variant\nSub Run(ByVal value As Variant)\nSet value = mE\nvalue = mE.Item\nVisit mE\nItem = 1\nEnd Sub\nSub Visit(ByVal value As Variant)\nEnd Sub\n";
        let mut previous = None;
        for source in [
            source.to_owned(),
            source.replace("Item = 1", "Item = 2 + 3"),
            source.replace("VERSION 1.0 CLASS\n", ""),
        ] {
            fs::write(&path, &source).unwrap();
            let mut service =
                FirstSliceService::new_durable(4, paths.state_dir(), &deadline()).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(receipt.indexed_files, 1);
            assert_eq!(
                service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap(),
                receipt
            );
            drop(service);
            let service =
                FirstSliceService::new_durable(4, paths.state_dir(), &deadline()).unwrap();
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            let class = document
                .entities
                .iter()
                .find(|entity| entity.kind == EntityKind::Class)
                .map(|entity| entity.id);
            assert_eq!(class.is_some(), source.starts_with("VERSION 1.0 CLASS"));
            if let Some((generation, old_class)) = previous {
                assert_ne!(receipt.generation, generation);
                if class.is_some() {
                    assert_eq!(class, old_class);
                }
            }
            previous = Some((receipt.generation, class));
            let sites: Vec<_> = document
                .occurrences
                .iter()
                .filter(|site| site.syntax_kind.as_str() == "vba.instance.reference")
                .collect();
            assert_eq!(sites.len(), 3);
            let expected: BTreeSet<_> = source
                .match_indices("mE")
                .map(|(start, _)| u64::try_from(start).unwrap())
                .collect();
            assert_eq!(
                sites
                    .iter()
                    .map(|site| site.source.span().start_byte())
                    .collect::<BTreeSet<_>>(),
                expected
            );
            if let Some(symbol) = class {
                let run = document
                    .entities
                    .iter()
                    .find(|entity| entity.canonical_name == "Run")
                    .unwrap()
                    .id;
                let result = service
                    .symbol_relationships(
                        receipt.generation,
                        BTreeSet::from([run]),
                        vec![RelationFamily::References],
                        Some(RelationDirection::Outbound),
                        0,
                        20,
                        0,
                        &deadline(),
                    )
                    .unwrap();
                let references: Vec<_> = result
                    .data
                    .groups
                    .iter()
                    .flat_map(|group| &group.items)
                    .filter(|edge| edge.symbol == symbol)
                    .flat_map(|edge| &edge.source_refs)
                    .collect();
                assert_eq!(references.len(), 3);
                assert_eq!(
                    references
                        .iter()
                        .map(|reference| reference.span().start_byte())
                        .collect::<BTreeSet<_>>(),
                    expected
                );
            }
            for site in sites {
                assert_eq!(site.role, OccurrenceRole::Reference);
                if let Some(symbol) = class {
                    assert_eq!(site.target, OccurrenceTarget::Resolved { symbol });
                } else {
                    assert!(matches!(site.target, OccurrenceTarget::Unresolved { .. }));
                    assert!(document.skipped_regions.iter().any(|gap| {
                        gap.source.span() == site.source.span()
                            && gap.detail == "vba-instance-owner-unavailable"
                    }));
                }
                assert_eq!(site.source.generation(), receipt.generation);
                let read = service
                    .source_read_with_options_and_budget(
                        receipt.generation,
                        vec![site.source.clone()],
                        SourceReadOptions::new()
                            .with_context_lines_before(0)
                            .with_context_lines_after(0),
                        FirstSliceBudget::default(),
                        &deadline(),
                    )
                    .unwrap();
                assert_eq!(read.data.chunks.len(), 1);
                assert_eq!(read.data.chunks[0].bytes, b"mE");
            }
        }
    }

    #[test]
    fn vba_procedure_pointers_follow_mutation_and_restart() {
        assert_vba_pointer_restart("[Notify]", "vba.procedure_pointer.reference");
    }

    #[test]
    fn vba_qualified_procedure_pointers_follow_mutation_and_restart() {
        assert_vba_pointer_restart(
            "Callbacks.[Notify]",
            "vba.qualified_procedure_pointer.reference",
        );
    }

    fn assert_vba_pointer_restart(spelling: &str, syntax: &str) {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let fixture = durable_test_tempdir();
        let path = fixture.path().join("callbacks.bas");
        let original = format!(
            "Attribute VB_Name = \"Callbacks\"\nPrivate Declare PtrSafe Sub Register Lib \"callbacks\" (ByVal address As LongPtr)\nPrivate Sub Notify()\nEnd Sub\nSub Run()\nDim Notify As Long\nCall Register(AddressOf {spelling})\nEnd Sub\n"
        );
        let mut previous = None;
        for (source, resolved) in [
            (original.to_owned(), true),
            (original.replace("Sub Notify()", "Sub Changed()"), false),
            (original.to_owned(), true),
        ] {
            fs::write(&path, &source).unwrap();
            let mut service =
                FirstSliceService::new_durable(4, paths.state_dir(), &deadline()).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(receipt.indexed_files, 1);
            assert_eq!(
                service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap(),
                receipt
            );
            if let Some(generation) = previous {
                assert_ne!(receipt.generation, generation);
            }
            previous = Some(receipt.generation);
            let before = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap()
                .document()
                .clone();
            drop(service);
            let service =
                FirstSliceService::new_durable(4, paths.state_dir(), &deadline()).unwrap();
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            assert_eq!(document, &before);
            let site = document
                .occurrences
                .iter()
                .find(|site| site.syntax_kind == syntax)
                .unwrap();
            assert_eq!(
                matches!(site.target, OccurrenceTarget::Resolved { .. }),
                resolved
            );
            assert_eq!(site.role, OccurrenceRole::Reference);
            assert_eq!(site.source.generation(), receipt.generation);
            assert_eq!(
                document.skipped_regions.iter().any(|gap| {
                    gap.source == site.source
                        && gap.detail == "vba-procedure-pointer-target-unavailable"
                }),
                !resolved
            );
            assert!(!document.relations.iter().any(|edge| {
                edge.predicate == RelationPredicate::Calls
                    && edge.evidence.source.as_ref() == Some(&site.source)
            }));
            if let OccurrenceTarget::Resolved { symbol } = site.target {
                assert!(document.entities.iter().any(|entity| {
                    entity.id == symbol
                        && entity.canonical_name == "Notify"
                        && entity.kind == EntityKind::Function
                }));
                let relationships = service
                    .symbol_relationships(
                        receipt.generation,
                        BTreeSet::from([symbol]),
                        vec![RelationFamily::References, RelationFamily::Calls],
                        Some(RelationDirection::Inbound),
                        0,
                        10,
                        0,
                        &deadline(),
                    )
                    .unwrap();
                let references: Vec<_> = relationships
                    .data
                    .groups
                    .iter()
                    .flat_map(|group| &group.items)
                    .flat_map(|edge| &edge.source_refs)
                    .collect();
                assert_eq!(references, vec![&site.source]);
            }
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![site.source.clone()],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .unwrap();
            assert_eq!(read.data.chunks.len(), 1);
            assert_eq!(read.data.chunks[0].bytes, spelling.as_bytes());
        }
    }

    #[test]
    fn vba_result_references_preserve_sources_after_restart_and_mutation() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let fixture = durable_test_tempdir();
        let path = fixture.path().join("holder.bas");
        let source = "Private Declare PtrSafe Function ReadClock Lib \"clock\" () As LongPtr\nFunction Measure() As Variant\n[mEaSuRe] = 1\n[mEaSuRe] = [mEaSuRe] + 1\nEnd Function\nProperty Get Item() As Variant\n[iTeM] = 1\n[iTeM] = [iTeM] + 1\nEnd Property\n";
        let mut previous = None;
        for source in [source.to_owned(), source.replace("+ 1", "+ 2 + 3")] {
            fs::write(&path, &source).unwrap();
            let mut service =
                FirstSliceService::new_durable(4, paths.state_dir(), &deadline()).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(receipt.indexed_files, 1);
            assert_eq!(
                service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap(),
                receipt
            );
            drop(service);
            let service =
                FirstSliceService::new_durable(4, paths.state_dir(), &deadline()).unwrap();
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            let symbols: BTreeMap<_, _> = document
                .entities
                .iter()
                .filter(|entity| matches!(entity.kind, EntityKind::Function | EntityKind::Property))
                .map(|entity| (entity.canonical_name.as_str(), entity.id))
                .collect();
            let identities = BTreeSet::from([symbols["Measure"], symbols["Item"]]);
            if let Some((old_generation, old_identities)) = previous {
                assert_ne!(receipt.generation, old_generation);
                assert_eq!(identities, old_identities);
            }
            previous = Some((receipt.generation, identities));
            for (name, spelling) in [("Measure", "[mEaSuRe]"), ("Item", "[iTeM]")] {
                let symbol = symbols[name];
                let relationships = service
                    .symbol_relationships(
                        receipt.generation,
                        BTreeSet::from([symbol]),
                        vec![RelationFamily::References, RelationFamily::Calls],
                        Some(RelationDirection::Outbound),
                        0,
                        10,
                        0,
                        &deadline(),
                    )
                    .unwrap();
                let edges: Vec<_> = relationships
                    .data
                    .groups
                    .iter()
                    .flat_map(|group| &group.items)
                    .collect();
                assert_eq!(edges.len(), 3);
                assert!(edges.iter().all(|edge| edge.symbol == symbol));
                let references: Vec<_> = edges.iter().flat_map(|edge| &edge.source_refs).collect();
                let expected: BTreeSet<_> = source
                    .match_indices(spelling)
                    .map(|(start, _)| u64::try_from(start).unwrap())
                    .collect();
                assert_eq!(expected.len(), 3);
                assert_eq!(references.len(), expected.len());
                assert_eq!(
                    references
                        .iter()
                        .map(|reference| reference.span().start_byte())
                        .collect::<BTreeSet<_>>(),
                    expected
                );
                for reference in references {
                    assert_eq!(reference.generation(), receipt.generation);
                    let site = document
                        .occurrences
                        .iter()
                        .find(|site| site.source.span() == reference.span())
                        .unwrap();
                    assert_eq!(site.role, OccurrenceRole::Reference);
                    assert_eq!(site.target, OccurrenceTarget::Resolved { symbol });
                    let read = service
                        .source_read_with_options_and_budget(
                            receipt.generation,
                            vec![reference.clone()],
                            SourceReadOptions::new()
                                .with_context_lines_before(0)
                                .with_context_lines_after(0),
                            FirstSliceBudget::default(),
                            &deadline(),
                        )
                        .unwrap();
                    assert_eq!(read.data.chunks.len(), 1);
                    assert_eq!(read.data.chunks[0].bytes, spelling.as_bytes());
                }
            }
        }
    }

