    #[test]
    fn utf16_dispositions_distinguish_routes_encodings_and_opaque_containers() {
        for little_endian in [true, false] {
            let fixture = TempDir::new().unwrap();
            let encode = |text: &str| {
                std::iter::once(0xfeff_u16)
                    .chain(text.encode_utf16())
                    .flat_map(|unit| {
                        if little_endian {
                            unit.to_le_bytes()
                        } else {
                            unit.to_be_bytes()
                        }
                    })
                    .collect::<Vec<_>>()
            };
            let cases = [
                (
                    "unclassified.sourceblob",
                    "lexicalMarker λ\r\n",
                    "unknown",
                    Some(UnsupportedSourceDisposition::Language),
                ),
                (
                    "headless.fs",
                    "let value = 1\r\n",
                    "unknown",
                    Some(UnsupportedSourceDisposition::Language),
                ),
                ("boot.asm", "entry:\r\nnop\r\n", "assembly", None),
                (
                    "sample.awk",
                    "function value() { return 1 }\r\n",
                    "awk",
                    Some(UnsupportedSourceDisposition::Encoding),
                ),
            ];
            for (path, text, _, _) in cases {
                fs::write(fixture.path().join(path), encode(text)).unwrap();
            }
            let container = b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1";
            fs::write(fixture.path().join("opaque.cfb"), container).unwrap();
            let malformed = if little_endian {
                [0xff, 0xfe, 0x00, 0xd8]
            } else {
                [0xfe, 0xff, 0xd8, 0x00]
            };
            fs::write(fixture.path().join("malformed.rs"), malformed).unwrap();
            let mut service = FirstSliceService::new(2).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(receipt.discovered_inputs, 6);
            // This counter covers excluded binaries; opaque containers retain
            // an admitted source record with their separate disposition below.
            assert_eq!(receipt.binary_inputs, 0);
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            assert_eq!(document.files.len(), 6);
            assert_eq!(
                document.entities.len(),
                2,
                "unexpected UTF-16 Assembly facts: entities={:#?}, diagnostics={:#?}",
                document.entities,
                document.diagnostics
            );
            encoded_bom_source_preservation::assert_opaque(
                &service,
                &receipt,
                "malformed.rs",
                &malformed,
                "rust",
            );
            for (path, text, language, disposition) in cases {
                let bytes = encode(text);
                let file = document
                    .files
                    .iter()
                    .find(|file| file.path == path)
                    .unwrap();
                assert_eq!(file.language, language);
                assert_eq!(
                    file.encoding,
                    if little_endian {
                        "utf-16le"
                    } else {
                        "utf-16be"
                    }
                );
                assert_eq!(file.content_hash, content_hash(&bytes));
                assert_eq!(file.byte_length, u64::try_from(bytes.len()).unwrap());
                let reference = file.evidence.source.clone().unwrap();
                assert_eq!(reference.repository(), receipt.repository);
                assert_eq!(reference.generation(), receipt.generation);
                assert_eq!(reference.content_hash(), file.content_hash);
                assert_eq!(
                    reference.span(),
                    SourceSpan::new(file.id, 0, file.byte_length).unwrap()
                );
                let coverage = service
                    .source_file_coverage_until(receipt.generation, file.id, &deadline())
                    .unwrap();
                let Some(disposition) = disposition else {
                    assert_eq!(language, "assembly");
                    assert_eq!(coverage.reason, None);
                    assert!(matches!(
                        coverage.status,
                        CoverageStatus::Bounded | CoverageStatus::Unknown
                    ));
                    assert!(!document.diagnostics.iter().any(|diagnostic| {
                        diagnostic
                            .source
                            .as_ref()
                            .is_some_and(|source| source.span().file() == file.id)
                            && matches!(
                                diagnostic.code.as_str(),
                                "unsupported-language" | "unsupported-encoding"
                            )
                    }));
                    let module = document
                        .entities
                        .iter()
                        .find(|entity| entity.kind == EntityKind::Module)
                        .unwrap();
                    assert_eq!(module.canonical_name, path);
                    assert_eq!(module.display_name, path);
                    assert_eq!(module.flags, [rootlight_ir::EntityFlag::Synthetic]);
                    assert_eq!(module.evidence.source.as_ref(), Some(&reference));
                    let label = document
                        .entities
                        .iter()
                        .find(|entity| entity.kind == EntityKind::StatementLabel)
                        .unwrap();
                    assert_eq!(label.canonical_name, "entry");
                    assert_eq!(label.display_name, "entry");
                    assert!(label.flags.is_empty());
                    let label_source = SourceRef::new(
                        receipt.repository,
                        receipt.generation,
                        SourceSpan::new(file.id, 2, 14).unwrap(),
                        file.content_hash,
                        None,
                    );
                    assert_eq!(label.evidence.source.as_ref(), Some(&label_source));
                    assert_eq!(document.occurrences.len(), 1);
                    let definition = &document.occurrences[0];
                    assert_eq!(definition.role, OccurrenceRole::Definition);
                    assert_eq!(
                        definition.target,
                        OccurrenceTarget::Resolved { symbol: label.id }
                    );
                    assert_eq!(
                        definition.source,
                        SourceRef::new(
                            receipt.repository,
                            receipt.generation,
                            SourceSpan::new(file.id, 2, 12).unwrap(),
                            file.content_hash,
                            None,
                        )
                    );
                    assert_eq!(definition.evidence.source.as_ref(), Some(&label_source));
                    assert!(document.skipped_regions.iter().any(|region| {
                        region.source == reference
                            && region.domain == rootlight_ir::FactDomain::Relations
                            && region.reason == SkippedRegionReason::UnsupportedConstruct
                            && region.detail == "assembly-expansion-and-binding-unavailable"
                    }));
                    let located = service
                        .code_locate(
                            receipt.generation,
                            "entry".to_owned(),
                            LocateMode::Prefix,
                            10,
                            0,
                            &deadline(),
                        )
                        .unwrap();
                    let hits = located.data.hits;
                    assert_eq!(
                        hits.len(),
                        2,
                        "unexpected UTF-16 Assembly locate hits: {hits:#?}"
                    );
                    assert!(hits.iter().all(|hit| hit.file == file.id));
                    let label_hit = hits
                        .iter()
                        .find(|hit| hit.symbol == Some(label.id))
                        .unwrap();
                    assert_eq!(label_hit.kind, "statement_label");
                    assert_eq!(label_hit.identifier, "entry");
                    assert_eq!(label_hit.path, path);
                    assert_eq!(label_hit.source.as_ref(), Some(&label_source));
                    let file_hit = hits.iter().find(|hit| hit.symbol.is_none()).unwrap();
                    assert_eq!(file_hit.kind, "file");
                    assert_eq!(file_hit.identifier, path);
                    assert_eq!(file_hit.path, path);
                    assert_eq!(file_hit.source.as_ref(), Some(&reference));
                    continue;
                };
                let (code, skipped_reason, coverage_reason) = match disposition {
                    UnsupportedSourceDisposition::Language => (
                        "unsupported-language",
                        SkippedRegionReason::UnsupportedConstruct,
                        FirstSliceSourceCoverageReason::UnsupportedLanguage,
                    ),
                    UnsupportedSourceDisposition::Encoding => (
                        "unsupported-encoding",
                        SkippedRegionReason::UnsupportedEncoding,
                        FirstSliceSourceCoverageReason::UnsupportedEncoding,
                    ),
                    UnsupportedSourceDisposition::AdmissionResourceBounded => (
                        "language-admission-resource-bounded",
                        SkippedRegionReason::ResourceLimit,
                        FirstSliceSourceCoverageReason::ResourceBounded,
                    ),
                    UnsupportedSourceDisposition::IntrinsicIdentityWorkLimit { .. } => (
                        "native-identity-work-limit",
                        SkippedRegionReason::ResourceLimit,
                        FirstSliceSourceCoverageReason::ResourceBounded,
                    ),
                    UnsupportedSourceDisposition::NativeIdentityRefusal { .. } => (
                        "native-query-refusal",
                        SkippedRegionReason::ResourceLimit,
                        FirstSliceSourceCoverageReason::ResourceBounded,
                    ),
                    UnsupportedSourceDisposition::NativeScannerRefusal { details } => match details {
                        rootlight_adapter_treesitter::NativeScannerRefusalDetails::DockerfileStateCapacity => (
                            "native-scanner-capacity", SkippedRegionReason::ResourceLimit, FirstSliceSourceCoverageReason::ResourceBounded,
                        ),
                        _ => panic!("construct refusal is checked by its separate source-preservation test"),
                    },
        UnsupportedSourceDisposition::AggregateFileCapacity => (
                        "aggregate-file-capacity",
                        SkippedRegionReason::ResourceLimit,
                        FirstSliceSourceCoverageReason::ResourceBounded,
                    ),
                    UnsupportedSourceDisposition::ParserSizeLimit => (
                        "source-parser-snapshot-size-limit",
                        SkippedRegionReason::ResourceLimit,
                        FirstSliceSourceCoverageReason::ResourceBounded,
                    ),
                };
                assert_eq!(coverage.status, CoverageStatus::Unknown);
                assert_eq!(coverage.reason, Some(coverage_reason));
                assert!(document.diagnostics.iter().any(|diagnostic| {
                    diagnostic.code == code
                        && diagnostic.source.as_ref() == Some(&reference)
                        && diagnostic.coverage_effect == CoverageStatus::Unknown
                }));
                let skipped = document
                    .skipped_regions
                    .iter()
                    .filter(|region| region.source.span().file() == file.id)
                    .collect::<Vec<_>>();
                assert_eq!(skipped.len(), 3);
                assert!(skipped.iter().all(|region| {
                    region.reason == skipped_reason
                        && region.detail == code
                        && region.source == reference
                }));
            }
            for (path, bytes) in cases
                .into_iter()
                .map(|(path, text, _, _)| (path, encode(text)))
                .chain(std::iter::once(("opaque.cfb", container.to_vec())))
            {
                let file = document
                    .files
                    .iter()
                    .find(|file| file.path == path)
                    .unwrap();
                let reference = file.evidence.source.clone().unwrap();
                assert_eq!(reference.generation(), receipt.generation);
                assert_eq!(reference.content_hash(), content_hash(&bytes));
                assert_eq!(
                    reference.span(),
                    SourceSpan::new(file.id, 0, u64::try_from(bytes.len()).unwrap()).unwrap()
                );
                let read = service
                    .source_read_with_options_and_budget(
                        receipt.generation,
                        vec![reference.clone()],
                        SourceReadOptions::new()
                            .with_context_lines_before(0)
                            .with_context_lines_after(0)
                            .with_encoding(rootlight_source::SourceEncoding::Bytes),
                        FirstSliceBudget::default(),
                        &deadline(),
                    )
                    .unwrap();
                assert_eq!(read.data.chunks.len(), 1);
                assert_eq!(read.data.chunks[0].bytes, bytes);
                assert_eq!(read.data.chunks[0].reference, reference);
                let located = service
                    .code_locate(
                        receipt.generation,
                        path.to_owned(),
                        LocateMode::Prefix,
                        10,
                        0,
                        &deadline(),
                    )
                    .unwrap();
                let hit = located
                    .data
                    .hits
                    .iter()
                    .find(|hit| hit.file == file.id && hit.symbol.is_none())
                    .unwrap();
                assert!(hit.symbol.is_none());
                assert_eq!(hit.kind, "file");
                assert_eq!(hit.source.as_ref(), Some(&reference));
                if path == "boot.asm" {
                    let module = document
                        .entities
                        .iter()
                        .find(|entity| entity.kind == EntityKind::Module)
                        .unwrap();
                    assert!(located.data.hits.iter().any(|hit| {
                        hit.symbol == Some(module.id)
                            && hit.file == file.id
                            && hit.source.as_ref() == Some(&reference)
                    }));
                } else {
                    assert!(
                        located
                            .data
                            .hits
                            .iter()
                            .all(|hit| hit.file != file.id || hit.symbol.is_none())
                    );
                }
            }
            let opaque = document
                .files
                .iter()
                .find(|file| file.path == "opaque.cfb")
                .unwrap();
            assert_eq!(opaque.language, "compound-document");
            assert_eq!(opaque.encoding, "binary");
            let coverage = service
                .source_file_coverage_until(receipt.generation, opaque.id, &deadline())
                .unwrap();
            assert_eq!(coverage.status, CoverageStatus::Unknown);
            assert_eq!(
                coverage.reason,
                Some(FirstSliceSourceCoverageReason::UnsupportedEncoding)
            );
            let message = "container bytes have no direct structural analyzer and derived source coverage is reported separately";
            assert!(
                receipt.diagnostics.iter().any(|diagnostic| {
                    diagnostic.code == "unsupported-encoding" && diagnostic.message == message
                }),
                "container disposition must retain its precise public diagnostic: {:?}",
                receipt.diagnostics
            );
            let reference = opaque.evidence.source.as_ref().unwrap();
            let diagnostic = document
                .diagnostics
                .iter()
                .find(|diagnostic| {
                    diagnostic.source.as_ref() == Some(reference)
                        && diagnostic.code == "unsupported-encoding"
                })
                .unwrap();
            assert_eq!(diagnostic.message, message);
            assert_eq!(diagnostic.coverage_effect, CoverageStatus::Unknown);
            assert_eq!(diagnostic.evidence.source.as_ref(), Some(reference));
            assert_eq!(diagnostic.provenance, opaque.provenance);
            let producer = document
                .provenance
                .iter()
                .find(|proof| proof.id == diagnostic.provenance)
                .unwrap();
            assert_eq!(
                producer.binary_digest,
                content_hash(LANGUAGE_DISPOSITION_PROVIDER_SEED)
            );
            assert_eq!(producer.rule.as_deref(), Some("unsupported-encoding"));
            assert_eq!(producer.input_sources, std::slice::from_ref(reference));
            assert_eq!(producer.evidence_sources, std::slice::from_ref(reference));
            let gaps = service
                .coverage_gaps_until(receipt.repository, receipt.generation, &deadline())
                .unwrap();
            assert!(gaps.iter().any(|gap| {
                gap.reason == FirstSliceCoverageGapReason::Unrecognized
                    && gap.language.as_deref() == Some("unknown")
                    && gap.files == 2
            }));
            assert!(!gaps.iter().any(|gap| {
                gap.reason == FirstSliceCoverageGapReason::Unsupported
                    && gap.language.as_deref() == Some("unknown")
            }));
            for language in ["assembly", "awk", "compound-document"] {
                assert!(gaps.iter().any(|gap| {
                    gap.reason == FirstSliceCoverageGapReason::Unsupported
                        && gap.language.as_deref() == Some(language)
                        && gap.files == 1
                }));
            }
        }
    }

    #[test]
    fn mixed_source_profiles_retain_exact_evidence_and_reason() {
        let fixture = TempDir::new().expect("fixture root exists");
        let sources = [
            (
                "Session.mm",
                "@interface Session : NSObject\n@end\n",
                "objective-cpp",
            ),
            (
                "classify.mlx",
                "function result = classify(value)\nresult = value;\nend\n",
                "matlab",
            ),
            (
                "mystery.sourceblob",
                "opaqueWidget configures lexicalFallback\n",
                "unknown",
            ),
            ("Shape.carbon", "fn MakeShape() {}\n", "carbon"),
            ("Main.idr", "module Main\n", "idris"),
            ("Algebra.lean", "namespace Algebra\n", "lean"),
            ("actor.pony", "actor Main\n", "pony"),
            ("theme.less", "@accent: blue;\n", "less"),
        ];
        for (path, content, _) in sources {
            fs::write(fixture.path().join(path), content).expect("source fixture writes");
        }
        let mut service = FirstSliceService::new(2).expect("service initializes");
        let receipt = service
            .index_repository(fixture.path(), &deadline())
            .expect("unsupported sources publish");
        let generation = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("published generation remains retained");

        for (path, content, language) in sources {
            let file = generation
                .document()
                .files
                .iter()
                .find(|file| file.path == path)
                .expect("unsupported file remains represented");
            let coverage = service
                .source_file_coverage_until(receipt.generation, file.id, &deadline())
                .expect("source coverage resolves");
            assert_eq!(coverage.language, language);
            assert_eq!(coverage.tier, AnalysisTier::TierD);
            let (expected_status, expected_reason) =
                if matches!(language, "pony" | "idris" | "lean" | "less") {
                    (CoverageStatus::Bounded, None)
                } else {
                    (
                        CoverageStatus::Unknown,
                        Some(FirstSliceSourceCoverageReason::UnsupportedLanguage),
                    )
                };
            assert_eq!(
                coverage.status, expected_status,
                "{path}: language={language}, reason={:?}",
                coverage.reason
            );
            assert_eq!(coverage.reason, expected_reason, "{path}");
            if language == "pony" {
                let declarations: Vec<_> = generation
                    .document()
                    .entities
                    .iter()
                    .filter(|entity| {
                        entity.language == "pony"
                            && entity.kind == EntityKind::Class
                            && entity.canonical_name == "Main"
                            && entity
                                .evidence
                                .source
                                .as_ref()
                                .is_some_and(|source| source.span().file() == file.id)
                    })
                    .collect();
                assert_eq!(declarations.len(), 1, "native actor declaration");
                let definitions: Vec<_> = generation
                    .document()
                    .occurrences
                    .iter()
                    .filter(|site| {
                        site.role == OccurrenceRole::Definition
                            && matches!(site.target, rootlight_ir::OccurrenceTarget::Resolved { symbol }
                                if symbol == declarations[0].id)
                    })
                    .collect();
                assert_eq!(definitions.len(), 1, "one native actor definition");
                assert_eq!(definitions[0].source.span().start_byte(), 6);
                assert_eq!(definitions[0].source.span().end_byte(), 10);
                assert_eq!(
                    definitions[0].source.content_hash(),
                    content_hash(content.as_bytes())
                );
            }
            let reference = file
                .evidence
                .source
                .clone()
                .expect("unsupported file carries source evidence");
            let read = service
                .source_read(receipt.generation, vec![reference.clone()], &deadline())
                .expect("unsupported source remains readable");
            assert_eq!(read.data.chunks[0].bytes, content.as_bytes());
            assert_eq!(read.data.chunks[0].language, language);
            let exact_identifier = content
                .split(|character: char| !(character == '_' || character.is_alphanumeric()))
                .find(|candidate| {
                    candidate.len() > 4
                        && candidate
                            .chars()
                            .next()
                            .is_some_and(|character| character.is_alphabetic())
                })
                .expect("fixture contains a searchable identifier");
            for (query, mode) in [
                (exact_identifier.to_owned(), LocateMode::Exact),
                (exact_identifier.to_owned(), LocateMode::Text),
                (path.to_owned(), LocateMode::Prefix),
            ] {
                let located = service
                    .code_locate(receipt.generation, query, mode, 10, 0, &deadline())
                    .expect("unsupported source locates");
                let hit = located
                    .data
                    .hits
                    .iter()
                    .find(|hit| hit.file == file.id && hit.symbol.is_none())
                    .expect("file-only source hit is returned");
                assert_eq!(hit.symbol, None);
                assert_eq!(hit.kind, "file");
                assert_eq!(hit.source.as_ref(), Some(&reference));
            }
        }
        let gaps = service
            .coverage_gaps_until(receipt.repository, receipt.generation, &deadline())
            .expect("coverage gaps resolve");
        assert!(gaps.iter().any(|gap| {
            gap.reason == FirstSliceCoverageGapReason::Unrecognized
                && gap.language.as_deref() == Some("unknown")
                && gap.files == 1
        }));
        for language in [
            "objective-cpp",
            "matlab",
            "carbon",
            "idris",
            "lean",
            "pony",
            "less",
        ] {
            assert!(gaps.iter().any(|gap| {
                gap.reason == FirstSliceCoverageGapReason::Unsupported
                    && gap.language.as_deref() == Some(language)
                    && gap.files == 1
            }));
        }
    }

    #[test]
    fn tcl_procedures_remain_source_backed_with_bounded_dynamic_semantics() {
        let fixture = TempDir::new().expect("fixture root exists");
        let source = "# proc hidden {} {}\nnamespace eval palette {\n  proc tone {value} {return $value}\n}\nproc render {} {tone blue}\nproc $runtime {} {return unknown}\n";
        fs::write(fixture.path().join("theme.tcl"), source).expect("Tcl source writes");
        let cancellation = deadline();
        let mut service = FirstSliceService::new(2).expect("service initializes");
        let receipt = service
            .index_repository(fixture.path(), &cancellation)
            .expect("Tcl source indexes");
        let snapshot = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("generation remains loaded");
        let document = snapshot.document();
        for (name, kind) in [
            ("palette", EntityKind::Namespace),
            ("tone", EntityKind::Function),
            ("render", EntityKind::Function),
        ] {
            assert!(
                document.entities.iter().any(|entity| {
                    entity.language == "tcl" && entity.kind == kind && entity.canonical_name == name
                }),
                "missing {name}"
            );
        }
        assert!(
            !document
                .entities
                .iter()
                .any(|entity| { matches!(entity.canonical_name.as_str(), "hidden" | "$runtime") })
        );
        let call = document
            .occurrences
            .iter()
            .find(|occurrence| {
                let span = occurrence.source.span();
                occurrence.syntax_kind == "tcl.command.call"
                    && source.as_bytes().get(
                        usize::try_from(span.start_byte()).expect("span fits")
                            ..usize::try_from(span.end_byte()).expect("span fits"),
                    ) == Some(b"tone".as_slice())
            })
            .expect("literal procedure call is retained");
        let span = call.source.span();
        assert_eq!(
            &source.as_bytes()[usize::try_from(span.start_byte()).expect("span fits")
                ..usize::try_from(span.end_byte()).expect("span fits")],
            b"tone"
        );
        assert!(
            !matches!(call.target, rootlight_ir::OccurrenceTarget::Resolved { .. }),
            "literal Tcl spelling alone does not prove a runtime binding"
        );
        assert!(document.skipped_regions.iter().any(|gap| {
            gap.detail == "tcl-dynamic-command-semantics-partial"
                && gap.source.generation() == receipt.generation
        }));
        let file = document
            .files
            .iter()
            .find(|file| file.path == "theme.tcl")
            .expect("Tcl file exists");
        let reference = file
            .evidence
            .source
            .clone()
            .expect("generation-bound source exists");
        let read = service
            .source_read(receipt.generation, vec![reference], &cancellation)
            .expect("Tcl source remains readable");
        assert_eq!(read.data.chunks[0].bytes, source.as_bytes());
        for (query, mode) in [
            ("tone", LocateMode::Exact),
            ("return", LocateMode::Text),
            ("theme.tcl", LocateMode::Prefix),
        ] {
            let located = service
                .code_locate(
                    receipt.generation,
                    query.to_owned(),
                    mode,
                    10,
                    0,
                    &cancellation,
                )
                .expect("Tcl source locates");
            assert!(located.data.hits.iter().any(|hit| hit.path == "theme.tcl"));
        }
        let status = service
            .repository_status(receipt.repository, Some(receipt.generation))
            .expect("Tcl coverage resolves");
        assert!(status.coverage.iter().any(|entry| {
            entry.language == "tcl"
                && entry.discovered_files == 1
                && entry.indexed_files == 1
                && entry.status == "bounded"
        }));
    }

    #[test]
    fn repeated_tcl_declarations_keep_separate_source_identities() {
        let fixture = TempDir::new().expect("fixture root exists");
        fs::write(
            fixture.path().join("commands.tcl"),
            "proc route {} {}\nproc route {} {}\nproc caller {} {route}\n",
        )
        .expect("Tcl source writes");
        let cancellation = deadline();
        let mut service = FirstSliceService::new(2).expect("service initializes");
        let receipt = service
            .index_repository(fixture.path(), &cancellation)
            .expect("Tcl source indexes");
        let snapshot = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("generation remains loaded");
        let document = snapshot.document();
        let definitions: Vec<_> = document
            .entities
            .iter()
            .filter(|entity| {
                entity.language == "tcl"
                    && entity.kind == EntityKind::Function
                    && entity.canonical_name == "route"
            })
            .collect();
        assert_eq!(definitions.len(), 2);
        assert_ne!(definitions[0].id, definitions[1].id);
        assert_ne!(
            definitions[0]
                .evidence
                .source
                .as_ref()
                .map(|source| source.span()),
            definitions[1]
                .evidence
                .source
                .as_ref()
                .map(|source| source.span())
        );
        let call = document
            .occurrences
            .iter()
            .find(|occurrence| occurrence.syntax_kind == "tcl.command.call")
            .expect("ambiguous written call stays in the index");
        assert!(!matches!(
            call.target,
            rootlight_ir::OccurrenceTarget::Resolved { .. }
        ));
    }

    #[test]
    fn tcl_cross_file_command_calls_retain_bounded_targets() {
        let fixture = TempDir::new().expect("fixture root exists");
        fs::write(
            fixture.path().join("caller.tcl"),
            "proc invoke {} {shared}\n",
        )
        .expect("caller source writes");
        fs::write(
            fixture.path().join("library.tcl"),
            "proc shared {} {return ok}\n",
        )
        .expect("library source writes");
        let cancellation = deadline();
        let mut service = FirstSliceService::new(2).expect("service initializes");
        let receipt = service
            .index_repository(fixture.path(), &cancellation)
            .expect("Tcl sources index");
        let snapshot = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("generation remains loaded");
        let document = snapshot.document();
        let shared = document
            .entities
            .iter()
            .find(|entity| entity.language == "tcl" && entity.canonical_name == "shared")
            .expect("shared command is indexed");
        let caller = document
            .files
            .iter()
            .find(|file| file.path == "caller.tcl")
            .expect("caller source is indexed");
        let call = document
            .occurrences
            .iter()
            .find(|occurrence| {
                occurrence.file == caller.id && occurrence.syntax_kind == "tcl.command.call"
            })
            .expect("cross-file command invocation is retained");
        assert!(matches!(
            &call.target,
            rootlight_ir::OccurrenceTarget::Candidates { symbols, .. }
                if symbols.contains(&shared.id)
        ));
    }

    #[test]
    fn tcl_substitution_calls_keep_exact_generation_bound_sources() {
        let fixture = TempDir::new().expect("fixture root exists");
        let source = "proc pulse {} {return ok}\nproc caller {} {\n  set value [pulse]\n  puts \"[pulse]\"\n  set escaped \\[pulse\\]\n  set literal {[pulse]}\n}\n";
        fs::write(fixture.path().join("commands.tcl"), source).expect("Tcl source writes");
        let cancellation = deadline();
        let mut service = FirstSliceService::new(2).expect("service initializes");
        let receipt = service
            .index_repository(fixture.path(), &cancellation)
            .expect("Tcl source indexes");
        let snapshot = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("generation remains loaded");
        let document = snapshot.document();
        let pulse = document
            .entities
            .iter()
            .find(|entity| entity.language == "tcl" && entity.canonical_name == "pulse")
            .expect("procedure is indexed");
        let calls = document
            .occurrences
            .iter()
            .filter(|occurrence| {
                let span = occurrence.source.span();
                occurrence.syntax_kind == "tcl.command.call"
                    && source.as_bytes().get(
                        usize::try_from(span.start_byte()).expect("span fits")
                            ..usize::try_from(span.end_byte()).expect("span fits"),
                    ) == Some(b"pulse".as_slice())
            })
            .collect::<Vec<_>>();
        assert_eq!(calls.len(), 2);
        for call in &calls {
            assert_eq!(call.source.generation(), receipt.generation);
            assert!(matches!(
                &call.target,
                rootlight_ir::OccurrenceTarget::Candidates { symbols, .. }
                    if symbols.contains(&pulse.id)
            ));
        }
        let read = service
            .source_read(
                receipt.generation,
                calls.iter().map(|call| call.source.clone()).collect(),
                &cancellation,
            )
            .expect("both substitutions retain exact source");
        assert_eq!(read.data.chunks.len(), 2);
        for (call, chunk) in calls.into_iter().zip(&read.data.chunks) {
            assert_eq!(chunk.reference, call.source);
            let start = usize::try_from(call.source.span().start_byte() - chunk.start_byte)
                .expect("selected start fits");
            assert_eq!(
                chunk.bytes.get(start..start + b"pulse".len()),
                Some(b"pulse".as_slice())
            );
        }
    }

    #[test]
    fn agda_declarations_are_source_backed_and_literate_prose_is_not_code() {
        let fixture = TempDir::new().expect("fixture root exists");
        let source = "{-# OPTIONS --safe #-}\nopen import Prelude\nmodule Sample where\n{- module Ghost where -}\n_∙_ : Nat → Nat → Nat\n_∙_ x y = x\ndata Choice : Set where\n  yes : Choice\nrecord Pair : Set where\n  field left : Nat\n";
        let literate =
            "module Prose where\n```agda\nmodule Literate where\nanswer : Nat\nanswer = 42\n```\n";
        fs::write(fixture.path().join("Sample.agda"), source).expect("Agda source writes");
        fs::write(fixture.path().join("Literate.lagda.md"), literate)
            .expect("literate source writes");
        let cancellation = deadline();
        let mut service = FirstSliceService::new(2).expect("service initializes");
        let receipt = service
            .index_repository(fixture.path(), &cancellation)
            .expect("Agda source indexes");
        let snapshot = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("generation remains loaded");
        let document = snapshot.document();
        for (name, kind) in [
            ("Sample", EntityKind::Module),
            ("_∙_", EntityKind::Function),
            ("Choice", EntityKind::Enum),
            ("Pair", EntityKind::Struct),
            ("Literate", EntityKind::Module),
            ("answer", EntityKind::Function),
        ] {
            assert!(
                document.entities.iter().any(|entity| {
                    entity.language == "agda"
                        && entity.kind == kind
                        && entity.canonical_name == name
                }),
                "missing {name}"
            );
        }
        assert!(
            !document
                .entities
                .iter()
                .any(|entity| entity.canonical_name == "Ghost" || entity.canonical_name == "Prose")
        );
        assert!(document.skipped_regions.iter().any(|gap| {
            gap.detail == "agda-layout-and-expression-semantics-partial"
                && gap.source.generation() == receipt.generation
        }));
        let file = document
            .files
            .iter()
            .find(|file| file.path == "Sample.agda")
            .expect("Agda file exists");
        let read = service
            .source_read(
                receipt.generation,
                vec![
                    file.evidence
                        .source
                        .clone()
                        .expect("generation-bound source"),
                ],
                &cancellation,
            )
            .expect("Agda source remains readable");
        assert_eq!(read.data.chunks[0].bytes, source.as_bytes());
        let located = service
            .code_locate(
                receipt.generation,
                "_∙_".to_owned(),
                LocateMode::Exact,
                10,
                0,
                &cancellation,
            )
            .expect("Agda symbol is locatable");
        assert!(located.data.hits.iter().any(|hit| {
            hit.path == "Sample.agda" && hit.language == "agda" && hit.symbol.is_some()
        }));
        let status = service
            .repository_status(receipt.repository, Some(receipt.generation))
            .expect("Agda coverage resolves");
        assert!(status.coverage.iter().any(|entry| {
            entry.language == "agda"
                && entry.discovered_files == 2
                && entry.indexed_files == 2
                && entry.status == "bounded"
        }));
    }

    #[test]
    fn agda_layout_preserves_nested_owners_and_distinct_names() {
        let fixture = TempDir::new().expect("fixture root exists");
        let source = "module Main where\n  module Left where\n    same : Nat\n    same = 1\n  module Right where\n    same : Nat\n    same = 2\n  data Choice : Set where\n    yes no : Choice\n  record Pair : Set where\n    constructor mkPair\n    field\n      left right : Nat\n    swap : Pair\n    swap = mkPair right left\n  private\n    hidden : Nat\n  top : Nat\n  top = 0 where\n    local : Nat\n    local = 1\n  another : Nat\n  another = local\n    where\n      local : Nat\n      local = 2\n";
        fs::write(fixture.path().join("Main.agda"), source).expect("Agda source writes");
        let cancellation = deadline();
        let mut service = FirstSliceService::new(2).expect("service initializes");
        let receipt = service
            .index_repository(fixture.path(), &cancellation)
            .expect("nested Agda source indexes");
        let snapshot = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("generation remains loaded");
        let document = snapshot.document();
        let entity = |qualified: &str, kind: EntityKind| {
            document
                .entities
                .iter()
                .find(|entity| {
                    entity.language == "agda"
                        && entity.qualified_name == qualified
                        && entity.kind == kind
                })
                .unwrap_or_else(|| panic!("missing {qualified}"))
        };
        let choice = entity("Main::Choice", EntityKind::Enum);
        for name in ["yes", "no"] {
            let constructor = entity(&format!("Main::Choice::{name}"), EntityKind::Constructor);
            assert_eq!(
                constructor.container,
                Some(rootlight_ir::ContainerRef::Entity(choice.id))
            );
        }
        let pair = entity("Main::Pair", EntityKind::Struct);
        for name in ["left", "right"] {
            let field = entity(&format!("Main::Pair::{name}"), EntityKind::Field);
            assert_eq!(
                field.container,
                Some(rootlight_ir::ContainerRef::Entity(pair.id))
            );
        }
        entity("Main::Pair::mkPair", EntityKind::Constructor);
        entity("Main::Pair::swap", EntityKind::Method);
        entity("Main::Left::same", EntityKind::Function);
        entity("Main::Right::same", EntityKind::Function);
        entity("Main::hidden", EntityKind::Function);
        let top = entity("Main::top", EntityKind::Function);
        let local = entity("Main::top::local", EntityKind::Function);
        assert_eq!(
            local.container,
            Some(rootlight_ir::ContainerRef::Entity(top.id))
        );
        let another = entity("Main::another", EntityKind::Function);
        let nested_local = entity("Main::another::local", EntityKind::Function);
        assert_eq!(
            nested_local.container,
            Some(rootlight_ir::ContainerRef::Entity(another.id))
        );
        for (qualified, equation, other) in [
            ("Main::Left::same", "same = 1", "same = 2"),
            ("Main::Right::same", "same = 2", "same = 1"),
            ("Main::top::local", "local = 1", "local = 2"),
            ("Main::another::local", "local = 2", "local = 1"),
        ] {
            let reference = entity(qualified, EntityKind::Function)
                .evidence
                .source
                .clone()
                .expect("nested definition has generation-bound source");
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![reference],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0),
                    FirstSliceBudget::default(),
                    &cancellation,
                )
                .expect("nested definition source is readable");
            let body =
                std::str::from_utf8(&read.data.chunks[0].bytes).expect("Agda definition is UTF-8");
            assert!(body.contains(equation), "missing {equation} in {qualified}");
            assert!(!body.contains(other), "cross-scope source in {qualified}");
        }
        let located = service
            .code_locate(
                receipt.generation,
                "same".to_owned(),
                LocateMode::Exact,
                10,
                0,
                &cancellation,
            )
            .expect("both scoped names locate");
        assert_eq!(
            located
                .data
                .hits
                .iter()
                .filter(|hit| hit.language == "agda" && hit.symbol.is_some())
                .count(),
            2
        );
    }

    #[test]
    fn scss_declarations_have_exact_source_backed_identities() {
        let fixture = TempDir::new().expect("fixture root exists");
        let source = "$accent: #123456;\n@mixin card($radius) { border-radius: $radius; $local: $radius; }\n@function scale($value) { @return $value * 2; }\n/* $phantom: red; */\n.note { content: \"@mixin ghost {}\"; $nested: blue; color: $accent; }\n.first { $same: 1; }\n.second { $same: 2; }\n";
        fs::write(fixture.path().join("theme.scss"), source).expect("SCSS source writes");
        let mut service = FirstSliceService::new(2).expect("service initializes");
        let receipt = service
            .index_repository(fixture.path(), &deadline())
            .expect("SCSS source publishes");
        let generation = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("generation remains retained");
        let mut entities = generation
            .document()
            .entities
            .iter()
            .filter(|entity| entity.language == "scss" && entity.kind != EntityKind::StyleRule)
            .collect::<Vec<_>>();
        entities.sort_unstable_by_key(|entity| entity.canonical_name.as_str());
        assert_eq!(
            entities
                .iter()
                .map(|entity| (entity.canonical_name.as_str(), entity.kind))
                .collect::<Vec<_>>(),
            [
                ("accent", EntityKind::Variable),
                ("card", EntityKind::Function),
                ("local", EntityKind::Variable),
                ("nested", EntityKind::Variable),
                ("radius", EntityKind::Parameter),
                ("same", EntityKind::Variable),
                ("same", EntityKind::Variable),
                ("scale", EntityKind::Function),
                ("value", EntityKind::Parameter),
            ]
        );
        let scoped = entities
            .iter()
            .filter(|entity| entity.canonical_name == "same")
            .collect::<Vec<_>>();
        assert_ne!(scoped[0].id, scoped[1].id);
        for entity in entities {
            let reference = entity
                .evidence
                .source
                .clone()
                .expect("declaration retains source evidence");
            assert_eq!(reference.generation(), receipt.generation);
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![reference.clone()],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0)
                        .with_encoding(SourceEncoding::Bytes),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .expect("declaration source resolves");
            let span = reference.span();
            let expected = source
                .as_bytes()
                .get(
                    usize::try_from(span.start_byte()).unwrap()
                        ..usize::try_from(span.end_byte()).unwrap(),
                )
                .expect("declaration span is within source");
            assert_eq!(read.data.chunks[0].bytes, expected);
        }
        let coverage = service
            .repository_status(receipt.repository, None)
            .expect("repository status resolves");
        assert!(coverage.coverage.iter().any(|entry| {
            entry.language == "scss"
                && entry.discovered_files == 1
                && entry.indexed_files == 1
                && entry.status == "bounded"
        }));
        let gaps = service
            .coverage_gaps_until(receipt.repository, receipt.generation, &deadline())
            .expect("SCSS coverage gaps resolve");
        assert!(gaps.iter().any(|gap| {
            gap.language.as_deref() == Some("scss")
                && gap.reason == FirstSliceCoverageGapReason::Unsupported
                && gap.files == 1
        }));
    }

