    #[test]
    fn durable_long_symbol_names_preserve_source_and_embedded_language_gaps() {
        let fixture = durable_test_tempdir();
        let state = durable_test_tempdir();
        let rust_name = format!("rustLongName_{}_End", "x".repeat(520));
        let script_name = format!("scriptLongName_{}_End", "y".repeat(520));
        let rust_source = format!("pub fn {rust_name}() {{}}\n");
        let html_source = format!("<script>function {script_name}() {{}}</script>\n");
        write_language_fixture(
            fixture.path(),
            &[
                ("src/long.rs", &rust_source),
                ("src/embedded.html", &html_source),
                ("src/clean.rs", "pub fn ordinary() {}\n"),
            ],
        );
        let paths =
            RuntimePaths::new(state.path().join("state"), state.path().join("runtime")).unwrap();
        paths.prepare_owner().unwrap();
        let mut service =
            FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).unwrap();
        let receipt = service
            .index_repository(fixture.path(), &deadline())
            .unwrap();
        assert_eq!(
            service
                .index_repository(fixture.path(), &deadline())
                .unwrap(),
            receipt
        );
        let snapshot = service
            .loaded_generation_snapshot(receipt.generation)
            .unwrap();
        let expected = [&rust_name, &script_name].map(|name| {
            snapshot
                .document()
                .entities
                .iter()
                .find(|entity| entity.canonical_name == *name)
                .unwrap()
                .clone()
        });
        drop(snapshot);
        drop(service);
        let restored = FirstSliceService::new_durable(3, paths.state_dir(), &deadline()).unwrap();
        assert_eq!(
            restored
                .generation_freshness(receipt.repository, receipt.generation)
                .unwrap(),
            FirstSliceFreshnessStatus {
                structural: FirstSliceObservedFreshness::CurrentAtLastAuthoritativeScan,
                semantic: FirstSliceObservedFreshness::PendingSemanticRefinement,
                publication: FirstSlicePublicationMode::DurableSingleStage,
                two_stage: FirstSliceTwoStageAvailability::UnavailableWithoutSemanticRefinement,
            }
        );
        for (entity, prefix, language, path) in [
            (&expected[0], "rustLongName", "rust", "src/long.rs"),
            (
                &expected[1],
                "scriptLongName",
                "javascript",
                "src/embedded.html",
            ),
        ] {
            for (query, mode) in [
                (prefix.to_owned(), LocateMode::Prefix),
                (format!("{prefix}*End"), LocateMode::Glob),
                (format!("{prefix}.*End"), LocateMode::SafeRegex),
            ] {
                let located = restored
                    .code_locate(receipt.generation, query, mode, 10, 0, &deadline())
                    .unwrap();
                let hit = located
                    .data
                    .hits
                    .iter()
                    .find(|hit| hit.symbol == Some(entity.id))
                    .unwrap();
                assert_eq!(hit.identifier, entity.display_name);
                assert_eq!(hit.qualified_name, entity.qualified_name);
                assert_eq!(hit.source, entity.evidence.source);
                let source = hit.source.clone().unwrap();
                assert_eq!(source.generation(), receipt.generation);
                let read = restored
                    .source_read_with_options_and_budget(
                        receipt.generation,
                        vec![source],
                        SourceReadOptions::new()
                            .with_context_lines_before(0)
                            .with_context_lines_after(0),
                        FirstSliceBudget::default(),
                        &deadline(),
                    )
                    .unwrap();
                assert!(
                    String::from_utf8(read.data.chunks[0].bytes.clone())
                        .unwrap()
                        .contains(&entity.display_name)
                );
            }
            let gaps = restored
                .coverage_gap_summary_for_paths_until(
                    receipt.repository,
                    receipt.generation,
                    &[language.to_owned()],
                    &[path.to_owned()],
                    &deadline(),
                )
                .unwrap();
            assert!(
                gaps.gaps
                    .iter()
                    .any(|gap| gap.reason == FirstSliceCoverageGapReason::Truncated
                        && gap.language.as_deref() == Some(language)),
                "{gaps:?}"
            );
            assert_eq!(gaps.skipped_inputs, 1);
            assert!(gaps.incomplete);
            assert_eq!(gaps.gaps.len(), 2);
            assert!(gaps.gaps.iter().any(|gap| {
                gap.reason == FirstSliceCoverageGapReason::Stale
                    && gap.language.is_none()
                    && gap.files == receipt.indexed_files
            }));
        }
        let clean = restored
            .coverage_gap_summary_for_paths_until(
                receipt.repository,
                receipt.generation,
                &["rust".to_owned()],
                &["src/clean.rs".to_owned()],
                &deadline(),
            )
            .unwrap();
        // This structural-only constructor does not certify project semantics.
        assert_eq!(
            clean.gaps,
            vec![FirstSliceCoverageGap {
                reason: FirstSliceCoverageGapReason::Stale,
                language: None,
                files: receipt.indexed_files,
            }]
        );
        assert_eq!(clean.skipped_inputs, 0);
        assert!(!clean.incomplete);
    }

    #[test]
    fn parser_artifact_dependencies_distinguish_analyzer_and_search_revisions() {
        let cancellation = Cancellation::new();
        let limits = PlanningLimits::default();
        let repository = RepositoryId::from_bytes([1; 16]);
        let file = FileId::from_bytes([2; 20]);
        let provider = derive_fact("incremental-provider", INCREMENTAL_PROVIDER_SEED).id();
        let adapter_key = InputKey::AdapterVersion(provider);
        let grammar = first_slice_grammar_revision_hash().unwrap();

        // A lexical migration changes generation identity, not parser dependencies.
        let previous_parser = hash_static_components(&[
            PARSER_PROVIDER_SET_SEED,
            TREE_SITTER_ADAPTER_VERSION.as_bytes(),
            TREE_SITTER_RUNTIME_VERSION.as_bytes(),
            ANALYZER_BINARY_SEED,
            grammar.as_bytes(),
        ])
        .unwrap();
        let current_parser = first_slice_parser_provider_hash().unwrap();
        let previous = InputSnapshot::new(
            [
                InputFingerprint::new(
                    InputKey::FileContent(file),
                    content_hash(b"fixture-content"),
                ),
                InputFingerprint::new(InputKey::FilePath(file), content_hash(b"fixture-path")),
                InputFingerprint::new(
                    InputKey::FileParserRoute(file),
                    content_hash(b"fixture-parser-route"),
                ),
                InputFingerprint::new(
                    InputKey::GrammarVersion(
                        derive_fact("rootlight.first-slice.grammar-input", GRAMMAR_REVISION_SEED)
                            .id(),
                    ),
                    grammar,
                ),
                InputFingerprint::new(adapter_key, previous_parser),
                InputFingerprint::new(
                    InputKey::ResolverVersion,
                    content_hash(RESOLVER_BINARY_SEED),
                ),
                InputFingerprint::new(
                    InputKey::ConfigurationRevision,
                    content_hash(b"fixture-configuration"),
                ),
                InputFingerprint::new(
                    InputKey::SearchRevision,
                    content_hash(b"rootlight.first-slice.search-schema/6"),
                ),
            ],
            limits,
            &cancellation,
        )
        .unwrap();
        let current = InputSnapshot::new(
            previous.iter().map(|input| match input.key() {
                key if key == adapter_key => InputFingerprint::new(key, current_parser),
                InputKey::SearchRevision => InputFingerprint::new(
                    InputKey::SearchRevision,
                    content_hash(SEARCH_REVISION_SEED),
                ),
                _ => input,
            }),
            limits,
            &cancellation,
        )
        .unwrap();
        let keys = incremental_input_keys(&previous, &current, &cancellation).unwrap();
        let files = BTreeSet::from([file]);
        let passes = first_slice_passes().unwrap();
        let (nodes, edges) =
            first_slice_dependency_parts(repository, &files, &keys, &passes, &cancellation)
                .unwrap();
        let search = *nodes
            .iter()
            .find(|node| node.domain() == FactDomain::Search)
            .unwrap();
        let graph_limits = GraphLimits::new(5, nodes.len(), edges.len()).unwrap();
        let registry =
            DependencyRegistry::new(passes.declarations().unwrap(), graph_limits, &cancellation)
                .unwrap();
        verify_first_slice_observations(&registry, &passes).unwrap();
        let graph =
            DependencyGraph::new(nodes, edges, &registry, graph_limits, &cancellation).unwrap();

        let artifact_id = parser_artifact_id(file);
        let artifact = ArtifactSummary::new(
            artifact_id,
            [FactNode::new(file_analysis_unit(file), FactDomain::Syntax)],
            previous
                .iter()
                .filter(|input| parser_artifact_depends_on(input.key(), file)),
            limits,
            &cancellation,
        )
        .unwrap();
        let parent = GenerationSummary::new(previous, [artifact], limits, &cancellation).unwrap();
        let plan = plan_invalidation(&parent, &current, &graph, limits, &cancellation).unwrap();
        assert_eq!(
            plan.changes()
                .changes()
                .iter()
                .map(|change| change.key())
                .collect::<Vec<_>>(),
            vec![InputKey::SearchRevision]
        );
        assert_eq!(plan.invalidated_nodes().collect::<Vec<_>>(), vec![search]);
        assert!(plan.fallback().is_none());
        assert_eq!(plan.artifact_decisions().len(), 1);
        assert_eq!(plan.artifact_decisions()[0].artifact(), artifact_id);
        assert_eq!(
            plan.artifact_decisions()[0].kind(),
            ArtifactDecisionKind::Reuse
        );
        let retained_dependencies = parent
            .artifacts()
            .next()
            .unwrap()
            .dependencies()
            .collect::<Vec<_>>();
        assert_eq!(retained_dependencies.len(), 6);
        assert_eq!(
            retained_dependencies,
            current
                .iter()
                .filter(|input| parser_artifact_depends_on(input.key(), file))
                .collect::<Vec<_>>()
        );
        assert_eq!(current_parser, previous_parser);

        let previous_provider_set = hash_static_components(&[
            PROVIDER_SET_SEED,
            previous_parser.as_bytes(),
            DISCOVERY_MANIFEST_VERSION.as_bytes(),
            RESOLVER_PROVIDER_VERSION.as_bytes(),
            RESOLVER_BINARY_SEED,
            b"rootlight.first-slice.search-schema/6",
            INCREMENTAL_SCHEMA_VERSION.as_bytes(),
            DERIVED_PLAN_REVISION_SEED,
            LANGUAGE_DISPOSITION_PROVIDER_SEED,
            SOURCE_FILE_FALLBACK_PROVIDER_SEED,
            container_sources::REVISION,
        ])
        .unwrap();
        assert_ne!(
            first_slice_provider_set_hash().unwrap(),
            previous_provider_set
        );

        let stale_parser = hash_static_components(&[
            PARSER_PROVIDER_SET_SEED,
            TREE_SITTER_ADAPTER_VERSION.as_bytes(),
            TREE_SITTER_RUNTIME_VERSION.as_bytes(),
            b"rootlight.first-slice.treesitter-structural/270",
            grammar.as_bytes(),
        ])
        .unwrap();
        let stale_inputs = InputSnapshot::new(
            current.iter().map(|input| {
                if input.key() == adapter_key {
                    InputFingerprint::new(adapter_key, stale_parser)
                } else {
                    input
                }
            }),
            limits,
            &cancellation,
        )
        .unwrap();
        let stale_artifact = ArtifactSummary::new(
            artifact_id,
            [FactNode::new(file_analysis_unit(file), FactDomain::Syntax)],
            stale_inputs
                .iter()
                .filter(|input| parser_artifact_depends_on(input.key(), file)),
            limits,
            &cancellation,
        )
        .unwrap();
        let stale_parent =
            GenerationSummary::new(stale_inputs, [stale_artifact], limits, &cancellation).unwrap();
        let analyzer_plan =
            plan_invalidation(&stale_parent, &current, &graph, limits, &cancellation).unwrap();
        assert_eq!(
            analyzer_plan
                .changes()
                .changes()
                .iter()
                .map(|change| change.key())
                .collect::<Vec<_>>(),
            vec![adapter_key]
        );
        assert!(
            analyzer_plan
                .invalidated_nodes()
                .any(|node| node == FactNode::new(file_analysis_unit(file), FactDomain::Syntax))
        );
        assert!(analyzer_plan.fallback().is_none());
        assert_eq!(analyzer_plan.artifact_decisions().len(), 1);
        assert_eq!(
            analyzer_plan.artifact_decisions()[0].artifact(),
            artifact_id
        );
        assert_eq!(
            analyzer_plan.artifact_decisions()[0].kind(),
            ArtifactDecisionKind::Rebuild
        );

        let stale_resolver_inputs = InputSnapshot::new(
            current.iter().map(|input| {
                if input.key() == InputKey::ResolverVersion {
                    InputFingerprint::new(
                        InputKey::ResolverVersion,
                        content_hash(b"rootlight.first-slice.resolve/112"),
                    )
                } else {
                    input
                }
            }),
            limits,
            &cancellation,
        )
        .unwrap();
        let resolver_artifact = ArtifactSummary::new(
            artifact_id,
            [FactNode::new(file_analysis_unit(file), FactDomain::Syntax)],
            stale_resolver_inputs
                .iter()
                .filter(|input| parser_artifact_depends_on(input.key(), file)),
            limits,
            &cancellation,
        )
        .unwrap();
        let resolver_parent = GenerationSummary::new(
            stale_resolver_inputs,
            [resolver_artifact],
            limits,
            &cancellation,
        )
        .unwrap();
        let resolver_plan =
            plan_invalidation(&resolver_parent, &current, &graph, limits, &cancellation).unwrap();
        assert_eq!(
            resolver_plan
                .changes()
                .changes()
                .iter()
                .map(|change| change.key())
                .collect::<Vec<_>>(),
            vec![InputKey::ResolverVersion]
        );
        assert_eq!(
            resolver_plan
                .invalidated_nodes()
                .map(|node| node.domain())
                .collect::<BTreeSet<_>>(),
            BTreeSet::from([
                FactDomain::Resolution,
                FactDomain::DerivedGraph,
                FactDomain::Search
            ])
        );
        assert!(resolver_plan.fallback().is_none());
        assert_eq!(resolver_plan.artifact_decisions().len(), 1);
        assert_eq!(
            resolver_plan.artifact_decisions()[0].artifact(),
            artifact_id
        );
        assert_eq!(
            resolver_plan.artifact_decisions()[0].kind(),
            ArtifactDecisionKind::Reuse
        );
    }

    #[test]
    fn preceding_structural_and_resolver_revisions_invalidate_cache_contexts() {
        let cancellation = Cancellation::new();
        let limits = PlanningLimits::default();
        let repository = RepositoryId::from_bytes([1; 16]);
        let file = FileId::from_bytes([2; 20]);
        let provider = derive_fact("incremental-provider", INCREMENTAL_PROVIDER_SEED).id();
        let adapter_key = InputKey::AdapterVersion(provider);
        let grammar = first_slice_grammar_revision_hash().unwrap();
        let previous_parser = |revision: &[u8]| {
            hash_static_components(&[
                PARSER_PROVIDER_SET_SEED,
                TREE_SITTER_ADAPTER_VERSION.as_bytes(),
                TREE_SITTER_RUNTIME_VERSION.as_bytes(),
                revision,
                grammar.as_bytes(),
            ])
            .unwrap()
        };
        let current = InputSnapshot::new(
            [
                InputFingerprint::new(
                    InputKey::FileContent(file),
                    content_hash(b"unchanged-content"),
                ),
                InputFingerprint::new(InputKey::FilePath(file), content_hash(b"unchanged-path")),
                InputFingerprint::new(adapter_key, first_slice_parser_provider_hash().unwrap()),
                InputFingerprint::new(
                    InputKey::ResolverVersion,
                    content_hash(RESOLVER_BINARY_SEED),
                ),
            ],
            limits,
            &cancellation,
        )
        .unwrap();
        let keys = incremental_input_keys(&current, &current, &cancellation).unwrap();
        let passes = first_slice_passes().unwrap();
        let (nodes, edges) = first_slice_dependency_parts(
            repository,
            &BTreeSet::from([file]),
            &keys,
            &passes,
            &cancellation,
        )
        .unwrap();
        let graph_limits = GraphLimits::new(5, nodes.len(), edges.len()).unwrap();
        let registry =
            DependencyRegistry::new(passes.declarations().unwrap(), graph_limits, &cancellation)
                .unwrap();
        verify_first_slice_observations(&registry, &passes).unwrap();
        let graph =
            DependencyGraph::new(nodes, edges, &registry, graph_limits, &cancellation).unwrap();
        let artifact_id = parser_artifact_id(file);
        let summary = |inputs: InputSnapshot| {
            let artifact = ArtifactSummary::new(
                artifact_id,
                [FactNode::new(file_analysis_unit(file), FactDomain::Syntax)],
                inputs
                    .iter()
                    .filter(|input| parser_artifact_depends_on(input.key(), file)),
                limits,
                &cancellation,
            )
            .unwrap();
            GenerationSummary::new(inputs, [artifact], limits, &cancellation).unwrap()
        };
        let unchanged = summary(current.clone());
        let reuse = plan_invalidation(&unchanged, &current, &graph, limits, &cancellation).unwrap();
        assert!(reuse.changes().changes().is_empty());
        assert_eq!(reuse.invalidated_nodes().count(), 0);
        assert_eq!(reuse.artifact_decisions().len(), 1);
        assert_eq!(
            reuse.artifact_decisions()[0].kind(),
            ArtifactDecisionKind::Reuse
        );
        for (changed_key, previous, expected_decision) in [
            (
                adapter_key,
                previous_parser(b"rootlight.first-slice.treesitter-structural/292"),
                ArtifactDecisionKind::Rebuild,
            ),
            (
                adapter_key,
                previous_parser(b"rootlight.first-slice.treesitter-structural/293"),
                ArtifactDecisionKind::Rebuild,
            ),
            (
                InputKey::ResolverVersion,
                content_hash(b"rootlight.first-slice.resolve/123"),
                ArtifactDecisionKind::Reuse,
            ),
            (
                InputKey::ResolverVersion,
                content_hash(b"rootlight.first-slice.resolve/124"),
                ArtifactDecisionKind::Reuse,
            ),
        ] {
            let previous_inputs = InputSnapshot::new(
                current.iter().map(|input| {
                    if input.key() == changed_key {
                        InputFingerprint::new(changed_key, previous)
                    } else {
                        input
                    }
                }),
                limits,
                &cancellation,
            )
            .unwrap();
            let parent = summary(previous_inputs);
            let plan = plan_invalidation(&parent, &current, &graph, limits, &cancellation).unwrap();
            assert_eq!(
                plan.changes()
                    .changes()
                    .iter()
                    .map(|change| change.key())
                    .collect::<Vec<_>>(),
                vec![changed_key]
            );
            assert!(plan.fallback().is_none());
            assert_eq!(plan.artifact_decisions().len(), 1);
            assert_eq!(plan.artifact_decisions()[0].artifact(), artifact_id);
            assert_eq!(plan.artifact_decisions()[0].kind(), expected_decision);
            if changed_key == adapter_key {
                assert!(plan.invalidated_nodes().any(|node| {
                    node == FactNode::new(file_analysis_unit(file), FactDomain::Syntax)
                }));
            } else {
                assert_eq!(
                    plan.invalidated_nodes()
                        .map(|node| node.domain())
                        .collect::<BTreeSet<_>>(),
                    BTreeSet::from([
                        FactDomain::Resolution,
                        FactDomain::DerivedGraph,
                        FactDomain::Search,
                    ])
                );
            }
        }
    }

    #[test]
    fn preceding_project_provider_revision_changes_both_deep_contexts() {
        let unavailable = FirstSliceService::new(2).expect("structural service initializes");
        let project_identity = content_hash(b"unchanged-project-analyzer");
        let configured = FirstSliceService::new_with_storage(
            2,
            MAX_RETAINED_SOURCE_BYTES,
            None,
            Some(Arc::new(FailingProjectAnalyzer {
                identity: project_identity,
                error: FirstSliceProjectAnalysisError::Analysis,
                calls: Arc::new(AtomicUsize::new(0)),
            })),
        )
        .expect("configured project service initializes");
        let contexts: [(&FirstSliceService, &[u8]); 2] = [
            (&unavailable, b"unavailable"),
            (&configured, project_identity.as_bytes()),
        ];
        for (service, project) in contexts {
            let structural = service
                .provider_set_hash(FirstSliceIndexMode::Structural)
                .expect("structural context derives");
            let current = service
                .provider_set_hash(FirstSliceIndexMode::Deep)
                .expect("deep context derives");
            assert_eq!(
                current,
                hash_static_components(&[
                    PROJECT_PROVIDER_SET_SEED,
                    structural.as_bytes(),
                    project
                ])
                .expect("current project recipe derives")
            );
            for revision in [
                b"rootlight.first-slice.project-provider/16".as_slice(),
                b"rootlight.first-slice.project-provider/17",
            ] {
                let previous = hash_static_components(&[revision, structural.as_bytes(), project])
                    .expect("preceding project context derives");
                assert_ne!(current, previous);
            }
        }
        assert_eq!(
            unavailable
                .provider_set_hash(FirstSliceIndexMode::Structural)
                .unwrap(),
            configured
                .provider_set_hash(FirstSliceIndexMode::Structural)
                .unwrap()
        );
    }

