    #[test]
    fn groovy_qualified_type_precedence_matches_compilation_units() {
        use rootlight_ir::{
            EntityKind, OccurrenceRole, OccurrenceTarget, RelationEndpoint, RelationPredicate,
        };

        let imported = "package sample\nclass Widget { static class Inner {} }\n";
        for (source, companion, written, target_name, target_path) in [
            (
                "import sample.Widget as Selected\nclass Holder<Selected> { Selected.Inner item }",
                imported,
                "Selected.Inner",
                "Inner",
                "definition.groovy",
            ),
            (
                "import sample.Widget as Selected\nclass Selected { static class Inner {} }\nclass Holder { Selected.Inner item }",
                imported,
                "Selected.Inner",
                "Inner",
                "definition.groovy",
            ),
            (
                "import sample.Widget as Selected\nclass Holder { static class Selected { static class Inner {} }\nSelected.Inner item }",
                imported,
                "Selected.Inner",
                "Inner",
                "definition.groovy",
            ),
            (
                "import sample.Widget as Selected\nclass Parent { static class Selected { static class Inner {} } }\nclass Holder extends Parent { Selected.Inner item }",
                imported,
                "Selected.Inner",
                "Inner",
                "definition.groovy",
            ),
            (
                "package sample\nimport other.Widget as sample\nclass Local {}\nclass Holder { sample.Local item }",
                "package other\nclass Widget { static class Local {} }",
                "sample.Local",
                "Local",
                "client.groovy",
            ),
            (
                "package sample\nclass Local {}\nclass Holder { sample.Local item }",
                "",
                "sample.Local",
                "Local",
                "client.groovy",
            ),
        ] {
            let fixture = TempDir::new().unwrap();
            fs::write(fixture.path().join("client.groovy"), source).unwrap();
            if !companion.is_empty() {
                fs::write(fixture.path().join("definition.groovy"), companion).unwrap();
            }
            let mut service = FirstSliceService::new(2).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            assert!(
                document.diagnostics.is_empty(),
                "{source}: {:?}",
                document.diagnostics
            );
            let target_file = document
                .files
                .iter()
                .find(|file| file.path == target_path)
                .unwrap()
                .id;
            let target = document
                .entities
                .iter()
                .find(|entity| {
                    entity.kind == EntityKind::Class
                        && entity.canonical_name == target_name
                        && entity.evidence.source.as_ref().unwrap().span().file() == target_file
                })
                .unwrap();
            let start = u64::try_from(source.find(written).unwrap()).unwrap();
            let site = document
                .occurrences
                .iter()
                .find(|site| {
                    site.syntax_kind == "groovy.qualified_type.reference"
                        && site.source.span().start_byte() == start
                })
                .unwrap();
            assert_eq!(
                site.target,
                OccurrenceTarget::Resolved { symbol: target.id },
                "{source}"
            );
            assert_eq!(site.role, OccurrenceRole::TypeUse);
            assert!(document.relations.iter().any(|relation| {
                relation.predicate == RelationPredicate::UsesType
                    && relation.subject == RelationEndpoint::Occurrence(site.id)
                    && relation.object == RelationEndpoint::Entity(target.id)
            }));
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![site.source.clone()],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .unwrap();
            assert_eq!(read.data.chunks[0].bytes, written.as_bytes());
        }
    }

    #[test]
    fn groovy_local_qualified_types_preserve_definition_ownership() {
        use rootlight_ir::{OccurrenceRole, OccurrenceTarget, RelationEndpoint, RelationPredicate};

        for (source, written, definition) in [
            (
                "class Outer { static class Inner {} }\nclass Holder { Outer.Inner item }",
                "Outer.Inner",
                "class Inner",
            ),
            (
                "package sample\nclass Outer { static class Inner {} }\nclass Holder { Outer.Inner item }",
                "Outer.Inner",
                "class Inner",
            ),
            (
                "package sample\nclass Outer { static class Inner {} }\nclass Holder { sample.Outer.Inner item }",
                "sample.Outer.Inner",
                "class Inner",
            ),
            (
                "class Holder { static class Outer { static class Inner {} }\nOuter.Inner item }",
                "Outer.Inner",
                "class Inner",
            ),
            (
                "class Outer { static class Inner {}\nstatic class Holder { Outer.Inner item } }",
                "Outer.Inner",
                "class Inner",
            ),
            (
                "class Outer { static class Inner {} }\nclass Holder<Outer> { Outer.Inner item }",
                "Outer.Inner",
                "class Inner",
            ),
            (
                "class Outer { static class Middle { static class Inner {} }\nstatic class Holder { Middle.Inner item } }",
                "Middle.Inner",
                "class Inner",
            ),
            (
                "class Outer { static class Inner {} }\nclass Holder { static class Outer { static class Inner {} }\nOuter.Inner item }",
                "Outer.Inner",
                "class Holder { static class Outer { static class Inner",
            ),
            (
                "class Outer { static class Inner {} }\nclass Holder { static class Outer {}\nOuter.Inner item }",
                "Outer.Inner",
                "class Inner",
            ),
            (
                "class Root { static class Outer { static class Inner {} }\nstatic class Middle { static class Outer { static class Inner {} }\nstatic class Holder { Outer.Inner item } } }",
                "Outer.Inner",
                "class Inner",
            ),
            (
                "class Outer { static class Holder { Outer.Holder item } }",
                "Outer.Holder",
                "class Holder",
            ),
            (
                "class Outer { static class Middle { static class Inner {} } }\nclass Holder { Outer.Middle.Inner item }",
                "Outer.Middle.Inner",
                "class Inner",
            ),
            (
                "class Outer { static class Inner {} }\nclass Holder { Outer /* gap */ . Inner[] item }",
                "Outer /* gap */ . Inner",
                "class Inner",
            ),
            (
                "class Δέντρο { static class Κλάδος {} }\nclass Holder { Δέντρο.Κλάδος item }",
                "Δέντρο.Κλάδος",
                "class Κλάδος",
            ),
            (
                "package sample\nclass Outer { static class Inner {} }\nclass Holder { static class Outer { static class Inner {} }\nsample.Outer.Inner item }",
                "sample.Outer.Inner",
                "class Inner",
            ),
        ] {
            let fixture = TempDir::new().unwrap();
            fs::write(fixture.path().join("client.groovy"), source).unwrap();
            let mut service = FirstSliceService::new(2).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            assert!(
                document.diagnostics.is_empty(),
                "{source}: {:?}",
                document.diagnostics
            );
            let definition_start = u64::try_from(
                source.find(definition).unwrap() + definition.rfind(' ').unwrap() + 1,
            )
            .unwrap();
            let declaration = document
                .occurrences
                .iter()
                .find(|site| {
                    site.role == OccurrenceRole::Definition
                        && site.source.span().start_byte() == definition_start
                })
                .unwrap();
            let OccurrenceTarget::Resolved { symbol } = declaration.target else {
                panic!("definition has no identity")
            };
            let site = document
                .occurrences
                .iter()
                .find(|site| {
                    site.syntax_kind == "groovy.qualified_type.reference"
                        && site.source.span().start_byte()
                            == u64::try_from(source.find(written).unwrap()).unwrap()
                })
                .unwrap();
            assert_eq!(
                site.target,
                OccurrenceTarget::Resolved { symbol },
                "{source}"
            );
            assert_eq!(site.role, OccurrenceRole::TypeUse);
            assert!(
                document
                    .relations
                    .iter()
                    .any(|relation| relation.predicate == RelationPredicate::UsesType
                        && relation.subject == RelationEndpoint::Occurrence(site.id)
                        && relation.object == RelationEndpoint::Entity(symbol))
            );
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![site.source.clone()],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .unwrap();
            assert_eq!(read.data.chunks[0].bytes, written.as_bytes());
        }
    }

