    #[test]
    fn groovy_type_imports_recompute_targets_when_declarations_change() {
        use rootlight_ir::{OccurrenceTarget, RelationPredicate};

        let fixture = TempDir::new().unwrap();
        fs::write(
            fixture.path().join("client.groovy"),
            "import sample.Widget\nclass Holder { Widget item }\n",
        )
        .unwrap();
        let definition = "package sample\nclass Widget {}\n";
        let mut service = FirstSliceService::new(3).unwrap();
        let mut prior = None;
        for (path, source, resolved, parsed) in [
            ("definition.groovy", Some(definition), true, 2),
            (
                "definition.groovy",
                Some("package elsewhere\nclass Widget {}\n"),
                false,
                1,
            ),
            ("definition.groovy", Some(definition), true, 1),
            ("duplicate.groovy", Some(definition), false, 1),
            ("duplicate.groovy", None, true, 0),
            ("definition.groovy", None, false, 0),
            ("definition.groovy", Some(definition), true, 1),
        ] {
            let path = fixture.path().join(path);
            if let Some(source) = source {
                fs::write(path, source).unwrap();
            } else {
                fs::remove_file(path).unwrap();
            }
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            if let Some(prior) = prior {
                assert_ne!(receipt.generation, prior);
                let work = service.incremental_evidence(receipt.generation).unwrap();
                assert_eq!(work.parsed_files(), parsed);
                assert!(
                    work.reused_parser_artifacts() >= 1,
                    "the unchanged importing file must be reused"
                );
            }
            prior = Some(receipt.generation);
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            let site = document
                .occurrences
                .iter()
                .find(|site| site.syntax_kind == "groovy.type_import.reference")
                .unwrap();
            assert_eq!(site.source.generation(), receipt.generation);
            assert_eq!(
                matches!(site.target, OccurrenceTarget::Resolved { .. }),
                resolved
            );
            let type_use = document
                .occurrences
                .iter()
                .find(|site| site.syntax_kind == "groovy.type_identifier.reference")
                .unwrap();
            assert_eq!(type_use.source.generation(), receipt.generation);
            assert_eq!(
                matches!(type_use.target, OccurrenceTarget::Resolved { .. }),
                resolved
            );
            if resolved {
                assert_eq!(type_use.target, site.target);
            }
            let uses: Vec<_> = document
                .relations
                .iter()
                .filter(|relation| relation.predicate == RelationPredicate::UsesType)
                .collect();
            assert_eq!(uses.len(), usize::from(resolved));
            if let OccurrenceTarget::Resolved { symbol } = type_use.target {
                assert_eq!(
                    uses[0].object,
                    rootlight_ir::RelationEndpoint::Entity(symbol)
                );
            }
            let relations: Vec<_> = document
                .relations
                .iter()
                .filter(|relation| relation.predicate == RelationPredicate::Imports)
                .collect();
            assert_eq!(relations.len(), usize::from(resolved));
            if let OccurrenceTarget::Resolved { symbol } = site.target {
                let target = document
                    .entities
                    .iter()
                    .find(|entity| entity.id == symbol)
                    .unwrap();
                let file = document
                    .files
                    .iter()
                    .find(|file| file.id == target.evidence.source.as_ref().unwrap().span().file())
                    .unwrap();
                assert_eq!(file.path, "definition.groovy");
                assert_eq!(
                    relations[0].object,
                    rootlight_ir::RelationEndpoint::Entity(symbol)
                );
            }
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![site.source.clone()],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .unwrap();
            assert_eq!(read.data.chunks[0].bytes, b"sample.Widget");
            drop(snapshot);
            assert_eq!(
                service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap()
                    .generation,
                receipt.generation
            );
            let prepared = service
                .prepare_repository_with_options(
                    fixture.path(),
                    FirstSliceIndexOptions::clean_rebuild(FirstSliceIndexMode::Structural),
                    &deadline(),
                )
                .unwrap();
            let clean = service
                .publish_prepared_with_metrics(prepared, &deadline())
                .unwrap();
            assert!(receipt.logical_snapshot.is_some());
            assert_eq!(clean.receipt().logical_snapshot, receipt.logical_snapshot);
        }
    }

    #[test]
    fn groovy_callable_metadata_tracks_headers_and_generation_reuse() {
        use rootlight_ir::{
            GROOVY_CALLABLE_NAMESPACE, GroovyCallableDispatch, decode_groovy_callable_envelope,
        };
        let fixture = TempDir::new().unwrap();
        fs::write(
            fixture.path().join("stable.groovy"),
            "class Stable { static def anchor() {} }",
        )
        .unwrap();
        let mut service = FirstSliceService::new(3).unwrap();
        let mut prior_generation = None;
        let mut prior_anchor = None;
        for (method, dispatch, count, required) in [
            (
                "static def fold(value = 1) { value }",
                GroovyCallableDispatch::Static,
                1,
                0,
            ),
            (
                "def fold(value) { value }",
                GroovyCallableDispatch::Instance,
                1,
                1,
            ),
            (
                "static def fold(value, extra = 1) { value }",
                GroovyCallableDispatch::Static,
                2,
                1,
            ),
            (
                "static def fold(value, extra = 1) { value + 1 }",
                GroovyCallableDispatch::Static,
                2,
                1,
            ),
        ] {
            fs::write(
                fixture.path().join("tools.groovy"),
                format!("class Tools {{ {method} }}\n"),
            )
            .unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(receipt.indexed_files, 2);
            if let Some(prior) = prior_generation {
                assert_ne!(receipt.generation, prior);
                let work = service.incremental_evidence(receipt.generation).unwrap();
                assert_eq!(work.parsed_files(), 1);
                assert!(work.reused_parser_artifacts() >= 1);
            }
            prior_generation = Some(receipt.generation);
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            assert!(
                document.diagnostics.is_empty(),
                "{:?}",
                document.diagnostics
            );
            let shapes: Vec<_> = document
                .extensions
                .iter()
                .filter(|envelope| envelope.namespace == GROOVY_CALLABLE_NAMESPACE)
                .collect();
            assert_eq!(shapes.len(), 2);
            let entity = document
                .entities
                .iter()
                .find(|entity| entity.canonical_name == "fold")
                .unwrap();
            let envelope = shapes
                .iter()
                .find(|envelope| envelope.evidence.source == entity.evidence.source)
                .unwrap();
            let shape = decode_groovy_callable_envelope(envelope).unwrap();
            assert_eq!(shape.dispatch, dispatch);
            assert_eq!(shape.parameter_count, count);
            assert_eq!(shape.required_parameter_count, required);
            let explained = service
                .symbol_explain(receipt.generation, entity.id, &deadline())
                .unwrap();
            assert_eq!(
                explained.data.entity.visibility,
                rootlight_ir::EntityVisibility::Public
            );
            let anchor = document
                .entities
                .iter()
                .find(|entity| entity.canonical_name == "anchor")
                .unwrap();
            let anchor_envelope = shapes
                .iter()
                .find(|envelope| envelope.evidence.source == anchor.evidence.source)
                .unwrap();
            let anchor_shape = decode_groovy_callable_envelope(anchor_envelope).unwrap();
            assert_eq!(
                anchor_envelope
                    .evidence
                    .source
                    .as_ref()
                    .unwrap()
                    .generation(),
                receipt.generation
            );
            if let Some(prior) = prior_anchor {
                assert_eq!(anchor_shape, prior);
            }
            prior_anchor = Some(anchor_shape);
            let reference = envelope.evidence.source.clone().unwrap();
            assert_eq!(reference.generation(), receipt.generation);
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![reference],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .unwrap();
            assert_eq!(read.data.chunks[0].bytes, method.as_bytes());
            drop(snapshot);
            assert_eq!(
                service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap()
                    .generation,
                receipt.generation
            );
            let clean = service
                .index_repository_with_options(
                    fixture.path(),
                    FirstSliceIndexOptions::clean_rebuild(FirstSliceIndexMode::Structural),
                    &deadline(),
                )
                .unwrap();
            assert!(receipt.logical_snapshot.is_some());
            assert_eq!(clean.logical_snapshot, receipt.logical_snapshot);
        }
    }

