    #[test]
    fn classic_variadic_calls_follow_parameter_edits_after_restart() {
        let fixture = durable_test_tempdir();
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        fs::write(fixture.path().join("project.vbp"), "Type=OleDll\nName=\"Primary\"\nClass=Collector; Collector.cls\nModule=Client; Client.bas\n").unwrap();
        let cases = [
            ("collector.Gather(1)", true),
            ("collector.Gather 1, 2, 3", true),
            ("Call collector.Gather(1, 2, 3)", true),
            ("collector.Gather(1, 2, 3)", true),
            ("collector.Gather(1,, 3)", true),
            ("collector.Gather()", false),
            ("collector.Gather(, 2)", false),
            ("collector.Gather(first:=1)", false),
            ("collector.Gather(1, items:=2)", false),
        ];
        let mut client = "Attribute VB_Name = \"Client\"\nSub Run(ByVal collector As Collector)\nDim result As Long\n".to_owned();
        for (expression, _) in cases {
            if expression.starts_with("Call ") || !expression.contains('(') {
                client.push_str(&format!("{expression}\n"));
            } else {
                client.push_str(&format!("result = {expression}\n"));
            }
        }
        client.push_str("End Sub\n");
        fs::write(fixture.path().join("Client.bas"), &client).unwrap();
        for (parameter, variadic) in [
            ("ParamArray items() As Variant", true),
            ("items As Variant", false),
            ("ParamArray items() As Variant", true),
        ] {
            let class = format!(
                "VERSION 1.0 CLASS\nAttribute VB_Name = \"Collector\"\nPublic Function Gather(ByVal first As Long, {parameter}) As Long\nEnd Function\n"
            );
            fs::write(fixture.path().join("Collector.cls"), &class).unwrap();
            let mut service =
                FirstSliceService::new_durable(2, paths.state_dir(), &deadline()).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(
                service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap(),
                receipt
            );
            drop(service);
            let service =
                FirstSliceService::new_durable(2, paths.state_dir(), &deadline()).unwrap();
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            let file = document
                .files
                .iter()
                .find(|file| file.path == "Client.bas")
                .unwrap();
            let target = document
                .entities
                .iter()
                .find(|entity| entity.canonical_name == "Gather")
                .unwrap();
            for (expression, valid) in cases {
                let expected = if variadic {
                    valid
                } else {
                    expression == "collector.Gather(1, items:=2)"
                };
                let start = if expression.starts_with("Call ") || !expression.contains('(') {
                    client.find(&format!("\n{expression}\n")).unwrap() + 1
                } else {
                    client.find(&format!("result = {expression}\n")).unwrap() + "result = ".len()
                };
                let start = u64::try_from(start).unwrap();
                let site = document
                    .occurrences
                    .iter()
                    .find(|site| {
                        site.file == file.id
                            && site.syntax_kind == "vba.application.reference"
                            && site.source.span().start_byte() == start
                            && site.source.span().end_byte()
                                == start + u64::try_from(expression.len()).unwrap()
                    })
                    .unwrap();
                assert_eq!(
                    site.target == OccurrenceTarget::Resolved { symbol: target.id },
                    expected,
                    "{parameter}: {expression}"
                );
                assert_eq!(
                    document
                        .skipped_regions
                        .iter()
                        .any(|gap| gap.source == site.source
                            && gap.detail == "vba-call-or-index-target-unavailable"),
                    !expected
                );
                assert!(
                    !document
                        .relations
                        .iter()
                        .any(|edge| edge.subject == RelationEndpoint::Occurrence(site.id)
                            && edge.predicate == RelationPredicate::Calls)
                );
                if expected {
                    let provenance = document
                        .provenance
                        .iter()
                        .find(|record| record.id == site.provenance)
                        .unwrap();
                    assert!(
                        provenance
                            .evidence_sources
                            .contains(target.evidence.source.as_ref().unwrap())
                    );
                    for formal in document.entities.iter().filter(|entity| {
                        entity.kind == EntityKind::Parameter
                            && entity.container == Some(ContainerRef::Entity(target.id))
                    }) {
                        assert!(
                            provenance
                                .evidence_sources
                                .contains(formal.evidence.source.as_ref().unwrap())
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn classic_project_qualified_exports_follow_visibility_and_collisions() {
        let fixture = durable_test_tempdir();
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let source = "Attribute VB_Name = \"Consumer\"\nSub Run(ByRef data As Primary.Payload, ByVal phase As Primary.Phase)\ndata.Count = 1\nEnd Sub\n";
        fs::write(fixture.path().join("Consumer.bas"), source).unwrap();
        for (access, collision, included, expected) in [
            ("Public", "", true, true),
            ("Private", "", true, false),
            (
                "Public",
                "Public Type Primary\nValue As Long\nEnd Type\n",
                true,
                false,
            ),
            (
                "Public",
                "Public Type Payload\nValue As Long\nEnd Type\nPublic Enum Phase\nReady = 1\nEnd Enum\n",
                true,
                false,
            ),
            ("Public", "", false, false),
            ("Public", "", true, true),
        ] {
            fs::write(fixture.path().join("Types.bas"), format!("Attribute VB_Name = \"Types\"\n{access} Type Payload\nCount As Long\nEnd Type\n{access} Enum Phase\nReady = 1\nEnd Enum\n")).unwrap();
            fs::write(
                fixture.path().join("Other.bas"),
                format!("Attribute VB_Name = \"Other\"\n{collision}"),
            )
            .unwrap();
            let target = if included {
                "Module=Types; Types.bas\n"
            } else {
                ""
            };
            fs::write(fixture.path().join("project.vbp"), format!("Type=OleDll\nName=\"Primary\"\n{target}Module=Consumer; Consumer.bas\nModule=Other; Other.bas\n")).unwrap();
            let mut service =
                FirstSliceService::new_durable(2, paths.state_dir(), &deadline()).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(
                receipt,
                service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap()
            );
            drop(service);
            let service =
                FirstSliceService::new_durable(2, paths.state_dir(), &deadline()).unwrap();
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            let document = snapshot.document();
            let consumer = document
                .files
                .iter()
                .find(|file| file.path == "Consumer.bas")
                .unwrap();
            let types = document
                .files
                .iter()
                .find(|file| file.path == "Types.bas")
                .unwrap();
            for (name, kind) in [("Payload", EntityKind::Struct), ("Phase", EntityKind::Enum)] {
                let path = format!("Primary.{name}");
                let start = u64::try_from(source.find(&path).unwrap()).unwrap();
                let site = document
                    .occurrences
                    .iter()
                    .find(|site| {
                        site.file == consumer.id
                            && site.source.span().start_byte() == start
                            && site.syntax_kind == "vba.direct_type_identifier.reference"
                    })
                    .unwrap();
                let target = document
                    .entities
                    .iter()
                    .find(|entity| {
                        entity.kind == kind
                            && entity.canonical_name == name
                            && entity
                                .evidence
                                .source
                                .as_ref()
                                .is_some_and(|source| source.span().file() == types.id)
                    })
                    .unwrap();
                assert_eq!(
                    site.target == OccurrenceTarget::Resolved { symbol: target.id },
                    expected,
                    "{name}: {access} {collision} included={included}"
                );
                if !expected {
                    assert!(matches!(site.target, OccurrenceTarget::Unresolved { .. }));
                }
                assert_eq!(
                    document
                        .skipped_regions
                        .iter()
                        .any(|gap| gap.source == site.source
                            && gap.detail == "vba-type-target-unavailable"),
                    !expected
                );
            }
            let member = document
                .occurrences
                .iter()
                .find(|site| {
                    site.file == consumer.id && site.syntax_kind == "vba.let_member.reference"
                })
                .unwrap();
            let field = document
                .entities
                .iter()
                .find(|entity| {
                    entity.kind == EntityKind::Field
                        && entity.canonical_name == "Count"
                        && entity
                            .evidence
                            .source
                            .as_ref()
                            .is_some_and(|source| source.span().file() == types.id)
                })
                .unwrap();
            assert_eq!(
                member.target == OccurrenceTarget::Resolved { symbol: field.id },
                expected
            );
            if !expected {
                assert!(matches!(member.target, OccurrenceTarget::Unresolved { .. }));
            }
        }
    }

    #[test]
    fn classic_new_type_paths_preserve_project_identity_after_restart() {
        for (path, admitted) in [
            ("Target", true),
            ("Primary.Target", true),
            ("[pRiMaRy].[tArGeT]", true),
            ("Primary _\r\n .Target", true),
            ("Foreign.Target", false),
            ("Primary.Target.Extra", false),
        ] {
            let fixture = durable_test_tempdir();
            let storage = durable_test_tempdir();
            let paths =
                RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
                    .unwrap();
            paths.prepare_owner().unwrap();
            fs::write(fixture.path().join("Target.cls"), "VERSION 1.0 CLASS\nAttribute VB_Name = \"Target\"\nPrivate Sub Class_Initialize()\nEnd Sub\n").unwrap();
            let source = format!(
                "Attribute VB_Name = \"Consumer\"\nPublic Sub Run()\nDim item As Object\nSet item = New {path}\nEnd Sub\n"
            );
            fs::write(fixture.path().join("Consumer.bas"), &source).unwrap();
            for included in [true, false, true] {
                let target = if included {
                    "Class=Target; Target.cls\n"
                } else {
                    ""
                };
                fs::write(
                    fixture.path().join("project.vbp"),
                    format!(
                        "Type=OleDll\nName=\"Primary\"\n{target}Module=Consumer; Consumer.bas\n"
                    ),
                )
                .unwrap();
                let mut service =
                    FirstSliceService::new_durable(2, paths.state_dir(), &deadline()).unwrap();
                let receipt = service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap();
                assert_eq!(
                    receipt,
                    service
                        .index_repository(fixture.path(), &deadline())
                        .unwrap()
                );
                drop(service);
                let service =
                    FirstSliceService::new_durable(2, paths.state_dir(), &deadline()).unwrap();
                let snapshot = service
                    .loaded_generation_snapshot(receipt.generation)
                    .unwrap();
                let document = snapshot.document();
                let file = document
                    .files
                    .iter()
                    .find(|file| file.path == "Consumer.bas")
                    .unwrap();
                let class = document
                    .entities
                    .iter()
                    .find(|entity| {
                        entity.kind == EntityKind::Class && entity.canonical_name == "Target"
                    })
                    .unwrap();
                let start = source.find("New ").unwrap() + 4;
                let sites: Vec<_> = document
                    .occurrences
                    .iter()
                    .filter(|site| {
                        site.file == file.id
                            && site.role == OccurrenceRole::TypeUse
                            && site.source.span().start_byte() == u64::try_from(start).unwrap()
                    })
                    .collect();
                assert_eq!(sites.len(), 1, "{path}");
                let site = sites[0];
                assert_eq!(
                    site.source.span().end_byte(),
                    u64::try_from(start + path.len()).unwrap(),
                    "{path}"
                );
                assert_eq!(
                    site.syntax_kind,
                    "vba.constructed_type_identifier.reference"
                );
                let expected = included && admitted;
                assert_eq!(
                    site.target == OccurrenceTarget::Resolved { symbol: class.id },
                    expected,
                    "{path}: included={included}"
                );
                if !expected {
                    assert!(matches!(site.target, OccurrenceTarget::Unresolved { .. }));
                }
                assert_eq!(
                    document
                        .skipped_regions
                        .iter()
                        .any(|gap| gap.source == site.source
                            && gap.detail == "vba-type-target-unavailable"),
                    !expected
                );
                let construction = document
                    .occurrences
                    .iter()
                    .find(|site| {
                        site.file == file.id && site.syntax_kind == "vba.construction.reference"
                    })
                    .unwrap();
                assert_eq!(
                    construction.source.span().start_byte(),
                    u64::try_from(start - 4).unwrap()
                );
                assert_eq!(
                    construction.source.span().end_byte(),
                    site.source.span().end_byte()
                );
                assert_eq!(
                    construction.target == OccurrenceTarget::Resolved { symbol: class.id },
                    expected
                );
                assert_eq!(
                    document
                        .skipped_regions
                        .iter()
                        .any(|gap| gap.source == construction.source
                            && gap.detail == "vba-construction-semantics-unavailable"),
                    !expected
                );
                let initializer = document
                    .entities
                    .iter()
                    .find(|entity| {
                        entity.canonical_name == "Class_Initialize"
                            && entity.container == Some(ContainerRef::Entity(class.id))
                    })
                    .unwrap();
                assert_eq!(
                    document.relations.iter().any(|edge| {
                        edge.predicate == RelationPredicate::Calls
                            && edge.object == RelationEndpoint::Entity(initializer.id)
                            && edge.evidence.source.as_ref() == Some(&construction.source)
                    }),
                    expected
                );
                let read = service
                    .source_read_with_options_and_budget(
                        receipt.generation,
                        vec![site.source.clone(), construction.source.clone()],
                        SourceReadOptions::new()
                            .with_context_lines_before(0)
                            .with_context_lines_after(0)
                            .with_encoding(SourceEncoding::Bytes),
                        FirstSliceBudget::default(),
                        &deadline(),
                    )
                    .unwrap();
                assert_eq!(read.data.chunks[0].bytes, path.as_bytes());
                assert_eq!(read.data.chunks[1].bytes, format!("New {path}").as_bytes());
                if expected {
                    let relationships = service
                        .symbol_relationships(
                            receipt.generation,
                            BTreeSet::from([class.id]),
                            vec![RelationFamily::Types],
                            Some(RelationDirection::Inbound),
                            0,
                            25,
                            0,
                            &deadline(),
                        )
                        .unwrap();
                    assert!(
                        relationships
                            .data
                            .groups
                            .iter()
                            .flat_map(|group| &group.items)
                            .any(|edge| edge.source_refs.contains(&site.source))
                    );
                }
            }
        }
    }

