    #[cfg(unix)]
    #[test]
    fn repository_operations_reject_symbolic_link_roots() {
        use std::os::unix::fs::symlink;

        let fixture = TempDir::new().expect("fixture root exists");
        let target = fixture.path().join("target");
        fs::create_dir(&target).expect("repository target exists");
        fs::write(target.join("lib.rs"), "pub fn answer() {}\n").expect("fixture source writes");
        let linked_root = fixture.path().join("linked");
        symlink(&target, &linked_root).expect("repository root symlink is created");

        assert_linked_repository_root_is_rejected(&linked_root);
    }

    #[cfg(windows)]
    #[test]
    fn repository_operations_reject_windows_reparse_roots() {
        use std::os::windows::fs::symlink_dir;

        const ERROR_PRIVILEGE_NOT_HELD: i32 = 1_314;

        let fixture = TempDir::new().expect("fixture root exists");
        let target = fixture.path().join("target");
        fs::create_dir(&target).expect("repository target exists");
        fs::write(target.join("lib.rs"), "pub fn answer() {}\n").expect("fixture source writes");
        let linked_root = fixture.path().join("linked");
        match symlink_dir(&target, &linked_root) {
            Ok(()) => {}
            Err(error) if error.raw_os_error() == Some(ERROR_PRIVILEGE_NOT_HELD) => return,
            Err(error) => panic!("repository root reparse point is created: {error}"),
        }

        assert_linked_repository_root_is_rejected(&linked_root);
    }

    #[cfg(any(unix, windows))]
    fn assert_linked_repository_root_is_rejected(root: &Path) {
        let service = FirstSliceService::new(2).expect("service initializes");
        let cancellation = deadline();

        assert!(matches!(
            service.admit_repository(root, &cancellation),
            Err(FirstSliceError::Repository)
        ));
        assert!(matches!(
            service.prepare_repository(root, &cancellation),
            Err(FirstSliceError::Repository)
        ));
        assert!(service.list_repositories().is_empty());
    }

    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    #[test]
    fn durable_service_restores_repository_query_and_source_state() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = durable_test_tempdir();
        fs::create_dir(fixture.path().join("src")).expect("fixture source directory exists");
        fs::write(
            fixture.path().join("src/lib.rs"),
            "pub fn durable_answer() -> u32 {\n    42\n}\n",
        )
        .expect("fixture source writes");
        let cancellation = Cancellation::new();
        let (_, empty_restore) = FirstSliceService::open_durable_deferred(2, paths.state_dir())
            .expect("empty durable boundary opens");
        assert!(
            !empty_restore
                .has_active_restore_work()
                .expect("empty durable metadata is readable")
        );
        drop(empty_restore);

        let receipt = {
            let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
                .expect("durable service initializes");
            service
                .index_rust_fixture(fixture.path(), &cancellation)
                .expect("durable generation publishes")
        };

        let (mut restored, deferred) =
            FirstSliceService::open_durable_deferred(2, paths.state_dir())
                .expect("durable boundary opens without scanning generations");
        assert!(restored.list_repositories().is_empty());
        assert!(
            deferred
                .has_active_restore_work()
                .expect("activation metadata is readable")
        );
        let restored_state = deferred
            .restore(&cancellation)
            .expect("durable generation verifies");
        assert_eq!(
            restored_state
                .recovery_observation()
                .expect("verified source observations fit"),
            FirstSliceRecoveryObservation {
                files_examined: 1,
                bytes_examined: 42,
            }
        );
        restored
            .install_deferred_restore(restored_state, &cancellation)
            .expect("verified durable generation installs");
        assert_eq!(
            restored.source_snapshots.retained_bytes(),
            source_generation_reference_bytes(0).expect("empty generation charge fits")
        );
        assert_eq!(
            restored.active_generation_for(receipt.repository),
            Some(receipt.generation)
        );
        assert_eq!(
            restored
                .resolve_generation(receipt.repository, None)
                .expect("restored generation resolves")
                .receipt,
            receipt
        );
        let located = restored
            .code_locate(
                receipt.generation,
                "durable_answer".to_owned(),
                LocateMode::Exact,
                8,
                0,
                &cancellation,
            )
            .expect("restored lexical query succeeds");
        let source = located
            .data
            .hits
            .first()
            .and_then(|hit| hit.source.clone())
            .expect("restored query carries source evidence");
        let read = restored
            .source_read(receipt.generation, vec![source], &cancellation)
            .expect("restored source bytes remain readable");
        assert_eq!(read.data.generation, receipt.generation);
    }

    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    #[test]
    fn durable_file_only_fallback_preserves_exact_query_source_and_coverage() {
        fn assert_file_only_state(
            service: &FirstSliceService,
            receipt: &FirstSliceIndexReceipt,
            sources: &[(&str, &str, &str, &str)],
        ) {
            assert_eq!(receipt.discovered_inputs, sources.len() as u64);
            assert_eq!(receipt.indexed_files, sources.len() as u64);
            assert_eq!(receipt.lexical_documents, sources.len() as u64);
            assert_eq!(receipt.entities, 0);
            assert!(
                receipt
                    .diagnostics
                    .iter()
                    .any(|diagnostic| { diagnostic.code == SOURCE_FILE_FALLBACK_DIAGNOSTIC_CODE }),
                "{receipt:#?}"
            );
            let generation = service
                .loaded_generation_snapshot(receipt.generation)
                .expect("file-only generation is loaded");
            assert_eq!(generation.file_count(), sources.len());
            assert_eq!(generation.document().files.len(), 1);
            let inspected = service
                .inspect_generation(
                    receipt.repository,
                    Some(receipt.generation),
                    &deadline(),
                    |snapshot| (snapshot.file_count(), snapshot.source_files().len()),
                )
                .expect("local inspection includes file-only records");
            assert_eq!(inspected, (sources.len(), sources.len() - 1));
            assert_eq!(generation.source_files().len(), sources.len() - 1);
            let projection = service
                .generation_language_coverage_until(
                    receipt.repository,
                    receipt.generation,
                    &deadline(),
                )
                .unwrap()
                .unwrap();
            assert_eq!(
                projection
                    .iter()
                    .map(|row| row.language.as_str())
                    .collect::<BTreeSet<_>>(),
                sources
                    .iter()
                    .map(|(_, _, language, _)| *language)
                    .collect::<BTreeSet<_>>()
            );
            assert!(projection.iter().all(
                |row| row.tier == AnalysisTier::TierD && row.status == CoverageStatus::Unknown
            ));

            for (path, content, language, canary) in sources {
                let file = generation
                    .document()
                    .files
                    .iter()
                    .chain(
                        generation
                            .source_files()
                            .entries()
                            .iter()
                            .map(|entry| entry.file()),
                    )
                    .find(|file| file.path == *path)
                    .expect("every safe tracked source has a file record");
                for (query, mode) in [
                    ((*path).to_owned(), LocateMode::Exact),
                    ((*path).to_owned(), LocateMode::Prefix),
                    ((*canary).to_owned(), LocateMode::Exact),
                    ((*canary).to_owned(), LocateMode::Text),
                ] {
                    let located = service
                        .code_locate(receipt.generation, query, mode, 10, 0, &deadline())
                        .expect("file-only source locates");
                    let hit = located
                        .data
                        .hits
                        .iter()
                        .find(|hit| hit.file == file.id)
                        .expect("the exact file-only hit is returned");
                    assert_eq!(hit.symbol, None);
                    assert_eq!(hit.kind, "file");
                    let source = hit
                        .source
                        .as_ref()
                        .expect("file-only hit carries direct source evidence");
                    assert_eq!(source.repository(), receipt.repository);
                    assert_eq!(source.generation(), receipt.generation);
                    assert_eq!(source.span().file(), file.id);
                    assert_eq!(source.content_hash(), file.content_hash);
                }
                let reference = file
                    .evidence
                    .source
                    .clone()
                    .expect("file record carries direct source evidence");
                let read = service
                    .source_read(receipt.generation, vec![reference], &deadline())
                    .expect("file-only source remains readable");
                assert_eq!(read.data.chunks.len(), 1);
                assert_eq!(read.data.chunks[0].bytes, content.as_bytes());
                assert_eq!(read.data.chunks[0].language, *language);
                let coverage = service
                    .source_file_coverage_until(receipt.generation, file.id, &deadline())
                    .expect("file-only source coverage resolves");
                assert_eq!(coverage.language, *language);
                assert_eq!(coverage.tier, AnalysisTier::TierD);
                assert_eq!(coverage.status, CoverageStatus::Unknown);
                assert_eq!(
                    coverage.reason,
                    Some(FirstSliceSourceCoverageReason::ResourceBounded)
                );
            }
            let absent = service
                .code_locate(
                    receipt.generation,
                    "absentFileOnlyNegativeControl".to_owned(),
                    LocateMode::Exact,
                    10,
                    0,
                    &deadline(),
                )
                .expect("negative control query succeeds");
            assert!(absent.data.hits.is_empty());

            let status = service
                .repository_status(receipt.repository, Some(receipt.generation))
                .expect("file-only repository status resolves");
            for (_, _, language, _) in sources {
                let coverage = status
                    .coverage
                    .iter()
                    .find(|coverage| coverage.language == *language)
                    .expect("file-only language coverage is reported");
                assert_eq!(coverage.tier, "tier_d");
                assert_eq!(coverage.status, "unknown");
                assert_eq!(coverage.discovered_files, 1);
                assert_eq!(coverage.indexed_files, 0);
            }
            let gaps = service
                .coverage_gaps_until(receipt.repository, receipt.generation, &deadline())
                .expect("file-only coverage gaps resolve");
            let summary = service
                .coverage_gap_summary_until(
                    receipt.repository,
                    receipt.generation,
                    &[],
                    &deadline(),
                )
                .expect("file-only coverage summary resolves");
            assert_eq!(summary.gaps, gaps);
            assert_eq!(summary.skipped_inputs, sources.len() as u64);
            assert!(summary.incomplete);
            for (_, _, language, _) in sources {
                assert!(gaps.iter().any(|gap| {
                    gap.reason == FirstSliceCoverageGapReason::Truncated
                        && gap.language.as_deref() == Some(*language)
                        && gap.files == 1
                }));
                let scoped = service
                    .coverage_gap_summary_until(
                        receipt.repository,
                        receipt.generation,
                        &[(*language).to_owned()],
                        &deadline(),
                    )
                    .expect("language-scoped file-only coverage resolves");
                assert_eq!(scoped.skipped_inputs, 1);
                assert!(scoped.incomplete);
                assert!(scoped.gaps.iter().all(|gap| {
                    gap.language
                        .as_deref()
                        .is_none_or(|value| value == *language)
                }));
            }
            let path_scoped = service
                .coverage_gap_summary_for_paths_until(
                    receipt.repository,
                    receipt.generation,
                    &[],
                    &["styles".to_owned()],
                    &deadline(),
                )
                .expect("path-scoped file-only coverage resolves");
            assert_eq!(path_scoped.skipped_inputs, 1);
            assert!(path_scoped.gaps.iter().any(|gap| {
                gap.reason == FirstSliceCoverageGapReason::Truncated
                    && gap.language.as_deref() == Some("css")
                    && gap.files == 1
            }));
            assert!(path_scoped.gaps.iter().all(|gap| {
                gap.language
                    .as_deref()
                    .is_none_or(|language| language == "css")
            }));
            let nonmatching = service
                .coverage_gap_summary_for_paths_until(
                    receipt.repository,
                    receipt.generation,
                    &[],
                    &["style".to_owned()],
                    &deadline(),
                )
                .expect("path prefix boundary is respected");
            assert_eq!(nonmatching.skipped_inputs, 0);
            assert!(nonmatching.gaps.iter().all(|gap| gap.language.is_none()));
        }

        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = durable_test_tempdir();
        let sources = [
            (
                "src/alpha.rs",
                "pub fn alpha_file_only() -> &'static str { \"alphaFileOnlyCanary\" }\n",
                "rust",
                "alphaFileOnlyCanary",
            ),
            (
                "styles/beta.css",
                ".betaFileOnlyCanary { display: block; }\n",
                "css",
                "betaFileOnlyCanary",
            ),
            (
                "scripts/gamma.lua",
                "local gammaFileOnlyCanary = true\n",
                "lua",
                "gammaFileOnlyCanary",
            ),
        ];
        for (path, content, _, _) in sources {
            let full_path = fixture.path().join(path);
            fs::create_dir_all(full_path.parent().expect("fixture path has a parent"))
                .expect("fixture source directory exists");
            fs::write(full_path, content).expect("file-only fixture writes");
        }
        let cancellation = deadline();
        let receipt = {
            let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
                .expect("durable service initializes");
            let mut ir = service.analysis_limits.ir().clone();
            ir.max_files = 1;
            replace_service_ir_limits(&mut service, ir);
            let receipt = service
                .index_repository(fixture.path(), &cancellation)
                .expect("resource-bounded repository publishes file-only fallback");
            assert_file_only_state(&service, &receipt, &sources);
            receipt
        };

        let mut restored = FirstSliceService::new_durable(2, paths.state_dir(), &deadline())
            .expect("file-only durable generation restores");
        assert_file_only_state(&restored, &receipt, &sources);

        let changed_sources = [
            (
                "src/alpha.rs",
                "pub fn alpha_file_only() -> &'static str { \"alphaFileOnlyChanged\" }\n",
                "rust",
                "alphaFileOnlyChanged",
            ),
            sources[1],
            sources[2],
        ];
        fs::write(fixture.path().join("src/alpha.rs"), changed_sources[0].1)
            .expect("file-only successor source writes");
        let mut ir = restored.analysis_limits.ir().clone();
        ir.max_files = 1;
        replace_service_ir_limits(&mut restored, ir);
        let successor = restored
            .index_repository(fixture.path(), &deadline())
            .expect("file-only successor publishes");
        assert_eq!(successor.parent, Some(receipt.generation));
        assert_file_only_state(&restored, &successor, &changed_sources);
        {
            let mut cache = restored
                .generation_cache
                .lock()
                .expect("generation cache lock remains available");
            let active_charge = cache
                .logical_charge_bytes_by_generation
                .get(&successor.generation)
                .copied()
                .expect("active file-only generation has an admission charge");
            cache
                .ensure_capacity(
                    MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES
                        .checked_sub(active_charge)
                        .expect("active file-only charge fits the process budget"),
                    PendingGenerationMemory::Staged,
                    true,
                )
                .expect("inactive file-only generation unloads");
            assert!(!cache.generations.is_loaded(receipt.generation));
        }
        drop(
            restored
                .generation_lease(receipt.generation, &deadline())
                .expect("unloaded file-only generation rehydrates with the same charge"),
        );
        assert_file_only_state(&restored, &receipt, &sources);
    }

    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    #[test]
    fn durable_file_only_inventory_completes_bounded_semantic_refinement() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = durable_test_tempdir();
        let sources = [
            ("alpha.rs", "pub fn inventory_alpha() -> bool { true }\n"),
            ("beta.css", ".inventoryBeta { display: block; }\n"),
            ("gamma.lua", "local inventoryGamma = true\n"),
        ];
        for (path, content) in sources {
            fs::write(fixture.path().join(path), content).expect("inventory fixture source writes");
        }

        let policy = FirstSliceStoragePolicy::resolve_user_config(
            Some("version = \"1.3\"\n[analysis]\nmax_discovery_entries = 2\n"),
            2,
        )
        .expect("bounded discovery configuration resolves");
        let analyzer_calls = Arc::new(AtomicUsize::new(0));
        let analyzer: Arc<dyn FirstSliceProjectAnalyzer> = Arc::new(FailingProjectAnalyzer {
            identity: content_hash(b"inventory-semantic-analyzer"),
            error: FirstSliceProjectAnalysisError::Analysis,
            calls: Arc::clone(&analyzer_calls),
        });
        let (mut service, deferred) =
            FirstSliceService::open_durable_deferred_with_project_analyzer_and_policy(
                policy,
                paths.state_dir(),
                analyzer,
            )
            .expect("durable inventory service opens");
        service
            .install_complete_deferred_restore_progressively(&deferred, &deadline())
            .expect("empty durable inventory state restores");

        let mut structural_progress = Vec::new();
        let structural_preparation = service
            .prepare_repository_with_mode_and_progress(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &deadline(),
                |progress| structural_progress.push(progress),
            )
            .expect("bounded structural inventory prepares");
        let structural = service
            .publish_prepared(structural_preparation, &deadline())
            .expect("bounded structural inventory publishes");
        assert_eq!(
            structural_progress
                .iter()
                .filter(|progress| progress.stage == FirstSliceIndexStage::Discovery)
                .map(|progress| progress.files_examined)
                .max(),
            Some(sources.len() as u64),
        );
        assert!(structural.discovery_complete);
        assert_eq!(structural.discovered_inputs, sources.len() as u64);
        assert!(
            structural
                .diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == SOURCE_FILE_FALLBACK_DIAGNOSTIC_CODE })
        );

        let semantic_preparation = service
            .prepare_semantic_refinement(fixture.path(), structural.generation, &deadline())
            .expect("bounded semantic inventory prepares without project analysis");
        let semantic = service
            .publish_prepared(semantic_preparation, &deadline())
            .expect("bounded semantic inventory publishes");
        assert_eq!(semantic.parent, Some(structural.generation));
        assert_ne!(semantic.generation, structural.generation);
        assert!(semantic.discovery_complete);
        assert_eq!(semantic.discovered_inputs, sources.len() as u64);
        assert_eq!(semantic.indexed_files, sources.len() as u64);
        assert_eq!(semantic.entities, 0);
        assert_eq!(analyzer_calls.load(Ordering::Relaxed), 0);
        assert!(
            service
                .active_generation_is_deep(semantic.repository)
                .expect("bounded semantic provider identity resolves")
        );
        let freshness = service
            .generation_freshness(semantic.repository, semantic.generation)
            .expect("bounded semantic freshness resolves");
        assert_eq!(
            freshness.semantic,
            FirstSliceObservedFreshness::CurrentAtLastAuthoritativeScan
        );
        let status = service
            .repository_status(semantic.repository, Some(semantic.generation))
            .expect("bounded semantic repository status resolves");
        assert_eq!(status.coverage.len(), sources.len());
        assert!(status.coverage.iter().all(|coverage| {
            coverage.tier == "tier_d"
                && coverage.status == "unknown"
                && coverage.discovered_files == 1
                && coverage.indexed_files == 0
        }));

        for (path, _) in sources {
            let located = service
                .code_locate(
                    semantic.generation,
                    path.to_owned(),
                    LocateMode::Exact,
                    8,
                    0,
                    &deadline(),
                )
                .expect("inventory path lookup succeeds");
            assert!(located.data.hits.iter().any(|hit| hit.path == path));
        }
        let absent = service
            .code_locate(
                semantic.generation,
                "semanticInventoryNegativeControl".to_owned(),
                LocateMode::Exact,
                8,
                0,
                &deadline(),
            )
            .expect("inventory negative control lookup succeeds");
        assert!(absent.data.hits.is_empty());
    }

    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    #[test]
    fn active_restore_preparation_does_not_require_the_service_lock() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = durable_test_tempdir();
        fs::write(
            fixture.path().join("lib.rs"),
            "pub fn recovery_lock_probe() -> bool { true }\n",
        )
        .expect("fixture source writes");
        let cancellation = deadline();
        let receipt = {
            let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
                .expect("durable service initializes");
            service
                .index_rust_fixture(fixture.path(), &cancellation)
                .expect("durable generation publishes")
        };
        let (service, deferred) = FirstSliceService::open_durable_deferred(2, paths.state_dir())
            .expect("deferred durable service opens");
        let restored = deferred
            .restore_active_repository(receipt.repository, &cancellation)
            .expect("active generation payload restores");
        let service = RwLock::new(service);
        let service_write = service.write().expect("service write lock opens");
        let (prepared_sender, prepared_receiver) = mpsc::sync_channel(1);

        thread::scope(|scope| {
            let preparation_cancellation = cancellation.clone();
            let preparation = scope.spawn(move || {
                prepared_sender
                    .send(restored.prepare_active_installation(&preparation_cancellation))
                    .expect("prepared restore sends");
            });
            let prepared = prepared_receiver
                .recv_timeout(Duration::from_secs(5))
                .expect("active restore prepares while the service write lock is held")
                .expect("active restore validation succeeds");
            drop(service_write);
            preparation.join().expect("restore preparation joins");
            service
                .write()
                .expect("service write lock reopens")
                .install_prepared_progressive_deferred_restore(prepared, &cancellation)
                .expect("prepared active restore installs");
        });

        assert_eq!(
            service
                .read()
                .expect("service read lock opens")
                .active_generation_for(receipt.repository),
            Some(receipt.generation)
        );
    }

    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    #[test]
    fn oracle_restore_admits_closed_registry_rows_under_pressure() {
        use rootlight_catalog::OracleReader;
        use rootlight_storage::GenerationReader as _;

        fn encoded_bytes(value: &impl serde::Serialize) -> u64 {
            let mut counter = SerializedSizeCounter::default();
            serde_json::to_writer(&mut counter, value).expect("fixture record serializes");
            counter.bytes
        }

        fn reserved(service: &FirstSliceService) -> u64 {
            service
                .generation_cache
                .lock()
                .expect("cache opens")
                .reserved_memory_bytes()
                .expect("reservation total reads")
        }

        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("runtime paths are valid");
        paths.prepare_owner().expect("private paths prepare");
        let fixture = durable_test_tempdir();
        let source = concat!(
            "pub fn stored_target(input: u32) -> u32 { input + 1 }\n",
            "pub fn stored_caller() -> u32 { stored_target(7) }\n",
        );
        fs::write(fixture.path().join("lib.rs"), source).expect("fixture source writes");
        let mut sources = BTreeMap::from([("lib.rs".to_owned(), source.to_owned())]);
        // Keep physical payloads small so this fixture isolates closed registry
        // keys rather than the independent transient cost of lexical batches.
        for ordinal in 0..30 {
            let source = format!(
                "pub fn stored_extra_{ordinal}(input: u32) -> u32 {{ input + {ordinal} }}\n"
            );
            let path = format!("extra_{ordinal}.rs");
            fs::write(fixture.path().join(&path), &source)
                .expect("additional fixture source writes");
            assert!(sources.insert(path, source).is_none());
        }
        let cancellation = deadline();
        let (receipt, expected) = {
            let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
                .expect("durable service initializes");
            let receipt = service
                .index_rust_fixture(fixture.path(), &cancellation)
                .expect("fixture publishes");
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .expect("published generation is loaded");
            assert_eq!(
                snapshot.metadata().contract_version(),
                GENERATION_CONTRACT_VERSION
            );
            let document = snapshot.document().clone();
            assert_eq!(
                document
                    .entities
                    .iter()
                    .filter(|entity| entity.kind == EntityKind::Function)
                    .count(),
                32
            );
            assert!(
                document
                    .relations
                    .iter()
                    .any(|relation| relation.predicate == RelationPredicate::Calls),
                "the fixture must retain a direct call before testing recovery"
            );
            (receipt, document)
        };
        let directory = paths
            .state_dir()
            .join("first-slice/repositories")
            .join(receipt.repository.to_string())
            .join(receipt.generation.to_string());
        assert!(
            !directory.join("recovery-manifest.json").exists(),
            "this regression exercises the authoritative oracle, not an optional snapshot"
        );
        let manifest_bytes = fs::read(directory.join("manifest.json")).expect("manifest reads");
        let manifest: serde_json::Value =
            serde_json::from_slice(&manifest_bytes).expect("manifest decodes");
        assert!(manifest["source_file_catalog"].is_null());
        assert_eq!(manifest["source_storage"]["version"], 2);
        assert_eq!(manifest["source_storage"]["files"], sources.len());
        assert_eq!(manifest["source_storage"]["packs"], 1);
        let packed_index =
            fs::read(directory.join("sources/index.msgpack")).expect("packed source index reads");
        let packed_index_bytes = manifest["source_storage"]["index_bytes"]
            .as_u64()
            .expect("packed source index byte count exists");
        assert!(packed_index_bytes > 0);
        assert_eq!(
            packed_index_bytes,
            u64::try_from(packed_index.len()).expect("packed source index size is representable")
        );
        assert_eq!(
            manifest["source_storage"]["index_digest"],
            serde_json::to_value(content_hash(&packed_index))
                .expect("packed source index digest serializes")
        );
        let incremental_bytes = manifest["incremental_state"]["bytes"].as_u64().unwrap_or(0);
        let staging_bytes = incremental_bytes
            .checked_add(packed_index_bytes)
            .and_then(|bytes| bytes.checked_mul(8))
            .and_then(|bytes| bytes.checked_add(GENERATION_MEMORY_FIXED_OVERHEAD_BYTES))
            .expect("fixture staging envelope is representable");
        let context = GenerationContext::new(&cancellation, GenerationBudget::default());
        let oracle = OracleReader::open_in(&directory, &context).expect("oracle header validates");
        let stats = oracle.stats();
        let identity_rows = [
            stats.files(),
            stats.entities(),
            stats.occurrences(),
            stats.relations(),
            stats.provenance(),
            stats.source_mappings(),
            stats.coverage(),
            stats.skipped_regions(),
            stats.diagnostics(),
            stats.extensions(),
        ]
        .into_iter()
        .try_fold(1_u64, u64::checked_add)
        .expect("fixture identity count is representable");
        let posting_bytes_per_row = u64::try_from(
            4 * std::mem::size_of::<(SymbolId, usize)>() + 2 * std::mem::size_of::<usize>(),
        )
        .expect("posting envelope is representable");
        let old_envelope = stats
            .stored_rows()
            .checked_mul(4096 + posting_bytes_per_row)
            .and_then(|bytes| bytes.checked_add(stats.text_bytes().checked_mul(6)?))
            .and_then(|bytes| bytes.checked_add(staging_bytes))
            .expect("old restore envelope is representable");

        // A closed registry key contains only a tag and one fixed-width ID.
        // This historical comparator discounts only registry keys. The actual
        // read plan also separates typed records and compact source buffers.
        let registry_bytes_per_row =
            u64::try_from(11 * std::mem::size_of::<[u8; 32]>() + 16 * std::mem::size_of::<usize>())
                .expect("registry envelope is representable");
        let identity_saving = identity_rows
            .checked_mul(4096 - registry_bytes_per_row)
            .and_then(|bytes| bytes.checked_sub(registry_bytes_per_row))
            .expect("closed registry envelope saves capacity in this fixture");
        let mut maximum_payload_bytes = 0;
        for record in &expected.source_mappings {
            maximum_payload_bytes = maximum_payload_bytes.max(encoded_bytes(record));
        }
        for record in &expected.skipped_regions {
            maximum_payload_bytes = maximum_payload_bytes.max(encoded_bytes(record));
        }
        for record in &expected.diagnostics {
            maximum_payload_bytes = maximum_payload_bytes.max(encoded_bytes(record));
        }
        for record in &expected.extensions {
            maximum_payload_bytes = maximum_payload_bytes.max(encoded_bytes(record));
        }
        for file in &expected.files {
            if let Some(locator) = &file.path_locator {
                maximum_payload_bytes =
                    maximum_payload_bytes.max(encoded_bytes(&locator.components()));
            }
        }
        let transient_bytes = maximum_payload_bytes
            .checked_mul(
                u64::try_from(4 * (std::mem::size_of::<String>() + std::mem::size_of::<usize>()))
                    .expect("decoder envelope is representable"),
            )
            .expect("fixture transient envelope is representable");
        let revised_upper_envelope = old_envelope - identity_saving + transient_bytes;
        let available_bytes = old_envelope - identity_saving / 4;
        assert!(revised_upper_envelope <= available_bytes);
        assert!(available_bytes < old_envelope);
        assert!(available_bytes < MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES);
        let pressure_bytes = MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES - available_bytes;

        let (mut service, deferred) =
            FirstSliceService::open_durable_deferred(2, paths.state_dir())
                .expect("deferred service opens");
        let competing = service
            .reserve_generation_memory(
                GenerationId::from_bytes([22; 20]),
                pressure_bytes,
                PendingGenerationMemory::Reserved,
            )
            .expect("another owner reserves the remaining capacity");
        assert_eq!(reserved(&service), pressure_bytes);
        let restored = deferred
            .restore_active_repository(receipt.repository, &cancellation)
            .expect("closed registry rows fit without weakening the remaining restore envelope");
        assert_eq!(
            restored.generation_ids(),
            BTreeSet::from([receipt.generation])
        );
        let prepared = restored
            .prepare_active_installation(&cancellation)
            .expect("complete restored generation prepares");
        service
            .install_prepared_progressive_deferred_restore(prepared, &cancellation)
            .expect("restored generation installs without a second admission");
        assert_eq!(reserved(&service), pressure_bytes);
        assert_eq!(
            service.active_generation_for(receipt.repository),
            Some(receipt.generation)
        );
        let restored_snapshot = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("restored document remains loaded");
        assert_eq!(restored_snapshot.document(), &expected);
        let located = service
            .code_locate(
                receipt.generation,
                "stored_target".to_owned(),
                LocateMode::Exact,
                10,
                0,
                &cancellation,
            )
            .expect("restored definition is queryable");
        assert!(located.data.hits.iter().any(|hit| {
            hit.identifier == "stored_target" && hit.path == "lib.rs" && hit.symbol.is_some()
        }));
        assert_eq!(expected.files.len(), sources.len());
        for file in &expected.files {
            let reference = file
                .evidence
                .source
                .clone()
                .expect("fixture file has whole-source evidence");
            let read = service
                .source_read(receipt.generation, vec![reference], &cancellation)
                .expect("all restored source bytes remain available");
            assert_eq!(read.data.chunks.len(), 1);
            assert_eq!(
                read.data.chunks[0].bytes,
                sources
                    .get(&file.path)
                    .expect("restored fixture path belongs to the written sources")
                    .as_bytes()
            );
        }
        assert_eq!(
            fs::read(directory.join("manifest.json")).expect("manifest still reads"),
            manifest_bytes
        );
        assert_eq!(
            fs::read_dir(paths.state_dir().join("first-slice/quarantine"))
                .expect("quarantine enumerates")
                .count(),
            0
        );
        drop(competing);
        assert_eq!(reserved(&service), 0);
    }

    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    #[test]
    fn deferred_restore_admits_before_payload_reads_and_preserves_retryable_generations() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("runtime paths are valid");
        paths.prepare_owner().expect("private paths prepare");
        let fixture = durable_test_tempdir();
        fs::write(
            fixture.path().join("lib.rs"),
            "pub fn recovered_answer() -> u32 { 7 }\n",
        )
        .expect("fixture writes");
        let cancellation = deadline();
        let receipt = {
            let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
                .expect("durable service initializes");
            let receipt = service
                .index_repository(fixture.path(), &cancellation)
                .expect("fixture publishes");
            let generation_directory = paths
                .state_dir()
                .join("first-slice/repositories")
                .join(receipt.repository.to_string())
                .join(receipt.generation.to_string());
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .expect("published snapshot resolves");
            assert_eq!(
                snapshot.metadata().contract_version(),
                GENERATION_CONTRACT_VERSION
            );
            durable::write_legacy_gzip_recovery_snapshot(&generation_directory, &snapshot)
                .expect("compatible recovery snapshot writes");
            receipt
        };
        let directory = paths
            .state_dir()
            .join("first-slice/repositories")
            .join(receipt.repository.to_string())
            .join(receipt.generation.to_string());
        let snapshot_path = directory.join("recovery.json.gz");
        let oracle_path = directory.join("oracle.sqlite3");
        let snapshot = fs::read(&snapshot_path).expect("snapshot reads");
        let oracle = fs::read(&oracle_path).expect("oracle reads");
        let (service, deferred) = FirstSliceService::open_durable_deferred(2, paths.state_dir())
            .expect("deferred service opens");
        let reserved = || {
            service
                .generation_cache
                .lock()
                .expect("cache opens")
                .reserved_memory_bytes()
                .expect("reservation total reads")
        };
        let pressure = service
            .reserve_generation_memory(
                GenerationId::from_bytes([19; 20]),
                MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES,
                PendingGenerationMemory::Reserved,
            )
            .expect("competing owner reserves the budget");

        // If payload decoding precedes admission, these bytes select quarantine.
        // Capacity pressure must instead leave the generation untouched for retry.
        fs::write(&snapshot_path, b"corrupt").expect("snapshot corrupts");
        fs::write(&oracle_path, b"corrupt").expect("oracle corrupts");
        assert!(matches!(
            deferred.restore_active_repository(receipt.repository, &cancellation),
            Err(FirstSliceError::GenerationMemoryLimit { .. })
        ));
        assert!(
            directory.exists(),
            "admission must precede payload reads and quarantine"
        );
        assert_eq!(reserved(), MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES);
        drop(pressure);
        assert_eq!(reserved(), 0);
        fs::write(&snapshot_path, snapshot).expect("snapshot repairs");
        let restored = deferred
            .restore_active_repository(receipt.repository, &cancellation)
            .expect("snapshot recovery retries while the oracle remains corrupt");
        assert_eq!(
            restored.generation_ids(),
            BTreeSet::from([receipt.generation])
        );
        drop(restored);
        assert_eq!(reserved(), 0);
        fs::write(&oracle_path, oracle).expect("oracle repairs");

        let descriptor_path = directory.join("recovery-manifest.json");
        let mut descriptor: serde_json::Value =
            serde_json::from_slice(&fs::read(&descriptor_path).expect("snapshot descriptor reads"))
                .expect("snapshot descriptor decodes");
        descriptor["decoded_bytes"] = serde_json::json!(128 * 1024 * 1024);
        fs::write(
            &descriptor_path,
            serde_json::to_vec(&descriptor).expect("descriptor serializes"),
        )
        .expect("optional snapshot advertises an over-budget decoded buffer");
        let pressure = service
            .reserve_generation_memory(
                GenerationId::from_bytes([21; 20]),
                MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES
                    - GENERATION_MEMORY_FIXED_OVERHEAD_BYTES
                    - 16 * 1024 * 1024,
                PendingGenerationMemory::Reserved,
            )
            .expect("oracle capacity remains while snapshot staging does not fit");
        let restored = deferred
            .restore_active_repository(receipt.repository, &cancellation)
            .expect("optional snapshot pressure selects a fitting authoritative oracle");
        assert_eq!(
            restored.generation_ids(),
            BTreeSet::from([receipt.generation])
        );
        drop(restored);
        drop(pressure);
        assert_eq!(reserved(), 0);

        fs::rename(
            &descriptor_path,
            directory.join("saved-recovery-manifest.json"),
        )
        .expect("legacy fixture has no recovery descriptor");
        let manifest: serde_json::Value = serde_json::from_slice(
            &fs::read(directory.join("manifest.json")).expect("manifest reads"),
        )
        .expect("manifest decodes");
        assert!(manifest["source_file_catalog"].is_null());
        assert!(manifest["source_storage"].get("index_bytes").is_none());
        let incremental_bytes = manifest["incremental_state"]["bytes"].as_u64().unwrap_or(0);
        let staging_bytes = GENERATION_MEMORY_FIXED_OVERHEAD_BYTES + incremental_bytes * 8;
        let pressure_bytes = MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES - staging_bytes;
        let pressure = service
            .reserve_generation_memory(
                GenerationId::from_bytes([20; 20]),
                pressure_bytes,
                PendingGenerationMemory::Reserved,
            )
            .expect("only sidecar capacity remains");
        assert!(matches!(
            deferred.restore_active_repository(receipt.repository, &cancellation),
            Err(FirstSliceError::GenerationMemoryLimit { .. })
        ));
        assert!(
            directory.exists(),
            "oracle admission failure must not quarantine"
        );
        assert_eq!(
            reserved(),
            pressure_bytes,
            "failed growth releases only its own staging charge"
        );
        drop(pressure);
        let restored = deferred
            .restore_active_repository(receipt.repository, &cancellation)
            .expect("legacy oracle recovery retries after pressure clears");
        assert_eq!(
            restored.generation_ids(),
            BTreeSet::from([receipt.generation])
        );
        drop(restored);
        assert_eq!(reserved(), 0);
    }

    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    #[test]
    fn deferred_restore_owns_memory_through_drop_and_installation() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths.prepare_owner().expect("private paths prepare");
        let fixture = durable_test_tempdir();
        fs::write(
            fixture.path().join("lib.rs"),
            "pub fn restored_value() -> u32 { 7 }\n",
        )
        .expect("fixture source writes");
        let cancellation = deadline();
        let receipt = {
            let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
                .expect("durable service initializes");
            service
                .index_rust_fixture(fixture.path(), &cancellation)
                .expect("fixture publishes")
        };
        let (mut service, deferred) =
            FirstSliceService::open_durable_deferred(2, paths.state_dir())
                .expect("deferred service opens");
        let reserved = || {
            service
                .generation_cache
                .lock()
                .expect("cache remains available")
                .reserved_memory_bytes()
                .expect("reservation total is representable")
        };
        let first = deferred
            .restore_active_repository(receipt.repository, &cancellation)
            .expect("first payload restores");
        let charge = reserved();
        assert!(
            charge > 0,
            "returned recovery payload must own a memory reservation"
        );
        let second = deferred
            .restore_active_repository(receipt.repository, &cancellation)
            .expect("a second payload of the same generation restores independently");
        assert_eq!(reserved(), charge * 2);
        drop(first);
        assert_eq!(reserved(), charge);
        let prepared = second
            .prepare_active_installation(&cancellation)
            .expect("active preparation transfers reservation ownership");
        assert_eq!(reserved(), charge);
        let competing = service
            .reserve_generation_memory(
                GenerationId::from_bytes([19; 20]),
                MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES - charge,
                PendingGenerationMemory::Reserved,
            )
            .expect("unreserved capacity remains available to another owner");
        service
            .install_prepared_progressive_deferred_restore(prepared, &cancellation)
            .expect("installation converts the existing charge without double admission");
        drop(competing);
        assert_eq!(
            service.active_generation_for(receipt.repository),
            Some(receipt.generation)
        );
        let cache = service
            .generation_cache
            .lock()
            .expect("cache remains available");
        assert_eq!(
            cache
                .reserved_memory_bytes()
                .expect("reserved charge reads"),
            0
        );
        assert_eq!(
            cache
                .resident_logical_charge_bytes()
                .expect("resident charge reads"),
            charge
        );
        drop(cache);

        let cancelled = Cancellation::new();
        let _ = cancelled.cancel(CancellationReason::Shutdown);
        let restored = deferred
            .restore_active_repository(receipt.repository, &cancellation)
            .expect("payload restores for cancelled preparation");
        assert!(matches!(
            restored.prepare_active_installation(&cancelled),
            Err(FirstSliceError::Cancelled(CancellationReason::Shutdown))
        ));
        assert_eq!(
            service
                .generation_cache
                .lock()
                .expect("cache remains available")
                .reserved_memory_bytes()
                .expect("reservation total reads"),
            0
        );

        let restored = deferred
            .restore_active_repository(receipt.repository, &cancellation)
            .expect("payload restores for cancelled installation");
        let prepared = restored
            .prepare_active_installation(&cancellation)
            .expect("payload prepares before cancellation");
        assert_eq!(
            service.install_prepared_progressive_deferred_restore(prepared, &cancelled),
            Err(FirstSliceError::Cancelled(CancellationReason::Shutdown))
        );
        assert_eq!(
            service
                .generation_cache
                .lock()
                .expect("cache remains available")
                .reserved_memory_bytes()
                .expect("reservation total reads"),
            0
        );

        let restored = deferred
            .restore_active_repository(receipt.repository, &cancellation)
            .expect("payload restores for another service owner");
        let prepared = restored
            .prepare_active_installation(&cancellation)
            .expect("payload prepares for transfer");
        let (mut replacement, _) = FirstSliceService::open_durable_deferred(2, paths.state_dir())
            .expect("replacement service opens the same catalog");
        replacement
            .install_prepared_progressive_deferred_restore(prepared, &cancellation)
            .expect("installation transfers the charge to its destination cache");
        assert_eq!(
            service
                .generation_cache
                .lock()
                .expect("origin cache remains available")
                .reserved_memory_bytes()
                .expect("origin reservation total reads"),
            0
        );
        let cache = replacement
            .generation_cache
            .lock()
            .expect("destination cache remains available");
        assert_eq!(
            cache
                .reserved_memory_bytes()
                .expect("destination reservation total reads"),
            0
        );
        assert_eq!(
            cache
                .resident_logical_charge_bytes()
                .expect("destination resident charge reads"),
            charge
        );
        drop(cache);

        let mut oversized_batch = Vec::new();
        for _ in 0..2 {
            let mut payloads = deferred
                .durable
                .restore_active_repository(receipt.repository, &cancellation)
                .expect("payload restores for admission failure injection");
            for payload in &mut payloads {
                payload.serialized_document_bytes =
                    Some(MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES / 2 + 1);
            }
            oversized_batch.extend(payloads);
        }
        assert!(matches!(
            deferred.reserve_restored_state(oversized_batch, &cancellation),
            Err(FirstSliceError::GenerationMemoryLimit { .. })
        ));
        assert_eq!(
            service
                .generation_cache
                .lock()
                .expect("origin cache remains available")
                .reserved_memory_bytes()
                .expect("failed batch releases all preceding owners"),
            0
        );
    }

    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    #[test]
    fn concurrent_repository_restore_preserves_active_and_retained_generation_identity() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("private runtime paths prepare");
        let fixtures = [durable_test_tempdir(), durable_test_tempdir()];
        let cancellation = deadline();
        let mut receipts = Vec::new();
        {
            let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
                .expect("durable service initializes");
            for fixture in &fixtures {
                let source = fixture.path().join("lib.rs");
                fs::write(&source, "pub fn retained_answer() -> u32 { 1 }\n")
                    .expect("retained source writes");
                let retained = service
                    .index_rust_fixture(fixture.path(), &cancellation)
                    .expect("retained generation publishes");
                fs::write(&source, "pub fn active_answer() -> u32 { 2 }\n")
                    .expect("active source writes");
                let active = service
                    .index_rust_fixture(fixture.path(), &cancellation)
                    .expect("active generation publishes");
                receipts.push((retained, active));
            }
        }
        let (mut service, deferred) =
            FirstSliceService::open_durable_deferred(2, paths.state_dir())
                .expect("deferred service opens");
        let prepared = thread::scope(|scope| {
            let workers = receipts
                .iter()
                .map(|(_, active)| {
                    let deferred = &deferred;
                    let cancellation = &cancellation;
                    scope.spawn(move || {
                        let restored =
                            deferred.restore_active_repository(active.repository, cancellation)?;
                        assert_eq!(
                            restored.generation_ids(),
                            BTreeSet::from([active.generation])
                        );
                        restored.prepare_active_installation(cancellation)
                    })
                })
                .collect::<Vec<_>>();
            workers
                .into_iter()
                .map(|worker| worker.join().expect("active worker joins"))
                .collect::<Result<Vec<_>, _>>()
        })
        .expect("independent active repositories restore concurrently");
        // Completion order must not replace the durable global activation order.
        for prepared in prepared.into_iter().rev() {
            service
                .install_prepared_progressive_deferred_restore(prepared, &cancellation)
                .expect("prepared active generation installs");
        }
        let latest = receipts
            .last()
            .expect("two repositories were published")
            .1
            .generation;
        assert_eq!(
            service
                .most_recent_activation
                .map(|(_, generation)| generation),
            Some(latest)
        );

        let retained = thread::scope(|scope| {
            let workers = receipts
                .iter()
                .map(|(retained, active)| {
                    let deferred = &deferred;
                    let cancellation = &cancellation;
                    scope.spawn(move || {
                        let restored = deferred.restore_retained_repository(
                            active.repository,
                            &BTreeSet::from([active.generation]),
                            cancellation,
                        )?;
                        assert_eq!(
                            restored.generation_ids(),
                            BTreeSet::from([retained.generation])
                        );
                        Ok::<_, FirstSliceError>(restored)
                    })
                })
                .collect::<Vec<_>>();
            workers
                .into_iter()
                .map(|worker| worker.join().expect("retained worker joins"))
                .collect::<Result<Vec<_>, _>>()
        })
        .expect("independent retained repositories restore concurrently");
        for retained in retained {
            service
                .install_additional_deferred_restore(retained, &cancellation)
                .expect("retained generation installs");
        }
        assert_eq!(service.receipts.len(), 4);
        assert_eq!(
            service
                .most_recent_activation
                .map(|(_, generation)| generation),
            Some(latest)
        );
        for (retained, active) in receipts {
            assert_eq!(
                service.active_generation_for(active.repository),
                Some(active.generation)
            );
            for (receipt, identifier) in [(retained, "retained_answer"), (active, "active_answer")]
            {
                assert_eq!(service.receipts.get(&receipt.generation), Some(&receipt));
                let located = service
                    .code_locate(
                        receipt.generation,
                        identifier.to_owned(),
                        LocateMode::Exact,
                        8,
                        0,
                        &cancellation,
                    )
                    .expect("generation-specific lookup succeeds");
                assert!(
                    located
                        .data
                        .hits
                        .iter()
                        .any(|hit| hit.identifier == identifier)
                );
            }
        }
    }

    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    #[test]
    fn synchronous_durable_restore_releases_each_repository_batch() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let repositories = [durable_test_tempdir(), durable_test_tempdir()];
        let cancellation = deadline();
        let mut expected = BTreeSet::new();
        let mut active = BTreeMap::new();
        {
            let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
                .expect("durable service initializes");
            for (ordinal, repository) in repositories.iter().enumerate() {
                let source = repository.path().join("lib.rs");
                fs::write(
                    &source,
                    format!("pub fn value_{ordinal}() -> u32 {{ 1 }}\n"),
                )
                .expect("initial fixture source writes");
                let first = service
                    .index_rust_fixture(repository.path(), &cancellation)
                    .expect("initial generation publishes");
                fs::write(
                    &source,
                    format!("pub fn value_{ordinal}() -> u32 {{ 2 }}\n"),
                )
                .expect("successor fixture source writes");
                let second = service
                    .index_rust_fixture(repository.path(), &cancellation)
                    .expect("successor generation publishes");
                expected.extend([first.generation, second.generation]);
                active.insert(second.repository, second.generation);
            }
        }

        let (_, deferred) = FirstSliceService::open_durable_deferred(2, paths.state_dir())
            .expect("deferred durable service opens");
        let mut observed = BTreeSet::new();
        let mut nonempty_batches = 0_usize;
        let mut visiting_repository = None;
        let mut completed_repositories = BTreeSet::new();
        deferred
            .durable
            .restore_progressively(&cancellation, |event| {
                match event {
                    durable::ProgressiveRestoreEvent::Generation(generation) => {
                        let repository = generation.receipt.repository;
                        if let Some(visiting) = visiting_repository {
                            assert_eq!(repository, visiting);
                        } else {
                            assert!(!completed_repositories.contains(&repository));
                            assert_eq!(
                                active.get(&repository),
                                Some(&generation.receipt.generation)
                            );
                            visiting_repository = Some(repository);
                        }
                        nonempty_batches = nonempty_batches
                            .checked_add(1)
                            .ok_or(FirstSliceError::Limits)?;
                        assert!(observed.insert(generation.receipt.generation));
                    }
                    durable::ProgressiveRestoreEvent::RepositoryComplete {
                        repository,
                        published_generation_count,
                        ..
                    } => {
                        assert_eq!(visiting_repository.take(), Some(repository));
                        assert_eq!(published_generation_count, 2);
                        assert!(completed_repositories.insert(repository));
                    }
                }
                Ok(())
            })
            .expect("durable restore visits one verified generation at a time");
        assert_eq!(nonempty_batches, expected.len());
        assert!(visiting_repository.is_none());
        assert_eq!(completed_repositories.len(), repositories.len());
        assert_eq!(observed, expected);

        let restored = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
            .expect("synchronous durable service restores progressively");
        for (repository, generation) in active {
            assert_eq!(restored.active_generation_for(repository), Some(generation));
        }
    }

    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    #[test]
    fn deferred_bootstrap_preserves_identity_across_concurrent_publication() {
        fn global_activation_sequence(
            paths: &RuntimePaths,
            receipt: &FirstSliceIndexReceipt,
        ) -> u64 {
            let generation = receipt.generation.to_string();
            let repository = paths
                .state_dir()
                .join("first-slice/repositories")
                .join(receipt.repository.to_string());
            fs::read_dir(repository)
                .expect("repository directory reads")
                .map(|entry| entry.expect("repository entry reads"))
                .find_map(|entry| {
                    entry
                        .file_name()
                        .to_str()
                        .is_some_and(|name| name.starts_with("activation-"))
                        .then(|| {
                            serde_json::from_slice::<serde_json::Value>(
                                &fs::read(entry.path().join("activation.json"))
                                    .expect("activation manifest reads"),
                            )
                            .expect("activation manifest parses")
                        })
                        .filter(|manifest| {
                            manifest["generation"].as_str() == Some(generation.as_str())
                        })
                })
                .and_then(|manifest| manifest["global_activation_sequence"].as_u64())
                .expect("global activation sequence is present")
        }

        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let old_fixtures = [durable_test_tempdir(), durable_test_tempdir()];
        for (ordinal, fixture) in old_fixtures.iter().enumerate() {
            fs::write(
                fixture.path().join("lib.rs"),
                format!("pub fn old_{ordinal}() -> u32 {{ {ordinal} }}\n"),
            )
            .expect("old fixture source writes");
        }
        let new_fixture = durable_test_tempdir();
        fs::write(
            new_fixture.path().join("lib.rs"),
            "pub fn newly_published() -> u32 { 3 }\n",
        )
        .expect("new fixture source writes");
        let cancellation = deadline();

        let old_receipts = {
            let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
                .expect("durable service initializes");
            old_fixtures
                .iter()
                .map(|fixture| {
                    service
                        .index_rust_fixture(fixture.path(), &cancellation)
                        .expect("old durable generation publishes")
                })
                .collect::<Vec<_>>()
        };

        let (mut service, deferred) =
            FirstSliceService::open_durable_deferred(2, paths.state_dir())
                .expect("deferred durable service opens");
        assert!(service.list_repositories().is_empty());
        for (fixture, receipt) in old_fixtures.iter().zip(&old_receipts) {
            assert_eq!(
                service
                    .registered_repository_for_root(fixture.path(), &cancellation)
                    .expect("bootstrapped root registration resolves"),
                Some(receipt.repository)
            );
        }

        let new_receipt = service
            .index_rust_fixture(new_fixture.path(), &cancellation)
            .expect("new repository publishes before payload restore");
        assert!(
            old_receipts
                .iter()
                .all(|receipt| receipt.repository != new_receipt.repository)
        );
        for target in deferred
            .active_targets()
            .expect("bootstrapped recovery targets remain available")
        {
            let restored = deferred
                .restore_active_repository(target.repository(), &cancellation)
                .expect("old active generation verifies");
            service
                .install_progressive_deferred_restore(restored, &cancellation)
                .expect("old active generation installs progressively");
        }
        for receipt in &old_receipts {
            assert_eq!(
                service.active_generation_for(receipt.repository),
                Some(receipt.generation)
            );
        }
        assert_eq!(
            service.active_generation_for(new_receipt.repository),
            Some(new_receipt.generation)
        );
        fs::write(
            old_fixtures[0].path().join("lib.rs"),
            "pub fn old_0_updated() -> u32 { 10 }\n",
        )
        .expect("old fixture update writes");
        let updated_old_receipt = service
            .index_rust_fixture(old_fixtures[0].path(), &cancellation)
            .expect("restored repository publishes with its bootstrapped frontier");
        assert_eq!(updated_old_receipt.repository, old_receipts[0].repository);
        drop(service);

        let mut activation_sequences = old_receipts
            .iter()
            .map(|receipt| global_activation_sequence(&paths, receipt))
            .collect::<Vec<_>>();
        let new_activation_sequence = global_activation_sequence(&paths, &new_receipt);
        let updated_activation_sequence = global_activation_sequence(&paths, &updated_old_receipt);
        assert!(
            activation_sequences
                .iter()
                .all(|sequence| *sequence < new_activation_sequence)
        );
        assert!(updated_activation_sequence > new_activation_sequence);
        activation_sequences.push(new_activation_sequence);
        activation_sequences.push(updated_activation_sequence);
        activation_sequences.sort_unstable();
        activation_sequences.dedup();
        assert_eq!(activation_sequences.len(), 4);

        let reopened = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
            .expect("fully populated catalog reopens cleanly");
        for receipt in [&updated_old_receipt, &old_receipts[1], &new_receipt] {
            assert_eq!(
                reopened.active_generation_for(receipt.repository),
                Some(receipt.generation)
            );
        }
    }

