    #[test]
    fn generation_memory_reservations_bound_concurrent_admission_and_cancelled_workers() {
        for duplicate_identity in [false, true] {
            let service = FirstSliceService::new(2).expect("service initializes");
            let cancellation = Cancellation::new();
            let charge = MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES / 2;
            let (ready_sender, ready_receiver) = mpsc::sync_channel(4);
            let (outcomes, reserved) = thread::scope(|scope| {
                let mut workers = Vec::new();
                let mut releases = Vec::new();
                for identity in 1_u8..=4 {
                    let service = &service;
                    let cancellation = &cancellation;
                    let ready_sender = ready_sender.clone();
                    let (release, released) = mpsc::sync_channel(1);
                    releases.push(release);
                    workers.push(scope.spawn(move || {
                        let generation = GenerationId::from_bytes(
                            [if duplicate_identity { 1 } else { identity }; 20],
                        );
                        let reservation = service.reserve_generation_memory(
                            generation,
                            charge,
                            PendingGenerationMemory::Reserved,
                        );
                        ready_sender
                            .send(reservation.as_ref().map(|_| ()).map_err(|error| *error))
                            .expect("admission outcome sends");
                        // Keep every successful charge live until all contenders
                        // have attempted admission; thread scheduling cannot free capacity.
                        released
                            .recv_timeout(Duration::from_secs(10))
                            .expect("coordinator releases the worker");
                        let _reservation = reservation?;
                        check_cancellation(cancellation)
                    }));
                }
                drop(ready_sender);
                let outcomes = (0..4)
                    .map(|_| {
                        ready_receiver
                            .recv_timeout(Duration::from_secs(10))
                            .expect("every contender reports admission")
                    })
                    .collect::<Vec<_>>();
                let reserved = service
                    .generation_cache
                    .lock()
                    .expect("cache remains available")
                    .reserved_memory_bytes()
                    .expect("aggregate charge is representable");
                let _ = cancellation.cancel(CancellationReason::Shutdown);
                for release in releases {
                    release.send(()).expect("worker is awaiting release");
                }
                let completed = workers
                    .into_iter()
                    .map(|worker| worker.join().expect("worker joins"))
                    .collect::<Vec<_>>();
                let admitted = outcomes.iter().filter(|outcome| outcome.is_ok()).count();
                assert_eq!(
                    completed
                        .iter()
                        .filter(|outcome| {
                            **outcome
                                == Err(FirstSliceError::Cancelled(CancellationReason::Shutdown))
                        })
                        .count(),
                    admitted
                );
                (outcomes, reserved)
            });

            let expected_admitted = if duplicate_identity { 1 } else { 2 };
            assert_eq!(
                outcomes.iter().filter(|outcome| outcome.is_ok()).count(),
                expected_admitted
            );
            assert_eq!(
                reserved,
                if duplicate_identity {
                    charge
                } else {
                    charge * 2
                }
            );
            for error in outcomes.into_iter().filter_map(Result::err) {
                if duplicate_identity {
                    assert_eq!(error, FirstSliceError::CatalogCorrupt);
                } else {
                    assert_eq!(
                        error,
                        generation_memory_limit(0, charge * 3, PendingGenerationMemory::Reserved)
                    );
                }
            }
            assert!(
                service
                    .generation_cache
                    .lock()
                    .expect("cache remains available")
                    .reservations
                    .is_empty()
            );
            let retry = service
                .reserve_generation_memory(
                    GenerationId::from_bytes([1; 20]),
                    MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES,
                    PendingGenerationMemory::Reserved,
                )
                .expect("joined cancelled workers release the entire budget and identity");
            drop(retry);
        }
    }

    #[test]
    fn generation_output_admission_preserves_active_state_under_pressure() {
        let fixture = TempDir::new().expect("fixture root exists");
        let source = "pub fn old_value() -> bool { true }\n";
        fs::write(fixture.path().join("lib.rs"), source).expect("initial source writes");
        let mut service = FirstSliceService::new(2).expect("service initializes");
        let active = service
            .index_repository(fixture.path(), &deadline())
            .expect("initial generation publishes");
        let successor = "pub fn new_value() -> bool { true }\n";
        fs::write(fixture.path().join("lib.rs"), successor).expect("successor source writes");
        let source_floor = ensure_generation_memory_preflight(
            u64::try_from(successor.len()).expect("fixture source size fits"),
        )
        .expect("source preflight fits");
        let resident = service
            .generation_cache
            .lock()
            .expect("cache opens")
            .resident_logical_charge_bytes()
            .expect("resident charge reads");
        let other_id = GenerationId::from_bytes([237; 20]);
        let other_bytes = MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES - resident - source_floor;
        let other = service
            .reserve_generation_memory(other_id, other_bytes, PendingGenerationMemory::Reserved)
            .expect("another preparation leaves exactly the source preflight allowance");

        let result = service.prepare_repository(fixture.path(), &deadline());
        match result {
            Ok(_) => panic!("completed output was accepted with only source allowance"),
            Err(error) => assert!(
                matches!(error, FirstSliceError::GenerationMemoryLimit { .. }),
                "unexpected preparation failure: {error:?}"
            ),
        }
        assert_eq!(
            service.active_generation_for(active.repository),
            Some(active.generation)
        );
        assert_eq!(service.receipts.len(), 1);
        {
            let cache = service.generation_cache.lock().expect("cache opens");
            assert_eq!(cache.reservations.len(), 1);
            assert_eq!(cache.reservations.get(&other_id), Some(&other_bytes));
            assert!(cache.generations.is_loaded(active.generation));
        }
        let located = service
            .code_locate(
                active.generation,
                "old_value".to_owned(),
                LocateMode::Exact,
                4,
                0,
                &deadline(),
            )
            .expect("active generation remains queryable");
        assert!(located.data.hits.iter().any(|hit| hit.symbol.is_some()));
        drop(other);
        let prepared = service
            .prepare_repository(fixture.path(), &deadline())
            .expect("released capacity admits a clean retry");
        let next = service
            .publish_prepared(prepared, &deadline())
            .expect("retried successor publishes");
        assert_eq!(next.parent, Some(active.generation));
        assert_eq!(
            service.active_generation_for(active.repository),
            Some(next.generation)
        );
        assert!(
            service
                .generation_cache
                .lock()
                .expect("cache opens")
                .reservations
                .is_empty()
        );
    }

    #[test]
    fn generation_memory_reservation_failed_growth_preserves_other_owners() {
        let service = FirstSliceService::new(2).expect("service initializes");
        let charge = MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES / 2;
        let first_id = GenerationId::from_bytes([1; 20]);
        let second_id = GenerationId::from_bytes([2; 20]);
        let mut first = service
            .reserve_generation_memory(first_id, charge, PendingGenerationMemory::Reserved)
            .expect("first half of the budget reserves");
        let second = service
            .reserve_generation_memory(second_id, charge, PendingGenerationMemory::Reserved)
            .expect("second half of the budget reserves");

        assert!(matches!(
            first.resize(charge + 1, PendingGenerationMemory::Reserved, true),
            Err(FirstSliceError::GenerationMemoryLimit { observed, .. })
                if observed == MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES + 1
        ));
        {
            let cache = service
                .generation_cache
                .lock()
                .expect("cache remains available");
            assert_eq!(cache.reservations.get(&first_id), Some(&charge));
            assert_eq!(cache.reservations.get(&second_id), Some(&charge));
        }
        drop(second);
        first
            .resize(
                MAX_FIRST_SLICE_GENERATION_MEMORY_BYTES,
                PendingGenerationMemory::Reserved,
                true,
            )
            .expect("released capacity admits growth");
        drop(first);
        assert!(
            service
                .generation_cache
                .lock()
                .expect("cache remains available")
                .reservations
                .is_empty()
        );
    }

