    #[test]
    fn structural_fact_preflight_preserves_fitting_demand_across_weight_changes() {
        let base = analysis_limits(16 * 1024 * 1024).unwrap();
        let limits = analysis_limits_with_syntax_records(&base, 20).unwrap();
        let first = FileId::from_bytes([1; 20]);
        let second = FileId::from_bytes([2; 20]);
        assert!(
            2 + partitioned_record_budget(16, 2, 17, 1).unwrap() < 7,
            "the prior weight-only policy clips fitting optional evidence"
        );
        for weight in [0, 1, 16, usize::MAX - 1] {
            let requirements = BTreeMap::from([
                (
                    first,
                    StructuralFactRequirement {
                        weight: 1,
                        required: 2,
                        complete_records: Some(7),
                    },
                ),
                (
                    second,
                    StructuralFactRequirement {
                        weight,
                        required: 2,
                        complete_records: Some(2),
                    },
                ),
            ]);
            let partitions =
                required_structural_analysis_limits(&limits, &requirements, &deadline()).unwrap();
            assert_eq!(partitions[&first].syntax_stream().max_records(), 7);
            assert_eq!(partitions[&second].syntax_stream().max_records(), 2);
        }
        let equal = StructuralFactRequirement {
            weight: 0,
            required: 0,
            complete_records: Some(0),
        };
        let zero = BTreeMap::from([(first, equal), (second, equal)]);
        let one_record = analysis_limits_with_syntax_records(&base, 1).unwrap();
        assert_eq!(
            required_structural_analysis_limits(&one_record, &zero, &deadline()),
            Err(FirstSliceError::ResourceLimit {
                resource: FirstSliceResource::Records,
                observed: 2,
                limit: 1
            })
        );
        let invalid = BTreeMap::from([(
            first,
            StructuralFactRequirement {
                required: 2,
                complete_records: Some(1),
                ..equal
            },
        )]);
        assert_eq!(
            required_structural_analysis_limits(&limits, &invalid, &deadline()),
            Err(FirstSliceError::Identity)
        );
        let cancelled = deadline();
        cancelled.cancel(CancellationReason::ClientRequest);
        assert!(required_structural_analysis_limits(&limits, &zero, &cancelled).is_err());
    }

    #[test]
    fn structural_fact_preflight_conserves_oversubscribed_optional_demand() {
        let base = analysis_limits(16 * 1024 * 1024).unwrap();
        for budget in 3..=15 {
            let limits = analysis_limits_with_syntax_records(&base, budget).unwrap();
            for weights in [[0, 0, 0], [1, 1, 1], [0, 1, 16], [16, 1, 0]] {
                for capacities in [[1, 1, 1], [1, 3, 20], [3, 7, 11], [20, 20, 20]] {
                    let requirements = weights
                        .into_iter()
                        .zip(capacities)
                        .enumerate()
                        .map(|(index, (weight, count))| {
                            (
                                FileId::from_bytes([u8::try_from(index).unwrap(); 20]),
                                StructuralFactRequirement {
                                    weight,
                                    required: 1,
                                    complete_records: Some(count),
                                },
                            )
                        })
                        .collect::<BTreeMap<_, _>>();
                    let partitions =
                        required_structural_analysis_limits(&limits, &requirements, &deadline())
                            .unwrap();
                    assert_eq!(
                        partitions
                            .values()
                            .map(|limit| limit.syntax_stream().max_records())
                            .sum::<usize>(),
                        budget.min(capacities.into_iter().sum()),
                        "budget={budget} weights={weights:?} capacities={capacities:?}"
                    );
                    for (file, requirement) in &requirements {
                        let quota = partitions[file].syntax_stream().max_records();
                        assert!(
                            quota >= requirement.required && quota <= requirement.capacity(budget)
                        );
                    }
                    let reversed = requirements
                        .iter()
                        .rev()
                        .map(|(file, requirement)| (*file, *requirement))
                        .collect();
                    assert_eq!(
                        partitions,
                        required_structural_analysis_limits(&limits, &reversed, &deadline())
                            .unwrap()
                    );
                }
            }
        }
        let limits = analysis_limits_with_syntax_records(&base, 20).unwrap();
        let known = FileId::from_bytes([1; 20]);
        let unknown = FileId::from_bytes([2; 20]);
        let requirements = BTreeMap::from([
            (
                known,
                StructuralFactRequirement {
                    weight: 1,
                    required: 2,
                    complete_records: Some(2),
                },
            ),
            (
                unknown,
                StructuralFactRequirement {
                    weight: 0,
                    required: 2,
                    complete_records: None,
                },
            ),
        ]);
        let partitions =
            required_structural_analysis_limits(&limits, &requirements, &deadline()).unwrap();
        assert_eq!(partitions[&known].syntax_stream().max_records(), 2);
        assert_eq!(partitions[&unknown].syntax_stream().max_records(), 18);
    }

    #[test]
    fn repository_analysis_preserves_fitting_optional_evidence_after_weight_only_edit() {
        let fixture = TempDir::new().unwrap();
        fs::write(
            fixture.path().join("read.rs"),
            "fn read(value: i32) -> i32 { value }\n",
        )
        .unwrap();
        fs::write(fixture.path().join("anchor.rs"), "fn anchor() {}\n").unwrap();
        let cancellation = deadline();
        let mut service = FirstSliceService::new(3).unwrap();
        service.analysis_limits =
            analysis_limits_with_syntax_records(&service.analysis_limits, 20).unwrap();
        let first = service
            .index_repository_with_mode(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &cancellation,
            )
            .unwrap();
        let snapshot = service
            .loaded_generation_snapshot(first.generation)
            .unwrap();
        assert!(
            !snapshot
                .document()
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == "syntax-extraction-limit")
        );
        let read_file = snapshot
            .document()
            .files
            .iter()
            .find(|file| file.path == "read.rs")
            .unwrap()
            .id;
        let mut optional_reads = snapshot
            .document()
            .occurrences
            .iter()
            .filter(|occurrence| {
                occurrence.role == rootlight_ir::OccurrenceRole::Reference
                    && occurrence.source.span().file() == read_file
            })
            .map(|occurrence| (occurrence.source.span(), occurrence.target.clone()))
            .collect::<Vec<_>>();
        // Fact IDs are generation-bound; compare unchanged evidence in source order.
        optional_reads.sort_by_key(|(span, _)| *span);
        assert!(!optional_reads.is_empty());
        drop(snapshot);
        fs::write(
            fixture.path().join("anchor.rs"),
            format!("fn anchor() {{ {} }}\n", " ".repeat(8192)),
        )
        .unwrap();
        let successor = service
            .index_repository_with_mode(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &cancellation,
            )
            .unwrap();
        let snapshot = service
            .loaded_generation_snapshot(successor.generation)
            .unwrap();
        assert!(
            !snapshot
                .document()
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == "syntax-extraction-limit")
        );
        let mut successor_reads = snapshot
            .document()
            .occurrences
            .iter()
            .filter(|occurrence| {
                occurrence.role == rootlight_ir::OccurrenceRole::Reference
                    && occurrence.source.span().file() == read_file
            })
            .map(|occurrence| (occurrence.source.span(), occurrence.target.clone()))
            .collect::<Vec<_>>();
        successor_reads.sort_by_key(|(span, _)| *span);
        assert_eq!(successor_reads, optional_reads);
        drop(snapshot);
        let work = service.incremental_evidence(successor.generation).unwrap();
        assert_eq!(work.parsed_files(), 1);
        assert_eq!(work.reused_parser_artifacts(), 1);
        assert_fresh_equivalent(
            &service,
            fixture.path(),
            first.generation,
            &successor,
            &cancellation,
        );
        let noop = service
            .index_repository_with_mode(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &cancellation,
            )
            .unwrap();
        assert_eq!(noop.generation, successor.generation);
    }

    #[test]
    fn repository_analysis_preserves_demand_after_local_batch_rejection() {
        let fixture = TempDir::new().unwrap();
        let sources = [
            (
                "clipped.rs",
                "fn alpha(value: i32) { value; }\nfn beta(value: i32) { value; }\nfn gamma(value: i32) { value; }\nfn omega(value: i32) { value; }\n",
            ),
            (
                "neighbor.rs",
                "fn first() {}\nfn second() {}\nfn third() {}\n",
            ),
        ];
        for (path, source) in sources {
            fs::write(fixture.path().join(path), source).unwrap();
        }
        let service = FirstSliceService::new(2).unwrap();
        let defaults = service.analysis_limits.clone();
        let repository = derive_repository(b"bounded-mandatory-demand").id();
        let root = RepositoryRoot::open(repository, fixture.path()).unwrap();
        let cancellation = deadline();
        let generation = GenerationId::from_bytes([1; 20]);
        let mut maximum_required = 0;
        for (path, source) in sources {
            let relative = RelativePath::parse(Path::new(path)).unwrap();
            let snapshot = root
                .snapshot(&relative, u64::try_from(source.len()).unwrap())
                .unwrap();
            let request = structural_analysis_request(
                repository, generation, &snapshot, false, "rust", "utf-8", &defaults,
            )
            .unwrap();
            maximum_required = maximum_required.max(
                service.structural_parsers["rust"]
                    .required_syntax_fact_count(&request.to_parse_request(), &cancellation)
                    .unwrap(),
            );
        }
        let batch_records = maximum_required.div_ceil(2);
        let base = &service.analysis_limits;
        let stream = base.syntax_stream();
        let batch = stream.batch();
        let syntax = StreamLimits::new(
            2,
            maximum_required,
            stream.max_output_bytes(),
            stream.max_diagnostics(),
            stream.max_diagnostic_bytes(),
            stream.max_string_bytes(),
            BatchThresholds::new(
                batch_records,
                batch.max_output_bytes(),
                batch.max_diagnostics(),
                batch.max_diagnostic_bytes(),
            )
            .unwrap(),
        )
        .unwrap();
        let bounded = AnalysisLimits::new(
            base.max_source_bytes(),
            base.max_syntax_nodes(),
            base.max_syntax_depth(),
            base.max_embedded_ranges(),
            base.max_reported_memory_bytes(),
            syntax,
            base.ir_stream().clone(),
            base.ir().clone(),
        )
        .unwrap();
        let mut required = 0;
        let mut complete_required = 0;
        let mut rejected = 0;
        for (path, source) in sources {
            let relative = RelativePath::parse(Path::new(path)).unwrap();
            let snapshot = root
                .snapshot(&relative, u64::try_from(source.len()).unwrap())
                .unwrap();
            let request = structural_analysis_request(
                repository, generation, &snapshot, false, "rust", "utf-8", &bounded,
            )
            .unwrap();
            let demand = service.structural_parsers["rust"]
                .required_syntax_fact_count(&request.to_parse_request(), &cancellation)
                .unwrap();
            required += demand;
            match service.analyzers["rust"].prepare_artifact(&request, &cancellation) {
                Ok(artifact) => assert_eq!(
                    artifact.required_syntax_fact_count(&cancellation).unwrap(),
                    demand,
                ),
                Err(error) => {
                    assert!(
                        matches!(
                            error,
                            AdapterError::Sink(SinkError::StreamLimit {
                                resource: ResourceKind::Batches,
                                observed: 2,
                                limit: 1,
                            })
                        ),
                        "unexpected local rejection: {error:?}"
                    );
                    assert!(demand > batch_records && demand <= maximum_required);
                    rejected += 1;
                }
            }
            let complete_request = structural_analysis_request(
                repository, generation, &snapshot, false, "rust", "utf-8", &defaults,
            )
            .unwrap();
            let artifact = service.analyzers["rust"]
                .prepare_artifact(&complete_request, &cancellation)
                .unwrap();
            assert!(artifact.syntax_partition_complete());
            let complete = artifact.required_syntax_fact_count(&cancellation).unwrap();
            assert_eq!(complete, demand);
            complete_required += complete;
        }
        assert!(rejected > 0 && required > maximum_required);
        assert_eq!(complete_required, required);
        let mut service = service;
        service.analysis_limits = bounded;
        assert!(matches!(
            service.prepare_rust_fixture(fixture.path(), &cancellation),
            Err(FirstSliceError::ResourceLimit {
                resource: FirstSliceResource::Batches,
                observed: 2,
                limit: 1,
            })
        ));
        assert!(service.active_by_repository.is_empty());
        // Isolate the repository-wide record ceiling from per-file batch
        // rejection; both must retain exact, independent mandatory demand.
        service.analysis_limits =
            analysis_limits_with_syntax_records(&defaults, maximum_required).unwrap();
        let required = u64::try_from(required).unwrap();
        assert!(
            matches!(service.prepare_rust_fixture(fixture.path(), &cancellation),
            Err(FirstSliceError::ResourceLimit { resource: FirstSliceResource::RequiredSyntaxFacts, observed, limit })
                if observed == required && limit == u64::try_from(maximum_required).unwrap())
        );
        assert!(service.active_by_repository.is_empty());
        service.analysis_limits = defaults;
        let recovered = service
            .index_repository_with_mode(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &cancellation,
            )
            .unwrap();
        let mut fresh = FirstSliceService::new(2).unwrap();
        // Keep the registered repository identity while rebuilding without caches.
        fresh.repositories = service.repositories.clone();
        let rebuilt = fresh
            .index_repository_with_mode(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &cancellation,
            )
            .unwrap();
        assert_eq!(recovered.repository, rebuilt.repository);
        equivalence_snapshot(&service, recovered.generation, &cancellation)
            .compare_clean(
                &equivalence_snapshot(&fresh, rebuilt.generation, &cancellation),
                &cancellation,
            )
            .unwrap()
            .require_equivalent()
            .unwrap();
        assert_eq!(recovered.logical_snapshot, rebuilt.logical_snapshot);
    }

    #[test]
    fn repository_analysis_preserves_frontend_declared_mandatory_facts() {
        let fixture = TempDir::new().unwrap();
        let sources = [
            (
                "first.awk",
                format!("function first() {{ {} }}\n", "dependency(); ".repeat(10)),
            ),
            (
                "second.awk",
                format!("function second() {{ {} }}\n", "dependency(); ".repeat(10)),
            ),
        ];
        for (path, source) in &sources {
            fs::write(fixture.path().join(path), source).unwrap();
        }
        let service = FirstSliceService::new(2).unwrap();
        let limits = analysis_limits_with_syntax_records(&service.analysis_limits, 20).unwrap();
        let repository = derive_repository(b"frontend-mandatory-demand").id();
        let root = RepositoryRoot::open(repository, fixture.path()).unwrap();
        let generation = GenerationId::from_bytes([1; 20]);
        let cancellation = deadline();
        let parser = &service.structural_parsers["awk"];
        let limits = provider_analysis_limits(&limits, parser.capabilities()).unwrap();
        assert!(!parser.supports_retained_identity_preflight());
        let mut required = 0;
        let mut maximum_required = 0;
        let mut generic_identity = 0;
        for (path, source) in &sources {
            let relative = RelativePath::parse(Path::new(path)).unwrap();
            let snapshot = root
                .snapshot(&relative, u64::try_from(source.len()).unwrap())
                .unwrap();
            let request = structural_analysis_request(
                repository, generation, &snapshot, false, "awk", "utf-8", &limits,
            )
            .unwrap();
            let demand = parser
                .required_syntax_fact_count(&request.to_parse_request(), &cancellation)
                .unwrap();
            let artifact = service.analyzers["awk"]
                .prepare_artifact(&request, &cancellation)
                .unwrap();
            assert!(artifact.syntax_partition_complete());
            assert_eq!(demand, artifact.syntax_fact_count());
            required += demand;
            maximum_required = maximum_required.max(demand);
            generic_identity += artifact.required_syntax_fact_count(&cancellation).unwrap();
        }
        assert!(generic_identity <= 20 && required > 20);
        assert!(maximum_required <= 20);
        assert!(!project_adapter_supports_language("awk"));
        let mut service = service;
        service.analysis_limits = limits;
        let prepared = service
            .prepare_repository_with_mode(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &cancellation,
            )
            .expect("each streamed file admits the frontend's full mandatory set");
        let FirstSliceIndexPreparation::Pending(pending) = &prepared else {
            panic!("initial streamed files must prepare a generation");
        };
        assert_eq!(pending.structural_artifacts.len(), 2);
        assert_eq!(
            pending
                .structural_artifacts
                .iter()
                .map(|(_, entry)| {
                    assert!(entry.artifact.syntax_partition_complete());
                    entry.artifact.syntax_fact_count()
                })
                .sum::<usize>(),
            required,
        );
        assert!(service.active_by_repository.is_empty());
        let complete = service.publish_prepared(prepared, &cancellation).unwrap();
        assert_eq!(
            service
                .loaded_generation_snapshot(complete.generation)
                .unwrap()
                .document()
                .occurrences
                .iter()
                .filter(|occurrence| occurrence.role == OccurrenceRole::CallSite)
                .count(),
            20,
        );

        let parent_fixture = TempDir::new().unwrap();
        fs::write(parent_fixture.path().join(sources[0].0), &sources[0].1).unwrap();
        let mut parent_service = FirstSliceService::new(2).unwrap();
        parent_service.analysis_limits =
            analysis_limits_with_syntax_records(&parent_service.analysis_limits, 20).unwrap();
        let parent = parent_service
            .index_repository_with_mode(
                parent_fixture.path(),
                FirstSliceIndexMode::Structural,
                &cancellation,
            )
            .unwrap();
        assert_eq!(
            parent_service
                .incremental_evidence(parent.generation)
                .unwrap()
                .parsed_files(),
            1
        );
        fs::write(parent_fixture.path().join(sources[1].0), &sources[1].1).unwrap();
        let successor = parent_service
            .index_repository_with_mode(
                parent_fixture.path(),
                FirstSliceIndexMode::Structural,
                &cancellation,
            )
            .expect("a reused parent preserves full frontend demand beside the added file");
        let evidence = parent_service
            .incremental_evidence(successor.generation)
            .unwrap();
        assert_eq!(evidence.parsed_files(), 1);
        assert_eq!(evidence.reused_parser_artifacts(), 1);
        assert_eq!(
            parent_service
                .loaded_generation_snapshot(successor.generation)
                .unwrap()
                .document()
                .occurrences
                .iter()
                .filter(|occurrence| occurrence.role == OccurrenceRole::CallSite)
                .count(),
            20,
        );
        let individual_limit = maximum_required - 1;
        parent_service.analysis_limits =
            analysis_limits_with_syntax_records(&parent_service.analysis_limits, individual_limit)
                .unwrap();
        assert_eq!(
            parent_service
                .prepare_repository_with_options(
                    parent_fixture.path(),
                    FirstSliceIndexOptions::clean_rebuild(FirstSliceIndexMode::Structural),
                    &cancellation,
                )
                .err(),
            Some(resource_limit(
                FirstSliceResource::RequiredSyntaxFacts,
                maximum_required,
                individual_limit,
            )),
            "a genuine per-file frontend overflow must still reject",
        );
        assert_eq!(
            parent_service.active_generation(),
            Some(successor.generation)
        );
        assert_eq!(successor.parent, Some(parent.generation));
    }

    #[test]
    fn body_edit_reuses_unchanged_bounded_markdown() {
        let fixture = TempDir::new().expect("fixture root exists");
        let mut markdown = (0..40)
            .map(|index| format!("~~~rust\nfn example_{index}() {{}}\n~~~\n\n"))
            .collect::<String>();
        markdown.push_str(&format!(
            "> ~~~rust\n{}> ~~~\n",
            "> let value = 1;\n".repeat(33)
        ));
        fs::write(fixture.path().join("guide.md"), markdown).expect("independent document writes");
        fs::write(fixture.path().join("value.rs"), "fn value() -> u32 { 1 }\n")
            .expect("initial function writes");
        let cancellation = deadline();
        let mut service = FirstSliceService::new(3).expect("service initializes");
        let baseline = service
            .index_repository_with_mode(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &cancellation,
            )
            .expect("baseline publishes");
        let snapshot = service
            .loaded_generation_snapshot(baseline.generation)
            .expect("baseline remains readable");
        assert!(
            snapshot
                .document()
                .skipped_regions
                .iter()
                .any(|gap| { gap.detail == "markdown-code-budget-unavailable" })
        );
        drop(snapshot);
        // Cross a source-weight bucket without changing the callable's surface.
        fs::write(
            fixture.path().join("value.rs"),
            format!("fn value() -> u32 {{ {}2 }}\n", " ".repeat(48)),
        )
        .expect("body-only edit writes");
        let successor = service
            .index_repository_with_mode(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &cancellation,
            )
            .expect("successor publishes");
        let evidence = service
            .incremental_evidence(successor.generation)
            .expect("incremental work remains observable");
        assert_eq!(evidence.parsed_files(), 1);
        assert_eq!(evidence.reused_parser_artifacts(), 1);
        assert_fresh_equivalent(
            &service,
            fixture.path(),
            baseline.generation,
            &successor,
            &cancellation,
        );
    }

    #[test]
    fn repository_analysis_reserves_identity_demand_before_optional_facts() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = TempDir::new().expect("fixture root exists");
        let sparse = "// lexical_fallback_marker\nstruct SparseAnchor;\n";
        let dense = concat!(
            "// lexical_fallback_marker\n",
            "fn alpha() {}\n",
            "fn beta() {}\n",
            "fn gamma() {}\n",
            "fn delta() {}\n",
            "fn epsilon() {}\n",
        );
        fs::write(fixture.path().join("a.rs"), dense).expect("dense source writes");
        fs::write(fixture.path().join("z.rs"), sparse).expect("sparse source writes");

        let base = analysis_limits(16 * 1024 * 1024).expect("analysis limits are valid");
        let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &deadline())
            .expect("durable service initializes");
        let repository = derive_repository(b"identity-reservation-demand").id();
        let root = RepositoryRoot::open(repository, fixture.path()).unwrap();
        let generation = GenerationId::from_bytes([1; 20]);
        let mut required = BTreeMap::new();
        for (path, source) in [("a.rs", dense), ("z.rs", sparse)] {
            let relative = RelativePath::parse(Path::new(path)).unwrap();
            let snapshot = root
                .snapshot(&relative, u64::try_from(source.len()).unwrap())
                .unwrap();
            let request = structural_analysis_request(
                repository, generation, &snapshot, false, "rust", "utf-8", &base,
            )
            .unwrap();
            let artifact = service.analyzers["rust"]
                .prepare_artifact(&request, &deadline())
                .unwrap();
            assert!(artifact.syntax_partition_complete());
            let demand = artifact.required_syntax_fact_count(&deadline()).unwrap();
            assert!(
                artifact.syntax_fact_count() > demand,
                "source includes optional facts"
            );
            required.insert(path, demand);
        }
        let record_budget = required.values().sum();
        let limits = analysis_limits_with_syntax_records(&base, record_budget)
            .expect("the budget fits exactly the complete mandatory closure");
        let sparse_weight =
            analysis_partition_weight(sparse.len()).expect("sparse weight is valid");
        let dense_weight = analysis_partition_weight(dense.len()).expect("dense weight is valid");
        let total_weight = sparse_weight
            .checked_add(dense_weight)
            .expect("combined weight is valid");
        let dense_partition = partitioned_analysis_limits(&limits, 2, total_weight, dense_weight)
            .expect("dense partition is valid");
        assert!(
            dense_partition.syntax_stream().max_records() < required["a.rs"],
            "the static partition alone must be too small for five declaration closures"
        );

        service.analysis_limits = limits;
        let receipt = service
            .index_repository_with_mode(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &deadline(),
            )
            .expect("mandatory demand is reserved before optional facts");
        let snapshot = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("generation remains queryable");
        let document = snapshot.document();
        let names = document
            .entities
            .iter()
            .map(|entity| entity.canonical_name.as_str())
            .collect::<BTreeSet<_>>();
        for expected in ["SparseAnchor", "alpha", "beta", "gamma", "delta", "epsilon"] {
            assert!(names.contains(expected), "{expected} remains queryable");
        }
        assert!(
            document
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == "syntax-extraction-limit"),
            "optional fact truncation remains explicit"
        );
        let limited_file = document
            .diagnostics
            .iter()
            .find(|diagnostic| diagnostic.code == "syntax-extraction-limit")
            .and_then(|diagnostic| diagnostic.source.as_ref())
            .and_then(|source| snapshot.find_file(source.span().file()))
            .expect("bounded syntax diagnostic identifies its source file");
        let limited_file_id = limited_file.id;
        let limited_path = limited_file.path.clone();
        let limited_symbol = document
            .entities
            .iter()
            .find(|entity| {
                entity
                    .evidence
                    .source
                    .as_ref()
                    .is_some_and(|source| source.span().file() == limited_file_id)
            })
            .map(|entity| (entity.id, entity.display_name.clone()))
            .expect("bounded file retains a structural symbol");
        let out_of_scope_symbol = document
            .entities
            .iter()
            .find(|entity| {
                entity
                    .evidence
                    .source
                    .as_ref()
                    .is_some_and(|source| source.span().file() != limited_file_id)
            })
            .map(|entity| (entity.id, entity.display_name.clone()))
            .expect("the other file retains a negative-control symbol");
        let located = service
            .code_locate_with_filters_and_budget(
                receipt.generation,
                "lexical_fallback_marker".to_owned(),
                LocateMode::Text,
                Vec::new(),
                vec![limited_path.clone()],
                8,
                0,
                FirstSliceBudget::default(),
                &deadline(),
            )
            .expect("an exact file scope can recover bounded source text");
        assert!(located.data.hits.iter().any(|hit| {
            hit.symbol.is_none() && hit.file == limited_file_id && hit.path == limited_path
        }));
        let located_symbol = service
            .code_locate_with_filters_and_budget(
                receipt.generation,
                limited_symbol.1.clone(),
                LocateMode::Text,
                Vec::new(),
                vec![limited_path.clone()],
                8,
                0,
                FirstSliceBudget::default(),
                &deadline(),
            )
            .expect("source fallback preserves a structural symbol in the same file");
        assert!(
            located_symbol
                .data
                .hits
                .iter()
                .any(|hit| hit.symbol == Some(limited_symbol.0))
        );
        let out_of_scope = service
            .code_locate_with_filters_and_budget(
                receipt.generation,
                out_of_scope_symbol.1.clone(),
                LocateMode::Text,
                Vec::new(),
                vec![limited_path.clone()],
                8,
                0,
                FirstSliceBudget::default(),
                &deadline(),
            )
            .expect("exact source fallback scope remains bounded to one file");
        assert!(
            out_of_scope
                .data
                .hits
                .iter()
                .all(|hit| hit.symbol != Some(out_of_scope_symbol.0))
        );

        drop(service);
        let restored = FirstSliceService::new_durable(2, paths.state_dir(), &deadline())
            .expect("durable service restores");
        let restored_locate = restored
            .code_locate_with_filters_and_budget(
                receipt.generation,
                "lexical_fallback_marker".to_owned(),
                LocateMode::Text,
                Vec::new(),
                vec![limited_path.clone()],
                8,
                0,
                FirstSliceBudget::default(),
                &deadline(),
            )
            .expect("restored exact scope can recover bounded source text");
        assert!(
            restored_locate
                .data
                .hits
                .iter()
                .any(|hit| { hit.symbol.is_none() && hit.file == limited_file_id })
        );
        let restored_symbol = restored
            .code_locate_with_filters_and_budget(
                receipt.generation,
                limited_symbol.1,
                LocateMode::Text,
                Vec::new(),
                vec![limited_path.clone()],
                8,
                0,
                FirstSliceBudget::default(),
                &deadline(),
            )
            .expect("restored fallback preserves the same structural symbol");
        assert!(
            restored_symbol
                .data
                .hits
                .iter()
                .any(|hit| hit.symbol == Some(limited_symbol.0))
        );
        let restored_out_of_scope = restored
            .code_locate_with_filters_and_budget(
                receipt.generation,
                out_of_scope_symbol.1,
                LocateMode::Text,
                Vec::new(),
                vec![limited_path],
                8,
                0,
                FirstSliceBudget::default(),
                &deadline(),
            )
            .expect("restored fallback keeps the negative-control symbol out of scope");
        assert!(
            restored_out_of_scope
                .data
                .hits
                .iter()
                .all(|hit| hit.symbol != Some(out_of_scope_symbol.0))
        );
    }

    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    #[test]
    fn durable_service_removes_unactivated_crash_artifacts_before_restore() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = durable_test_tempdir();
        fs::create_dir(fixture.path().join("src")).expect("fixture source directory exists");
        fs::write(
            fixture.path().join("src/lib.rs"),
            "pub fn retained_answer() -> u32 {\n    42\n}\n",
        )
        .expect("fixture source writes");
        let cancellation = Cancellation::new();

        let receipt = {
            let mut service = FirstSliceService::new_durable(3, paths.state_dir(), &cancellation)
                .expect("durable service initializes");
            service
                .index_rust_fixture(fixture.path(), &cancellation)
                .expect("durable generation publishes")
        };
        let repository_directory = paths
            .state_dir()
            .join("first-slice")
            .join("repositories")
            .join(receipt.repository.to_string());
        let staging_directory = repository_directory.join("stage-crash-fixture");
        let repository_capability =
            Dir::open_ambient_dir(&repository_directory, ambient_authority())
                .expect("repository capability opens");
        PrivateDirectory::verify_parent(&repository_capability)
            .expect("repository capability remains private");
        drop(
            PrivateDirectory::create(&repository_capability, OsStr::new("stage-crash-fixture"))
                .expect("orphan staging directory creates"),
        );
        let orphan_generation = GenerationId::from_bytes([99; 20]);
        let orphan_directory = repository_directory.join(orphan_generation.to_string());
        drop(
            PrivateDirectory::create(
                &repository_capability,
                OsStr::new(&orphan_generation.to_string()),
            )
            .expect("unactivated generation directory creates"),
        );

        let restored = FirstSliceService::new_durable(3, paths.state_dir(), &cancellation)
            .expect("durable service restores");
        assert_eq!(
            restored.active_generation_for(receipt.repository),
            Some(receipt.generation)
        );
        assert!(!staging_directory.exists());
        assert!(!orphan_directory.exists());
    }

