    #[test]
    fn durable_repository_metadata_rename_and_delete_survive_restart() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let fixture = durable_test_tempdir();
        fs::create_dir(fixture.path().join("src")).expect("fixture source directory exists");
        let source = fixture.path().join("src/lib.rs");
        fs::write(&source, "pub fn durable_metadata_probe() -> u32 { 42 }\n")
            .expect("fixture source writes");
        let cancellation = deadline();

        let receipt = {
            let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
                .expect("durable service initializes");
            let receipt = service
                .index_rust_fixture(fixture.path(), &cancellation)
                .expect("fixture publishes");
            service
                .rename_repository(receipt.repository, "Renamed project".to_owned())
                .expect("repository alias persists");
            receipt
        };

        let mut restored = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
            .expect("renamed repository restores");
        let page = restored
            .repository_catalog_page(
                CatalogPageRequest::new(
                    None,
                    None,
                    catalog::CatalogListFilter::new(None, None, None).expect("filter is valid"),
                    catalog::CatalogPageSize::new(20).expect("page size is valid"),
                )
                .expect("request is valid"),
                CatalogInstant::from_millis(1_000),
            )
            .expect("catalog page succeeds");
        assert_eq!(page.items().len(), 1);
        assert_eq!(page.items()[0].alias(), Some("Renamed project"));
        assert!(page.items()[0].root_path().is_some_and(|root| {
            fixture
                .path()
                .file_name()
                .is_some_and(|name| root.ends_with(&name.to_string_lossy().to_string()))
        }));

        restored
            .delete_repository(receipt.repository)
            .expect("Rootlight-owned repository state deletes");
        assert!(source.exists(), "source repository must remain untouched");
        assert!(
            !paths
                .state_dir()
                .join("first-slice")
                .join("repositories")
                .join(receipt.repository.to_string())
                .exists()
        );
        drop(restored);

        let reopened = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
            .expect("deleted repository state stays absent");
        let page = reopened
            .repository_catalog_page(
                CatalogPageRequest::new(
                    None,
                    None,
                    catalog::CatalogListFilter::new(None, None, None).expect("filter is valid"),
                    catalog::CatalogPageSize::new(20).expect("page size is valid"),
                )
                .expect("request is valid"),
                CatalogInstant::from_millis(1_000),
            )
            .expect("empty catalog page succeeds");
        assert!(page.items().is_empty());
        assert!(source.exists(), "source repository must survive restart");
    }

    #[cfg(any(target_os = "linux", target_os = "macos", windows))]
    #[test]
    fn durable_reactivation_compacts_markers_and_restores_global_chronology() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("account-private runtime paths prepare");
        let first_fixture = durable_test_tempdir();
        let second_fixture = durable_test_tempdir();
        for (fixture, function) in [
            (&first_fixture, "first_repository"),
            (&second_fixture, "second_repository"),
        ] {
            fs::create_dir(fixture.path().join("src")).expect("fixture source directory exists");
            fs::write(
                fixture.path().join("src/lib.rs"),
                format!("pub fn {function}() -> u32 {{ 42 }}\n"),
            )
            .expect("fixture source writes");
        }
        let cancellation = deadline();

        let most_recent = {
            let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
                .expect("durable service initializes");
            let first = service
                .index_rust_fixture(first_fixture.path(), &cancellation)
                .expect("first repository publishes");
            let second = service
                .index_rust_fixture(second_fixture.path(), &cancellation)
                .expect("second repository publishes");
            let (fixture, expected) = if first.repository < second.repository {
                (&first_fixture, first)
            } else {
                (&second_fixture, second)
            };
            for _ in 0..32 {
                let repeated = service
                    .index_rust_fixture(fixture.path(), &cancellation)
                    .expect("retained generation reactivates");
                assert_eq!(repeated, expected);
            }
            assert_eq!(service.active_generation(), Some(expected.generation));
            expected
        };

        let repository_directory = paths
            .state_dir()
            .join("first-slice")
            .join("repositories")
            .join(most_recent.repository.to_string());
        let activation_markers = fs::read_dir(repository_directory)
            .expect("repository directory reads")
            .filter_map(|entry| {
                entry
                    .ok()
                    .and_then(|entry| entry.file_name().into_string().ok())
            })
            .filter(|name| name.starts_with("activation-"))
            .count();
        assert_eq!(activation_markers, 1);

        let restored = FirstSliceService::new_durable(2, paths.state_dir(), &cancellation)
            .expect("durable state restores");
        assert_eq!(restored.active_generation(), Some(most_recent.generation));
        assert_eq!(
            restored.active_generation_for(most_recent.repository),
            Some(most_recent.generation)
        );
    }

    const EQUIVALENCE_INITIAL: &str =
        "pub fn answer() -> u32 {\n    42\n}\n\npub fn helper() -> u32 {\n    7\n}\n";
    const EQUIVALENCE_BODY_EDIT: &str =
        "pub fn answer() -> u32 {\n    43\n}\n\npub fn helper() -> u32 {\n    7\n}\n";

    #[test]
    fn text_query_term_admission_preserves_the_effective_limit() {
        let fixture = TempDir::new().unwrap();
        let source = "pub fn merge_selected_rows(input_rows: Vec<InputRow>, selected_rows: Vec<SelectedRow>) -> Vec<OutputRow> { Vec::new() }\n";
        fs::write(fixture.path().join("rows.rs"), source).unwrap();
        let mut service = FirstSliceService::new(2).unwrap();
        let cancellation = Cancellation::new();
        let receipt = service
            .index_rust_fixture(fixture.path(), &cancellation)
            .unwrap();
        let locate = |query: &str, budget, cancellation: &Cancellation| {
            service.code_locate_with_filters_and_budget(
                receipt.generation,
                query.to_owned(),
                LocateMode::Text,
                Vec::new(),
                vec!["rows.rs".to_owned()],
                64,
                0,
                budget,
                cancellation,
            )
        };
        let budget = FirstSliceBudget::default();
        assert_eq!(
            locate(source.trim(), budget, &cancellation).unwrap_err(),
            FirstSliceError::QueryTermBudget {
                limit: u64::try_from(budget.search().max_terms).unwrap(),
            },
        );
        let located = locate("merge_selected_rows", budget, &cancellation).unwrap();
        assert!(located.data.hits.iter().any(|hit| hit.symbol.is_some()));
        for limit in [0, 1] {
            assert_eq!(
                locate(
                    "merge selected",
                    budget.reduce_search_max_terms(limit),
                    &cancellation
                )
                .unwrap_err(),
                FirstSliceError::QueryTermBudget {
                    limit: u64::try_from(limit).unwrap()
                },
            );
        }
        for mode in [LocateMode::Exact, LocateMode::Prefix] {
            assert_eq!(
                service
                    .code_locate_with_filters_and_budget(
                        receipt.generation,
                        "merge_selected_rows".to_owned(),
                        mode,
                        Vec::new(),
                        vec!["rows.rs".to_owned()],
                        64,
                        0,
                        budget.reduce_search_max_terms(0),
                        &cancellation,
                    )
                    .unwrap_err(),
                FirstSliceError::QueryTermBudget { limit: 0 },
            );
        }
        let _ = cancellation.cancel(CancellationReason::ClientRequest);
        assert_eq!(
            locate(source.trim(), budget, &cancellation).unwrap_err(),
            FirstSliceError::Cancelled(CancellationReason::ClientRequest),
        );
    }

    #[test]
    fn lexical_query_budget_failures_remain_distinct() {
        let cancellation = Cancellation::new();
        for error in [
            SearchError::InvalidQuery(rootlight_search::QueryViolation::TooLong),
            SearchError::InvalidQuery(rootlight_search::QueryViolation::TermTooLong),
            SearchError::InvalidQueryBudget {
                resource: "query_terms",
            },
            SearchError::BuildBudgetExceeded {
                resource: "documents",
            },
            SearchError::CandidateBudgetExceeded,
            SearchError::TermExpansionBudgetExceeded,
            SearchError::TermExaminationBudgetExceeded,
            SearchError::PostingBudgetExceeded,
            SearchError::ReturnedTextBudgetExceeded,
        ] {
            assert_eq!(
                map_search_error(error.clone(), &cancellation),
                FirstSliceError::BudgetExceeded
            );
            assert_eq!(
                map_query_error(QueryError::Search(error), &cancellation),
                FirstSliceError::BudgetExceeded
            );
        }
        assert_eq!(
            map_query_error(
                QueryError::Search(SearchError::IncompatibleIndex),
                &cancellation
            ),
            FirstSliceError::Search
        );
        assert_eq!(
            map_query_error(QueryError::SymbolNotFound, &cancellation),
            FirstSliceError::SymbolNotFound
        );
        let _ = cancellation.cancel(CancellationReason::Shutdown);
        assert_eq!(
            map_query_error(
                QueryError::Search(SearchError::CandidateBudgetExceeded),
                &cancellation
            ),
            FirstSliceError::Cancelled(CancellationReason::Shutdown)
        );
    }

    #[test]
    fn scoped_text_query_admission_is_not_missing_source() {
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .expect("test runtime paths are valid");
        paths
            .prepare_owner()
            .expect("private runtime paths prepare");
        let fixture = TempDir::new().expect("fixture root exists");
        fs::write(
            fixture.path().join("source.rs"),
            "// alpha\npub fn ordinary_value() -> u32 { 1 }\n",
        )
        .expect("source writes");
        let mut service = FirstSliceService::new_durable(2, paths.state_dir(), &deadline())
            .expect("service initializes");
        let receipt = service
            .index_repository_with_mode(
                fixture.path(),
                FirstSliceIndexMode::Structural,
                &deadline(),
            )
            .expect("fixture publishes");
        for restored in [false, true] {
            if restored {
                drop(service);
                service = FirstSliceService::new_durable(2, paths.state_dir(), &deadline())
                    .expect("service restores");
            }
            let result = service.code_locate_with_filters_and_budget(
                receipt.generation,
                "alpha ".repeat(17),
                LocateMode::Text,
                Vec::new(),
                vec!["source.rs".to_owned()],
                8,
                0,
                FirstSliceBudget::default(),
                &deadline(),
            );
            assert!(
                matches!(result, Err(FirstSliceError::QueryTermBudget { limit: 16 })),
                "restored={restored}, result={result:?}"
            );
            for (query, expected) in [("alpha", true), ("absentToken", false)] {
                let located = service
                    .code_locate_with_filters_and_budget(
                        receipt.generation,
                        query.to_owned(),
                        LocateMode::Text,
                        Vec::new(),
                        vec!["source.rs".to_owned()],
                        8,
                        0,
                        FirstSliceBudget::default(),
                        &deadline(),
                    )
                    .expect("admitted query executes");
                assert_eq!(
                    located.data.hits.iter().any(|hit| hit.path == "source.rs"),
                    expected
                );
            }
        }
    }

