    #[test]
    fn utf16_encoding_survives_restart_and_incremental_transitions() {
        let fixture = TempDir::new().unwrap();
        let storage = durable_test_tempdir();
        let paths = RuntimePaths::new(storage.path().join("state"), storage.path().join("runtime"))
            .unwrap();
        paths.prepare_owner().unwrap();
        let source = "pub fn value() {}\r\n// λ𝄞\r\n";
        let little = std::iter::once(0xfeff_u16)
            .chain(source.encode_utf16())
            .flat_map(u16::to_le_bytes)
            .collect::<Vec<_>>();
        let big = std::iter::once(0xfeff_u16)
            .chain(source.encode_utf16())
            .flat_map(u16::to_be_bytes)
            .collect::<Vec<_>>();
        let mut previous: Option<(GenerationId, String)> = None;
        for (encoding, bytes) in [
            ("utf-16le", little),
            ("utf-16be", big),
            ("utf-8", source.as_bytes().to_vec()),
        ] {
            let policy = FirstSliceStoragePolicy::resolve_user_config(None, 2).unwrap();
            let mut service =
                FirstSliceService::new_durable_with_policy(policy, paths.state_dir(), &deadline())
                    .unwrap();
            if let Some((generation, old_encoding)) = &previous {
                let restored = service
                    .index_repository(fixture.path(), &deadline())
                    .unwrap();
                assert_eq!(restored.generation, *generation);
                let snapshot = service.loaded_generation_snapshot(*generation).unwrap();
                assert_eq!(snapshot.document().files[0].encoding, *old_encoding);
            }
            fs::write(fixture.path().join("source.rs"), &bytes).unwrap();
            let receipt = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            if let Some((generation, _)) = previous {
                assert_ne!(receipt.generation, generation);
            }
            let snapshot = service
                .loaded_generation_snapshot(receipt.generation)
                .unwrap();
            assert_eq!(snapshot.document().files.len(), 1);
            let file = &snapshot.document().files[0];
            assert_eq!(file.encoding, encoding);
            assert_eq!(file.content_hash, content_hash(&bytes));
            assert!(!snapshot.document().entities.is_empty(), "{encoding}");
            let read = service
                .source_read_with_options_and_budget(
                    receipt.generation,
                    vec![file.evidence.source.clone().unwrap()],
                    SourceReadOptions::new()
                        .with_context_lines_before(0)
                        .with_context_lines_after(0)
                        .with_encoding(rootlight_source::SourceEncoding::Bytes),
                    FirstSliceBudget::default(),
                    &deadline(),
                )
                .unwrap();
            assert_eq!(read.data.chunks[0].bytes, bytes);
            let noop = service
                .index_repository(fixture.path(), &deadline())
                .unwrap();
            assert_eq!(noop.generation, receipt.generation);
            previous = Some((receipt.generation, encoding.to_owned()));
        }
    }

    #[test]
    fn invalid_utf8_source_publishes_bounded_file_coverage() {
        let fixture = TempDir::new().expect("fixture root exists");
        fs::create_dir(fixture.path().join("src")).expect("fixture source directory exists");
        fs::write(
            fixture.path().join("src/lib.rs"),
            "pub fn retained() -> u32 { 42 }\n",
        )
        .expect("valid source writes");
        let invalid_bytes = b"pub fn unavailable() {}\n\xff";
        fs::write(fixture.path().join("src/invalid.rs"), invalid_bytes)
            .expect("invalid UTF-8 source writes");
        let cancellation = Cancellation::new();
        let mut service = FirstSliceService::new(2).expect("first-slice service initializes");

        let receipt = service
            .index_rust_fixture(fixture.path(), &cancellation)
            .expect("invalid UTF-8 bounds one file without rejecting the repository");
        assert_eq!(receipt.indexed_files, 2);
        let generation = service
            .loaded_generation_snapshot(receipt.generation)
            .expect("published generation is retained");
        let invalid_file = generation
            .document()
            .files
            .iter()
            .find(|file| file.path == "src/invalid.rs")
            .expect("invalid source retains its file identity");
        assert_eq!(invalid_file.encoding, "bytes");
        assert_eq!(invalid_file.content_hash, content_hash(invalid_bytes));
        assert!(receipt.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "unsupported-encoding"
                && diagnostic.message == "raw source bytes remain readable but unsupported text encoding prevents structural analysis and lexical vocabulary projection and literal text matching"
        }));
        assert!(generation.document().diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "unsupported-encoding"
                && diagnostic.coverage_effect == CoverageStatus::Unknown
                && diagnostic.source.as_ref().is_some_and(|source| {
                    source.span().file() == invalid_file.id
                        && source.content_hash() == content_hash(invalid_bytes)
                })
        }));
        assert!(generation.document().skipped_regions.iter().any(|region| {
            region.source.span().file() == invalid_file.id
                && region.reason == rootlight_ir::SkippedRegionReason::UnsupportedEncoding
                && region.detail == "unsupported-encoding"
        }));
        assert!(
            generation
                .document()
                .coverage_records
                .iter()
                .any(|coverage| {
                    coverage.scope == rootlight_ir::CoverageScope::File(invalid_file.id)
                        && coverage.domain == rootlight_ir::FactDomain::Entities
                        && coverage.status == CoverageStatus::Unknown
                        && coverage.discovered == 1
                        && coverage.indexed == 0
                        && coverage.skipped == 1
                })
        );
        let reference = invalid_file.evidence.source.clone().unwrap();
        fs::write(fixture.path().join("src/invalid.rs"), b"changed live bytes").unwrap();
        let read = service
            .source_read_with_options_and_budget(
                receipt.generation,
                vec![reference.clone()],
                SourceReadOptions::new()
                    .with_context_lines_before(0)
                    .with_context_lines_after(0)
                    .with_encoding(SourceEncoding::Bytes),
                FirstSliceBudget::new(),
                &cancellation,
            )
            .unwrap();
        assert_eq!(read.data.chunks[0].reference, reference);
        assert_eq!(read.data.chunks[0].bytes, invalid_bytes);
        assert_eq!(
            service
                .code_locate_with_filters_and_budget(
                    receipt.generation,
                    "unavailable".to_owned(),
                    LocateMode::Text,
                    Vec::new(),
                    vec!["src/invalid.rs".to_owned()],
                    8,
                    0,
                    FirstSliceBudget::new(),
                    &cancellation,
                )
                .unwrap_err(),
            FirstSliceError::SourceEncodingUnsupported,
        );
        service
            .code_locate(
                receipt.generation,
                "retained".to_owned(),
                LocateMode::Exact,
                8,
                0,
                &cancellation,
            )
            .expect("valid peer remains queryable");
    }

    #[test]
    fn aggregate_lexical_summary_batches_preserve_full_coverage() {
        let fixture = TempDir::new().expect("fixture root exists");
        fs::create_dir(fixture.path().join("src")).expect("fixture source directory exists");
        for file_index in 0..16 {
            let mut source = String::new();
            for comment_index in 0..800 {
                source.push_str(&format!(
                    "// lexical evidence {file_index:02} {comment_index:04}\n"
                ));
            }
            source.push_str(&format!(
                "pub fn indexed_{file_index:02}() -> usize {{ {file_index} }}\n"
            ));
            fs::write(
                fixture.path().join(format!("src/file_{file_index:02}.rs")),
                source,
            )
            .expect("extension-heavy source writes");
        }
        let cancellation = Cancellation::new();
        let mut service = FirstSliceService::new(2).expect("first-slice service initializes");

        let first = service
            .index_rust_fixture(fixture.path(), &cancellation)
            .expect("optional extension overflow preserves a generation");
        let repeated = service
            .index_rust_fixture(fixture.path(), &cancellation)
            .expect("unchanged bounded generation remains reusable");
        assert_eq!(repeated.generation, first.generation);
        let snapshot = service
            .loaded_generation_snapshot(first.generation)
            .expect("bounded generation remains retained");
        let document = snapshot.document();
        let lexical = document
            .extensions
            .iter()
            .filter(|extension| extension.namespace == LEXICAL_EXTENSION_NAMESPACE)
            .collect::<Vec<_>>();
        assert!(lexical.len() < MAX_RETAINED_OPTIONAL_EXTENSIONS);
        let retained_summaries = lexical
            .iter()
            .filter(|extension| extension.version == rootlight_ir::LEXICAL_SUMMARY_BATCH_VERSION)
            .map(|extension| {
                rootlight_ir::decode_lexical_summary_batch_envelope(extension)
                    .expect("each summary batch validates")
                    .len()
            })
            .sum::<usize>();
        assert!(retained_summaries >= 12_800);
        let retained_signatures = document
            .extensions
            .iter()
            .filter(|extension| {
                extension.namespace == LEXICAL_EXTENSION_NAMESPACE
                    && extension.version != rootlight_ir::LEXICAL_SUMMARY_BATCH_VERSION
            })
            .filter_map(|extension| {
                let evidence = rootlight_ir::decode_lexical_evidence_envelope(extension)
                    .expect("retained lexical evidence validates");
                (evidence.kind() == rootlight_ir::LexicalEvidenceKind::Signature)
                    .then_some(evidence.subject())
            })
            .collect::<BTreeSet<_>>();
        let expected_signatures = document
            .entities
            .iter()
            .filter(|entity| entity.canonical_name.starts_with("indexed_"))
            .map(|entity| FactRef::Entity(entity.id))
            .collect::<BTreeSet<_>>();
        assert_eq!(expected_signatures.len(), 16);
        assert_eq!(retained_signatures, expected_signatures);
        assert!(
            document.extensions.len() <= service.analysis_limits.ir().max_extensions,
            "required identity extensions remain inside the hard IR capacity"
        );
        assert!(!document.coverage_records.iter().any(|coverage| {
            coverage.domain == rootlight_ir::FactDomain::Extensions
                && coverage.status == CoverageStatus::Bounded
                && coverage.skipped > 0
        }));
        assert!(!first.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "extension-coverage-bounded"
                && diagnostic
                    .message
                    .ends_with("optional lexical extensions omitted by aggregate resource limit")
        }));
    }

    #[test]
    fn required_extension_cache_rebuilds_all_totals_after_invalidation() {
        let repository = derive_repository(b"required-extension-cache").id();
        let generation = GenerationId::from_bytes([82; 20]);
        let file = FileId::from_bytes([83; 20]);
        let provenance = FactId::from_bytes([84; 20]);
        let required = |id: u8, payload: &str| ExtensionEnvelope {
            id: FactId::from_bytes([id; 20]),
            repository,
            generation,
            namespace: "test.required".to_owned(),
            version: "1".to_owned(),
            criticality: rootlight_ir::ExtensionCriticality::Noncritical,
            payload: payload.to_owned(),
            provenance,
            evidence: FactEvidence {
                source: None,
                derivation: Vec::new(),
            },
        };
        let lexical = |text: &str| {
            let evidence = rootlight_ir::LexicalEvidenceV1::from_complete_text(
                rootlight_ir::LexicalEvidenceKind::CommentSummary,
                FactRef::File(file),
                rootlight_ir::LexicalEvidenceFormat::PlainText,
                text,
            )
            .unwrap();
            rootlight_ir::new_lexical_evidence_envelope(
                repository,
                generation,
                provenance,
                SourceRef::new(
                    repository,
                    generation,
                    SourceSpan::new(file, 0, 1).unwrap(),
                    content_hash(b"x"),
                    None,
                ),
                &evidence,
            )
            .unwrap()
        };
        let assert_usage = |target: &NormalizedIrDocument, state: &DocumentAppendState| {
            let required = target
                .extensions
                .iter()
                .filter(|extension| extension.namespace != LEXICAL_EXTENSION_NAMESPACE);
            assert_eq!(
                state.required_extension_usage,
                Some((
                    required.clone().count(),
                    required
                        .map(|extension| extension.payload.len())
                        .sum::<usize>(),
                ))
            );
            assert_eq!(
                state.extension_payload_bytes,
                target
                    .extensions
                    .iter()
                    .map(|extension| extension.payload.len())
                    .sum::<usize>()
            );
        };
        let mut target = NormalizedIrDocument::empty(repository, generation);
        let mut state = DocumentAppendState::default();
        assert_eq!(state.required_extension_usage, None);
        for (id, payload, comment) in [(85, "é", "first note"), (86, "{}", "second note")] {
            let mut source = NormalizedIrDocument::empty(repository, generation);
            source.extensions = vec![required(id, payload), lexical(comment)];
            append_normalized_document(&mut target, source, &IrLimits::default(), &mut state)
                .unwrap();
            assert_usage(&target, &state);
            assert!(state.usage.is_some());
        }
        assert_usage(
            &target,
            &DocumentAppendState::from_document(&target).unwrap(),
        );
        target
            .extensions
            .retain(|extension| extension.namespace != LEXICAL_EXTENSION_NAMESPACE);
        target.extensions[0].payload = "expanded payload".to_owned();
        target.extensions.push(required(87, "é"));
        state.invalidate_usage();
        state.extension_payload_bytes = usize::MAX;
        assert_eq!(state.required_extension_usage, None);
        assert!(state.usage.is_none());
        let mut source = NormalizedIrDocument::empty(repository, generation);
        source.extensions = vec![required(88, "{}"), lexical("later note")];
        append_normalized_document(&mut target, source, &IrLimits::default(), &mut state).unwrap();
        assert_usage(&target, &state);
        assert_eq!(state.required_extension_usage.unwrap().0, 4);
        assert!(state.usage.is_some());
    }

    #[test]
    fn required_extension_quotas_preserve_cached_and_invalidated_state() {
        let repository = derive_repository(b"required-extension-quota-atomicity").id();
        let generation = GenerationId::from_bytes([89; 20]);
        let required = |id: u8| ExtensionEnvelope {
            id: FactId::from_bytes([id; 20]),
            repository,
            generation,
            namespace: "test.required".to_owned(),
            version: "1".to_owned(),
            criticality: rootlight_ir::ExtensionCriticality::Noncritical,
            payload: "{}".to_owned(),
            provenance: FactId::from_bytes([90; 20]),
            evidence: FactEvidence {
                source: None,
                derivation: Vec::new(),
            },
        };
        for invalidated in [false, true] {
            for resource in [
                FirstSliceResource::Extensions,
                FirstSliceResource::ExtensionBytes,
            ] {
                let mut target = NormalizedIrDocument::empty(repository, generation);
                let mut state = DocumentAppendState::from_document(&target).unwrap();
                let mut first = NormalizedIrDocument::empty(repository, generation);
                first.extensions.push(required(91));
                append_normalized_document(&mut target, first, &IrLimits::default(), &mut state)
                    .unwrap();
                if invalidated {
                    target.extensions.push(required(92));
                    state.invalidate_usage();
                    state.extension_payload_bytes = usize::MAX;
                }
                assert_eq!(state.required_extension_usage.is_none(), invalidated);
                let mut source = NormalizedIrDocument::empty(repository, generation);
                source.extensions = vec![required(93), required(94)];
                let observed_count = target.extensions.len() + source.extensions.len();
                let observed_bytes = target
                    .extensions
                    .iter()
                    .chain(&source.extensions)
                    .map(|extension| extension.payload.len())
                    .sum::<usize>();
                let mut limits = IrLimits::default();
                limits.max_total_extension_bytes = observed_bytes - 1;
                let observed = match resource {
                    FirstSliceResource::Extensions => {
                        limits.max_extensions = observed_count - 1;
                        observed_count
                    }
                    FirstSliceResource::ExtensionBytes => observed_bytes,
                    _ => unreachable!("fixture exercises only required extension quotas"),
                };
                let before = target.clone();
                let state_before = state.clone();
                assert_eq!(
                    append_normalized_document(&mut target, source.clone(), &limits, &mut state),
                    Err(resource_limit(resource, observed, observed - 1))
                );
                assert_eq!(target, before);
                assert_eq!(state, state_before);
                let cancelled = Cancellation::new();
                assert!(cancelled.cancel(CancellationReason::ClientRequest));
                assert_eq!(
                    append_normalized_document_with_cancellation(
                        &mut target,
                        source,
                        &limits,
                        &mut state,
                        &cancelled,
                    ),
                    Err(FirstSliceError::Cancelled(
                        CancellationReason::ClientRequest
                    ))
                );
                assert_eq!(target, before);
                assert_eq!(state, state_before);
            }
        }
    }

    #[test]
    fn mixed_optional_evictions_keep_coverage_and_indices_consistent() {
        let repository = derive_repository(b"optional-extension-eviction").id();
        let generation = GenerationId::from_bytes([41; 20]);
        let file = FileId::from_bytes([42; 20]);
        let provenance = FactId::from_bytes([43; 20]);
        let source = SourceRef::new(
            repository,
            generation,
            SourceSpan::new(file, 0, 1).expect("fixture span is valid"),
            content_hash(b"x"),
            None,
        );
        let lexical = |kind, format, text| {
            let evidence = rootlight_ir::LexicalEvidenceV1::from_complete_text(
                kind,
                FactRef::File(file),
                format,
                text,
            )
            .expect("fixture lexical evidence is valid");
            rootlight_ir::new_lexical_evidence_envelope(
                repository,
                generation,
                provenance,
                source.clone(),
                &evidence,
            )
            .expect("fixture lexical envelope is valid")
        };
        let mut target = NormalizedIrDocument::empty(repository, generation);
        target.extensions.push(lexical(
            rootlight_ir::LexicalEvidenceKind::CommentSummary,
            rootlight_ir::LexicalEvidenceFormat::PlainText,
            "comment",
        ));
        target.extensions.push(lexical(
            rootlight_ir::LexicalEvidenceKind::Signature,
            rootlight_ir::LexicalEvidenceFormat::SourceText,
            "signature",
        ));
        let mut coverage = CoverageRecord {
            id: FactId::from_bytes([0; 20]),
            repository,
            generation,
            scope: CoverageScope::File(file),
            domain: IrFactDomain::Extensions,
            tier: AnalysisTier::TierB,
            status: CoverageStatus::Complete,
            discovered: 2,
            indexed: 2,
            skipped: 0,
            provenance,
            evidence: FactEvidence {
                source: Some(source.clone()),
                derivation: Vec::new(),
            },
        };
        coverage.id = derive_coverage_record_id(&coverage).expect("coverage identity derives");
        target.coverage_records.push(coverage);
        let state = DocumentAppendState::from_document(&target).expect("append state initializes");
        assert_eq!(state.required_extension_usage, Some((0, 0)));
        let mut next = NormalizedIrDocument::empty(repository, generation);
        next.extensions.push(ExtensionEnvelope {
            id: FactId::from_bytes([44; 20]),
            repository,
            generation,
            namespace: "test.required".to_owned(),
            version: "1".to_owned(),
            criticality: rootlight_ir::ExtensionCriticality::Noncritical,
            payload: "{}".to_owned(),
            provenance,
            evidence: FactEvidence {
                source: Some(source),
                derivation: Vec::new(),
            },
        });
        let mut limits = IrLimits::default();
        limits.max_extensions = 1;

        let mut rejected_source = next.clone();
        rejected_source.files.push(FileRecord {
            id: file,
            repository,
            generation,
            path: "src/long-file-name-for-aggregate-admission.rs".to_owned(),
            path_locator: None,
            content_hash: content_hash(b"x"),
            byte_length: 1,
            language: "rust".to_owned(),
            encoding: "utf-8".to_owned(),
            generated: false,
            provenance,
            evidence: FactEvidence {
                source: None,
                derivation: Vec::new(),
            },
        });
        let original_target = target.clone();
        let mut rejected_state = state.clone();
        let raw_limits = IrLimits::default();
        let original_usage = IrDocumentUsage::measure(&target, &raw_limits).unwrap();
        let after_summary_eviction = original_usage
            .clone()
            .checked_sub(
                IrDocumentUsage::measure_extension(&target.extensions[0], &raw_limits).unwrap(),
            )
            .unwrap();
        let source_usage = IrDocumentUsage::measure(&rejected_source, &raw_limits).unwrap();
        let combined = after_summary_eviction
            .checked_add(source_usage.clone(), &raw_limits)
            .unwrap();
        let mut rejection_limits = raw_limits;
        rejection_limits.max_extensions = 2;
        rejection_limits.max_total_string_bytes = combined.total_string_bytes() - 1;
        assert!(original_usage.total_string_bytes() <= rejection_limits.max_total_string_bytes);
        assert!(source_usage.total_string_bytes() <= rejection_limits.max_total_string_bytes);
        assert_eq!(
            append_normalized_document(
                &mut target,
                rejected_source,
                &rejection_limits,
                &mut rejected_state
            ),
            Err(FirstSliceError::ResourceLimit {
                resource: FirstSliceResource::StringBytes,
                observed: u64::try_from(combined.total_string_bytes()).unwrap(),
                limit: u64::try_from(rejection_limits.max_total_string_bytes).unwrap(),
            }),
            "a rejected aggregate must not apply planned summary eviction",
        );
        assert_eq!(target, original_target);
        assert_eq!(rejected_state, state);
        let cancelled = Cancellation::new();
        assert!(cancelled.cancel(CancellationReason::ClientRequest));
        assert_eq!(
            append_normalized_document_with_cancellation(
                &mut target,
                next.clone(),
                &limits,
                &mut rejected_state,
                &cancelled,
            ),
            Err(FirstSliceError::Cancelled(
                CancellationReason::ClientRequest
            )),
        );
        assert_eq!(target, original_target);
        assert_eq!(rejected_state, state);

        let next_state =
            truncate_optional_extensions(&mut target, &mut next, &state, 0, 0, &limits)
                .expect("optional eviction preserves required facts");
        assert!(target.extensions.is_empty());
        assert_eq!(next.extensions.len(), 1);
        assert_eq!(next_state.truncated_extensions, 2);
        assert_eq!(next_state.required_extension_usage, Some((1, 2)));
        assert_eq!(next_state.extension_payload_bytes, 2);
        assert_eq!(target.coverage_records[0].indexed, 0);
        assert_eq!(target.coverage_records[0].skipped, 2);
        assert_eq!(target.coverage_records[0].status, CoverageStatus::Bounded);
    }

    #[test]
    fn summary_partitions_preserve_colocated_evidence_across_generations() {
        let mut boundary_spans = (0..96).collect::<Vec<u64>>();
        boundary_spans.extend(std::iter::repeat_n(96, 64));
        boundary_spans.extend(97..145);
        let mut oversized_spans = vec![0; rootlight_ir::MAX_LEXICAL_SUMMARY_BATCH_ENTRIES + 1];
        oversized_spans.extend(1..50);
        let default_payload_limit = IrLimits::default().max_extension_payload_bytes;
        for (spans, payload_limit) in [
            (boundary_spans.clone(), default_payload_limit),
            (oversized_spans, default_payload_limit),
            (boundary_spans, 4 * 1024),
        ] {
            let mut partitions = Vec::new();
            for generation_byte in [61, 62] {
                let repository = derive_repository(b"summary-partition-fixture").id();
                let generation = GenerationId::from_bytes([generation_byte; 20]);
                let file = FileId::from_bytes([63; 20]);
                let provenance = FactId::from_bytes([generation_byte; 20]);
                let mut document = NormalizedIrDocument::empty(repository, generation);
                for (index, &start) in spans.iter().enumerate() {
                    let subject = rootlight_ids::derive_fact(
                        "summary-fixture-subject",
                        format!("{generation_byte}:{index}").as_bytes(),
                    )
                    .id();
                    let evidence = rootlight_ir::LexicalEvidenceV1::from_complete_text(
                        rootlight_ir::LexicalEvidenceKind::CommentSummary,
                        FactRef::Fact(subject),
                        rootlight_ir::LexicalEvidenceFormat::PlainText,
                        &format!("summary {index}"),
                    )
                    .unwrap();
                    let source = SourceRef::new(
                        repository,
                        generation,
                        SourceSpan::new(file, start, start + 1).unwrap(),
                        content_hash(b"fixture"),
                        None,
                    );
                    document.extensions.push(
                        rootlight_ir::new_lexical_evidence_envelope(
                            repository, generation, provenance, source, &evidence,
                        )
                        .unwrap(),
                    );
                }
                document.extensions.sort_unstable_by_key(|entry| entry.id);
                let original = document.extensions.clone();
                if generation_byte == 62 {
                    document.extensions.reverse();
                }
                let mut limits = IrLimits::default();
                limits.max_extension_payload_bytes = payload_limit;
                compact_lexical_summaries(&mut document, &limits).unwrap();
                let mut reconstructed = Vec::new();
                let mut groups = Vec::new();
                for envelope in document.extensions {
                    let children =
                        if envelope.version == rootlight_ir::LEXICAL_SUMMARY_BATCH_VERSION {
                            assert!(envelope.payload.len() <= payload_limit);
                            rootlight_ir::decode_lexical_summary_batch_envelope(&envelope).unwrap()
                        } else {
                            vec![envelope]
                        };
                    let mut group = children
                        .iter()
                        .map(|child| {
                            let evidence =
                                rootlight_ir::decode_lexical_evidence_envelope(child).unwrap();
                            (lexical_summary_span(child), evidence.text().to_owned())
                        })
                        .collect::<Vec<_>>();
                    group.sort_unstable();
                    groups.push(group);
                    reconstructed.extend(children);
                }
                reconstructed.sort_unstable_by_key(|entry| entry.id);
                assert_eq!(
                    reconstructed, original,
                    "every source, subject and payload must survive packing"
                );
                groups.sort_unstable();
                partitions.push(groups);
            }
            assert_eq!(partitions[0], partitions[1]);
        }
    }

