    #[test]
    fn compressed_normalized_cache_reuses_unchanged_lowering_within_the_same_bound() {
        let fixture = TempDir::new().expect("fixture root exists");
        fs::create_dir(fixture.path().join("src")).expect("source directory exists");
        let source = |name: &str, value: u32| {
            (0..80)
                .map(|index| {
                    format!(
                        "/// Repeated documentation for a generic cache fixture.\npub fn {name}_{index}() -> u32 {{ {value} }}\n"
                    )
                })
                .collect::<String>()
        };
        for name in ["alpha", "bravo", "delta"] {
            fs::write(
                fixture.path().join(format!("src/{name}.rs")),
                source(name, 1),
            )
            .expect("independent repeated source writes");
        }
        let (budget, root_identity, repository) = {
            let sizing = FirstSliceService::new(3).expect("sizing service initializes");
            let prepared = sizing
                .prepare_rust_fixture(fixture.path(), &deadline())
                .expect("unconstrained cache prepares");
            let FirstSliceIndexPreparation::Pending(pending) = &prepared else {
                panic!("initial fixture requires a generation");
            };
            let mut parser_bytes = 0_usize;
            let mut compressed_bytes = 0_usize;
            let mut canonical_bytes = 0_usize;
            for (_, entry) in pending.structural_artifacts.iter() {
                parser_bytes += entry.artifact.accounted_bytes();
                let chunk = entry
                    .normalized
                    .as_ref()
                    .expect("complete chunk is retained");
                compressed_bytes += chunk.accounted_bytes();
                canonical_bytes += chunk.canonical_json_bytes();
            }
            assert!(compressed_bytes * 2 < canonical_bytes);
            let budget = parser_bytes + compressed_bytes * 2;
            assert!(budget < parser_bytes + canonical_bytes);
            assert!(budget <= MAX_RETAINED_STRUCTURAL_ARTIFACT_BYTES);
            (budget, pending.root_identity, pending.receipt.repository)
        };
        let mut service = FirstSliceService::new(3).expect("bounded service initializes");
        service
            .restore_repository_registration(root_identity, repository)
            .expect("sizing identity is preserved");
        service.structural_artifacts.maximum_bytes = budget;
        let first = service
            .index_rust_fixture(fixture.path(), &deadline())
            .expect("initial generation publishes");
        let artifacts = service
            .structural_artifacts
            .generation(first.generation)
            .unwrap();
        assert_eq!(artifacts.len(), 3);
        assert_eq!(
            artifacts
                .iter()
                .filter(|(_, entry)| entry.normalized.is_some())
                .count(),
            3
        );
        assert!(artifacts.accounted_bytes <= budget);
        fs::write(fixture.path().join("src/alpha.rs"), source("alpha", 2))
            .expect("one body changes");
        let second = service
            .index_rust_fixture(fixture.path(), &deadline())
            .expect("successor publishes");
        let evidence = service.incremental_evidence(second.generation).unwrap();
        assert_eq!(evidence.parsed_files(), 1);
        assert_eq!(evidence.reused_parser_artifacts(), 2);
        assert_eq!(evidence.lowered_files(), 1);
        assert!(evidence.reused_normalized_facts() > 0);
        assert!(service.structural_artifacts.retained_bytes <= budget);
        // This compares hundreds of independent queries, not one timed request.
        // Keep each operation bounded without sharing its elapsed deadline.
        assert_fresh_equivalent_with_cancellations(
            &service,
            fixture.path(),
            first.generation,
            &second,
            deadline,
        );
    }

    #[test]
    fn optional_normalized_cache_pressure_preserves_parser_reuse() {
        let fixture = TempDir::new().expect("fixture root exists");
        fs::create_dir(fixture.path().join("src")).expect("source directory exists");
        for name in ["alpha", "bravo", "delta"] {
            fs::write(
                fixture.path().join(format!("src/{name}.rs")),
                format!("pub fn {name}() -> u32 {{ 1 }}\n"),
            )
            .expect("independent source writes");
        }
        let cancellation = deadline();
        let (budget, root_identity, repository) = {
            let sizing = FirstSliceService::new(3).expect("sizing service initializes");
            let prepared = sizing
                .prepare_rust_fixture(fixture.path(), &cancellation)
                .expect("unconstrained cache prepares");
            let FirstSliceIndexPreparation::Pending(pending) = &prepared else {
                panic!("initial fixture requires a generation");
            };
            let artifacts = &pending.structural_artifacts;
            assert_eq!(artifacts.len(), 3);
            let smallest_chunk = artifacts
                .iter()
                .map(|(_, entry)| {
                    entry
                        .normalized
                        .as_ref()
                        .expect("source supports normalized reuse")
                        .accounted_bytes()
                })
                .min()
                .expect("normalized chunks exist");
            let budget = artifacts
                .accounted_bytes
                .checked_sub(smallest_chunk)
                .expect("all parsers and two normalized chunks fit");
            (budget, pending.root_identity, pending.receipt.repository)
        };
        let mut service = FirstSliceService::new(3).expect("bounded service initializes");
        // Raw identity bytes change decimal widths in normalized JSON. Calibrate
        // and index the same registration rather than two random repositories.
        service
            .restore_repository_registration(root_identity, repository)
            .expect("sizing identity is reserved for bounded indexing");
        service.structural_artifacts.maximum_bytes = budget;
        let first = service
            .index_rust_fixture(fixture.path(), &cancellation)
            .expect("bounded initial generation publishes");
        assert_eq!(first.repository, repository);
        let artifacts = service
            .structural_artifacts
            .generation(first.generation)
            .expect("published cache is recorded");
        assert_eq!(artifacts.len(), 3, "optional chunks must not evict parsers");
        assert!(artifacts.retention_complete);
        assert!(artifacts.accounted_bytes <= budget);
        assert_eq!(
            artifacts
                .iter()
                .filter(|(_, entry)| entry.normalized.is_some())
                .count(),
            2,
            "identity-consistent budget must retain two normalized chunks"
        );
        assert!(
            artifacts
                .iter()
                .any(|(_, entry)| entry.normalized.is_none())
        );

        fs::write(
            fixture.path().join("src/alpha.rs"),
            "pub fn alpha() -> u32 { 2 }\n",
        )
        .expect("one body changes");
        let second = service
            .index_rust_fixture(fixture.path(), &cancellation)
            .expect("incremental successor publishes");
        let evidence = service
            .incremental_evidence(second.generation)
            .expect("incremental evidence is retained");
        assert_eq!(evidence.parsed_files(), 1);
        assert_eq!(evidence.reused_parser_artifacts(), 2);
        assert!(evidence.reused_normalized_facts() > 0);
        assert!(service.structural_artifacts.retained_bytes <= budget);
        assert_fresh_equivalent(
            &service,
            fixture.path(),
            first.generation,
            &second,
            &cancellation,
        );

        // Optional eviction follows file identities, not fixture names. Leave
        // one retained normalized input unchanged so this step proves reuse.
        let retained_file = service
            .structural_artifacts
            .generation(second.generation)
            .expect("successor cache is retained")
            .iter()
            .find_map(|(file, entry)| entry.normalized.as_ref().map(|_| *file))
            .expect("bounded cache retains a normalized input");
        let snapshot = service
            .loaded_generation_snapshot(second.generation)
            .expect("successor snapshot remains loaded");
        let (name, path) = [("bravo", "src/bravo.rs"), ("delta", "src/delta.rs")]
            .into_iter()
            .find(|(_, path)| {
                snapshot
                    .document()
                    .files
                    .iter()
                    .any(|file| file.path == *path && file.id != retained_file)
            })
            .expect("an independent file can change without replacing retained evidence");
        fs::write(
            fixture.path().join(path),
            format!("pub fn {name}() -> u32 {{ 3 }}\n"),
        )
        .expect("a later independent body changes");
        let third = service
            .index_rust_fixture(fixture.path(), &cancellation)
            .expect("later successor publishes within the same cache bound");
        let evidence = service
            .incremental_evidence(third.generation)
            .expect("later incremental evidence is retained");
        assert_eq!(evidence.parsed_files(), 1);
        assert_eq!(evidence.reused_parser_artifacts(), 2);
        assert!(evidence.reused_normalized_facts() > 0);
        assert!(evidence.structural_cache_retained());
        assert!(service.structural_artifacts.retained_bytes <= budget);
        assert_fresh_equivalent(
            &service,
            fixture.path(),
            second.generation,
            &third,
            &cancellation,
        );
    }

    #[test]
    fn structural_cache_pressure_preserves_staged_owners_and_cancellation() {
        let fixture = TempDir::new().expect("fixture root exists");
        fs::write(
            fixture.path().join("lib.rs"),
            "pub fn value() -> u32 { 1 }\n",
        )
        .expect("source writes");
        let cancellation = deadline();
        let service = FirstSliceService::new(3).expect("service initializes");
        let prepared = service
            .prepare_rust_fixture(fixture.path(), &cancellation)
            .expect("parser artifact prepares");
        let FirstSliceIndexPreparation::Pending(pending) = &prepared else {
            panic!("initial source requires a generation");
        };
        let (_, entry) = pending
            .structural_artifacts
            .iter()
            .next()
            .expect("parser artifact exists");
        let budget = entry.accounted_bytes().expect("cache charge fits");
        let artifacts = || {
            StructuralGenerationArtifacts::new(
                [StructuralArtifactEntry {
                    id: entry.id,
                    artifact: Arc::clone(&entry.artifact),
                    normalized: entry.normalized.as_ref().map(Arc::clone),
                }],
                budget,
                true,
                &cancellation,
            )
            .expect("complete cache fits exactly")
        };
        let first = GenerationId::from_bytes([1; 20]);
        let second = GenerationId::from_bytes([2; 20]);
        let mut retention =
            StructuralArtifactRetention::new(3, budget).expect("bounded cache initializes");
        assert!(
            retention
                .stage(first, artifacts(), &cancellation)
                .expect("first stages")
        );
        assert!(
            !retention
                .stage(second, artifacts(), &cancellation)
                .expect("second stages uncached")
        );
        assert_eq!(
            retention
                .staged
                .get(&first)
                .expect("staged owner remains")
                .len(),
            1
        );
        assert_eq!(retention.retained_bytes, budget);
        let release = retention
            .begin_discard(second)
            .expect("uncached staging releases");
        retention.finish_discard(release);
        retention.commit_staged(first).expect("first cache commits");

        let cancelled = deadline();
        assert!(cancelled.cancel(CancellationReason::ClientRequest));
        assert!(matches!(
            retention.stage(second, artifacts(), &cancelled),
            Err(FirstSliceError::Cancelled(
                CancellationReason::ClientRequest
            ))
        ));
        assert_eq!(
            retention
                .generation(first)
                .expect("committed cache remains")
                .len(),
            1
        );
        assert_eq!(retention.retained_bytes, budget);
        assert!(
            retention
                .stage(second, artifacts(), &cancellation)
                .expect("successor stages")
        );
        assert_eq!(
            retention
                .generation(first)
                .expect("old cache record remains")
                .len(),
            0
        );
        assert_eq!(retention.retained_bytes, budget);
        let release = retention
            .begin_discard(second)
            .expect("successor rolls back");
        retention.finish_discard(release);
        assert_eq!(retention.retained_bytes, 0);
    }

    #[test]
    fn structural_cache_exhaustion_falls_back_to_fresh_parsing() {
        let fixture = TempDir::new().expect("fixture root exists");
        fs::create_dir(fixture.path().join("src")).expect("fixture source directory exists");
        let source = fixture.path().join("src/lib.rs");
        fs::write(&source, "pub fn value() -> u32 { 1 }\n").expect("Rust source writes");
        let cancellation = deadline();
        let mut service = FirstSliceService::new(3).expect("service initializes");
        service.structural_artifacts.maximum_bytes = 1;

        let prepared = service
            .prepare_rust_fixture(fixture.path(), &cancellation)
            .expect("initial generation prepares within the structural cap");
        let FirstSliceIndexPreparation::Pending(pending) = &prepared else {
            panic!("changed fixture requires a pending generation");
        };
        assert!(pending.structural_artifacts.by_file.is_empty());
        assert_eq!(pending.structural_artifacts.accounted_bytes, 0);
        assert!(!pending.structural_artifacts.retention_complete);
        let first = service
            .publish_prepared(prepared, &cancellation)
            .expect("initial generation publishes without structural retention");
        let initial = service
            .incremental_evidence(first.generation)
            .expect("initial evidence remains retained");
        assert!(!initial.structural_cache_retained());
        assert_eq!(service.structural_artifacts.retained_bytes, 0);

        fs::write(&source, "pub fn value() -> u32 { 2 }\n").expect("Rust source changes");
        let prepared = service
            .prepare_rust_fixture(fixture.path(), &cancellation)
            .expect("successor prepares with immediate artifact eviction");
        let FirstSliceIndexPreparation::Pending(pending) = &prepared else {
            panic!("changed fixture requires a pending generation");
        };
        assert!(pending.structural_artifacts.by_file.is_empty());
        assert_eq!(pending.structural_artifacts.accounted_bytes, 0);
        assert!(!pending.structural_artifacts.retention_complete);
        let second = service
            .publish_prepared(prepared, &cancellation)
            .expect("successor generation performs a fresh parse");
        let successor = service
            .incremental_evidence(second.generation)
            .expect("successor evidence remains retained");

        assert_eq!(successor.parsed_files(), 1);
        assert_eq!(successor.reused_parser_artifacts(), 0);
        assert_eq!(successor.lowered_files(), 1);
        assert!(!successor.structural_cache_retained());
        assert_eq!(service.structural_artifacts.retained_bytes, 0);
    }

    #[test]
    fn unavailable_normalized_chunk_falls_back_to_parser_artifact_lowering() {
        let fixture = TempDir::new().expect("fixture root exists");
        fs::create_dir(fixture.path().join("src")).expect("fixture source directory exists");
        fs::write(
            fixture.path().join("src/lib.rs"),
            "pub fn stable() -> u32 { 1 }\n",
        )
        .expect("Rust source writes");
        let readme = fixture.path().join("notes.unrecognized");
        fs::write(&readme, "first\n").expect("unsupported source writes");
        let cancellation = deadline();
        let mut service = FirstSliceService::new(3).expect("service initializes");
        let first = service
            .index_rust_fixture(fixture.path(), &cancellation)
            .expect("initial generation publishes");

        let artifacts = service
            .structural_artifacts
            .committed
            .get_mut(&first.generation)
            .expect("initial structural cache remains retained");
        let entry = artifacts
            .by_file
            .values_mut()
            .next()
            .expect("initial parser artifact remains retained");
        let normalized_bytes = entry
            .normalized
            .take()
            .expect("initial normalized chunk remains retained")
            .accounted_bytes();
        artifacts.accounted_bytes = artifacts
            .accounted_bytes
            .checked_sub(normalized_bytes)
            .expect("generation cache charge includes the chunk");
        service.structural_artifacts.retained_bytes = service
            .structural_artifacts
            .retained_bytes
            .checked_sub(normalized_bytes)
            .expect("aggregate cache charge includes the chunk");

        fs::write(&readme, "second\n").expect("unsupported source changes");
        let second = service
            .index_rust_fixture(fixture.path(), &cancellation)
            .expect("successor publishes through the lowering fallback");
        let evidence = service
            .incremental_evidence(second.generation)
            .expect("successor evidence remains retained");

        assert_eq!(evidence.parsed_files(), 0);
        assert_eq!(evidence.reused_parser_artifacts(), 1);
        assert_eq!(evidence.lowered_files(), 1);
        assert_eq!(evidence.reused_normalized_facts(), 0);
        assert!(evidence.rebuilt_normalized_facts() > 0);
        assert_fresh_equivalent(
            &service,
            fixture.path(),
            first.generation,
            &second,
            &cancellation,
        );
    }

    #[test]
    fn aggregate_length_checks_bounds_and_overflow() {
        assert_eq!(
            checked_combined_length(2, 2, 3),
            Err(FirstSliceError::Limits)
        );
        assert_eq!(
            checked_combined_length(usize::MAX, 1, usize::MAX),
            Err(FirstSliceError::Limits)
        );
        assert_eq!(
            checked_resource_length(10_000, 1, 10_000, FirstSliceResource::Extensions),
            Err(FirstSliceError::ResourceLimit {
                resource: FirstSliceResource::Extensions,
                observed: 10_001,
                limit: 10_000,
            })
        );
    }

    #[test]
    fn source_verification_duration_keeps_omission_and_explicit_default_distinct() {
        let default = FirstSliceBudget::default();
        assert_eq!(default.query().explicit_max_duration(), None);
        assert_eq!(default.source().max_verification_duration, None);
        let explicit = default.reduce_max_duration(Duration::from_secs(2));
        assert_eq!(
            explicit.query().explicit_max_duration(),
            Some(Duration::from_secs(2))
        );
        assert_eq!(
            explicit.source().max_verification_duration,
            Some(Duration::from_secs(2))
        );
        let longer = default.reduce_max_duration(Duration::from_secs(5));
        assert_eq!(longer.query().max_duration(), Duration::from_secs(2));
        assert_eq!(longer.source().max_duration, Duration::from_secs(2));
        assert_eq!(
            longer.query().explicit_max_duration(),
            Some(Duration::from_secs(5))
        );
        assert_eq!(
            longer.source().max_verification_duration,
            Some(Duration::from_secs(5))
        );
    }

    #[test]
    fn first_slice_budget_reductions_are_monotonic_for_every_lower_layer() {
        let reduced = FirstSliceBudget::default()
            .reduce_max_rows(20_000)
            .reduce_max_edges(9_000)
            .reduce_max_results(40)
            .reduce_max_source_bytes(8_000)
            .reduce_max_json_bytes(32_000)
            .reduce_max_tokens(16_000)
            .reduce_max_memory_bytes(64_000)
            .reduce_max_duration(Duration::from_millis(500))
            .reduce_search_max_query_bytes(128)
            .reduce_search_max_candidates(2_000)
            .reduce_search_max_terms(8)
            .reduce_search_max_expanded_terms(256)
            .reduce_search_max_examined_terms(1_024)
            .reduce_search_max_postings(20_000)
            .reduce_search_max_returned_text_bytes(32_000)
            .reduce_source_max_selectors(8)
            .reduce_source_max_context_lines(4)
            .reduce_source_max_metadata_bytes(32_000)
            .reduce_source_max_snapshot_bytes(1_000_000);
        let query = reduced.query();
        let search = reduced.search();
        let source = reduced.source();

        assert_eq!(query.max_rows(), 20_000);
        assert_eq!(query.max_edges(), 9_000);
        assert_eq!(query.max_results(), 40);
        assert_eq!(query.max_source_bytes(), 8_000);
        assert_eq!(query.max_json_bytes(), 32_000);
        assert_eq!(query.max_tokens(), 16_000);
        assert_eq!(query.max_memory_bytes(), 64_000);
        assert_eq!(query.max_duration(), Duration::from_millis(500));
        assert_eq!(
            query.explicit_max_duration(),
            Some(Duration::from_millis(500))
        );
        assert_eq!(search.max_results, 40);
        assert_eq!(search.max_query_bytes, 128);
        assert_eq!(search.max_candidates, 2_000);
        assert_eq!(search.max_terms, 8);
        assert_eq!(search.max_expanded_terms, 256);
        assert_eq!(search.max_examined_terms, 1_024);
        assert_eq!(search.max_postings, 20_000);
        assert_eq!(search.max_returned_text_bytes, 32_000);
        assert_eq!(search.max_duration, Duration::from_millis(500));
        assert_eq!(source.max_selectors, 8);
        assert_eq!(source.max_context_lines, 4);
        assert_eq!(source.max_source_bytes, 8_000);
        assert_eq!(source.max_metadata_bytes, 32_000);
        assert_eq!(source.max_response_memory_bytes, 64_000);
        assert_eq!(source.max_snapshot_bytes, 1_000_000);
        assert_eq!(source.max_duration, Duration::from_millis(500));
        assert_eq!(
            source.max_verification_duration,
            Some(Duration::from_millis(500))
        );

        let attempted_raise = reduced
            .reduce_max_rows(u64::MAX)
            .reduce_max_edges(u64::MAX)
            .reduce_max_results(u64::MAX)
            .reduce_max_source_bytes(u64::MAX)
            .reduce_max_json_bytes(u64::MAX)
            .reduce_max_tokens(u64::MAX)
            .reduce_max_memory_bytes(u64::MAX)
            .reduce_max_duration(Duration::MAX)
            .reduce_search_max_query_bytes(usize::MAX)
            .reduce_search_max_candidates(usize::MAX)
            .reduce_search_max_terms(usize::MAX)
            .reduce_search_max_expanded_terms(usize::MAX)
            .reduce_search_max_examined_terms(usize::MAX)
            .reduce_search_max_postings(u64::MAX)
            .reduce_search_max_returned_text_bytes(usize::MAX)
            .reduce_source_max_selectors(usize::MAX)
            .reduce_source_max_context_lines(u16::MAX)
            .reduce_source_max_metadata_bytes(usize::MAX)
            .reduce_source_max_snapshot_bytes(u64::MAX);
        assert_eq!(attempted_raise, reduced);
    }

    #[test]
    fn reduced_policy_reaches_query_search_and_source_plans() {
        let fixture = TempDir::new().expect("fixture root exists");
        fs::create_dir(fixture.path().join("src")).expect("fixture source directory exists");
        fs::write(
            fixture.path().join("src/lib.rs"),
            "pub fn item_one() -> u32 { 1 }\npub fn item_two() -> u32 { 2 }\n",
        )
        .expect("budget fixture writes");
        let cancellation = deadline();
        let mut service = FirstSliceService::new(2).expect("first-slice service initializes");
        let receipt = service
            .index_rust_fixture(fixture.path(), &cancellation)
            .expect("budget fixture indexes");

        let first = service
            .code_locate_with_budget(
                receipt.generation,
                "item".to_owned(),
                LocateMode::Prefix,
                10,
                0,
                FirstSliceBudget::default()
                    .reduce_max_rows(10_001)
                    .reduce_max_results(1),
                &cancellation,
            )
            .expect("reduced query policy admits its exact conservative plan");
        assert_eq!(first.plan.estimate.rows, 10_001);
        assert_eq!(first.plan.estimate.results, 1);
        assert_eq!(first.data.hits.len(), 1);
        assert!(first.data.execution.is_truncated());

        let tightly_bounded = service
            .code_locate_with_budget(
                receipt.generation,
                "item".to_owned(),
                LocateMode::Prefix,
                1,
                0,
                FirstSliceBudget::default()
                    .reduce_max_rows(224)
                    .reduce_max_results(4),
                &cancellation,
            )
            .expect("row reduction also narrows the search candidate plan");
        assert_eq!(tightly_bounded.plan.estimate.rows, 224);
        assert_eq!(tightly_bounded.data.hits.len(), 1);

        assert!(matches!(
            service.code_locate_with_budget(
                receipt.generation,
                "item_one".to_owned(),
                LocateMode::Exact,
                1,
                0,
                FirstSliceBudget::default().reduce_search_max_query_bytes(4),
                &cancellation,
            ),
            Err(FirstSliceError::BudgetExceeded)
        ));

        let second = service
            .code_locate(
                receipt.generation,
                "item_two".to_owned(),
                LocateMode::Exact,
                1,
                0,
                &cancellation,
            )
            .expect("second symbol locates");
        let references = vec![
            first.data.hits[0]
                .source
                .clone()
                .expect("first symbol has source evidence"),
            second.data.hits[0]
                .source
                .clone()
                .expect("second symbol has source evidence"),
        ];
        assert!(matches!(
            service.source_read_with_budget(
                receipt.generation,
                references,
                FirstSliceBudget::default().reduce_source_max_selectors(1),
                &cancellation,
            ),
            Err(FirstSliceError::BudgetExceeded)
        ));
    }

